window.HARDTRP.receive("64123",[[64124,"2026-06-20T18:52:54",9,"Начало темы.\n\n@elsio28   Дм этой темы.",64123,null],[64160,"2026-06-20T19:12:39",5,"Описание и объявление.\nКвест «Забытый тайник»\nДля 3-4 игроков 3+ уровня (сложность снижена, но не мир пони). Опасность: сложная.\n#Поиск\n\nОднажды вам в руки попадает объявление со следующим текстом:\n«Ищу смелых героев, готовых добраться до моего старого тайника в заброшенном карьере. Награда щедрая. Ищите мой дом в деревне \"Большие башмаки\", на крыше флюгер в виде воина со щитом.»\nПодпись: Алексий\n\nПравила:\n1. Пунктуальность. Если договорились играть в какое-то время, будьте добры явиться\n2. Без ХБ. Сам новичок, поэтому не беру хб.\n3. Магические свитки могут использовать все герои, пройдя проверку Магии сл. 5\n\nУчастники:\nHard https://t.me/c/3239766844/183\n@H_Kruz https://t.me/c/3239766844/851/853\n@cirson https://t.me/c/3239766844/2463\n@Xaosick https://t.me/c/3239766844/2358",64123,null],[64162,"2026-06-20T19:13:13",5,"Начало в 20:00",64123,null],[64381,"2026-06-20T19:56:20",32,"Я тут",64123,null],[64395,"2026-06-20T19:59:45",5,"// после начала прошу все неигровые комментарии писать через //",64123,null],[64397,"2026-06-20T20:01:06",32,"// иногда могу по привычке брать просто в скобки мета комментарии//",64395,null],[64399,"2026-06-20T20:01:31",5,"Привлечённые жаждой наживы, желанием помочь или чем-то другим, в деревню \"Большие башмаки\" один за другим прибыли авантюристы. На небольшом рынке один за другим появились силуэты героев. Кто же там был?",64123,null],[64400,"2026-06-20T20:01:36",5,"// киньте арты, немного опишите",64123,null],[64401,"2026-06-20T20:01:44",5,"// можете познакомиться и поговорить",64123,null],[64414,"2026-06-20T20:03:46",32,"Не очень высокий и болезненно худой три-крин но одет очень богато",64123,null],[64417,"2026-06-20T20:04:15",32,"/Волшебник первого уровня",64123,null],[64418,"2026-06-20T20:04:41",40,"/арта нет, кроме через хуй нарисованный своими руками\n\nдед воин под сраку лет (около 60) стоит изучая то как местный конюх прибивает подкову кляче попутно заёбывая историей о том как он лично видел что лощадь лягнула конюза насмерть во время смены подковы в соседней деревне. \n\nсудя по ебальнику конюха, он парень молодой, возраст уважает и потому из последних сил сдерживается чтобы не послать нахуй старого",64123,null],[64420,"2026-06-20T20:04:46",9,"*Гигант медленно шёл к назначенному место. Когда он двигался, создавалось впечатление что тот плыл над землёй, подолы закрывающие низ тянулись по земле.*\n\n// Леда — https://t.me/c/3239766844/183",64123,null],[64422,"2026-06-20T20:05:04",40,"щит кольчуга да топор был при дедушке",64418,null],[64434,"2026-06-20T20:06:14",32,"Конкретно жук шёл относительно медленной шаркающей походкой глубоко в своих мыслях",64415,null],[64443,"2026-06-20T20:08:12",5,"Небольшой грязный домишко с красивым флюгером наверху заметен издалека. Ветер дует сильно, флюгер-воин колышется, будто закрываясь щитом от приближающейся опасности.",64123,null],[64447,"2026-06-20T20:09:23",32,"//кстати мастер нужно кинуть 2 д20 знамения//",64123,null],[64448,"2026-06-20T20:09:33",5,"// кидай",64447,null],[64449,"2026-06-20T20:09:40",32,"/roll@roll_bot",64123,null],[64453,"2026-06-20T20:11:09",40,"после возмущенного крика мальчишки \n\n\"Дед, иди нахуй пока я тебе подкову к затылку не прибил, мудак старый!\"\n\nу данного дома с флюгером материализовался и старик, глядя на своих товарищей по приключению\n-Тож на заказ пришли, молодые люди... и не люди... Муравей?! Кхм... прости, брат, правда я таких не видовал раньше. Я однажды малину ел, а там мне и муравей попался, я его нечаянно перекусил зубами - сука муравьиная кислота конечно гадкая вещь - как вспомню аппетит пропадает. У тебя муравьиная кислота имеется, родной?",64123,null],[64458,"2026-06-20T20:11:52",47,"Это Талон. Я сейчас маленько отвлекаться буду, но так в игре",64123,null],[64460,"2026-06-20T20:12:21",11,"// а ты весёлый, интересно за твоей игрой посмотреть будет",64453,null],[64464,"2026-06-20T20:12:38",32,"-Я богомол (педантично поправил деда не отвлекаясь от мыслей о окружающем настолько задумчив что даже не обратил внимания что к нему обратились)",64453,null],[64465,"2026-06-20T20:12:41",40,"//ну я хохмить сильно много не буду - там где уместно",64123,null],[64466,"2026-06-20T20:12:41",5,"// вххвах я не могу. Держи вдохновение к4",64453,null],[64468,"2026-06-20T20:13:03",40,"-Верующий стало быть.",64464,null],[64470,"2026-06-20T20:13:09",40,"-Какому богу ты молишься?",64123,null],[64471,"2026-06-20T20:13:16",40,"-Я тоже своего рода... богомол",64123,null],[64473,"2026-06-20T20:13:18",47,"К месту назначению ровным шагом вышел моложавый человек. Его лицо было слегка прикрыто капюшоном, но не скрывало основных черт лица. За спиной колчан, а за поясом рапира",64123,null],[64475,"2026-06-20T20:13:28",9,"*Леда посмотрел на окрудающих. Здороваться он не спешил, перед ним был дом, а там его злейшие враги... низкие потолки и узкая дверь...*",64123,null],[64476,"2026-06-20T20:13:31",47,"/могу по бырому списать 5 голды и взять щит?",64123,null],[64477,"2026-06-20T20:13:36",32,"(а потом чуть прочухался и повернул голову к говорившему старику)\n-Точнее три-крин по расе",64464,null],[64478,"2026-06-20T20:14:07",9,"//Он 10 стоит вродь, покупал последний раз",64476,null],[64479,"2026-06-20T20:14:08",5,"// делай и пиши где-то во флуде по несвязанным с квестом вопросам",64476,null],[64480,"2026-06-20T20:14:10",32,"-А ты дед человек? Впервые вас вижу ,на обезьяну похож\n(Ну не мог грубо на грубость не ответить)",64477,null],[64481,"2026-06-20T20:14:14",47,"Он оглядел остальных и пока стоял спокойно, наблюдая за реакцией остальных",64123,null],[64488,"2026-06-20T20:15:21",32,"// да тебя передразнили//",64485,null],[64490,"2026-06-20T20:15:35",40,"*молчаливый взгляд полный осуждения*",64123,null],[64492,"2026-06-20T20:15:56",40,"-Ладно, давайте работать что ли...",64123,null],[64494,"2026-06-20T20:16:05",5,"Две немолодые женщины, сидящие на скамье около соседнего дома, таращатся на жука и слушают этот необычный диалог. Они тихо шушукаются о чем-то.\n\nВоин-флюгер всё так же закрывается от вас щитом.",64123,null],[64497,"2026-06-20T20:16:29",9,"*Заметил длинные уши. Эльфов велика не видел ещё, наёмники говрят — редкость.*\n\n— Фея. — *Коротко заключил Леда и достал яблоко протянув его парню с длинными ушами в своих больших ладонях.* — Держи, угощение.",64481,null],[64498,"2026-06-20T20:16:30",32,"//Кстати говорит жук не словами а телепатией что не сразу заметно правда",64492,null],[64501,"2026-06-20T20:17:01",5,"// значит дед говорит с молчащими спутниками. Ещё забавнее",64498,null],[64502,"2026-06-20T20:17:14",47,"Талон молча проигнорировал угощение, так как не считал себя феей",64497,null],[64503,"2026-06-20T20:18:02",9,"*Непонял Леда, обычно феи принимают угощение. Решил что может не хочет и спрятал.*",64502,null],[64510,"2026-06-20T20:18:31",11,"// чел харош, хочу с тобой поиграть..",64471,null],[64513,"2026-06-20T20:19:03",47,"/Талон уже в ахуе с компашки, но лицо камнем",64123,null],[64514,"2026-06-20T20:19:05",32,"-Приветствую коллеги, на пути приключений. И вас хозяева (сразу ко всем обратился жук) ко мне можете обращаться Ей ты там или как ещё придумаете мое имя все равно на ваш язык не переводится",64123,null],[64515,"2026-06-20T20:19:06",40,"-Помилуй души этих юнцов, Ильматер, - шепнул старик и заметив пожилых дам, слегка поправил волосы, глядя на себя в лужу словно в зеркало, чтобы убедиться что пару оставшихся на бошке локанов он уложил наиболее симпатичным обращом.\n\nположив обе руки на кожанный пояс с которого свисал топор, он явно флиртуя с дамами его возраста произносит:\n-Девочки, не видали ли великана тут? Говорят с его дырявого мешка выпали две красавицы, хе-хе",64123,null],[64516,"2026-06-20T20:19:07",47,"Скинул капюшон",64123,null],[64517,"2026-06-20T20:19:20",40,"-Чую их я и нашел на столь прелестном крыльце",64123,null],[64519,"2026-06-20T20:19:28",11,"// не стесняйтесь, химия персов любая это круто",64480,null],[64520,"2026-06-20T20:19:38",9,"— Мы все приши сюда по одной причине. — *Толи заключил, толи спросил.*",64123,null],[64521,"2026-06-20T20:20:16",9,"*Слегка поднял бровь, но ничего не сказал.*",64515,null],[64522,"2026-06-20T20:20:29",5,"Женщины смущаются и продолжает шептаться между собой. Они не отвечают тебе, но щёки одной слегка покраснели",64517,null],[64524,"2026-06-20T20:21:39",40,"-Ладушки, милые мои, не подскажете ли какие новости у вас в поселении, чем живёте. Как видите не местные мы.",64522,null],[64525,"2026-06-20T20:21:41",32,"(в время флирта после того как представился всем я снова вернулся в свиток с своими расчетами)",64123,null],[64528,"2026-06-20T20:22:32",32,"-Это настолько заметно? \n(Ехидный голос звучал в головах всех окружающих)",64524,null],[64529,"2026-06-20T20:23:32",40,"*посмотрел на богомола и отвернулся*",64123,null],[64530,"2026-06-20T20:23:32",5,"— Новости? А да какие новости у нас, в глуши такой! Вот подрали Никитку волки в лесу, едва живой ушёл! — женщина с немного покрасневшими щеками отвечает тебе",64524,null],[64534,"2026-06-20T20:23:51",9,"*Леда понял что остальные заняты своими делами. Взглянул на молчаливого фея с длинными ушами который ничего не делал и решил. Он подошёл к двери и мягко постукал, осторожно, чтобы не выбить своими большими нерасторопными руками.*",64123,null],[64537,"2026-06-20T20:24:06",40,"/а почему блять пикча а не гифка...",64123,null],[64538,"2026-06-20T20:24:18",9,"— Гости, путники.",64534,null],[64539,"2026-06-20T20:24:23",5,"— Входите, всегда открыто! — мягкий старческий голос донёсся из домика",64534,null],[64550,"2026-06-20T20:25:14",47,"Тал решает шагать рядом с насекомым. Адекватным, хоть и странным кажется он",64123,null],[64555,"2026-06-20T20:25:37",9,"*Собрался с мыслями и открыв дверь заглядывает внутрь. Он то пролезет, кое как, но высота потолков.*",64123,null],[64556,"2026-06-20T20:25:46",40,"-Ну и на том спасибо, буду знать что в округе лес недобрый. Бывайте дамы, - старик поковылял к дому с флюгером услышав что там движ начался",64530,null],[64557,"2026-06-20T20:25:46",32,"(Я пристроился так чтобы быть в центре между всеми напарниками)",64550,null],[64560,"2026-06-20T20:26:07",47,"Спереди. Чтобы ты спину прикрыл",64557,null],[64562,"2026-06-20T20:26:27",5,"Небольшой домик, внутри крайне бедная обстановка. Почти нет мебели. У стены на скамье сидит седой старик. Перед ним пустой стол",64555,null],[64567,"2026-06-20T20:26:43",32,"//у меня 5 ХП я спину могу перекрыть только смазкой под ноги недобрым гадам//",64560,null],[64574,"2026-06-20T20:27:38",32,"-Приветствую дедушка (расчеты не сошлись потому были отложены нахрен обратно в сумку а я наконец собрался с мыслями)",64562,null],[64576,"2026-06-20T20:27:51",40,"-Добрый день, - вежливости ради поприветствовал хозяина Хорхе и встал у дверей. привычка военного, стоять у путей отхода в случае чего. Но Хорхе расслаблен, опасностей вроде тут нет",64123,null],[64577,"2026-06-20T20:27:58",5,"— О-о-ох, о-ох какие гости! — дед смотрит на вас с надеждой\n\n— Неужто дошла моя просьба о помощи до смелых героев! Заходите, заходите!\n\nОн осматривает комнату и грустно говорит.\n\n— Угостил бы вас, да сам последние крохи доедаю",64123,null],[64580,"2026-06-20T20:28:11",9,"— Здравствуйте\n\n*Согнутый в три погибели маленький великан кое как заходит в дом.*",64123,null],[64587,"2026-06-20T20:28:52",47,"/потому я и спереди прикрываю. А ты сзади щитом укроешься если что",64567,null],[64590,"2026-06-20T20:29:02",47,"/вообще могу на 300 фт бить/",64123,null],[64595,"2026-06-20T20:29:57",9,"— Незванные гости сами угощают хозяина. — *Великан щитал так и просто выложил на стол куль свежих покупок которые закупал для себя.*\n\n//- 6 рацинов",64577,null],[64598,"2026-06-20T20:30:18",32,"(я просто подхожу к столу и выкладываю два суточных рациона сущеное мясо и аналогичное на хищный образ жизни)",64577,null],[64599,"2026-06-20T20:30:20",47,"/эльф перекусил заранее",64123,null],[64600,"2026-06-20T20:30:50",32,"(одобрительный зырк свой своего)",64595,null],[64601,"2026-06-20T20:31:10",5,"— Звать меня Алексий, заходите, расскажу вам обо всём. — говорит старик. \n\nОн сидит около стены. Одежда поношенная, но левая рука сжимает что-то блестящее. Небольшой священный символ. Глаза тусклые, но в глубине угадывается недюжинная сила воли.",64123,null],[64602,"2026-06-20T20:31:14",9,"//Я как игрок не понимаю что это было ~",64600,null],[64604,"2026-06-20T20:31:29",32,"(тож кстати два суточных это 6 рационов)",64598,null],[64607,"2026-06-20T20:31:53",9,"//Рацион вообще на день вродь)",64123,null],[64608,"2026-06-20T20:31:54",32,"(Просто немного повернул голову и подвигал усиками)",64602,null],[64610,"2026-06-20T20:32:13",5,"— Ох, спасители вы мои! Только зашли, а мне уже в ноги кланятся охота — пытается встать — ох, спина!",64595,null],[64613,"2026-06-20T20:32:20",32,"//А тогда на шесть дней",64607,null],[64615,"2026-06-20T20:32:37",5,"// держи вдохновение к12",64595,null],[64616,"2026-06-20T20:32:43",5,"// а ты к4",64598,null],[64619,"2026-06-20T20:33:11",32,"-в нашей культуре положено помогать нуждающихся",64610,null],[64620,"2026-06-20T20:33:14",9,"— Простая вежливость цены не имеет. — *Просто старается казаться скромным чтобы старик не перенапрягся.*",64610,null],[64621,"2026-06-20T20:33:17",32,"???",64616,null],[64624,"2026-06-20T20:33:36",5,"// вдохновение можно добавить к любому броску. У  тебя в виде кубика д4",64123,null],[64627,"2026-06-20T20:34:16",32,"//Я одного не понимаю вроде одно и тоже и в одном и том же формате/объеме совершили",64624,null],[64629,"2026-06-20T20:34:24",32,"..",64613,null],[64634,"2026-06-20T20:34:40",5,"// ты поддержал, но идея не твоя",64627,null],[64637,"2026-06-20T20:34:55",5,"// или вы оджновременно?",64123,null],[64640,"2026-06-20T20:35:20",5,"— Вежливость дороже денег, внучок",64620,null],[64643,"2026-06-20T20:35:25",32,"Я писал ето ещё до прихода",64634,null],[64645,"2026-06-20T20:35:35",32,"Наши сообщения пришли одновременно!",64123,null],[64646,"2026-06-20T20:35:40",5,"// ок тогда тоже к12",64643,null],[64648,"2026-06-20T20:36:04",32,"//пасиб",64646,null],[64649,"2026-06-20T20:36:07",5,"—Давайте расскажу я вам, о чём писал. О тайнике моём старинном",64123,null],[64650,"2026-06-20T20:36:26",9,"*Не сталспорить с дедом.*",64640,null],[64652,"2026-06-20T20:36:49",32,"(жук просто присел в свободном углу смотрел фасеточными глазами внимательно слушая)",64649,null],[64656,"2026-06-20T20:37:14",47,"Талон укрылся рядом",64123,null],[64662,"2026-06-20T20:38:02",40,"Хорхе устало стоит у входа периодически наблюдая за обстановкой в окнах, за звуками в соседних помещениях. Внимание Хорхе обращено во все части куда не смотрят остальные герои. Тоже привычка военная - осмотрительность в любой момент, даже если кажется что противников рядом нет.",64123,null],[64664,"2026-06-20T20:38:53",5,"— Много лет минуло уже, ох как много. Друг мой верный и я шли по дороге приключений, как вы сейчас. Ох, какие там дела были...\n\nДед задумывается.\n\n— Давно это было, давно! Много добычи было волшебной, делали мы тайники. Собирали на беспечную старость.",64123,null],[64665,"2026-06-20T20:38:55",32,"-у меня из-за фасеточных глаз угол обзора 270° так что не напрягайся",64662,null],[64673,"2026-06-20T20:40:10",5,"За окном обычная деревенская обстановка. Периодически ходят люди, о чём-то толкуют. Всё выглядит мирно.\n\nОднако, ты вспоминаешь небо. И ветер. Тёмные тучи собираются на горизонте. Чутьё тебе подсказывает, что без дождя не обойдётся",64662,null],[64679,"2026-06-20T20:40:58",47,"/я пока обживаюсь тут, и с персом сейчас не знаю как отыгрывать. Лорную часть, читаю",64123,null],[64680,"2026-06-20T20:41:06",47,"/поэтому пока слабый отыгрыш будет",64123,null],[64681,"2026-06-20T20:41:37",5,"— Да... Много лет прошло, поистратились тайники. Один остался, в карьере заброшенном. А ходят о нём скверные слухи. Люди там пропадают",64664,null],[64682,"2026-06-20T20:41:40",32,"//я тоже просто делай так как делал в реале и не парься//",64679,null],[64685,"2026-06-20T20:42:07",32,"-Какие слухи?",64681,null],[64687,"2026-06-20T20:42:08",9,"//Эльфы почти вымерли, поэтому Леда и пощитал тебя феей, а так вродь там ничё особенного эльфам",64680,null],[64688,"2026-06-20T20:42:11",47,"/я бы в реале Цепанул наушники пока все хуйней занимаются. Дождался ЦУ и пошёл делать работу",64682,null],[64689,"2026-06-20T20:42:11",5,"// ничего страшного, осваивайся. Не стесняйся спрашивать и вообще говорить персом что угодно",64680,null],[64700,"2026-06-20T20:43:01",32,"//тогда просто поливались к боку жука он может тебе пару книг почитать дать//",64688,null],[64702,"2026-06-20T20:43:06",47,"/ну и при этом это всё по стойке смирно, чтобы даже замечаний не было, а в случае личных или общих вопросов \"так точно\" Или \"никак нет\", или \" Есть\"",64123,null],[64703,"2026-06-20T20:43:10",40,"-Фасеточных... - буркнул Хорхе дальше приглядываясь к обстановке снаружи",64665,null],[64709,"2026-06-20T20:43:30",47,"/Талон не любитель почитать. Он больше попытаться убедить, не получилось, на месте пристрелить/",64700,null],[64716,"2026-06-20T20:44:34",32,"//какая компания где по идее самый злой из моих персов самый добрый в команде//",64709,null],[64718,"2026-06-20T20:45:31",5,"— Один я туда не пойду, старый уже. А вот вы. Прошу, сходите туда, заберите тайник. Золота достаточно там со старых времён. Заберёте себе, сколько посчитаете нужным. А мне немного оставьте, доживать свой век",64681,null],[64719,"2026-06-20T20:45:35",40,"/Талон короче выглядит как воин-эльф с мечем и т.д., верно?",64709,null],[64721,"2026-06-20T20:45:38",32,"-Завидуй молча!(С лёгким злорадством ответил жук только дед и он)",64703,null],[64728,"2026-06-20T20:45:58",47,"Выше есть фото. Клинок, как и броня, укрыты плащом, а так да/",64719,null],[64733,"2026-06-20T20:46:13",47,"/он добрый. Он рад решить всё мирно и разговором",64716,null],[64747,"2026-06-20T20:46:55",9,"*Кивает.*\n\n— Быть тому. Согласен.",64718,null],[64751,"2026-06-20T20:47:19",32,"-Хорошо дед есть у тебя что из уже не нужного оружия? Свитки с магией чего ещё что молодым и амбициозным может быть полезно.\nВыступление+4",64718,null],[64752,"2026-06-20T20:47:25",40,"-Хищные создания имеют глаза фронтально на черепе, чтобы концентрировать зрение. А глаза по бокам у букашек, баранов, ослов - им надо следить чтобы хищник их за сраку не поймал. Такие дела, родной. Не не боись, я насекомых не обижаю",64721,null],[64755,"2026-06-20T20:47:47",9,"*Положил руку на грудь символизируя искренность слов своих, клятву, обещание.*",64747,null],[64756,"2026-06-20T20:48:38",5,"// кидай кубик",64751,null],[64757,"2026-06-20T20:48:45",32,"(повернулся раздвинул мандибулы сжал раздвинул ещё раз развел усики и отвернулся)",64752,null],[64758,"2026-06-20T20:48:53",32,"/roll@roll_bot",64756,null],[64760,"2026-06-20T20:49:07",32,"//Мм кажется это фиаско",64759,null],[64762,"2026-06-20T20:49:48",5,"— Оружие? Свитки? Знакомы мне слова, да много лет уже прошло. Ничего не осталось у меня, живу, крошки считаю",64751,null],[64763,"2026-06-20T20:50:21",32,"Проницательность+4",64762,null],[64764,"2026-06-20T20:50:25",32,"/roll@roll_bot",64123,null],[64767,"2026-06-20T20:50:38",32,"/Да вы издеваетесь!",64765,null],[64768,"2026-06-20T20:50:45",5,"// нет, ты уже проиграл, один бросок на одно и тоже",64763,null],[64769,"2026-06-20T20:50:58",40,"реакция Хорхе на мувы богомола",64123,null],[64770,"2026-06-20T20:51:03",9,"//Непереживай, это мои двойки. Когда я в игре рещультаты 2 и 22 приследуют всех",64123,null],[64771,"2026-06-20T20:51:10",32,"//я проверить его искриность в словах хотел//",64768,null],[64772,"2026-06-20T20:51:56",5,"— Но знаете... — старик задумался. — Я могу пойти с вами. Ходить ещё умею. Да и по старой памяти что-то сотворить могу. Боюсь лишь вас замедлить, обузой стать",64123,null],[64773,"2026-06-20T20:51:59",32,"//но у меня бдительный даёт приимущество на проницательность и внимательность//",64123,null],[64774,"2026-06-20T20:52:09",32,"/roll@roll_bot",64123,null],[64776,"2026-06-20T20:52:28",9,"*Кивает, немного неодобрительно смотря на богомола.*\n\n— Укрытые сединой люди богаты лишь опытом.",64762,null],[64778,"2026-06-20T20:52:41",5,"// перестань кидать, ты проверяешь слова которые старик сказал из-за твоего неудачного броска. Кидай новое только на другую тему",64123,null],[64781,"2026-06-20T20:53:11",40,"*нихуя себе, анальный мудрец* - подумал Хорхе про себя",64776,null],[64783,"2026-06-20T20:53:36",32,"//а это разве так работает? Я попытался его убедить что нам нужнее он сказал что нет он мог соврать//",64778,null],[64788,"2026-06-20T20:54:30",9,"— Желаете вспомнить былые дни — этим неуклюжим рукам не составит труда вас нести.",64772,null],[64789,"2026-06-20T20:54:34",40,"(кстати я могу подумать в твой адрес чтобы ты услышал или это так не работает? на игре скрытая связь может быть полезна)",64783,null],[64791,"2026-06-20T20:55:08",32,"//Да ты можешь отвечать мне мыслями",64789,null],[64793,"2026-06-20T20:55:32",5,"// мог и соврать. Но ты пытаешься повторять разные броски для того же желаемого результата. Придумай другую тему, вместо допроса. Тогда можешь кидать",64783,null],[64799,"2026-06-20T20:56:44",5,"— Ох, да ты здоровяк! И правда, донесёшь без труда. Но как в карьере, там уступы высокие?",64788,null],[64802,"2026-06-20T20:57:12",5,"Старик колеблется. Вам решать, готовы ли взять его с собой.",64123,null],[64804,"2026-06-20T20:58:11",32,"-Идём с нами (киваю я правда решение мое вызвано культурой три-крин где старики уходили на последнюю охоту (правда за счёт опыта скорее всего не по одному кругу)",64123,null],[64805,"2026-06-20T20:58:16",9,"— Не знаю. Лишь вам решать го овы ли вы рискнуть. — *Он лишь предложил, думал может старик хочет вспомнить молодость.*",64799,null],[64808,"2026-06-20T21:00:20",5,"Дед Алексий вздыхает и думает.\n\n— Ещё хотел сказать... Как тайник найти. Карьер этот, ступени там. Вот, закопали мы с другом тайник в стене, на второй ступени...",64805,null],[64809,"2026-06-20T21:00:32",5,"— Или на третей? Ох, подводит меня память!",64123,null],[64810,"2026-06-20T21:00:41",40,"-Кто то еще его может искать?",64808,null],[64811,"2026-06-20T21:00:59",5,"// 1 к 1, вам решать. Мнение жука обосновано)",64805,null],[64817,"2026-06-20T21:01:58",5,"— Лежит он там 20 лет уж как, не меньше. Знал про него только я, да друг мой старый. Пропал он давно, сгинул... — старику стало очень грустно и он замолчал",64810,null],[64819,"2026-06-20T21:02:17",32,"-Без вашей помощи на месте можем и не найти вы явно хорошо его спрятали",64809,null],[64820,"2026-06-20T21:02:44",40,"-Соболезную вашей утрате. Я лишь хочу быть уверен что нам не придётся соперничать с теми кто параллельно с нами ищет ценности",64817,null],[64821,"2026-06-20T21:03:14",5,"— Вспомнил! Метку поставили мы. На стене ступени, что выше тайника... Увидите метку, спускайтесь вниз. Там и найдёте",64819,null],[64822,"2026-06-20T21:03:19",47,"Отошёл/",64123,null],[64827,"2026-06-20T21:04:25",5,"— Не ищет его никто, не ходит в тот карьер никто больше. А если и ходит, то не возвращается. Но вы... вы сильные и справитесь",64820,null],[64829,"2026-06-20T21:04:45",32,"-Спасибо за помощь (киваю я все ещё жду решения старого воина готов он к последней охоте или нет)",64821,null],[64830,"2026-06-20T21:04:46",40,"-Принято, спасибо Алексий",64123,null],[64834,"2026-06-20T21:05:35",5,"// я тоже жду, @H_Kruz мнение?",64829,null],[64835,"2026-06-20T21:06:22",40,"//ну так да, я для этого и пришел на квест. А оно же не обязательно должно закончиться смертью для нас, почему последняя?))",64123,null],[64836,"2026-06-20T21:06:27",9,"— Вскоре вернёмся. Нести хорошие новости, прийдёт тот час.",64123,null],[64837,"2026-06-20T21:06:49",5,"// конечно не обязательно",64835,null],[64838,"2026-06-20T21:07:34",32,"//последняя не обязательно не зря же я ироничный комментарий добавлял обычно три-крины просто умирали от старости на охоте//",64835,null],[64840,"2026-06-20T21:08:17",5,"Старик Алексий сидит на скамейке, сжимаю в руках блестящий символ. На улице дует ветер. Он всё ещё в нерешимости, стоит ли идти в карьер с вами.",64123,null],[64842,"2026-06-20T21:09:01",5,"— Возвращайтесь, внучки мои! Жду вас... Если что забыл рассказать, не серчайте, память уже не та",64836,null],[64843,"2026-06-20T21:09:14",32,"- мы выступаем на охоту. Удачного дня старший.(Вторая часть адресована старику а первая ритуальная)",64836,null],[64845,"2026-06-20T21:10:25",9,"*Пока все идут он решил познакомиться.*\n\n— Я — Леда. Имя что помню, что знаю. Наёмник.",64123,null],[64846,"2026-06-20T21:11:06",9,"//С сопартийцами, но да",64123,null],[64847,"2026-06-20T21:11:32",32,"-Я уже говорил но повторю (и просто слово в слово повторил произнесённое)",64123,null],[64848,"2026-06-20T21:11:32",32,"-Приветствую коллеги, на пути приключений. И вас хозяева (сразу ко всем обратился жук) ко мне можете обращаться Ей ты там или как ещё придумаете мое имя все равно на ваш язык не переводится",64123,null],[64850,"2026-06-20T21:11:45",5,"Герои вышли из дома старика. Вокруг деревни сплошной густой лес, в верхушках завывает ветер. Тёмные облака несутся по небу.",64123,null],[64852,"2026-06-20T21:12:12",32,"(усики жука поддергиваются отмечая смену температуры воздуха и влажность)",64850,null],[64853,"2026-06-20T21:12:50",9,"*Кивает.*\n\n— Буду помнить тебя.",64848,null],[64856,"2026-06-20T21:13:49",32,"-Я бывший инженер маготехнолог сейчас безработный на пол ставки",64853,null],[64860,"2026-06-20T21:16:07",9,"— Магия близка мне, чувствую её. Знаю о ней, не знаю. — *Леда сам запутался.*",64856,null],[64862,"2026-06-20T21:16:31",9,"*Смотрит на надвигающуюся погоду. Часто приходилось прлсто пережидать такое под скалами, деревьями. Что то он вспомнил, время, или мысль что переплетаясь в слова стала живой, влилась в уста усталыми звуками меланхолиии, о чём-то, о забытом.*\n\n— Взойдёт палящее солнце Кыиланга. Идёт шаман неся в руках ворона укравшего песню героя. Замурован в перьях, в полых костях да остром клюве, порыв души искренний, великий. Да за кругом не видно чужого простора. Сказанное не имелось в виду, слова навлекли беду. Птица льёт правду в уши человеческим голосом. \n\"Сердце окаменей. И больше не смей, и больше не смей...\"",64850,null],[64865,"2026-06-20T21:18:18",32,"(жук с интересом слушал но смысл немного не уловил)",64123,null],[64867,"2026-06-20T21:18:51",32,"-Это хорошо что чувствуешь а умеешь что из чародейства творить?",64860,null],[64868,"2026-06-20T21:19:22",9,"— Тьма, чувствую её.",64867,null],[64869,"2026-06-20T21:20:08",32,"-Ты владеешь обнаружением магии?",64868,null],[64870,"2026-06-20T21:20:27",40,"@elsio28 \nХорхе чтобы отвлечься от пиздеца творимого его соратниками решает вспоминть географию местности в которую они идут. \n\nпогода - пасмурно вероятно дождь\nместность - лес\n\nХорхе пытается это вспомнить чтобы понять будет ли иметь смысл где то делать временные укрепления, окопчик или лисья нора (маскировочное укрытие на 1-2 чела закрытое ветками) на случай если группа встретит особо яростное сопротивление и придется отступать. есть ли там река течение которой может унести от опасности быстрее бега пешком. и т.д.\n\n//Хорхе военный а потому карту знает хорошо, военные географию всегда учитывают при выполнении заданий + мелкие инженерные укрепления умеет делать я это вписал ему в наративные умения",64123,null],[64871,"2026-06-20T21:22:01",32,"//если что я могу благодаря чувствительным антенкам предсказать погоду с высокой точностью//",64123,null],[64872,"2026-06-20T21:22:14",9,"*Неуверен что отвечать.*\n\n— Не знаю\n\n//Воззвание потом возьму",64869,null],[64873,"2026-06-20T21:22:52",32,"(жук здесь недавно вообще а потому не знает куда идти)",64870,null],[64874,"2026-06-20T21:23:20",5,"Дождь ещё не начался, но может пойти в любую минуту.\n\nПуть к карьеру лежит через густой, дикий лес. Он займёт несколько часов, если идти без задержек.\n\nРек по пути не встретится, лишь в стороне от дороге находятся несколько болот.",64870,null],[64876,"2026-06-20T21:23:56",5,"В таком лесу создать небольшое укрытие из подручных материалов не будет проблемой, это займёт окло получаса",64870,null],[64877,"2026-06-20T21:25:19",5,"// кинь природу",64871,null],[64878,"2026-06-20T21:25:21",47,"Талон в основном шпион, разведчик, и так далее, и хотя его основа быстрый переход и внедрение внутрь объекта, он всё де обладает навыками передвижения по лесу и остановкам в нём",64123,null],[64879,"2026-06-20T21:25:24",47,"Помощь",64877,null],[64880,"2026-06-20T21:25:47",32,"(Жуку впринципе нормально идти и под дождём хитиновый панцирь не продувает а мантия непромокаемая разве что на десять минут отвлечься и призвать парящий диск чтобы свою сумку на него положить нужно ибо намокшую уже просто не уволочет)",64874,null],[64881,"2026-06-20T21:26:03",32,"/roll@roll_bot",64877,null],[64883,"2026-06-20T21:26:15",32,"🤨",64882,null],[64884,"2026-06-20T21:26:24",47,"/преимущество.я помог",64123,null],[64885,"2026-06-20T21:26:34",9,"//Это не 2, не моя вина",64123,null],[64886,"2026-06-20T21:26:59",32,"Ещё один кинуть?",64884,null],[64887,"2026-06-20T21:27:03",5,"// да",64886,null],[64888,"2026-06-20T21:27:18",32,"/roll@roll_bot",64123,null],[64890,"2026-06-20T21:27:58",32,"+2 от мудрости",64889,null],[64891,"2026-06-20T21:28:06",47,"Там интелект/",64123,null],[64892,"2026-06-20T21:28:13",32,"Тогда+3",64123,null],[64893,"2026-06-20T21:28:14",5,"Твоё усики позволяют узнать больше, чем чутьё старого вояки. Воздух свежий, но дождь пока не пойдёт. Он начнётся через 3 часа",64889,null],[64894,"2026-06-20T21:28:47",5,"// вы стоите в деревне. Ваши действия?",64123,null],[64895,"2026-06-20T21:29:53",47,"/направиться в сторону тайника?",64123,null],[64896,"2026-06-20T21:30:01",47,"Я просто слегка отвлёкся и влом читать/",64123,null],[64897,"2026-06-20T21:30:05",32,"-До дождя примерно 2-3 часа мы можем сходить закупится например конопляного масла купить \nИ в любом я хочу призвать парящий диск я слишком слаб чтобы нести свою сумку и можно и чужие положить",64893,null],[64898,"2026-06-20T21:31:03",32,"//слишком слаб имеется ввиду что она его сильно нагружает но он может но не не хочет//",64123,null],[64899,"2026-06-20T21:31:37",9,"— Груз посильный несут плечи. — *Леда тащит на себе даж сундук, и по личным причинам не даст то что закрывает от взглядов его ужасный лик...*",64897,null],[64900,"2026-06-20T21:32:14",9,"//да, на картинке тож это переданно)",64420,null],[64901,"2026-06-20T21:32:16",32,"-Ну как хотите но мне нужно десять минут.",64899,null],[64902,"2026-06-20T21:32:48",9,"*Никаких возражений не высказал.*",64901,null],[64903,"2026-06-20T21:35:01",32,"Тогда остановится на немного и на вогнутую как линза стекляшку капнул пару капель ртути и проводил магический ритуал призывая парящий диск из силового поля который будет на дистанции 20 футов следовать за мной и возложил на диск свой рюкзак и собрал компоненты обратно в кармашки мантии",64123,null],[64904,"2026-06-20T21:35:41",5,"// ты можешь оглядеться в поисках торговца если что",64897,null],[64905,"2026-06-20T21:36:05",32,"Внимательность с приимуществом",64904,null],[64906,"2026-06-20T21:36:10",5,"// кидай",64905,null],[64907,"2026-06-20T21:36:16",32,"/roll@roll_bot",64123,null],[64909,"2026-06-20T21:36:21",32,"/roll@roll_bot",64123,null],[64911,"2026-06-20T21:36:31",32,"+4 =22",64910,null],[64912,"2026-06-20T21:36:43",5,"// так, если что это можно кидать вот так",64123,null],[64913,"2026-06-20T21:36:47",5,"/r +d20+4",64123,null],[64915,"2026-06-20T21:36:59",9,"//Я придумал, в следующий раз куплю бочку и кучу масла чтобы запалнить её им, леда будет кидать не флягу масла а сразу бочку ^^",64123,null],[64917,"2026-06-20T21:38:37",5,"Три-крину даже не надо поворачиваться, чтобы увидеть какого-то старика, развешивающего травы на нитках около дома. Ты понимаешь, что это травник.\n\nНа рыночной площади ,однако, пусто. Деревня небольшая, чудо, что же здессь можно купить хоть что-то",64123,null],[64919,"2026-06-20T21:39:09",5,"// конопляное масло то бишь фляга с маслом?",64897,null],[64920,"2026-06-20T21:39:32",32,"//Не совсем большой кувшин а лучше не один",64917,null],[64921,"2026-06-20T21:39:47",5,"// ты это ему говоришь?)",64920,null],[64922,"2026-06-20T21:39:56",32,"//Чтобы прямо разлить можно было на пол и поджечь",64123,null],[64924,"2026-06-20T21:40:11",9,"*Леда отдыхает, ест пока остальные соберутся.*\n\n//-1 рацион за раз, он крупный",64123,null],[64925,"2026-06-20T21:40:35",5,"// немного взаимодействуй с торговцем",64123,null],[64926,"2026-06-20T21:41:26",32,"-Здравствуйте вы торговец, какие товары у вас есть?\nИ можно ли купить у вас горючее масло?",64123,null],[64927,"2026-06-20T21:41:42",32,"//ты сам меня сбил вопросом//",64925,null],[64928,"2026-06-20T21:42:41",5,"Травник оборачивается и немного испуганно смотрит на жука.\n\n— Масло, да, есть маслице.\n\nОн достаёт небольшие бутылочки.\n\n— Вот, 6 штук. Отдам за 5 серебряных\n\nТы замечаешь, что у него на поясе висит какое-то интересное зелье.",64123,null],[64929,"2026-06-20T21:42:47",40,"В очереди за жуком стоит Хорхе",64123,null],[64930,"2026-06-20T21:42:54",5,"// можешь говорить",64929,null],[64931,"2026-06-20T21:43:02",40,"Бубнит надоедливую песню",64123,null],[64932,"2026-06-20T21:43:13",40,"Чтобы заебать жука",64123,null],[64933,"2026-06-20T21:43:47",32,"-Это все? Для моей задумки нужно больше. Где ещё можно купить такое?",64928,null],[64934,"2026-06-20T21:44:33",40,"И потом говорит:\n-драсть, а уксус винный имеется?\n\n/сразу хочу подушнить, винный уксус получается когда испортилось вино в бочке. То есть по сути это товар на выброс. Он не должен дорого стоить. Но при этом уксус по сути кислота и при попадании на слизистую может нанести ожог",64123,null],[64935,"2026-06-20T21:44:34",5,"— Не в нашей деревне. Хочешь много — делай заказ. Подсуечусь, к завтрашнему дню найду тебе масла. Но деньги вперёд",64933,null],[64936,"2026-06-20T21:44:41",32,"//Жук абсолютно спокоен ибо и не с такими работал у него Стажоры! были",64932,null],[64937,"2026-06-20T21:45:10",5,"— Уксус? Есть немного\n\nДостаёт 2 бутылочки\n\n— 4 медных монеты",64934,null],[64938,"2026-06-20T21:45:55",32,"-Хорошо (выкладывает на прилавок 4 золотых) вот предзаказ",64935,null],[64939,"2026-06-20T21:46:00",40,"-и крепкий алкоголь, самогонка или чего есть. Главное чтоб градусов побольше",64123,null],[64940,"2026-06-20T21:46:13",32,"-и заберу что есть сейчас",64928,null],[64941,"2026-06-20T21:46:15",47,"0/0",64938,null],[64942,"2026-06-20T21:46:24",47,"/по деньгам почитай ещё",64123,null],[64943,"2026-06-20T21:46:27",5,"Быстро забирает, в глазах жадность.\n\n— Договорились. Эти брать будешь?",64938,null],[64944,"2026-06-20T21:46:57",5,"// +6 фляг, -4 зм",64940,null],[64945,"2026-06-20T21:47:42",5,"Достаёт бутылку и бурчит\n\n— Вот, травяная настойка. Суммарно 1 серебряный",64939,null],[64946,"2026-06-20T21:47:59",40,"/горючая верно?",64123,null],[64947,"2026-06-20T21:47:59",32,"(проницательность с приимуществом. Какой шанс что он просто сбежит с деньгами?)",64943,null],[64948,"2026-06-20T21:48:19",32,"Добудь на 6 золотых две после сделки",64943,null],[64949,"2026-06-20T21:48:27",5,"// сомнительно, но пахнет интересно. Возможен скрытый эффект если выпить",64946,null],[64950,"2026-06-20T21:48:39",5,"// кидай",64947,null],[64951,"2026-06-20T21:48:50",32,"-я могу проверить у меня есть медицина",64949,null],[64952,"2026-06-20T21:49:07",5,"// без преимущества, твоя черта не так работает",64123,null],[64953,"2026-06-20T21:49:37",40,"*даю одно золото*\n-доброго дня",64123,null],[64954,"2026-06-20T21:49:44",5,"// можешь тоже кинуть",64951,null],[64955,"2026-06-20T21:49:57",32,"Проницательность с преимуществом а медецина нет",64952,null],[64956,"2026-06-20T21:50:03",32,"Вся",64123,null],[64957,"2026-06-20T21:50:07",5,"Смотрит на тебя\n\n—Договорились. Всё будет. Приходи завтра",64948,null],[64959,"2026-06-20T21:50:30",5,"// черта какая?",64955,null],[64960,"2026-06-20T21:51:04",5,"// откуда преимущество",64123,null],[64961,"2026-06-20T21:51:23",32,"Бдительный восприятие и проницательность с приимуществом",64959,null],[64962,"2026-06-20T21:51:46",32,"Или я путаю что-то?",64123,null],[64963,"2026-06-20T21:51:49",5,"// нет",64961,null],[64964,"2026-06-20T21:52:21",32,"Значит без приимуществ а приимущества от внимательный",64963,null],[64965,"2026-06-20T21:52:36",5,"// кидай что говорил",64964,null],[64966,"2026-06-20T21:52:39",32,"Прости что дурнул",64964,null],[64967,"2026-06-20T21:52:56",32,"/roll@roll_bot",64123,null],[64969,"2026-06-20T21:53:09",32,"14+4 проницательность",64968,null],[64970,"2026-06-20T21:53:41",5,"Может и жадный, но честный торговец. Привезёт как сказано",64969,null],[64971,"2026-06-20T21:54:35",32,"(Потом посмотрю понюхать (усиками) травяной настой осмотреть цвет и есть ли там листочки или ещё что)",64954,null],[64972,"2026-06-20T21:54:48",32,"/roll@roll_bot",64123,null],[64974,"2026-06-20T21:55:01",32,"17+4 медецина",64123,null],[64975,"2026-06-20T21:55:09",40,"-э!",64123,null],[64976,"2026-06-20T21:55:18",47,"Я пока в ахуе",64123,null],[64977,"2026-06-20T21:55:21",40,"Возмутился Хорхе",64123,null],[64978,"2026-06-20T21:55:30",47,"За 6-8 золотых купил то, чем можно подорвать отряд",64123,null],[64979,"2026-06-20T21:55:47",5,"Настойка очень хорошая. Кроме опьянения, может хорошо укрепить организм. На время.",64971,null],[64980,"2026-06-20T21:56:07",32,"Зелье героизма?",64123,null],[64981,"2026-06-20T21:56:10",5,"// не купил, заказал)",64978,null],[64982,"2026-06-20T21:56:32",32,"//если подождем до завтра купил",64981,null],[64983,"2026-06-20T21:56:34",5,"Нет. Это настойка. Опьяняющая. Но качественная",64980,null],[64984,"2026-06-20T21:57:13",5,"// ещё что-то с торговцем? Или другие действия?",64123,null],[64985,"2026-06-20T21:57:31",32,"-не магическая бурда. Пьянит и вызывает прилив сил временно. Укрепит тело",64983,null],[64986,"2026-06-20T21:57:51",11,"// смотрю на вас и реал сама с вами поиграть хочу..",64123,null],[64987,"2026-06-20T21:58:23",32,"(я спокойно распрощался и просил перед тем как уходить) -а где можно переночевать и дождаться заказ?",64984,null],[64988,"2026-06-20T21:58:40",32,"//я не против)",64986,null],[64989,"2026-06-20T21:58:44",9,"//Мы до скольки играем? Если чо, просто мы так и не выйдем из деревни)))",64984,null],[64990,"2026-06-20T21:59:14",5,"Травник недоволен и ворчит\n\n— Где переночевать? Я травы продаю, не комнату на ночь.",64987,null],[64991,"2026-06-20T21:59:20",32,"//я могу хоть ещё 3 часа//",64989,null],[64992,"2026-06-20T21:59:33",5,"// я играю пока есть игроки)",64989,null],[64993,"2026-06-20T21:59:51",40,"-на каких лугах трава помягче?",64990,null],[64994,"2026-06-20T21:59:59",40,"-там и переночует",64123,null],[64995,"2026-06-20T22:00:28",5,"— Нету здесь лугов никаких. Один лес. Идите ищите, может поляну найдёте.",64993,null],[64996,"2026-06-20T22:00:38",32,"(посмотрел на свой кошелёк посмотрел на деда и решил) я составлю тебе компанию вместе теплее",64994,null],[64997,"2026-06-20T22:00:53",5,"Травник что-то вспоминает.\n\n— Если набредёте в лесу на заросли малины, набирайте и несите ко мне. Заплачу",64123,null],[64998,"2026-06-20T22:01:29",9,"//Заплачет как актёр! Ещё как, дед не полуэльф?)))",64997,null],[64999,"2026-06-20T22:01:30",32,"-Могу и молодых побегов на отвары нарезать?",64997,null],[65000,"2026-06-20T22:02:11",40,"-из нас двоих теплокровное токмо я. Ты, кстати, видать девственник, раз хочешь спать со мной? Ибо если бы ты с богомолицей близость имел так она бы голову тебе отчикрыжила да сожрала",64996,null],[65001,"2026-06-20T22:02:38",5,"— Давай, сметливый ты малый. Нам такие нужны в деревне — травник даже улыбнулся жуку",64999,null],[65002,"2026-06-20T22:02:53",5,"// м? не выкупил немного",64998,null],[65003,"2026-06-20T22:03:26",40,"-старина, а это... Паф-паф есть? Ну ты понял. Тыры пыры? Ну ты понял?",65001,null],[65004,"2026-06-20T22:03:40",9,"//Это из карнавала. Там полуэльф всегда говорил \"я даже заплачу\" вот и плакал в награду)",64123,null],[65005,"2026-06-20T22:03:42",40,"-я б взял. Молодость вспомнить",64123,null],[65006,"2026-06-20T22:03:43",32,"(просто промолчал решив не посвящать деда в свою личную жизнь)",65000,null],[65007,"2026-06-20T22:04:19",5,"// я не понял, наркотики?",65003,null],[65008,"2026-06-20T22:04:27",40,"//Мария Иванова",64123,null],[65009,"2026-06-20T22:04:38",40,"//да",64123,null],[65010,"2026-06-20T22:05:14",11,"// киньте это в эпичное кто-то боже",65000,null],[65011,"2026-06-20T22:05:19",5,"Травник внимательно смотрит на тебя и медлит с ответом.",65003,null],[65012,"2026-06-20T22:05:23",32,"(кивнул травнику и прикинул направление куда в лес мы будем идти спать)",65001,null],[65013,"2026-06-20T22:05:32",5,"// кинб убеждение  или проницательность",65005,null],[65014,"2026-06-20T22:05:41",40,"-я могу позже подойти, чтоб не при людях",65011,null],[65015,"2026-06-20T22:05:51",5,"// с преимуществом",65014,null],[65016,"2026-06-20T22:05:53",40,"/ща, убежд",64123,null],[65017,"2026-06-20T22:06:27",40,"/r d20+4+2",64123,null],[65019,"2026-06-20T22:06:30",32,"(пихнул слабой рученкой с сила -1 в бок вояку за \"не при людях\"",65014,null],[65020,"2026-06-20T22:06:59",40,"-иди очко свое потрогайте, жужжалик",65019,null],[65021,"2026-06-20T22:07:17",5,"— Есть кое-что. Даже сейчас отдам. Увидишь больше, чем следует. 1 золотой",65018,null],[65022,"2026-06-20T22:07:31",47,"/в ахуе",64123,null],[65023,"2026-06-20T22:07:33",40,"-ХА-ХА-ХА, СЮДА!!!",64123,null],[65024,"2026-06-20T22:07:36",47,"/хуйня",64123,null],[65025,"2026-06-20T22:07:39",40,"Даю золотой",64123,null],[65026,"2026-06-20T22:08:07",32,"-Я вообще-то могу и волной грома тебя пихнуть.\n(Обижено проговорил жук)",65020,null],[65027,"2026-06-20T22:08:10",5,"Травник передаёт тебе 2 стебля интересной травки. Её можно выкурить",65025,null],[65028,"2026-06-20T22:08:26",40,"-я помолюсь за твое здоровье",64123,null],[65029,"2026-06-20T22:08:40",40,"-шучу, не злись",65026,null],[65030,"2026-06-20T22:08:42",47,"/в принципе... Мой персонаж может и перестрелять этих низших существ",64123,null],[65031,"2026-06-20T22:08:50",5,"Он кивает и уходит в дом. Похоже, ему хватило странных покупателей",65028,null],[65032,"2026-06-20T22:09:08",47,"/если бойня начнётся",64123,null],[65033,"2026-06-20T22:09:09",40,"Спрятал хапку петрушки в внутренний карман где самое ценное",64123,null],[65034,"2026-06-20T22:09:27",32,"- не злюсь просто говорю что могу тебе и без болотника устроить радужные брызги и полеты в небесах",65029,null],[65035,"2026-06-20T22:09:31",9,"*Леда в это время опирается на дерево при выходе из деревни, ждёт остальных.*",64123,null],[65036,"2026-06-20T22:10:03",47,"- Просьба успокоиться. Мы хоть и недолго, но должны держаться вместе. Неужели вы хотите ударить того, кто в бою будет прикрывать вам спину?",64123,null],[65037,"2026-06-20T22:10:12",32,"(иду первый догоняя Леду",65035,null],[65038,"2026-06-20T22:10:17",40,"-угомонись, мы ж команда",65034,null],[65039,"2026-06-20T22:10:34",40,"-я всегда сотоварищу спину прикрою",64123,null],[65040,"2026-06-20T22:10:39",32,"-Да я не злюсь все спокойно.",65038,null],[65041,"2026-06-20T22:11:02",32,"-Просто не одобряю покупки и предлагаю альтернативы",64123,null],[65042,"2026-06-20T22:11:18",32,"(скорее весело чем злобно выдал жук)",64123,null],[65043,"2026-06-20T22:11:21",9,"*Видит, что вы гаконец показались в поле его зрения.*\n\n— Пора.",64123,null],[65044,"2026-06-20T22:11:25",5,"Великан провёл время, созерцая величественный сосновый лес. Казалось, тот звал голиафа к себе. Он уже чувствовал себя как дома, среди сосен.",65035,null],[65045,"2026-06-20T22:11:32",40,"-доживешь до моих лет, все сам поймёшь",65041,null],[65046,"2026-06-20T22:11:46",32,"-Не доживу",65045,null],[65047,"2026-06-20T22:11:53",40,"-а чего так...",64123,null],[65048,"2026-06-20T22:11:54",47,"Талон подходит к Леде. В его движениях заметно, что они стали более резкими и механичными",64123,null],[65049,"2026-06-20T22:12:01",32,"-Мы в тридцать умираем от старости",64123,null],[65050,"2026-06-20T22:12:04",40,"*идёт*",64123,null],[65051,"2026-06-20T22:12:19",40,"-бля... Дай бог тебе здоровья тогда",65049,null],[65052,"2026-06-20T22:12:36",32,"-Мне шестнадцать лет кстати",64123,null],[65053,"2026-06-20T22:12:43",9,"*Ветер качает нерасчёсанные волосы ниспадающие на плечи. Блеск золотистых глаз, запах старых елей, поёт соловей.*",65044,null],[65054,"2026-06-20T22:13:16",5,"И волки. Где-то очень далеко, едва слышно. Но это вой волков. Ты не ошибаешься",65053,null],[65055,"2026-06-20T22:13:23",40,"-несовершеннолетний... Надо Алексию сказать что он детей на убой отправляет. Бессовестный",64123,null],[65056,"2026-06-20T22:13:40",9,"— Тревогу вижу. Случилось что?",65048,null],[65057,"2026-06-20T22:14:00",32,"-Спасибо. А расскажи о вашей местной религии?",65051,null],[65058,"2026-06-20T22:14:03",32,"(жук шел спокойно но проявил интерес местами для сближения команды местами просто потому что до этого от этом боге он не слышал)",64123,null],[65059,"2026-06-20T22:14:05",40,"-две симпатичные бабки говорили про Волков!",64123,null],[65060,"2026-06-20T22:14:14",40,"-внимательнее господа",64123,null],[65061,"2026-06-20T22:14:34",47,"Тал слегка притормаживает в движениях. И отвечает:\n- Мне не нравится излишняя эмоциональность наших союзников",64123,null],[65062,"2026-06-20T22:15:02",32,"-Я взлослый охотник у меня перед инженерным образованием в клане дети были(обиделся)",65055,null],[65063,"2026-06-20T22:15:08",9,"— Волки не далеко. Слышал их вой.",64123,null],[65064,"2026-06-20T22:15:36",9,"— Живым не запретить жить, это суть.",65061,null],[65065,"2026-06-20T22:16:32",40,"-аскелатор - бог что заменил людям солнце на небе. Но я старый, ещё помню тех богов что были до катоклизма. Ильматер - бог слез, милосердия, бог обездоленных, страждущих, нуждающихся. \n\nХорхе улыбнулся:\n-однако он не слабый, ежели кто по злому обходится с беззащитным и безоружным то ярость этого бога не сравниться по опасности ни с чем что вам может быть ведомомо",65057,null],[65066,"2026-06-20T22:16:32",32,"(высматриваю округу мгновенно собрался усики щупают воздух голова немного поворачивается из стороны в сторону чтобы охватить больше пространства а в руках отложенным действием горит сгусток магии мистического заряда который будет выпущен в первого увиденного)",65059,null],[65067,"2026-06-20T22:16:44",5,"// такс, вы идёте в лес? Определите, кто как идёт. Скрытно, обычно или быстро",64123,null],[65068,"2026-06-20T22:16:46",47,"Иду на готове, готовый стрелять, если будет опасность",65063,null],[65069,"2026-06-20T22:16:47",9,"*Леда выглядит грустным и меланхоличным в этот день.*",64123,null],[65070,"2026-06-20T22:16:55",47,"Скрытно",65067,null],[65071,"2026-06-20T22:17:08",47,"/r d20+6 скрытность",64123,null],[65073,"2026-06-20T22:17:32",40,"Хорхе с щитом в руке, обычно. Внимательно изучает лес чтобы заранее опередить опасность",64123,null],[65074,"2026-06-20T22:18:11",9,"*Леда шёл взяв пока лишь в руки свой старый жезл.*",64123,null],[65075,"2026-06-20T22:18:19",5,"Через лес вас ведёт небольшая тропинка. Деревья вокруг стоят густой стеной, полян не видно.",64123,null],[65076,"2026-06-20T22:18:29",32,"(я один иду с обычной скоростью только держу посох и  жест активатор заклинания но так совершенно невозмутим)",64123,null],[65077,"2026-06-20T22:18:42",5,"/r d6 что в лесу",64123,null],[65079,"2026-06-20T22:19:24",32,"//Что в лесу \"что-то\"",65077,null],[65080,"2026-06-20T22:20:15",5,"Отряд идёт по тропинке, эльф крадётся сзади всех. Вы слышите вой волков. Уже ближе. Гораздо ближе.",64123,null],[65081,"2026-06-20T22:20:50",5,"// у вас есть время предпринять что-то",64123,null],[65082,"2026-06-20T22:20:52",40,"-в круг спина к спине?",64123,null],[65083,"2026-06-20T22:21:08",40,"-слабые в центр круга",64123,null],[65084,"2026-06-20T22:21:15",47,"Эльф на готове. Он спокоен. Тетива надета на лук. Стрела на тетиве. Выстрел будет мгновенным /",64123,null],[65085,"2026-06-20T22:21:28",47,"Он в кустах /",64123,null],[65086,"2026-06-20T22:21:40",9,"*Леда лишь поднял жезл готовый призвать осколки той самой тьмы.*",64123,null],[65087,"2026-06-20T22:22:06",32,"(без вопросов захожу в центр круга осматриваясь)",65082,null],[65088,"2026-06-20T22:22:25",40,"-ясно... - дед встал спиной к широко ствольному дереву чтобы его сзади нельзя было атаковать",64123,null],[65089,"2026-06-20T22:22:33",32,"//Откуда предположительно будет нападение?",64123,null],[65090,"2026-06-20T22:23:04",5,"// природа",65089,null],[65091,"2026-06-20T22:23:08",32,"(располагаюсь рядом с дедом с левого плеча)",65088,null],[65092,"2026-06-20T22:23:13",32,"/roll@roll_bot",65090,null],[65094,"2026-06-20T22:23:19",40,"/никто в круг и не встал. Давай на дерево залезь, я помогу подсадкой, бонус на ловкость будет? @elsio28",65087,null],[65095,"2026-06-20T22:23:19",32,"23",65093,null],[65097,"2026-06-20T22:23:43",5,"// можешь лезть. Кто лезет кидает акробатику сл 15",65094,null],[65098,"2026-06-20T22:24:13",40,"/я хочу жуку помочь, подсадить чтобы его волки не драли",65097,null],[65099,"2026-06-20T22:24:16",47,"Я б залез/",65097,null],[65100,"2026-06-20T22:24:20",40,"/а он с дерева атакует",64123,null],[65101,"2026-06-20T22:24:22",32,"-Я лёгкий и сам залезу",65094,null],[65102,"2026-06-20T22:24:22",32,"/roll@roll_bot",64123,null],[65103,"2026-06-20T22:24:22",32,"Акробатика+2 ловкости",64123,null],[65105,"2026-06-20T22:24:27",40,"/тоже го",65099,null],[65106,"2026-06-20T22:24:40",47,"Заготовка с атаки не сольётся?",65105,null],[65107,"2026-06-20T22:24:40",40,"/я могу чё то на помощь кинуть им?",64123,null],[65108,"2026-06-20T22:24:40",9,"//Я не против в круг, но вы не встали, леда просто стоит посреди дороги",65094,null],[65109,"2026-06-20T22:24:50",40,"/хз",65106,null],[65110,"2026-06-20T22:25:35",40,"-залезайте кто захочет, подсажу короче... - сказал хорхе",64123,null],[65111,"2026-06-20T22:25:46",5,"Ты вспоминаешь тактику волков. Они нападают стаей, но необязательно с одной стороны.\n\nТакже ты вспоминаешь, что волки полагаются на нюх. Спрятаться от них нелегко, одинокий вони может стать лёгкой добычей.\n\nВолки — не самые смелые создания. Почуяв силу жертвы, они могут сбежать. И они точно не будут сражаться до смерти.",65093,null],[65112,"2026-06-20T22:25:46",32,"Блин первым делом хилый три-крин возьмёт силы",64123,null],[65114,"2026-06-20T22:26:32",32,"(Я отбросил идею с залезанием буду снизу",65110,null],[65115,"2026-06-20T22:26:38",5,"// помощь тебе дали",65104,null],[65116,"2026-06-20T22:26:44",40,"/давай может преимущество за мою помощь?",65103,null],[65117,"2026-06-20T22:26:54",5,"// все могут лезть с преимуществом",64123,null],[65118,"2026-06-20T22:27:06",32,"/roll@roll_bot",65116,null],[65120,"2026-06-20T22:27:35",40,"-БЛЯТЬ, ТЫ ЖУК ИЛИ КТО?! ПОЧЕМУ НЕ УМЕЕШЬ ЛАЗАТЬ СУКА",64123,null],[65121,"2026-06-20T22:27:37",32,"12 акробатики должно хватать чтобы не очень красиво на забраться на ветви",65119,null],[65122,"2026-06-20T22:27:41",9,"*Маленький гигант стоит готовый действовать, просто невозмутимо ждёт.*",64123,null],[65123,"2026-06-20T22:28:14",5,"Опираясь на бывалого деда, богомол полез вверх по стволу. Однако его лапки были слишком слабы. Он пролез немного, а затем сорвался и кубарем полетел на землю.",65119,null],[65124,"2026-06-20T22:28:19",5,"// сразу написал, сл 15",65121,null],[65125,"2026-06-20T22:28:21",32,"-Я лазал в канализации а не по деревьям! И вообще мы из пусшинь у нас нет деревьев почти!",65120,null],[65126,"2026-06-20T22:28:36",32,"//Не видел пардон",65124,null],[65127,"2026-06-20T22:28:59",5,"// получи д4 урона. Ты лежишь под деревом и ничего не можешь сделать до нападения",65121,null],[65128,"2026-06-20T22:29:11",32,"//Главное чтобы не урон от падения...",65123,null],[65129,"2026-06-20T22:29:24",32,"//Кинь урон пж",65127,null],[65130,"2026-06-20T22:29:32",5,"/r d4",65129,null],[65132,"2026-06-20T22:29:43",9,"*Ветер гоняет волосы, он слег улыбнулся слыша как товарищи препираются и пытаются что-то сделать.*\n\n— Иди сюда волшебник, ты.",65122,null],[65133,"2026-06-20T22:29:45",32,"У меня осталось 2 хп",65131,null],[65134,"2026-06-20T22:30:05",40,"-сука... \n\nХорхе стоит так чтобы волки не могли мимо него пойти к жуку \n\n(Можно что волки спровоцированку ловят, типо мимо меня бегут если хотят кусать жука?)",64123,null],[65135,"2026-06-20T22:30:18",32,"(знал что это плохая идея",65114,null],[65136,"2026-06-20T22:30:23",5,"// окей, Леда на тропе, Хорхе и жук около дерева. Эльф в кустах. Больше нет заявок?",64123,null],[65137,"2026-06-20T22:30:35",5,"// можно",65134,null],[65138,"2026-06-20T22:30:38",9,"//.",65132,null],[65139,"2026-06-20T22:30:47",40,"-зелье здоровья у меня в рюкзаке на спине. Когда встанешь - возьми выпей",65135,null],[65140,"2026-06-20T22:30:49",9,"//Зову трикрина",64123,null],[65141,"2026-06-20T22:30:56",5,"// можешь его тащить, он лежит",65140,null],[65143,"2026-06-20T22:31:29",32,"-Я вас слышу но у меня спина так болит что я встать не могу!",65140,null],[65144,"2026-06-20T22:31:43",40,"-я прикрою",64123,null],[65145,"2026-06-20T22:31:45",40,"/все наверно",64123,null],[65146,"2026-06-20T22:31:58",40,"/а блять я мастер щита же",64123,null],[65147,"2026-06-20T22:32:06",40,"/я чё то такое умею",64123,null],[65148,"2026-06-20T22:32:16",32,"/да план боя пошел по звизде а хотел с смазки начать а не с урона",65145,null],[65149,"2026-06-20T22:32:18",5,"// ок, жук между вами двумя лежит",64123,null],[65150,"2026-06-20T22:32:33",5,"// @cirson кидай скрытность",64123,null],[65151,"2026-06-20T22:32:35",9,"//Короче, я бы щас обезопасил нашего волшебника, но ко мне не подошли 🫠",64123,null],[65152,"2026-06-20T22:32:48",5,"// все кидают инициативу",64123,null],[65153,"2026-06-20T22:33:00",32,"/roll@roll_bot",64123,null],[65155,"2026-06-20T22:33:04",9,"//Вот, поздно",64123,null],[65156,"2026-06-20T22:33:11",32,"7+7=14",64123,null],[65157,"2026-06-20T22:33:52",9,"/roll 1d20-1 иня и заготовленные волшебные стрелы ток пусть подойдут на 120 футов",64123,null],[65159,"2026-06-20T22:34:17",9,"// 8",65158,null],[65160,"2026-06-20T22:34:34",9,"//Забыл что цыфры писать нельзя",64123,null],[65161,"2026-06-20T22:34:39",40,"/roll@roll_bot",64123,null],[65163,"2026-06-20T22:34:46",40,"(блять ну и дела)",64123,null],[65165,"2026-06-20T22:35:22",5,"// так, щас приготовлю карту и список",64123,null],[65166,"2026-06-20T22:35:29",5,"// и где @cirson",64123,null],[65167,"2026-06-20T22:36:10",32,"//Он писал что отошёл но так и не вернулся",65166,null],[65168,"2026-06-20T22:36:45",47,"Уже, там 20/",65150,null],[65169,"2026-06-20T22:37:02",5,"// иню",65168,null],[65170,"2026-06-20T22:37:14",47,"/r d20+4 инь",64123,null],[65172,"2026-06-20T22:37:24",47,"И видимо Янь/",64123,null],[65173,"2026-06-20T22:37:33",47,"/но реакцией смогу стрельнуть из кустов",64123,null],[65175,"2026-06-20T22:38:11",9,"//Чтош, спасу трикрина, там проще простого",64123,null],[65176,"2026-06-20T22:38:21",9,"//Что там с эй там?",64123,null],[65177,"2026-06-20T22:38:45",5,"// лежит за тобой. 2 хп или типа того",65176,null],[65178,"2026-06-20T22:39:02",32,"Два",65177,null],[65179,"2026-06-20T22:39:32",9,"//Окечи, жить будет, ели волки не умеют прыгать или чет такое. Я тут подумал",64123,null],[65180,"2026-06-20T22:39:36",32,"Но если повезёт хожу первым если не ходят первыми волки)",64123,null],[65181,"2026-06-20T22:39:48",9,"/roll 1d12 к инициативе вдохнову",64123,null],[65183,"2026-06-20T22:39:56",9,"//Иня 18",64123,null],[65184,"2026-06-20T22:40:26",32,"//Тогда вторым)",65183,null],[65185,"2026-06-20T22:40:59",5,"/r 6d20",64123,null],[65187,"2026-06-20T22:43:42",32,"//? Почему 6",65185,null],[65188,"2026-06-20T22:43:56",5,"// не совсем правильно кинул",65187,null],[65189,"2026-06-20T22:44:00",5,"Волки появились с двух сторон, но вы были готовы. Слева тяжело прыгал огромный волк, за ними ещё 2 зверя поменьше. Справой стороны прямо на бывалого ветерана бегут 3 волка.",64123,null],[65190,"2026-06-20T22:44:06",5,"Инициатива, лесная тропа\n\nЛеда 18\nБольшой волк 18\nБогомол 14\nСтая слева 10\nЭльф 6\nСтая справа 3\nЮнус 1",64123,null],[65192,"2026-06-20T22:44:13",9,"*Леда проводит рукой в воздухе, перед ним появляется непрозрачное зеркало словно из самой тьмы. Лишь коснувшись к еему, то с хрустом стеклы как разбитое зеркало разлетается на осколки что летят в ближайшего волка точно раня его и исчезая в чёрной дымке.*",64123,null],[65193,"2026-06-20T22:44:30",9,"/roll 1d4+1 по волку три раза заготовленным волшебная стрела",64123,null],[65196,"2026-06-20T22:45:08",5,"// по какому?",65194,null],[65197,"2026-06-20T22:45:29",9,"//По тому кто первый вошёл в поле зрение",64123,null],[65198,"2026-06-20T22:45:48",9,"//Мой ход?)",64123,null],[65199,"2026-06-20T22:46:49",9,"*Леда подходит к жуку и сажает его себе на шею. Гигант высок, целых 2,5 метра, мага не достанут просто так.*\n\n— Держись покрепче.\n\n//Ход",64123,null],[65200,"2026-06-20T22:47:04",47,"А",64123,null],[65201,"2026-06-20T22:47:07",5,"Магические стрелы влетают прямо в морду огромного волка, бегущего впереди остальных. С клыков текут слюни, глаза горят. Это не только не остановило его, но лишь разозлило. Волк бежит ещё быстрее, прямо на гиганта",65192,null],[65202,"2026-06-20T22:47:17",47,"Заготовленным действием из скрыта в большого волка",64123,null],[65203,"2026-06-20T22:47:25",9,"//Так, мага засейвил, если это не волки попрыгунчики",64123,null],[65204,"2026-06-20T22:47:30",47,"/r +d20+8",64123,null],[65206,"2026-06-20T22:47:44",5,"// урон",65205,null],[65207,"2026-06-20T22:47:51",47,"/r d20+8 переброс 10",64123,null],[65209,"2026-06-20T22:47:58",47,"/оой",64123,null],[65210,"2026-06-20T22:48:06",47,"/r d8+4",64123,null],[65212,"2026-06-20T22:48:32",5,"Стрела вонзилась в шкуру волка, он дёрнулся от боли",65202,null],[65213,"2026-06-20T22:48:35",47,"Стрела врезается точно в грудь большому волку. Он может видеть эльфа что находится на полусогнутых ногах",64123,null],[65214,"2026-06-20T22:48:39",5,"/// ход?",65203,null],[65215,"2026-06-20T22:49:00",9,"//А чё, это действие потратило, ход",65214,null],[65216,"2026-06-20T22:49:24",5,"/r +5",64123,null],[65218,"2026-06-20T22:49:45",5,"/r 2d6+3",64123,null],[65220,"2026-06-20T22:49:55",9,"//Кому это",64123,null],[65221,"2026-06-20T22:50:03",32,"Тебе похоже",65220,null],[65222,"2026-06-20T22:50:03",5,"// 11 урона по Леде, спасбросок Силы сл 13",65219,null],[65223,"2026-06-20T22:50:28",9,"/roll 1d12+3 выносливость камня меньше урона",64123,null],[65225,"2026-06-20T22:50:47",9,"/roll 1d20+2 спас силы",64123,null],[65227,"2026-06-20T22:50:54",32,"(а где сейчас остальные волки относительно вожака?",65222,null],[65228,"2026-06-20T22:51:14",5,"// отстали, как на начальной карте. Вожак у Леды",65227,null],[65229,"2026-06-20T22:51:21",32,"Какое расстояние в футах?",65227,null],[65230,"2026-06-20T22:52:01",5,"Вожак с разгону бросается на Леду, клыки входят в его ногу (или что там под юбкой). Волк дёргает пастью, пытаясь сбить того с ного, но гигант стоит крепко",64123,null],[65231,"2026-06-20T22:52:17",5,"30 футов//",65229,null],[65232,"2026-06-20T22:52:20",9,"//Трикрин у меня на плечах, кста",65199,null],[65233,"2026-06-20T22:52:34",5,"// ход жука",64123,null],[65234,"2026-06-20T22:54:19",32,"И прямо с плеч я и кидаю ответов в волка.\nХаотический заряд. Кидай 2 к8 урона (одну из восьмерик по таблице выберу на определенные урона и ещё  к8 если совпадет с одним из прошлых уронов атака перескочит на цель в 30 футах",65231,null],[65235,"2026-06-20T22:55:10",47,"/так ты кидаешь сначала атаку. Потом урон",65234,null],[65236,"2026-06-20T22:55:15",5,"// При попадании цель получает 2к8 + 1к6 урона.",64123,null],[65237,"2026-06-20T22:55:26",32,"/roll@roll_bot",64123,null],[65239,"2026-06-20T22:55:30",47,"/кинь д20+стат +2, а потом 2д8+1д6",64123,null],[65240,"2026-06-20T22:55:35",47,"/не везёт",64123,null],[65241,"2026-06-20T22:56:04",32,"//Знал что надо использовать знамение 15 с советами под руку магу лезете",64123,null],[65242,"2026-06-20T22:56:53",5,"// ход?",64123,null],[65243,"2026-06-20T22:57:07",47,"/а, так ты не озвучил. Сори/",65241,null],[65244,"2026-06-20T22:57:15",47,"/мастер может дать преимущество за высоту",64123,null],[65245,"2026-06-20T22:57:23",5,"// маловато",65244,null],[65246,"2026-06-20T22:57:42",40,"Hard /\"маловато\"",64123,null],[65247,"2026-06-20T22:57:52",32,"За неподвижность я нахожусь ровно притирку над по дерущему ногу гиганту волком",65245,null],[65248,"2026-06-20T22:57:55",40,"/в твой огород камень",64123,null],[65249,"2026-06-20T22:58:05",9,"//Чё там",64123,null],[65250,"2026-06-20T22:58:16",5,"// ты на плечах гиганта. Можешь стрелять без помех",65247,null],[65251,"2026-06-20T22:58:29",40,"/последние 5-6 сообщений чек",65249,null],[65252,"2026-06-20T22:58:29",5,"// ещё действия?",64123,null],[65253,"2026-06-20T22:58:34",5,"Три-крин барахтается на плечах голиафа и пускает магический снаряд. Тот летит совсем не туда и лишь чудом не отрывает ухо Леды.",64123,null],[65254,"2026-06-20T22:59:01",9,"//Шде что, я не понимаю",65251,null],[65255,"2026-06-20T22:59:15",5,"// не будет преимущества за высоту",64123,null],[65256,"2026-06-20T22:59:45",40,"/жук на плечах твоих. Попросил бонус высоты. ДМ говорит ему \"маловато\". Ну я тебе адресую, мол твой рост обоссали что ты маловат)",65254,null],[65257,"2026-06-20T23:00:06",32,"//непроверенная магия ведёт себя говняно а мог бы громовой волной шибануть//",64123,null],[65258,"2026-06-20T23:00:29",5,"// пиши ход если всё сделал",65257,null],[65260,"2026-06-20T23:01:43",32,"//ход",65258,null],[65261,"2026-06-20T23:02:05",32,"//(сначала пришла мысля но не ну нафиг)",65258,null],[65262,"2026-06-20T23:02:28",5,"Два волка следует за своим вожаком, они дружно бросаются на голиафа и кусают его",64123,null],[65263,"2026-06-20T23:02:42",5,"/r +d20+4",64123,null],[65266,"2026-06-20T23:02:57",5,"// кд леды?",65264,null],[65267,"2026-06-20T23:03:14",5,"/r 4d4+2",64123,null],[65269,"2026-06-20T23:03:18",9,"//12 моё кд. Некогда было щит брать",64123,null],[65270,"2026-06-20T23:03:26",5,"/r 2d4+2",64123,null],[65272,"2026-06-20T23:03:36",5,"// 19 урона, кидай 2 спаса силы",64123,null],[65273,"2026-06-20T23:03:51",32,"//а я могу реакцией на Леду щит кинуть или только на себя можно?",65269,null],[65274,"2026-06-20T23:04:00",5,"// на себя",65273,null],[65275,"2026-06-20T23:04:41",40,"-пиздец что за дела...",64123,null],[65276,"2026-06-20T23:04:47",5,"Волки окружили голиафа. Они кидаются на него со всех сторон, кусаясь и пытаясь повалить гиганта.",64123,null],[65277,"2026-06-20T23:05:04",5,"// Hard",65272,null],[65278,"2026-06-20T23:05:40",9,"/roll 1d20+2",64123,null],[65281,"2026-06-20T23:06:25",9,"*Леду грызут на части, но он словно скала стоит, не дрогнет, лишь смотрит свысока на волков.*",64123,null],[65282,"2026-06-20T23:06:37",11,"// не бойся действовать, мне кажется что за хорошие идеи мастер только наградит",65261,null],[65283,"2026-06-20T23:06:45",32,"//интересный факт у меня только на внимательность без преимущества прокнул успех)",64123,null],[65284,"2026-06-20T23:06:52",5,"// ход кустового эльфа",64123,null],[65285,"2026-06-20T23:07:11",5,"// кстати, проверки типа разговоров и анализа можно делать свободным действием",64123,null],[65286,"2026-06-20T23:07:20",32,"//В том то и идея что говно был план и сделать я не мог ничего пока",65282,null],[65287,"2026-06-20T23:07:47",47,"Эльф делает короткую перебежку и прям в прыжке выпускает стрелу в того же вожака.",64123,null],[65288,"2026-06-20T23:07:52",47,"/r +d20+8",64123,null],[65290,"2026-06-20T23:08:02",47,"/r d20+8 эльф точность",64123,null],[65292,"2026-06-20T23:08:04",5,"// куда бежишь?",65287,null],[65293,"2026-06-20T23:08:10",47,"/r 2d8+4",64123,null],[65295,"2026-06-20T23:08:13",11,"// главное красиво напиши)) а там посмотришь что будет",65286,null],[65296,"2026-06-20T23:08:29",47,"Подальше от волков. Кусают больно/",65292,null],[65297,"2026-06-20T23:08:56",5,"// 12 урона",64123,null],[65298,"2026-06-20T23:09:01",47,"Выстрел ложится чётко в грудь вожаку, отталкивая его от Голиафа, и давая тому свободу/",64123,null],[65299,"2026-06-20T23:09:15",5,"// кстати ели по правилам, ты делаешь переброс когда увидел результат первого выстрела",64123,null],[65300,"2026-06-20T23:09:38",47,"/что?",65299,null],[65301,"2026-06-20T23:09:42",5,"/r +3",65298,null],[65303,"2026-06-20T23:10:03",5,"Стрела ударила волка, но тот не двинулся. Он всё также грызёт гиганта",65298,null],[65304,"2026-06-20T23:10:54",5,"// чертой точности ты делаешь переброс урона. Не просто добавляешь кубик",65300,null],[65305,"2026-06-20T23:10:59",5,"// ход?",64123,null],[65306,"2026-06-20T23:11:03",32,"//вы главное вожака до моего хода не убейте я его сам хочу громовой волной убить!",65303,null],[65307,"2026-06-20T23:12:19",47,"Переброс атаки. Я могу перебросить любой из двух кубиков. Прям так и написано. Если 1 и 7,я перебросил 1. Выпало 20. Использую 20.\n Или 1 и 11,переброс, выплат 1 юзаю 11/",65304,null],[65308,"2026-06-20T23:13:05",5,"// ммм окей. Можем потом во флуде поспорить",65307,null],[65309,"2026-06-20T23:13:10",5,"// ?",65305,null],[65310,"2026-06-20T23:14:32",5,"Стая из трёх нетронутых волков прыжками несётся прямо на Хорхе.",64123,null],[65311,"2026-06-20T23:14:42",5,"/r +d20+4",64123,null],[65314,"2026-06-20T23:14:49",40,"-Пшли нахер, дворняги!",64123,null],[65316,"2026-06-20T23:15:20",5,"/r 6d4+6",64123,null],[65318,"2026-06-20T23:15:34",47,"/65 фт между мной и волками. Слава богу/",64123,null],[65319,"2026-06-20T23:15:44",5,"// 20 урона по Хорхе",65314,null],[65320,"2026-06-20T23:15:56",5,"// стоишь?",64123,null],[65321,"2026-06-20T23:16:04",40,"/у меня 20 хп всего",64123,null],[65322,"2026-06-20T23:16:29",40,"Хорхе с порванной сракой падает с истошным воплем",64123,null],[65323,"2026-06-20T23:16:49",5,"Твой ход, спас смерти//",64123,null],[65324,"2026-06-20T23:16:55",32,"//кажется нам потихоньку пизда",64123,null],[65325,"2026-06-20T23:16:58",40,"/чё кидаю?",64123,null],[65326,"2026-06-20T23:17:06",5,"// чистый д20",64123,null],[65327,"2026-06-20T23:17:10",40,"/roll@roll_bot",64123,null],[65329,"2026-06-20T23:17:15",47,"/еба везёт нам",64123,null],[65330,"2026-06-20T23:17:15",40,"/ура блять",64123,null],[65331,"2026-06-20T23:17:32",5,"// спас не провален, ещё 3 и на кладбище",64123,null],[65332,"2026-06-20T23:17:35",47,"Нас 4 да? Против 5 волков и вожака?",64123,null],[65333,"2026-06-20T23:17:36",32,"Я не успел мог я знамения 15 использовать?",64123,null],[65335,"2026-06-20T23:17:43",47,"Да/",65333,null],[65336,"2026-06-20T23:17:44",5,"// можешь",65333,null],[65337,"2026-06-20T23:17:46",5,"// на что?",64123,null],[65338,"2026-06-20T23:17:56",32,"На спас от смерти",65337,null],[65339,"2026-06-20T23:18:01",11,"// пробуй все что можешь",65333,null],[65340,"2026-06-20T23:18:06",5,"// ок, Юнус держится",64123,null],[65341,"2026-06-20T23:18:12",32,"Я просто написать не успел!",65339,null],[65342,"2026-06-20T23:18:59",32,"Хорошо сейчас у нас по новой круг и ход Леды",64123,null],[65343,"2026-06-20T23:19:06",47,"/ебать.я в ахуе. 75 хп. Как это нахуй убиватт",64123,null],[65344,"2026-06-20T23:19:32",40,"/могу чё то сделать или просто стою?",64123,null],[65345,"2026-06-20T23:19:35",32,"Вожак?",65343,null],[65346,"2026-06-20T23:19:39",5,"// лежишь(",65344,null],[65348,"2026-06-20T23:19:41",47,"/да",64123,null],[65349,"2026-06-20T23:19:46",11,"// пиши задним числом главное убедительно😁\nНадеюсь вы не против что я тут подсматриваю, веселые вы и интересно как Эл ведёт:3",65341,null],[65350,"2026-06-20T23:20:07",5,"// если интересно состояние кого-то, осмотрите его свободным действием",64123,null],[65351,"2026-06-20T23:20:13",9,"//Что же, мой ход?",64123,null],[65352,"2026-06-20T23:20:34",32,"//а вы кто кстати?",65349,null],[65354,"2026-06-20T23:22:36",9,"*Леда просто отпускает жезл, медленно набирает полные лёгкие воздуха, и взяв алибарду из за спины со свей своей мощью бьёт по вожаку стаи. Волосы во все стороны, мышцы напрягаются на всём корпусе, даже если он ранен и истекает кровью.*\n\n— ааааааААААААААААААА!!!",64123,null],[65355,"2026-06-20T23:22:40",5,"// моя подруга, смотрит за игрой просто",65352,null],[65356,"2026-06-20T23:22:51",9,"/roll +d20+4 в ярости по вожаку",64123,null],[65358,"2026-06-20T23:23:20",9,"/roll 1d10+2+2+1d6 ярость сила урон и удар великана",64123,null],[65360,"2026-06-20T23:23:32",32,"(три-крин на спине стрекочет и отчаянно весит на шее)\n-Я не хочу вниз! я не хочу вниз!!",65354,null],[65361,"2026-06-20T23:23:35",9,"//Спас силы сложность 13 или вожак упал",64123,null],[65362,"2026-06-20T23:23:50",47,"/кстати, спас силы у тебя +4 если ты варвар/",64123,null],[65363,"2026-06-20T23:24:01",9,"//Я чародей основным",64123,null],[65364,"2026-06-20T23:24:06",47,"/ок",64123,null],[65365,"2026-06-20T23:24:16",40,"*Хорхе видит свет в конце тоннеля. Но с другой стороны его зовёт голос. \n\n-не иди на свет!!!\n\nХорхе обернулся.\nЭто был голос тех двух хапулек петрушки которые ещё не выкурены \n\n-не иди на свет, ты нас ещё не выкурил!*",64123,null],[65366,"2026-06-20T23:24:20",5,"// опиши добивание",65359,null],[65367,"2026-06-20T23:24:45",47,"/так. Это другой вожак значит",64123,null],[65368,"2026-06-20T23:25:12",32,"//А ещё телепатический вой три-крина)",65365,null],[65369,"2026-06-20T23:25:29",40,"//спокойно сдохнуть не даст...",65368,null],[65370,"2026-06-20T23:26:13",9,"*Лезвие опускается ему на спину и ломает хребтину. Вшивый пёс, хоть и перерос, все ещё пёс, неприятно кровавое зрелище.*",65366,null],[65371,"2026-06-20T23:26:35",5,"// ход жука",64123,null],[65372,"2026-06-20T23:27:12",5,"Волки вокруг мёртвого вожака замерли на месте. Возможно, чуткий следопыт мог бы понять, что они сделают дальше.",64123,null],[65373,"2026-06-20T23:27:29",47,"/сбегут.",64123,null],[65374,"2026-06-20T23:27:40",32,"//если я предупрежу Леду о том что использую смазку он получит преимущество на  спасбросок ловкости?",64123,null],[65375,"2026-06-20T23:27:53",9,"//Неа, фигачте чет, у меня хиты кончаются 🫠",64123,null],[65376,"2026-06-20T23:28:11",5,"// мм? спасбросок от масла?",65374,null],[65377,"2026-06-20T23:28:15",9,"//У меня преимущество от варвара",65374,null],[65378,"2026-06-20T23:28:44",47,"/для меня логично",65373,null],[65379,"2026-06-20T23:29:01",47,"/я 30% игр провёл за следопыта",64123,null],[65380,"2026-06-20T23:29:05",5,"// дашь преимущество, если всё логично",64123,null],[65381,"2026-06-20T23:29:19",32,"Ну тогда.\n-Держись! (И кидаю под лапы волков смазку вообще не целя в Леду)",65377,null],[65382,"2026-06-20T23:29:38",5,"// на масле тут не поскальзываются если что",64123,null],[65383,"2026-06-20T23:29:42",5,"только доп урон огнем//",64123,null],[65384,"2026-06-20T23:29:52",32,"Заклинание смазка!",64123,null],[65385,"2026-06-20T23:29:57",5,"// понял",64123,null],[65386,"2026-06-20T23:30:07",32,"Сокольский пол трансмутация",64123,null],[65387,"2026-06-20T23:30:28",5,"// сложность спаса?",64123,null],[65388,"2026-06-20T23:30:31",5,"// Леда кидай",64123,null],[65389,"2026-06-20T23:30:39",32,"В соседний квадрат от нас",65381,null],[65390,"2026-06-20T23:30:48",32,"13 ловкость",65387,null],[65391,"2026-06-20T23:30:51",9,"/roll +d20-1",64123,null],[65393,"2026-06-20T23:30:59",47,"Мне больно/",64123,null],[65394,"2026-06-20T23:31:02",5,"// волки прямо вокруг голиафа, так не получится",65389,null],[65395,"2026-06-20T23:31:10",47,"Два Крита/",64123,null],[65396,"2026-06-20T23:31:12",47,"До слез/",64123,null],[65397,"2026-06-20T23:31:19",32,"Ну сама судьба на нашей стороне",65394,null],[65398,"2026-06-20T23:31:31",5,"/r +2",64123,null],[65401,"2026-06-20T23:31:34",32,"Под ноги гиганта",64123,null],[65402,"2026-06-20T23:31:39",9,"*Леда стоит как скала, его не сдвинет ничто, он врос в землю под своим весом.*",64123,null],[65403,"2026-06-20T23:31:39",40,"//волки с преимуществом бьют?",64123,null],[65404,"2026-06-20T23:31:41",32,"Да сука!",64123,null],[65405,"2026-06-20T23:31:48",5,"// да, можешь описать если хочешь",65401,null],[65406,"2026-06-20T23:32:35",5,"// тактика стаи. Кодга есть другие рядом",65403,null],[65407,"2026-06-20T23:33:50",32,"Три-крин как только Леда нанес удар произнес (прострекотал) формулу и просто швырнул под ноги кусок сала который растекся под ними очень Сокольский едва заметной маслянистой пленкой волки заскользили и упали",65405,null],[65408,"2026-06-20T23:34:32",47,"/смысла только в этом...",64123,null],[65409,"2026-06-20T23:34:39",5,"Волки с воем валяются в магическом жире. Провозившись несколько секунд, они встают и со страхом смотрят на голиафа и богомола на нём.",64123,null],[65410,"2026-06-20T23:34:39",32,"И теперь они ничком и если к нам подбегает другие то то же попадают",64123,null],[65411,"2026-06-20T23:34:47",5,"// ход эльфа",64123,null],[65412,"2026-06-20T23:34:58",47,"Бегом на 35 ближе",64123,null],[65413,"2026-06-20T23:35:06",47,"/r +d20+8 на бегу в прыжке",64123,null],[65415,"2026-06-20T23:35:11",47,"/r d20+8",64123,null],[65417,"2026-06-20T23:35:19",47,"/r 2d8+4",64123,null],[65419,"2026-06-20T23:35:19",5,"// урон",64123,null],[65420,"2026-06-20T23:35:38",5,"// по кому?",65418,null],[65421,"2026-06-20T23:35:45",47,"По стае возле упавшего",64123,null],[65422,"2026-06-20T23:35:45",32,"Они половину своего движения в следующем ходу на то чтобы встать потратят",65409,null],[65423,"2026-06-20T23:36:09",32,"А сейчас они по идее лежат и стрельба по ним с помехой",64123,null],[65424,"2026-06-20T23:36:17",5,"Стрела пронзает шею волка. Он бездыханно падает в лужу жира.",65421,null],[65425,"2026-06-20T23:36:19",47,"/те что возле упавшего, нет/",64123,null],[65426,"2026-06-20T23:36:35",47,"/мастер, разреши хотя бы атаки самостоятельно описывать!",64123,null],[65427,"2026-06-20T23:36:36",32,"Да по тем что возле упавшего нет",65425,null],[65428,"2026-06-20T23:36:43",5,"// конечно описывай)",65426,null],[65429,"2026-06-20T23:36:47",5,"// я только за",64123,null],[65430,"2026-06-20T23:38:27",47,"Разогнавшись эльф вновь делает короткий прыжок выцеливая уязвимые точки у противника. Слегка приоткрытая пасть позволяет стреле пройти насквозь. Кувырок, эльф совсем близко. Он аккуратно бросает лук и достаёт рапиру",64123,null],[65431,"2026-06-20T23:38:49",5,"// ты в 30 футах",65430,null],[65432,"2026-06-20T23:38:53",47,"Да/",65431,null],[65433,"2026-06-20T23:39:03",5,"// убил волка в масле около вожака, верно?",64123,null],[65434,"2026-06-20T23:39:06",47,"/нет",64123,null],[65435,"2026-06-20T23:39:13",47,"/возле ранее упавшего товарища",64123,null],[65436,"2026-06-20T23:40:14",5,"Волки возле Хорхе кажется осознали ситуацию. Они бегут. Но не в лес. А прямо к отбившемуся от группы эльфу.",64123,null],[65437,"2026-06-20T23:40:24",5,"/r +d20+4",64123,null],[65440,"2026-06-20T23:40:32",47,"/мимо и мимо/",64123,null],[65443,"2026-06-20T23:41:29",5,"Эльф остается невредимым, и волки спасаются бегством",64123,null],[65444,"2026-06-20T23:41:37",47,"Провоцирка",64123,null],[65445,"2026-06-20T23:41:44",47,"/r d20+6",64123,null],[65447,"2026-06-20T23:41:49",32,"И от Леды тоже кстати и от меня",64123,null],[65448,"2026-06-20T23:41:53",47,"/r d8+4",64123,null],[65450,"2026-06-20T23:42:09",5,"// вы были далеко Хорхе",65447,null],[65451,"2026-06-20T23:42:17",5,"// хм хотя Леда с алебардойц, может",64123,null],[65452,"2026-06-20T23:42:24",5,"// живой",65449,null],[65453,"2026-06-20T23:42:30",32,"А те что у нас не побегут?",65450,null],[65454,"2026-06-20T23:42:32",40,"*в спутанном сознании хрипит*\n-вот и помер дед Максим... Да и х... Остался с ним...",64123,null],[65456,"2026-06-20T23:43:06",5,"// они пока в масле валялись",65453,null],[65457,"2026-06-20T23:43:11",5,"// кидай спас)",65454,null],[65458,"2026-06-20T23:43:16",40,"/r",64123,null],[65460,"2026-06-20T23:43:24",32,"-Вставай ленивая жопа!",65454,null],[65461,"2026-06-20T23:43:35",40,"/а какая сложность у Спасов жизни?",64123,null],[65462,"2026-06-20T23:43:37",5,"// ход Леды",64123,null],[65463,"2026-06-20T23:43:41",47,"Волки в 10 футах от меня, как понимаю/",64123,null],[65464,"2026-06-20T23:43:49",47,"10/",65461,null],[65465,"2026-06-20T23:43:52",32,"Враги ничком идеальные удары",65462,null],[65467,"2026-06-20T23:44:45",32,"20 за два успеха считается \n а 1 за два провала вроде.",65464,null],[65468,"2026-06-20T23:44:47",5,"// Hard",64123,null],[65469,"2026-06-20T23:44:56",47,"Да/",64123,null],[65470,"2026-06-20T23:45:09",5,"// на 20 сам встанешь)",65467,null],[65471,"2026-06-20T23:45:42",5,"// пока великан думает, ходи богомол",64123,null],[65472,"2026-06-20T23:46:08",9,"/Рядом есть тот кто стоит волк?",64123,null],[65473,"2026-06-20T23:46:22",5,"Два волка валяются в твоих ногах и скулят от страха",64123,null],[65474,"2026-06-20T23:46:28",32,"Я помогаю эльфу мистический заряд пускаю в небитого волка",65471,null],[65475,"2026-06-20T23:46:37",32,"/roll@roll_bot",64123,null],[65477,"2026-06-20T23:46:38",9,"/roll +d20+4 тогда безрассудная",64123,null],[65479,"2026-06-20T23:46:55",47,"Без безрассудной и так преимущество по упавшим/",65477,null],[65480,"2026-06-20T23:47:00",32,"Есть пробитие \nКинь д10 силового",65476,null],[65481,"2026-06-20T23:47:06",9,"/roll 1d20+4 урон без удара великана",64123,null],[65484,"2026-06-20T23:47:19",47,"Это д20/",65482,null],[65485,"2026-06-20T23:47:30",9,"//Бля, там д 10 но пусть будет 5, пох",64123,null],[65486,"2026-06-20T23:47:36",5,"// жив",64123,null],[65487,"2026-06-20T23:48:02",9,"//Безрассудная и всётакое, я а ирл занят чтобы думать",64123,null],[65488,"2026-06-20T23:48:10",47,"- Так не должно быть. Волки не столь агрессивны - шепчет Тал",64123,null],[65489,"2026-06-20T23:48:11",9,"//Варвар бить",64123,null],[65490,"2026-06-20T23:48:14",32,"/roll d10",64123,null],[65492,"2026-06-20T23:48:26",32,"Есть пробитие!",65491,null],[65493,"2026-06-20T23:48:31",47,"/вау.почти ваншот",64123,null],[65495,"2026-06-20T23:48:48",32,"А сколько у волка?",65493,null],[65496,"2026-06-20T23:48:49",5,"// окей, добей раз так",65492,null],[65497,"2026-06-20T23:48:57",5,"// опиши",64123,null],[65498,"2026-06-20T23:49:01",47,"8-13",65495,null],[65499,"2026-06-20T23:49:07",47,"Не помню точно/",64123,null],[65500,"2026-06-20T23:49:27",5,"// вопрос откуда у волшебника мистический заряд оставлю на потом...",64123,null],[65501,"2026-06-20T23:49:33",32,"С учётом бонуса дальнобойной атаки ручек чистого силового поля просто вошёл в висок и взорвал голову",65496,null],[65502,"2026-06-20T23:49:42",47,"/посвящённый в магию",65500,null],[65503,"2026-06-20T23:50:33",32,"Предыстория даёт заговор на выбор (и кучу законов для изучения так как громовая волна или хаотический заряд (ни то ни то волшебник обычно взять не может даже в дополнениях))",65500,null],[65504,"2026-06-20T23:50:48",5,"Барахтающиеся волки вскакивают и улепётывают в лес\n\n// отход, 40 футов",64123,null],[65505,"2026-06-20T23:50:55",32,"//Инженер иззетов предыстория",64123,null],[65506,"2026-06-20T23:51:01",47,"/25 ведь? /",64123,null],[65507,"2026-06-20T23:51:09",47,"Они же половину скорости тратят? /",64123,null],[65508,"2026-06-20T23:51:11",32,"Ещё один заряд в догонку!",65504,null],[65509,"2026-06-20T23:51:18",5,"// не, они так-то в прошлый ход встали, просто ничего не делали",64123,null],[65510,"2026-06-20T23:51:36",40,"/спас?",64123,null],[65511,"2026-06-20T23:51:48",5,"// ход эльфа",64123,null],[65512,"2026-06-20T23:51:50",32,"Ты уже с нами",65510,null],[65513,"2026-06-20T23:52:04",40,"/да? Два успеха было только",64123,null],[65514,"2026-06-20T23:52:17",32,"А больше и не надо",65513,null],[65515,"2026-06-20T23:52:24",47,"Эльф берёт лук и роняет рапиру. Выстрел в недобитка",64123,null],[65516,"2026-06-20T23:52:33",40,"/надо же три, не? Я так то не против встать щас",64123,null],[65517,"2026-06-20T23:52:36",47,"/r d20+8",64123,null],[65519,"2026-06-20T23:52:41",32,"//У тебя кубика Спаса три а бросаешь два",64123,null],[65520,"2026-06-20T23:52:56",47,"/r d8+4",64123,null],[65522,"2026-06-20T23:53:04",5,"// добивай",65521,null],[65523,"2026-06-20T23:53:07",32,"//Точнее тебе надо два успеха",65519,null],[65524,"2026-06-20T23:53:28",40,"@elsio28 / с двух успехов на спас смерти я встаю?",64123,null],[65525,"2026-06-20T23:53:46",5,"// нет, с 3 стабилируешься, встаёшь только с крита",65524,null],[65526,"2026-06-20T23:54:01",47,"Уже не глядя на на выстрел, эльф знает. Стрела попадёт в волка. Он спешит за другими. Если этих сейчас отпустить, нападение на мирных путников продолжится, кувырок, и короткий рывок за другой частью стаи",64123,null],[65527,"2026-06-20T23:54:20",47,"Я такопнимаю в 10 фт +-? /",64123,null],[65528,"2026-06-20T23:54:29",5,"// бросай спас",65524,null],[65529,"2026-06-20T23:54:36",40,"/roll@roll_bot",64123,null],[65531,"2026-06-20T23:54:44",5,"40//",65527,null],[65532,"2026-06-20T23:54:48",47,"В это время стрела настигает волка, вонзаясь чётко в ухо. Волк замирает/",64123,null],[65533,"2026-06-20T23:54:57",47,"Я подбежал на 35/",65531,null],[65534,"2026-06-20T23:55:11",5,"// ты от остальных юыл на 30 изначально",64123,null],[65535,"2026-06-20T23:55:13",40,"-АААААА БЛЯТЬ! Дворняги , ебать вас в три погибели!!! Был бы я помоложе!!!",64123,null],[65536,"2026-06-20T23:55:25",47,"/то есть в 35 от волков? /",64123,null],[65537,"2026-06-20T23:55:34",47,"Ок! /",64123,null],[65538,"2026-06-20T23:55:45",32,"-дед самый больной среди нас я! У меня спина болит!(Только деду",65535,null],[65539,"2026-06-20T23:55:53",5,"Волки убегают.  Три-крин может выстрелить ещё раз вдогонку.",64123,null],[65540,"2026-06-20T23:55:56",5,"// или отпустить",64123,null],[65541,"2026-06-20T23:56:05",32,"В догонку",65539,null],[65542,"2026-06-20T23:56:08",32,"/roll@roll_bot",64123,null],[65544,"2026-06-20T23:56:11",47,"/они по дороге бегут? /",64123,null],[65545,"2026-06-20T23:56:13",5,"Вокруг вас лежат тёплые тела мёртвых волков",64123,null],[65546,"2026-06-20T23:56:16",5,"// в лес",65544,null],[65547,"2026-06-20T23:56:24",40,"-а ты горазд на шее у мужиков сидеть!..",65538,null],[65548,"2026-06-20T23:56:24",32,"+5 на попадание заклинанием",64123,null],[65549,"2026-06-20T23:56:46",32,"/roll d10",64123,null],[65551,"2026-06-20T23:57:06",5,"2 последних волка, скуля скрываются в чаще леса.",64123,null],[65552,"2026-06-20T23:57:07",32,"-Не буьни под руку развалина старая!",65547,null],[65553,"2026-06-20T23:57:08",9,"//Скоро вернус",64123,null],[65554,"2026-06-20T23:57:20",5,"// конец боя",64123,null],[65555,"2026-06-20T23:57:45",9,"*Леда садится ц дерева, очень ранен, тяжело дышит.*\n\n// 6/31 хитов",64123,null],[65556,"2026-06-20T23:57:51",32,"Мы кое-как выжили затащил Леда просто в соляново",64123,null],[65557,"2026-06-20T23:57:54",40,"Сразу закидываюсь травяной настойкой и курю хапку:\n-ну его нахуй, пока не сдох надо поймать все кайфы",64123,null],[65558,"2026-06-20T23:58:21",47,"Талон шагает и вырывает стрелы из волков, чистит от крови, убедившись, что никто из союзников не собирается умирать от кровопотери в ближайшее время",64123,null],[65559,"2026-06-20T23:58:45",40,"Hard \n-зелье лечения есть, надо?",64123,null],[65560,"2026-06-20T23:58:49",32,"Я рядом стараюсь не слишком шипя размять забитую спину",65557,null],[65561,"2026-06-20T23:58:53",47,"/лан поцы. Я ща заявки оставлю и спать",64123,null],[65562,"2026-06-20T23:59:30",32,"-Себе оставь дед меня моя магия подлетает завтра как новый буду",65559,null],[65563,"2026-06-20T23:59:42",47,"Так же Талон подходит после к телу вожака и обследует его. Тощий ли он? Если нет, то почему же он мог напасть на идущую группу людей? Волки обычно не столь рисковые животные",64123,null],[65564,"2026-06-20T23:59:58",47,"/r d20 рандом заявка",64123,null],[65566,"2026-06-21T00:00:25",32,"А я после восстановления прихрамывая начал снимать шкуры (медецина)",64123,null],[65567,"2026-06-21T00:00:30",32,"/roll@roll_bot",64123,null],[65569,"2026-06-21T00:00:37",32,"15+4",65568,null],[65570,"2026-06-21T00:01:21",47,"/лан.спокойных.вырубает.",64123,null],[65571,"2026-06-21T00:01:24",5,"// так, ща",64123,null],[65572,"2026-06-21T00:01:35",32,"И потом Леда помог их заскоблить и замазать мозгами самих зверюг",64123,null],[65573,"2026-06-21T00:02:11",5,"Шкуры многих волков повреждены, тебе удалось успешно снять лишь 2",65566,null],[65574,"2026-06-21T00:02:37",32,"Снял все на работу кожевника и обрезки нужны",65573,null],[65575,"2026-06-21T00:02:43",40,"-короткий привал может? - спросил пьяный дед",64123,null],[65576,"2026-06-21T00:03:06",40,"В руке дымился косяк",64123,null],[65577,"2026-06-21T00:03:13",32,"Мне кажется нам бы заночевать где.",65575,null],[65578,"2026-06-21T00:03:38",5,"Волк не очень тощий. Тебе приходит мысль, что в этот лес боятся ходить люди, поэтому волки чувствуют себя смело.",65563,null],[65579,"2026-06-21T00:03:46",5,"// так тебе будет бэдтрип",65576,null],[65580,"2026-06-21T00:03:52",5,"// можешь часть сам написать",64123,null],[65581,"2026-06-21T00:04:04",5,"// что ты там увидел, я дополню",64123,null],[65582,"2026-06-21T00:04:17",32,"С учётом того чем занята голова была то с жуками будет",64123,null],[65583,"2026-06-21T00:04:40",32,"У деда мультик",65582,null],[65584,"2026-06-21T00:04:54",5,"Вы стоите на тропе посреди леса. Волки вас задержали, но дождь ещё не начался. Время близится к вечеру",64123,null],[65585,"2026-06-21T00:05:06",5,"// обсуждайте какой",65575,null],[65586,"2026-06-21T00:05:12",5,"// вас 2 осталось, так что вы решаете",64123,null],[65587,"2026-06-21T00:06:03",40,"Хорхе часть жизни был в военной разведке, потом его выперли за вызывающее поведение в отношении командиров.\n\nТогда он пошел коронером (суд мед эксперт) и помогал страже изучая криминальные трупы\n\n/Ну короче чё то связанное с этим пусть будет. С биографией",64123,null],[65588,"2026-06-21T00:06:11",32,"Короткий отдых чтобы собрать шкуры когти и вырезку (три-крины едят все мясное потому будет шашлындос)",65584,null],[65589,"2026-06-21T00:07:15",32,"-Предлагаю в деревню валить отсыпаться я знаете готов нам всем комнату оплатить одну на всех правда и кровать моя но всё-таки",65588,null],[65590,"2026-06-21T00:07:32",40,"/за короткий отхилимся же в фул?",65586,null],[65591,"2026-06-21T00:07:38",9,"//Короткий?",64123,null],[65592,"2026-06-21T00:07:44",5,"// по кубикам хитов",65590,null],[65593,"2026-06-21T00:08:01",40,"/я 2 ур воин, 2д10?",64123,null],[65594,"2026-06-21T00:08:15",32,"Мне один только кинуть надо д6",65590,null],[65595,"2026-06-21T00:08:41",32,"/roll d6",64123,null],[65597,"2026-06-21T00:08:52",32,"Все у меня полные",65596,null],[65598,"2026-06-21T00:09:21",5,"// + мод тела",65593,null],[65599,"2026-06-21T00:09:36",40,"/я второе дыхание использую до отдыха. Потом короткий. Я думаю буду фул и второе дыхание вернётся от отдыха",64123,null],[65600,"2026-06-21T00:09:40",40,"/верно?",64123,null],[65601,"2026-06-21T00:10:25",32,"Оно раз в долгий отдых перезаряжается",65599,null],[65603,"2026-06-21T00:10:39",9,"/roll 2d12+1d6+9",64123,null],[65605,"2026-06-21T00:10:52",9,"//Фулл как раз",64123,null],[65606,"2026-06-21T00:11:02",40,"/r d10+2",64123,null],[65608,"2026-06-21T00:11:16",40,"И Хорхе лег спать под дерево",64123,null],[65609,"2026-06-21T00:11:55",32,"Я уселся рядом, наблюдать пациента",64123,null],[65610,"2026-06-21T00:12:06",32,"/roll@roll_bot",64123,null],[65612,"2026-06-21T00:12:22",32,"Да не слишком успешно правда",64123,null],[65613,"2026-06-21T00:12:45",5,"Дед курил и перед его глазами появились видения. Он находился уже совсем не лесу.\n\nОдно из его старых дел. Тело обнаружили в песчаном карьере и Хорхе видит себя именно там. \n\nОн нагнулся на несчастной жертвой. Шея чем-то перебита. След как будто били... булавой? \n\nВнезапно, тело шевельнулось. Оно поползло к стене карьера. Начало рыть. Голыми руками, судорожно ища что-то. Песок сыпется, карьер затягивает туман.\n\nТело роет и роет. Хорхе видит себя прямо за его спиной. В руке булава. \n\n~Бей — говорит неведомый голос",64123,null],[65614,"2026-06-21T00:13:27",9,"*Глядя на леду, что сидит словно в трансе можно было заметить как лёгкие сгустки тьмы клубятся у страшных рваных ран и те зарастают без следов.*",64123,null],[65615,"2026-06-21T00:13:31",40,"/r 1d10+2",64123,null],[65617,"2026-06-21T00:13:36",40,"/r 1d10+2",64123,null],[65619,"2026-06-21T00:13:44",40,"Дед фул",64123,null],[65620,"2026-06-21T00:13:49",5,"// такс, ну вы запишите сколько у вас там хп, продолжим в след раз. Сейчас только бэдтрип",64123,null],[65621,"2026-06-21T00:13:59",32,"А кстати за короткий отдых я даже восстановление чар провести не могу оно со второго уровня",64123,null],[65622,"2026-06-21T00:14:02",5,"// дейтсвия?",65613,null],[65623,"2026-06-21T00:14:13",40,"/читаю",64123,null],[65624,"2026-06-21T00:15:01",32,"//сразу уточню меня пингуйте у меня местные чаты заглушены",65620,null],[65625,"2026-06-21T00:15:03",40,"-что?!\n\nХорхе оглянулся ища голос\n\n-шмаль, отпусти...",65613,null],[65626,"2026-06-21T00:15:43",40,"Смотрю на булаву, она в крови?",64123,null],[65627,"2026-06-21T00:15:50",32,"//а я телепатией могу эму передавать ещё голосов?",65625,null],[65628,"2026-06-21T00:16:01",40,"/гнида какая",65627,null],[65629,"2026-06-21T00:17:02",32,"Так то мыслеречь не ограничена только моим внутренним голосом я могу любое существо на любом известном мне языке подражать например дракона я знаю драконий!",64123,null],[65630,"2026-06-21T00:17:20",5,"Голос прямо у тебя в голове. Это твой голос. Рука судорожно сжимает булаву. На булаве крови нет, пока что...\n\n~Бей — повторил голос\n\nТы осматриваешь карьер  цепким взглядом. Ничто не укроется. Ты совершенно один. Никто не увидит, что ты сделаешь.\n\n~Бей — настойчиво говорит голос",65625,null],[65633,"2026-06-21T00:18:12",5,"Дед лежит за земле, глаза закатились. Он тебя не слышит, не отвечает на все твои попытки",65629,null],[65634,"2026-06-21T00:18:47",32,"Печально а я думал хоть что-то буркнет!",65633,null],[65635,"2026-06-21T00:19:13",5,"// травка мощная",65634,null],[65636,"2026-06-21T00:19:17",32,"Ладно где там был его отвар укрепляющий и опьяняющий?",64123,null],[65637,"2026-06-21T00:19:24",5,"// у него в рюкзаке",65636,null],[65638,"2026-06-21T00:19:48",40,"-НЕТ!!! \n\nХорхе бросает булаву под ноги себе и идёт к трупу который роет, хватает за ноги и тянет назад\n\n-ЛЕЖАТЬ СУКА!!! ИМЕНЕМ ЗАКОНА, Приказываю лежать!!! Я коронер! Я объявляю тебя мертвым!!! Я констатирую твою смерть!!!",64123,null],[65639,"2026-06-21T00:20:09",32,"Залить эму в рот от травм чтобы тело приходило в себя быстрее и главное его ещё сильнее вштырило",65637,null],[65640,"2026-06-21T00:20:24",40,"/я все выпил",64123,null],[65641,"2026-06-21T00:20:26",5,"Можешь описать, как насильно поишь его",65639,null],[65642,"2026-06-21T00:20:30",40,"/я покурил и выпил",64123,null],[65643,"2026-06-21T00:20:38",5,"// ок))",65642,null],[65644,"2026-06-21T00:21:01",32,"Печаль но ладно",64123,null],[65645,"2026-06-21T00:22:39",9,"//Деда вштырило?",64123,null],[65646,"2026-06-21T00:22:54",32,"//Ладно что там по добыче со шкур какая оценочная стоимость 2 целых и 2 обрезками? Хорошо обработанных",64123,null],[65647,"2026-06-21T00:23:10",32,"//хотел помочь но он сам справился",65645,null],[65648,"2026-06-21T00:25:21",5,"Булава на земле. Она в крови.\n\nТело перед тобой. Стоило сказать \"ИМЕНЕМ ЗАКОНА\" и оно обмякло на земле. Ты наклоняешься. Он мёртв. Совершенно мёртв.\n\nКровавый шрам на шее. Булава в крови рядом. И подозрительный мужчина, склонившийся над трупом.\n\n— Именем закона, ни с места! — раздаётся строгий оклик.\n\nПрямо рядом с тобой в карьер прыгает стражник в тяжелых латах. Ты слышишь тяжёлые шаги сзади. Поднимаешь голову. Стражник без шлема.\n\nТы широко открываешь глаза и видишь... жука. Он стоит прямо перед тобой и что-то стрекочет. В лесу кричит кукушка. Первая капля дождя сбегает по щеке.",65638,null],[65649,"2026-06-21T00:26:28",32,"//приехали.",65648,null],[65650,"2026-06-21T00:27:11",32,"-Очнулся? Отлично приходи в себя ты так молчал! так молчал! мы думали умер",65648,null],[65651,"2026-06-21T00:29:10",9,"*Леда открыл глаза, кажется словно снова начал дышать.*\n\n— Что-то случилось?",64123,null],[65652,"2026-06-21T00:29:16",40,"-ААААА, пидрила, я так и знал что это ты! Ещё дурь на карман мне подкинешь чтобы оформить? \n\n*Рука пошла в карман и достала оставшуюся хапку травы*\n\n-Закинули. Отвечаю, закинули не мое!!!\n\n*Другой рукой достаю винный уксус и обливают себя*\n\n-что ты жвала свои разминаешь?! Готовишься схавать меня! А ТЕПЕРЬ Я НЕВКУСНЫЙ!!! ГОВНА ПОЖУЙ МУДИЛА!!!",64123,null],[65653,"2026-06-21T00:29:26",9,"//Я предлагаю ждать миху всё же",64123,null],[65654,"2026-06-21T00:29:48",5,"// да, на сегодня всё",65653,null],[65655,"2026-06-21T00:29:52",5,"// тут так, социалка",64123,null],[65656,"2026-06-21T00:29:57",5,"// дальше пойдём в след раз",64123,null],[65657,"2026-06-21T00:29:57",32,"-Сам себя замариновал!? (Про поливание уксусом)",65652,null],[65658,"2026-06-21T00:30:53",32,"Ладно спокойной ночи я сам уже задолбался честно говоря",64123,null],[65660,"2026-06-21T00:31:25",5,"// спокойной",65658,null],[65661,"2026-06-21T00:31:56",5,"// держи вдохновение на переброс чего угодно",65652,null],[65662,"2026-06-21T00:32:22",5,"// сам опиши, какой там эффект обливания и что ты сделал со второй дозой",65652,null],[65663,"2026-06-21T00:34:29",40,"Вторую дозу Хорхе скинул с криком: найдено не при мне, не докажете что мое! Оно принадлежит вот этому трупа с перебитой шеей!\n\nА обливание дало мне защиту от всех животных и некоторых звероподобных рас",64123,null],[65665,"2026-06-21T00:36:10",5,"// позже напишу, когда продолжение будет",64123,null],[65666,"2026-06-21T00:36:35",40,"/все тогда до завтра, спасибо было прикольно, хотя я и пролежал весь бой",64123,null],[65672,"2026-06-21T00:58:01",40,"/блять, погоди. Я это сделал уже не в трипе а в реальности?  Я надеюсь я не проебал уксус и вторую хапку?)))",65652,null],[65676,"2026-06-21T01:01:09",5,"// ну вообще да, в реальности. Там жук, кукушка в лесу и начало дождя.",65672,null],[65677,"2026-06-21T01:02:12",5,"// хапку можешь с земли подобрать",65672,null],[65679,"2026-06-21T01:04:51",40,"Хорхе нагнулся чтобы поднять хапку, блеванул, отполз под куст и накрывшись чем то из своего рюкзака лег спать",64123,null],[65694,"2026-06-21T07:07:06",47,"/можно кратко, что произошло за эти +- 70 сообщений?",64123,null],[65696,"2026-06-21T09:59:10",40,"/мой бэдтрип от петрушки",65694,null],[65697,"2026-06-21T10:12:49",40,"Хорхе приходит светлая мысль: он ведь имеет слепозрение. В будущем стоит запастись дымовыми шашками. Стая которая не видит имеет помеху, а хорхе помехи иметь не будет\n\n@elsio28 /технически по правилам верно?",64123,null],[65702,"2026-06-21T11:01:30",47,"/он ещё и преимущество по ним иметь будет",65697,null],[65793,"2026-06-21T17:06:32",5,"// если правда имеешь слепо зрение, то да",65697,null],[65797,"2026-06-21T17:30:22",5,"// сегодня игры точно не будет",64123,null],[67924,"2026-06-22T10:17:41",40,"//а сёдня?",64123,null],[68214,"2026-06-22T14:58:05",32,"Главное что ты своей жопой нас от половины противников закрыл",65666,null],[68216,"2026-06-22T14:59:45",32,"Ну зато жук подобрал ценный алхимический реагент который выкинул дед потом смолы и угольного порошка купит и смешает дымовую шашку с галлюцинагеном",65663,null],[68223,"2026-06-22T15:30:51",40,"/Хапку я забрал с земли обратно, не пизди",68216,null],[68224,"2026-06-22T15:31:42",32,"/Печалька. Мне было бы нужнее.",68223,null],[68225,"2026-06-22T15:31:55",40,"/ну попросишь - вместе раскурим",64123,null],[68226,"2026-06-22T15:32:10",40,"/осуждаю",64123,null],[68283,"2026-06-22T16:58:25",47,"@elsio28",64123,null],[68346,"2026-06-22T17:39:42",5,"// сегодня игра в 20:00, если все будут\n@H_Kruz @Xaosick @cirson Hard",64123,null],[68351,"2026-06-22T17:40:16",9,"//Океши, буду",64123,null],[68355,"2026-06-22T17:40:29",5,"// мне нравится твоя идея, можно устроить, если проверку пройдешь",68216,null],[68359,"2026-06-22T17:41:34",47,"Возможно меня не будет",64123,null],[68360,"2026-06-22T17:42:16",5,"Позже сегодня сможешь?",68359,null],[68361,"2026-06-22T17:42:38",47,"Наоборот/",64123,null],[68362,"2026-06-22T17:42:57",47,"С обеда до ужина могу/. Я в военной академии и тут сложно с этим",64123,null],[68364,"2026-06-22T17:43:47",5,"// скажи по времени",68362,null],[68365,"2026-06-22T17:44:36",47,"2-6 мск",68364,null],[68366,"2026-06-22T17:45:34",5,"// это очень неудобно для меня, я могу только с 18 начинать",68365,null],[68377,"2026-06-22T17:49:03",47,"/сори.пока так",64123,null],[68379,"2026-06-22T17:49:26",47,"Я постараюсь поменять, но не могу до конца недели/",64123,null],[68397,"2026-06-22T17:58:17",40,"/буду",68346,null],[68441,"2026-06-22T18:03:36",5,"Я сразу в наборе написал в какое время веду игру. Так что если другие игроки будут, то я не хочу откладывать короткий ваншот на целую неделю",68379,null],[68444,"2026-06-22T18:03:56",5,"Очень не люблю тянуть игры где всем трудно собраться сорри",64123,null],[68447,"2026-06-22T18:04:40",47,"У меня эта фигня вчера началась/",68441,null],[68448,"2026-06-22T18:04:53",47,"Потому что чуваки накосячили, забирают у всех/",64123,null],[68488,"2026-06-22T18:22:18",32,"Я буду если после шквала свет не оборвет то буду на игре",68346,null],[68492,"2026-06-22T18:23:56",32,"// ну можно ещё у травника спросить если будет реагент то я попробую (как минимум у меня по возвращении в деревню будут два новых знамения потому если выпадет хороший кубик кину через прорицание",68355,null],[68686,"2026-06-22T19:19:35",47,"Ещё могу",64123,null],[68727,"2026-06-22T19:50:33",47,"@elsio28",64123,null],[68728,"2026-06-22T19:50:40",5,"// ща начну",64123,null],[68732,"2026-06-22T19:53:00",5,"Спустя час отдыха, отряд пробудился. Герои отдыхали в разных местах: кто прислонился к дереву, кто неспешно очищал волчьи шкуры, а кто-то даже залез под куст и накрылся чем-то. И от него несло перегаром и ещё невесть чем.\n\nБитва с волками и отдых вас задержали. Прошло почти 3 часа с момента выхода из деревни и начал накрапывать слабый дождик.\n\nТропа лежала впереди, чётко указывая путь к карьеру. Что делаете, герои?",64123,null],[68733,"2026-06-22T19:53:20",5,"// восстанавливаете всё за быстрый отдых, можете поговорить там персонажами",64123,null],[68734,"2026-06-22T19:53:27",5,"// и идти дальше когда готовы",64123,null],[68739,"2026-06-22T19:55:03",32,"-я не готов к путешествию дальше у меня магии 1/5 арсенала",64123,null],[68740,"2026-06-22T19:55:10",32,"То есть только заговор",64123,null],[68741,"2026-06-22T19:56:30",9,"— Силы идти есть. — *Леда сказал как есть, выровнявшись, он отдыхал стоя облокотившись на дерево.*\n\n//У меня минус 1 ячейка, ярость и удар с выносливостью. Живём пока",64123,null],[68743,"2026-06-22T19:58:03",32,"(жук говорил спокойно и если соратники скажут он готов идти но хотел бы сначала восстановить чары)",64123,null],[68746,"2026-06-22T19:58:59",5,"// это вы договариваетесь что делать",64123,null],[68748,"2026-06-22T20:00:35",9,"— Место на моих плечах — пусто. — *Предложил великан, он уже видел насколько хрупок жук.*",64123,null],[68749,"2026-06-22T20:00:37",32,"//кстати мастер а после тайника будет игра какая?",68746,null],[68750,"2026-06-22T20:01:16",5,"// то есть? Я пока эту игру веду, о другом не думаю",68749,null],[68751,"2026-06-22T20:01:21",32,"(жук подумал и без слов подошёл к гиганту просясь на ручки)",68748,null],[68753,"2026-06-22T20:01:57",32,"//ты вроде говорил что это ваншот?",68750,null],[68754,"2026-06-22T20:02:02",5,"/@H_Kruz",64123,null],[68755,"2026-06-22T20:02:13",5,"// да, это ваншот",64123,null],[68756,"2026-06-22T20:02:44",5,"// потенциально тут будет возможность для расширения, но когда-то потом",64123,null],[68758,"2026-06-22T20:03:26",32,"//видимо деда капитально вштырило и нести Леда будет не жука",64123,null],[68759,"2026-06-22T20:04:29",9,"*Подсадил жука на шею.*",68751,null],[68760,"2026-06-22T20:04:55",9,"//Если бы взял фата мы бы померли все, у него 10 хитов",64123,null],[68761,"2026-06-22T20:05:40",47,"О долгий отдых",68732,null],[68762,"2026-06-22T20:05:53",9,"//Вродь короткий?",64123,null],[68763,"2026-06-22T20:05:54",47,"Не зря эльф/",64123,null],[68764,"2026-06-22T20:06:20",9,"//У тебя есть магическое восстановление если волшебник, можешь восстановить 1 ячейку 1 ур на 1 ур вродь",68758,null],[68765,"2026-06-22T20:06:37",47,"У меня за 4 часа долгий. Я ещё часикбы отдохнул и могу вас послать на этот. Часик. Столько Абилок откатится. /",64123,null],[68766,"2026-06-22T20:06:40",32,"//оно со второго уровня вродь)",68764,null],[68767,"2026-06-22T20:06:54",5,"// вы отдыхали всего 1 час",68765,null],[68768,"2026-06-22T20:06:54",9,"//Вот гадство",64123,null],[68769,"2026-06-22T20:07:14",47,"/а, да. Не туда глянул",64123,null],[68770,"2026-06-22T20:08:16",5,"// и я не уверен, но ведь способности лесного эльфа берутся вместо обычных? Типа у лесного нету транса",68768,null],[68771,"2026-06-22T20:09:04",9,"//Восстанавливай ячейку",64123,null],[68772,"2026-06-22T20:09:17",9,"//У эльфа есть основа + весь бонус от подвида вродь, да они имба",68770,null],[68773,"2026-06-22T20:12:44",32,"Я тоже в книгу игрока смотрел да первого уровня. Тогда у меня одна ячейка первого уровня есть. Уже что-то",64123,null],[68774,"2026-06-22T20:14:30",32,"//почему так долго искал? Да потому что сука 5,5 классы в алфавитном порядке а в 5 е как Тиамат пошлёт!\nИ собственно долго листал",68773,null],[68775,"2026-06-22T20:15:15",9,"//Я на днд су сморю, там удобно",64123,null],[68776,"2026-06-22T20:17:18",32,"//ВПН работает через раз. Когда подключится к подходящей стране работает не повезло перегенеривай хочу другую страну и при этом с шансом ~90% тебе дадут тот же сервер",68775,null],[68777,"2026-06-22T20:17:40",9,"//Латвия имба, ток на ней все сайты грузит, тож впн",64123,null],[68778,"2026-06-22T20:19:28",32,"//Ладно идём к тайнику шкуры на парящий диск (его ритуалом снова создал и загрузил) и мы можем идти",64123,null],[68780,"2026-06-22T20:21:32",9,"*Леда идёт не спеша, со щитом в руке и алибардой в другой.*\n\n//Я знаю что так не атакуешь, но если что выпущу щит и перехвачусь",64123,null],[68781,"2026-06-22T20:23:05",32,"//Если дед спит мы можем и его на парящий диск всунуть.",68778,null],[68783,"2026-06-22T20:23:36",32,"//А сам я на плечах Леды поеду",64123,null],[68784,"2026-06-22T20:25:01",5,"Великан с жуком на плече неспешно идёт по тропе. \n\nТучи не расходятся, слабый летний дождик падает вам на голову. Вскоре к этому добавился туман. Слабый, стелящийся по земле. Но мешающий обзору. Тропу стало плохо видно.",64123,null],[68785,"2026-06-22T20:25:25",5,"https://www.youtube.com/watch?v=iG7JDXCd-pc",64123,null],[68786,"2026-06-22T20:25:29",5,"// музыка",64123,null],[68787,"2026-06-22T20:27:15",5,"В какой-то момент Леда осознал, что не уверен в направлении. Туман в ногах совершенно застилал обзор тропы.",64123,null],[68788,"2026-06-22T20:28:04",32,"-Леда тормози. Где наш эльф?",64123,null],[68789,"2026-06-22T20:28:39",32,"(парящий диск идёт за нами в 6 метрах (20 футов) я его вижу?)",64123,null],[68790,"2026-06-22T20:28:40",47,"Ветка касается Три крина.",64123,null],[68791,"2026-06-22T20:28:53",47,"Это оказывается рука эльфа",64123,null],[68792,"2026-06-22T20:29:46",32,"-Ты так не подкрадывается (гасит алое сияние уже готового было выстрелить огненного снаряда испугал его эльф)",68790,null],[68793,"2026-06-22T20:30:03",5,"// да, диск виден",68789,null],[68794,"2026-06-22T20:30:03",47,"- я тут всё время",64123,null],[68795,"2026-06-22T20:30:17",5,"// туман стелется по земле, сверху видимость обычная",64123,null],[68796,"2026-06-22T20:31:21",32,"//я могу кинуть аркану на проверку насколько этот туман магический?",64123,null],[68797,"2026-06-22T20:31:30",9,"— Туман. — *Леда вешает щит и берёт Алибарду обеими руками шаркая древком по земле перед собой, прослеживая тропу чтобы не потерять.*",64123,null],[68799,"2026-06-22T20:31:42",32,"Точнее попробовать понять его источник",68796,null],[68800,"2026-06-22T20:32:03",5,"// кидай анализ магию или выживание",68799,null],[68801,"2026-06-22T20:32:12",32,"/roll@roll_bot",64123,null],[68803,"2026-06-22T20:32:23",47,"/помогу?",64123,null],[68804,"2026-06-22T20:32:24",32,"+5\n15 арканы",64123,null],[68805,"2026-06-22T20:32:37",47,"/я в течении игры насекомому помогаю, как одному из адекватных",64123,null],[68806,"2026-06-22T20:32:47",5,"/r d20+5 пиши вот так пж в будущем, всем удобнее",64123,null],[68808,"2026-06-22T20:33:17",32,"/roll d20+5",64123,null],[68810,"2026-06-22T20:33:21",5,"// ты не афк нпс, требуется заявка для помощи",68805,null],[68811,"2026-06-22T20:34:31",5,"Три-крин понимает, что туман совершенно точно неестественный. Он так же замечает, что чем дальше они шли по тропе, тем выше становился полог тумана. Росла и его густота. Очевидно, источник тумана — карьер.",64123,null],[68812,"2026-06-22T20:34:40",47,"Талон подходя к Три крину говорит:\n- Обычный туман возникает тогда, когда влажно, и резко изменяется температура",64123,null],[68813,"2026-06-22T20:34:55",5,"// воздух влажный, идёт слабый дождь",68812,null],[68815,"2026-06-22T20:35:38",47,"- Температура вроде стабильно прохладная в последнее время",64123,null],[68816,"2026-06-22T20:35:51",32,"//Не туман немного не так работает не только влага но и перепад температуры нужен",68813,null],[68817,"2026-06-22T20:36:53",32,"(Чтобы земля была холоднее воздуха (собственно потому чаще всего по утрам появляется))",68816,null],[68818,"2026-06-22T20:37:37",47,"/я это и написал...",68816,null],[68819,"2026-06-22T20:38:24",32,"//я просто не заметил (не обратил внимание прости)",68818,null],[68820,"2026-06-22T20:39:50",5,"Ты шаркаешь древком и понимаешь, что уже стоишь не на тропе. Под ногами обычная лесная растительность",68797,null],[68821,"2026-06-22T20:40:03",32,"-Мне это прямо капитально не нравится так предлагаю вот что зажигаем факелы и расходимся квадратом",64123,null],[68822,"2026-06-22T20:40:39",5,"// то что я написал узнал только ты. Чтобы остальные знали, надо им рассказать",68821,null],[68823,"2026-06-22T20:41:04",32,"//спасибо что уточнил я действительно не подумал)",68822,null],[68824,"2026-06-22T20:41:31",32,"-Туман неестественный, явно магический. Источник карьер куда мы шли",68821,null],[68825,"2026-06-22T20:41:34",9,"— Сошли с тропы. — *Предупредил спутников.*",68820,null],[68826,"2026-06-22T20:46:29",32,"//?",68821,null],[68827,"2026-06-22T20:51:02",5,"// где же играющие игроки(",64123,null],[68828,"2026-06-22T20:51:10",9,"— Хмммм. — *Достаёт верёвку.* — Обвяжемся меж собой. Пропавших безвести не будет.",68821,null],[68829,"2026-06-22T20:51:30",9,"//Я б деда ждал",68827,null],[68830,"2026-06-22T20:52:09",32,"-Тоже вариант но я хочу контролировать большую площадь",68828,null],[68831,"2026-06-22T20:52:09",5,"// можем подождать тогда @H_Kruz",68829,null],[68832,"2026-06-22T20:52:49",32,"-Могу и верёвку держать и с факелом идти в десятке метров так все уже не потеряемся",68830,null],[68833,"2026-06-22T20:53:20",9,"//Ток за",68831,null],[68834,"2026-06-22T20:53:37",32,"Сзади идущий заметит что мы отклонились как и идущие с боков",68832,null],[68835,"2026-06-22T20:53:59",9,"— Одного быстро съедят. — *Великана чуть волки не загвызли вот недавно, он помнит всё ещё.*",68832,null],[68836,"2026-06-22T20:55:57",32,"-Одной кучкой потеряемся.\nТогда по парно разйтись и идти горизонтально когда кто-то начнет уходить другие заметят. Это даст ценные данные о работе магической защиты",68835,null],[68837,"2026-06-22T20:57:26",9,"*Вздыхает и больше не настаивает, как решите так и сделает. Просто всматривается в туман.*",64123,null],[68838,"2026-06-22T20:59:01",5,"// кидай восприятие",68837,null],[68839,"2026-06-22T20:59:27",32,"-по моей предварительной гипотезе если мы будем идти в правильном направлении то нас должно разводить в разные стороны",68837,null],[68840,"2026-06-22T21:00:13",9,"/roll 1d20+3 я больше нарративно смотрел вникуда, но лан",64123,null],[68842,"2026-06-22T21:01:02",32,"//напомню третий Крит за игру",64123,null],[68843,"2026-06-22T21:01:13",9,"//Чей?",64123,null],[68844,"2026-06-22T21:01:27",9,"//Там не 22, я не доволен ^^",64123,null],[68845,"2026-06-22T21:01:32",32,"//твой",68843,null],[68846,"2026-06-22T21:01:49",9,"//Ок, не слежу",68845,null],[68847,"2026-06-22T21:02:31",9,"//Щас мастер опишет что я увидел а я опишу как это увидел)",64123,null],[68848,"2026-06-22T21:05:11",5,"Взгляд Голиафа пронзил туман. Его глаза различили каждую деталь и собрали цельный образ.\n\nПо положению деревьев он увидел, что тропа совсем недалеко от них, в 30 футах слева. Ещё дальше за тропой находился огромный пень. Он почему-то привлекал внимание, как будто бросал вызов силе голиафа.\n\nСправа, в 20 футах от его ног на земле лежала непонятная серая куча. Немного подумав, он понял, что это скелет. И заметил, что тот немного шевелится. Других подобных куч, а точнее костей, рядом не было.",64123,null],[68849,"2026-06-22T21:05:47",9,"//А, вспомнил, там было 2 крита за бросок на подскальзывание с преимуществом?)",68842,null],[68850,"2026-06-22T21:08:28",9,"*Взгляд золотистых глаз прорезал туман. Он не мог заглянуть далеко, но кое что видел... словно в трансе леда подошёл к куче и просто из белого молока вытащил скелета на вытянутую руку перед собой.*\n\n//Захват?",64123,null],[68851,"2026-06-22T21:08:44",5,"// с преимуществом",68850,null],[68852,"2026-06-22T21:09:12",5,"/roll@roll_bot",64123,null],[68854,"2026-06-22T21:09:30",9,"/roll +d20+4 атлетика",64123,null],[68856,"2026-06-22T21:09:55",5,"// успешно, опиши как и что делаешь",64123,null],[68857,"2026-06-22T21:09:55",32,"Если что меня нельзя застать в расплох и я готов ударить огненной стрелой",68851,null],[68858,"2026-06-22T21:10:08",5,"// скелета застали врасплох",68857,null],[68859,"2026-06-22T21:10:12",5,"// он полз по своим делам...",64123,null],[68860,"2026-06-22T21:11:42",9,"— Нежить... разумная? — *Леда просто хватил под ребра скелет огромными ручищами идержит на вытянутую руку перед собой. Путается понять с чем имеет дело.* — Успокойся умертвие, если меня понимаешь...",64123,null],[68861,"2026-06-22T21:12:11",32,"-Почти наверняка нет это скелет",68860,null],[68862,"2026-06-22T21:12:20",9,"//Бля что кинуть, леда тож наполовину мертвец, подкласс теневой магии, даж навык называется сила могилы",64123,null],[68863,"2026-06-22T21:12:39",5,"// хочешь что-то интересное?",68862,null],[68864,"2026-06-22T21:12:51",9,"//Если что — кину скелета ^^",64123,null],[68865,"2026-06-22T21:12:54",32,"А кинь убеждение убеди его заговорить!",64123,null],[68866,"2026-06-22T21:12:58",9,"//Сам решай)",68863,null],[68867,"2026-06-22T21:13:19",5,"// ну вот идеи есть, выбирайте что кидать, вдруг получится",68865,null],[68868,"2026-06-22T21:13:56",32,"// ну я чисто по приколу попробую телепатией к нему обратится если жертва понимает хоть один язык он услышит.\n-Ты имеешь разум?",68863,null],[68869,"2026-06-22T21:14:43",5,"// кидай что хочешь связанное",68868,null],[68870,"2026-06-22T21:14:47",32,"/варварство это заразно",68868,null],[68871,"2026-06-22T21:15:07",32,"Выступление",68869,null],[68872,"2026-06-22T21:15:24",32,"/roll d20+4",64123,null],[68874,"2026-06-22T21:15:48",9,"— Мёрвым неведом покой. Что держит тебя здесь, кто ты.",64123,null],[68875,"2026-06-22T21:17:17",32,"(как минимум товарищей развлеку своими попытками заговорить с безмозглым (это буквально) скелетом)",68873,null],[68876,"2026-06-22T21:17:48",9,"*Всё ещё пытается понять разумная ли нежить. Леда немного пришёл в себя и если что приготовился метнуть скелета.*\n\n//Заготавливаю метпние скелета как импровизированное если он агрессивный. Вес высушенного скелета 5-7 кд, мокрого и тд в 2-3 раза больше, должен смочь",64123,null],[68877,"2026-06-22T21:17:48",5,"Скелет бессмысленно дёргался в руках великана. Короткий ржавый меч лежал в тумане в траве. Захват был столь внезапен, что скелет ничего не успел сообразить.\n\nПри первых звуках телепатического сообщение скелет перестал дёргаться. Он повернул голову к три-крину и начал яростно щёлкать челюстью.",64123,null],[68878,"2026-06-22T21:18:44",9,"//Я тож не успел сообразить, сделал первое что в голову пришло",64123,null],[68879,"2026-06-22T21:18:47",32,"//если он хочет ответить то я его и телепатией слушаю)",68877,null],[68880,"2026-06-22T21:19:03",5,"В твоей голове тихо",68879,null],[68881,"2026-06-22T21:19:31",9,"*Тупо смотрит на это чудо, медленно приподняв бровь.*\n\n— Понимаешь меня? Кивни.",68877,null],[68882,"2026-06-22T21:19:43",32,"-Хмм замри! (Командую скелету.)\n//Мастер можно мне его приручить?",68880,null],[68883,"2026-06-22T21:19:59",5,"Скелет смотрит на тебя секунду. Потом щёлкает челюстью. Много раз",68881,null],[68884,"2026-06-22T21:20:05",5,"// кидай дрессировку",68882,null],[68885,"2026-06-22T21:20:20",32,"Это от какой характеристики?",68884,null],[68886,"2026-06-22T21:20:30",5,"// уход за животными, мудрость",64123,null],[68887,"2026-06-22T21:20:49",32,"/roll d20+2",64123,null],[68890,"2026-06-22T21:21:12",9,"*Просто берет верёвку и обвязывает костяк плотно, вешает на спину.*\n\n//Где то я это видел но там был лич",68883,null],[68892,"2026-06-22T21:22:13",9,"//Ни михи но деда. Ужс 🫠",64123,null],[68893,"2026-06-22T21:22:27",5,"Он снова смотрит на тебя. И замирает. Продолжает смотреть на богомола",68882,null],[68894,"2026-06-22T21:22:27",32,"//я так понимаю это успех?",68888,null],[68895,"2026-06-22T21:22:40",5,"// ты связал скелета и повесил за спину?",68890,null],[68896,"2026-06-22T21:23:21",5,"Скелёт висит на спине великана и совсем не дёргается. Пустые глазницы направлены на три-крина.",64123,null],[68897,"2026-06-22T21:24:00",32,"//(это точно эпический момент. Так как приручение я просто по приколу кинул)",68893,null],[68898,"2026-06-22T21:24:29",9,"— Время будет. — *Пошёл к дороге, к тому самому пню.*\n\n//Теперь предлагаю точно их ждать",64123,null],[68899,"2026-06-22T21:26:22",32,"Сижу и рассматриваю скелета. Осматриваю кости и прислушиваюсь к магии костяка.\n(Можно аркану кинуть на изучение костяка с помехой?)",64123,null],[68900,"2026-06-22T21:26:37",5,"// давай",68899,null],[68901,"2026-06-22T21:29:08",32,"/roll 2 d20+5",64123,null],[68903,"2026-06-22T21:29:30",47,"Талон пока в шоке. Но ничего не делает",64123,null],[68904,"2026-06-22T21:29:47",32,"12+5 арканы на изучение",68902,null],[68905,"2026-06-22T21:30:30",32,"/А почему оно ещё и 1 д20 кинули после 2д20?",68902,null],[68906,"2026-06-22T21:30:41",47,"/написал неправильно",64123,null],[68907,"2026-06-22T21:30:56",32,"/Пробел ставить не нужно было?",68906,null],[68908,"2026-06-22T21:31:12",5,"// да, надо было 2d20+5",64123,null],[68909,"2026-06-22T21:31:24",5,"// или чтобы само считало помеху с минусом",64123,null],[68910,"2026-06-22T21:31:28",5,"/r -d20+5",64123,null],[68912,"2026-06-22T21:31:42",5,"// большие кубы всем летят...",64123,null],[68913,"2026-06-22T21:34:18",32,"//Спасибо за пояснение",68912,null],[68914,"2026-06-22T21:34:22",5,"Это скелет, голые кости, к тому же мокрые и покрытые иголками и землёй.\n\nСудя по лёгкости его \"приручения\" скелет не подчиняется воле могущественного мага. \n\nСкелет прятался в тумане, это может быть как-то связано",68902,null],[68915,"2026-06-22T21:35:37",32,"-Ну туман явно некротической энергией напитан потому и поднялась нежить. Почти уверен что это не единственная нежить что мы тут встретим",68914,null],[68916,"2026-06-22T21:36:45",32,"-Назову тебя Костяк.",68914,null],[68917,"2026-06-22T21:37:19",5,"// одно имя на всех походу",68916,null],[68918,"2026-06-22T21:38:07",5,"Скелет висит и не двигается. Его глазницы направлены на тебя, но он не реагирует",68916,null],[68919,"2026-06-22T21:38:47",32,"//ну не Костян же его называть? И уж точно не щелкунчик:)",68917,null],[68920,"2026-06-22T21:39:15",32,"-Леда сними его пожалуйста.",68918,null],[68921,"2026-06-22T21:39:27",47,"В шоке",64123,null],[68922,"2026-06-22T21:39:29",47,"Талон",64123,null],[68923,"2026-06-22T21:39:40",47,"Ему кстати в тумане не нравится. Взял клинок и щит",64123,null],[68924,"2026-06-22T21:40:32",9,"*Гигант послушался, он кстати привёл всех к тому пню. Так то он стал большим и сильным из за проклятия, так что гордости за свою величину и силу у него нет.*",64123,null],[68925,"2026-06-22T21:40:49",9,"*Костяк лежит под пнём.*",64123,null],[68926,"2026-06-22T21:41:13",32,"(жук был увлечен своим исследованием и только из-за своего прошлого охотника в племени следил по сторонам но разум был занят другим)",64123,null],[68927,"2026-06-22T21:41:59",5,"Пень очень большой и на нём хватает места всем. Но каждый сидящий ощущает, что пню всё это не нравится.",68924,null],[68928,"2026-06-22T21:42:07",47,"Я пока не могу понять зачем Талон пошёл сюда/",64123,null],[68929,"2026-06-22T21:42:19",32,"-Костян (общаюсь только с скелетом) встань",68925,null],[68930,"2026-06-22T21:42:50",32,"//Ну я на пень не садился только рядом качал навык дрессировка",68927,null],[68931,"2026-06-22T21:43:17",5,"Скелет полежал несколько секунд, а затем двинулся. И пополз по земле. Прочь от вас. К тропе.\n\nПриказ богомола его не остановил. Он всё ползёт. Но медленно.",68925,null],[68932,"2026-06-22T21:43:38",9,"*Леда не сидит, он всегда стоит, даже когда спит опирается на что-то просто, ему очень неудобно лежать по своим причинам.*",68927,null],[68933,"2026-06-22T21:43:52",5,"// ну смотри на объявление, зачем герой мог взяться за нгео",68928,null],[68934,"2026-06-22T21:43:56",9,"— ... с пнём что-то не так. Уходим.",68931,null],[68936,"2026-06-22T21:44:24",32,"-хмм страно Костяк реагирует неадекватно.",68931,null],[68937,"2026-06-22T21:44:27",47,"/что можно придумать чуваку чья задача служить ордену. Но он его подвёл. Потерял большую часть возможностей (до упадка 7 лвл +-). По причине того, что яд уничтожил нахуй его",64123,null],[68938,"2026-06-22T21:44:44",47,"/типо заработать денег на лечение?",64123,null],[68939,"2026-06-22T21:44:58",5,"Костяк не реагирует на твои слова и ползёт дальше. Понемногу приближаясь к тропе",68936,null],[68940,"2026-06-22T21:45:35",32,"(жук согласился с словами Леды и двинулся за ползущим скелетом наблюдая за происходящим)",68936,null],[68942,"2026-06-22T21:46:18",5,"Жук следует за скелетом, тот уже переполз тропу и куда-то движется. Всё так же медленно",68940,null],[68943,"2026-06-22T21:46:28",32,"Я осматриваюсь внимательно.",64123,null],[68944,"2026-06-22T21:46:33",32,"/roll@roll_bot",64123,null],[68946,"2026-06-22T21:47:09",32,"//Пардоньте по привычке кинул через всплывающие\n19 на внимательность",68945,null],[68947,"2026-06-22T21:47:15",5,"Несложно догадаться, куда ползёт скелет. К своему ржавому мечу",68945,null],[68949,"2026-06-22T21:47:45",47,"- Фух - вновь смена оружия. В руках лук.",64123,null],[68951,"2026-06-22T21:48:15",9,"//Мне это скажут?)))",68947,null],[68955,"2026-06-22T21:49:20",9,"//Я щас столтко приколов имею в уме, лишь бы перс знал, го я тож агализ кину",64123,null],[68956,"2026-06-22T21:49:21",32,"(я решаю ещё раз выступить перед скелетом в основном транслируя ощущения)\n(Подхожу касаюсь скелета и передаю ощущение защищённости)",68947,null],[68957,"2026-06-22T21:49:43",32,"/roll d20+4",64123,null],[68959,"2026-06-22T21:49:46",5,"// кидай",64123,null],[68960,"2026-06-22T21:49:55",5,"// опиши что именно передаёшь",68958,null],[68961,"2026-06-22T21:50:11",9,"/roll 1d20+2 анализ происходящего, молчат все",64123,null],[68963,"2026-06-22T21:50:29",9,"//Понимаю?)",64123,null],[68964,"2026-06-22T21:50:39",5,"Очевидно, скелет ползёт к своему оружию. А жук идёт за ним, ослеплённый верой в дружелюбие нежити",68962,null],[68965,"2026-06-22T21:50:51",32,"//отрицание агрессии, дружелюбие, спокойствие.",68960,null],[68966,"2026-06-22T21:51:02",47,"/насколько густой туман?",64123,null],[68967,"2026-06-22T21:51:12",5,"// не, давай словами,  что ты ему сказал",68965,null],[68968,"2026-06-22T21:51:20",32,"(ну вообще-то у меня громовая волна готова",68964,null],[68970,"2026-06-22T21:51:30",5,"// туман густой, но только по земле. Не даёт видеть свои башмаки",68966,null],[68971,"2026-06-22T21:51:41",9,"*Леда просто неспеша обгоняет их, берёт тот ржавый меч и поднимает повыше чтобы скелет не достал, на вытянутой руке.*",68964,null],[68972,"2026-06-22T21:51:44",5,"// а это что голиаф понял, а не ты)",68968,null],[68973,"2026-06-22T21:51:50",32,"А смысл у него интелект 3 он не понимает речи",68967,null],[68974,"2026-06-22T21:52:28",5,"// вообще-то 6. Ну и смысл, в том, что игроки конкретно говорят",68973,null],[68975,"2026-06-22T21:52:30",32,"Я понял куда он ползёт и этого чтобы 2+2 хватило",68972,null],[68976,"2026-06-22T21:53:10",32,"У зомби 3 в бестиарии было",68974,null],[68977,"2026-06-22T21:53:30",5,"Скелет дополз до голиафа. Он сидит у его ног и смотрит вверх. Последние послания жука не возымели видимого эффекта.",68958,null],[68978,"2026-06-22T21:53:54",9,"— Ненависть нежити сильна. — *Заключил гигант, он ощущал что-то родное, но нет ненависти к живым.*",64123,null],[68979,"2026-06-22T21:53:56",47,"Я хочу прислушаться. К интуиции",64123,null],[68980,"2026-06-22T21:54:33",5,"// мм кидай природу или выживание",68979,null],[68981,"2026-06-22T21:54:34",9,"//Интуиция говорит что дед был самым вменяемым, великан и жук как дети",68979,null],[68982,"2026-06-22T21:54:45",5,"/r -1",64123,null],[68984,"2026-06-22T21:54:59",47,"/r d20+2",64123,null],[68986,"2026-06-22T21:55:09",47,"/выживание",64123,null],[68987,"2026-06-22T21:55:29",5,"Скелет тянет руку к юбке голиафа и выхватывает оттуда камень. Какой использует для пращи",68983,null],[68988,"2026-06-22T21:55:54",9,"//Есть такой",64123,null],[68989,"2026-06-22T21:56:02",5,"// чего кинжалы не носишь)",68988,null],[68990,"2026-06-22T21:56:06",47,"/",64123,null],[68991,"2026-06-22T21:56:16",47,"Я хочу убить скелета/",64123,null],[68992,"2026-06-22T21:56:29",9,"//Смысл?",68989,null],[68993,"2026-06-22T21:56:30",47,"/тем более по лору эльфы одни из самых жёстких ненавистников нежити",64123,null],[68994,"2026-06-22T21:56:49",9,"//Чел, делай чё хош, я ток за",64123,null],[68995,"2026-06-22T21:56:59",5,"Ты в лесу, спутники очевидно нашли дорогу к карьеру. Туман стелется по земле, но другой нежити рядом не видно.",68985,null],[68996,"2026-06-22T21:57:12",5,"// чтобы вытаскивать у тебя из кармашка)",68992,null],[68997,"2026-06-22T21:57:16",47,"/ощущаю ли опасность? Напряжение?",68995,null],[68998,"2026-06-22T21:57:17",32,"(ну первым среагировал на выхватывание камня и ударил в него огненной стрелой",64123,null],[68999,"2026-06-22T21:57:20",47,"/такого типа интуиция",64123,null],[69000,"2026-06-22T21:57:35",9,"//Пф, ну только для этого мб)",68996,null],[69001,"2026-06-22T21:57:51",5,"Ощущаешь напряжение от тумана. Он неестественный.\n\nИ от скелета. Он агрессивный",68997,null],[69002,"2026-06-22T21:57:59",5,"// кидай попадание",68998,null],[69003,"2026-06-22T21:58:15",32,"/roll d20+5",64123,null],[69005,"2026-06-22T21:58:29",32,"/roll d10",64123,null],[69007,"2026-06-22T21:59:16",5,"// опиши куда целишься и с каким эффектом попал. Убиваешь скелета или нет(ты можешь)",64123,null],[69009,"2026-06-22T21:59:19",47,"- Я бы не хотел здесь задерживаться. Давайте ускоримся - мрачно произносит Талон",64123,null],[69010,"2026-06-22T21:59:30",47,"/это после смерти скелета",69009,null],[69011,"2026-06-22T22:00:47",32,"//я целился в позвоночник\nСтрела взорвала и разорвала грудную клетку на отдельные рёбрышки",69007,null],[69014,"2026-06-22T22:01:33",32,"/Я был со спины нежити",69011,null],[69015,"2026-06-22T22:01:38",5,"Одни кости белеют в тумане на траве. Вот и помер дед Костяк",64123,null],[69017,"2026-06-22T22:02:26",32,"Ну почему же? Я подбираю череп и более менее целые кости складываю в сумку на парящем диске",69015,null],[69018,"2026-06-22T22:02:32",9,"— Нежить здесь не разумна. — *Кивнул Леда и повёл всех дальше по тропинке, конечно усадив жука обратно на шею.*",64123,null],[69019,"2026-06-22T22:03:05",47,"Напряжение в движениях Талона достигает максимума. Стрела на тетиве. Он сам как тетива.",64123,null],[69020,"2026-06-22T22:03:43",9,"//Имба на 1х уровнях голиафом носить лёгкого волшебника на спине. Пока нет зональных эффектов со спасом всё отлично",64123,null],[69022,"2026-06-22T22:04:13",32,"(Жук спокойно осматривал местность и прикидывал путь вперёд)",64123,null],[69023,"2026-06-22T22:04:17",32,"Внимательность",64123,null],[69024,"2026-06-22T22:04:28",32,"/roll d20+4",64123,null],[69026,"2026-06-22T22:05:04",5,"Вы уже нашли тропу и уверенно движетесь. Уровень тумана всё повышается, но других скелетов не видно",64123,null],[69028,"2026-06-22T22:05:14",5,"// готовы к карьеру?",64123,null],[69030,"2026-06-22T22:05:41",32,"/Да я готов.",69028,null],[69031,"2026-06-22T22:08:57",9,"//Где дддееееееддддд 🥲",64123,null],[69032,"2026-06-22T22:09:25",32,"//На парящем диске он почти сдох похоже",69031,null],[69033,"2026-06-22T22:09:39",9,"//Я лично за то чтобы деда ждать ~",64123,null],[69034,"2026-06-22T22:09:56",5,"// окей",69033,null],[69035,"2026-06-22T22:10:01",32,"//Хорошо перерыв?",69033,null],[69036,"2026-06-22T22:10:11",5,"// тогда ждём деда",64123,null],[69037,"2026-06-22T22:10:27",47,"За/",64123,null],[69048,"2026-06-22T22:28:18",32,"Ну сегодня я уже не смогу похоже. Спокойной ночи",64123,null],[69049,"2026-06-22T22:35:57",5,"// спокойной",69048,null],[69090,"2026-06-22T23:38:22",40,"/сорян, я домой пришел и отрубился",64123,null],[69091,"2026-06-22T23:38:33",40,"/реально как дед",64123,null],[69096,"2026-06-22T23:41:27",5,"// возможно завтра сыграем",64123,null],[69097,"2026-06-22T23:41:38",5,"// можешь почитать что тут было если хочешь",69090,null],[69109,"2026-06-22T23:46:15",40,"/да, чтоб ориентироватсья",64123,null],[69110,"2026-06-22T23:46:20",40,"/ща",64123,null],[69124,"2026-06-23T02:03:39",5,"// игра будет сегодня (вторник) в 20:00",64123,null],[69216,"2026-06-23T10:24:51",40,"/я буду, теперь точно)",64123,null],[69607,"2026-06-23T14:39:46",40,"/короче вы массажировали скелета всей толпой, так?",64123,null],[69608,"2026-06-23T14:42:38",47,"Не/",69607,null],[69627,"2026-06-23T15:26:35",40,"/не все? Только великан?))",69608,null],[69631,"2026-06-23T15:45:01",47,"/и маг",69627,null],[69635,"2026-06-23T15:54:12",9,"//Я тут",64123,null],[69636,"2026-06-23T15:56:30",32,"//Я буду вечером но скорее всего крайне заебаный",69124,null],[69703,"2026-06-23T16:52:50",40,"/я буду веселый. У меня одно вдохновение на перекид",64123,null],[69704,"2026-06-23T16:53:13",40,"/и я намерен перекинуть @Xaosick твою 20 на 1))))",64123,null],[69705,"2026-06-23T16:53:20",40,"/шучу, брат",64123,null],[69747,"2026-06-23T17:10:50",32,"//ты мне за транспортные услуги за проезд на парящем диске должен!",69704,null],[69748,"2026-06-23T17:12:03",32,"/я тоже шучу но мне действительно может быть нужна твоя помощь в добыче редких алхимических ингредиентов",69705,null],[69751,"2026-06-23T17:13:37",40,"/ты на моей морщинистой жопе будешь выращивать редкие алхимические ингредиенты?",64123,null],[69752,"2026-06-23T17:13:45",40,"/какая моя помощь?))",64123,null],[69753,"2026-06-23T17:14:00",40,"/не, я рад помочь. Ты только дай инструкции",64123,null],[70087,"2026-06-23T18:42:27",32,"/нужны ещё твои духмяные травы которые деда почти мгновенно в наркотрип затянули. Добудь их и  древесной смолы/горючей коры (по типу бересты из берёзы) и угольного порошка.\nИ пращу чтобы ты мог эти снаряды потом метать",69753,null],[70159,"2026-06-23T19:19:08",40,"/я лучше просто сделаю затяг петрушкой",64123,null],[70169,"2026-06-23T19:24:04",5,"// одного раза не хватило?)",64123,null],[70179,"2026-06-23T19:26:56",47,"Талон на готове идет пригибаясь низко к земле, дабы его укрыл туман (пока без рп отыгрыша, сори)",64123,null],[70182,"2026-06-23T19:27:06",47,"/r d20+6 скрыт",64123,null],[70225,"2026-06-23T19:45:17",40,"/Лан если ты меня таскал, хапку могу подарить",70087,null],[70226,"2026-06-23T19:45:55",40,"/ну и через внимательность поищу для тебя чё там ты хочешь. Но если не найду, сорян",64123,null],[70258,"2026-06-23T19:51:57",5,"// ну что, собирайтесь",64123,null],[70260,"2026-06-23T19:52:17",47,"Тут/",64123,null],[70263,"2026-06-23T19:53:42",5,"// очень жду рп отыгрыш а не просто палку ходилку",70179,null],[70265,"2026-06-23T19:54:16",47,"/я вот сейчас планирую создать такого рп персонажа. Что-то никто не кричит: го я подключусь, раскроем перса!",64123,null],[70268,"2026-06-23T19:54:43",47,"/этот пока без рп. Его недавно разьебало, он скромный. В напряге.",64123,null],[70282,"2026-06-23T19:59:55",5,"// ещё раз музыка",64123,null],[70283,"2026-06-23T19:59:57",5,"https://www.youtube.com/watch?v=iG7JDXCd-pc",64123,null],[70285,"2026-06-23T20:00:26",5,"Лес заканчивается, отряд выходит на открытую местность. Туман стал менее густым, сквозь него видно, но он расстилается на большую высоту.\n\nВпереди стена тумана, выходящая из огромного провала вниз. Это карьер.  И вы не видите его дальних краёв.\n\nСквозь завесу тумана впереди вы видите неясный мерцающий огонёк. И какой-то очень знакомый звук. Дождь усилился и мешает определить, что же это.",64123,null],[70286,"2026-06-23T20:00:52",5,"Hard \n@H_Kruz \n@cirson\n@Xaosick",64123,null],[70287,"2026-06-23T20:02:06",47,"/замечательно. Я могу скрыться даже просто стоя на месте.",64123,null],[70288,"2026-06-23T20:03:08",40,"-где мы бл...ть?",64123,null],[70289,"2026-06-23T20:03:23",40,"Дед очнулся",64123,null],[70290,"2026-06-23T20:03:40",47,"Талон, используя свои великолепные навыки скрытности сливается с дождём",64123,null],[70291,"2026-06-23T20:03:50",47,"Он исчезает даже для союзников оставляя их в неведении",64123,null],[70292,"2026-06-23T20:07:15",40,"Дед (где бы он не был) осматривает внимательнее свечение вдали",64123,null],[70294,"2026-06-23T20:07:25",40,"Напоминает ли ему чё нить",64123,null],[70295,"2026-06-23T20:07:33",5,"// восприятие либо история хд",64123,null],[70296,"2026-06-23T20:08:01",9,"*Леда просто идёт вперёд, ничто его не может смутить.*",64123,null],[70297,"2026-06-23T20:08:20",9,"/roll 1d20+3 восприятие кину всё же, пусть",64123,null],[70299,"2026-06-23T20:08:33",40,"/r d20+1",64123,null],[70301,"2026-06-23T20:09:10",40,"Дед вспомнил детство",64123,null],[70302,"2026-06-23T20:09:13",40,"(история)",64123,null],[70303,"2026-06-23T20:09:29",5,"Вы оба понимаете, что огонёк похож на свет факела. Самого обычного. Который видели тысячу раз",64123,null],[70310,"2026-06-23T20:10:43",5,"// хмм давайте подождём жука что ли",64123,null],[70319,"2026-06-23T20:19:18",40,"Дед копает и делает волчью яму (ну пока ждём. Каждый 10 минут буду одно чё нить делать)",70303,null],[70344,"2026-06-23T20:26:15",40,"Дед копает ячейку (типо окоп но на одного) для наших стрелков",64123,null],[70352,"2026-06-23T20:26:52",5,"Дед успешно выкопал себе яму",64123,null],[70354,"2026-06-23T20:27:02",5,"// но я жду жука чтобы продолжать играть",64123,null],[70364,"2026-06-23T20:28:28",9,"//Жду жучару",64123,null],[70379,"2026-06-23T20:32:03",40,"@Xaosick",64123,null],[70391,"2026-06-23T20:35:42",32,"//Простите за опоздание у меня был завал на работе",64123,null],[70392,"2026-06-23T20:35:56",32,"Я тут",64123,null],[70393,"2026-06-23T20:36:07",5,"// ура",64123,null],[70395,"2026-06-23T20:36:11",5,"// давай вливайся",64123,null],[70398,"2026-06-23T20:36:55",32,"Я лепкой земли помогаю деду справиться за 12 секунд",70319,null],[70399,"2026-06-23T20:37:00",5,"Теперь вы стоит ещё и около окопа, выкопанного дедом",70285,null],[70403,"2026-06-23T20:37:38",40,"-Молодец и холодец и на дуде игрец",64123,null],[70405,"2026-06-23T20:37:45",40,"-и хера тебе в попец",64123,null],[70406,"2026-06-23T20:37:46",5,"Огонёк приближается и разделяется на 2 части. Вы слышите стук копыт",64123,null],[70408,"2026-06-23T20:37:58",40,"-В укрытие!",64123,null],[70409,"2026-06-23T20:38:02",40,"Дед в окоп",64123,null],[70414,"2026-06-23T20:39:00",40,"-Ебал-воевал, меня так просто не возьмёшь! Мужики, - говорю своим, - от тута волчья яма. Не упадите",64123,null],[70418,"2026-06-23T20:40:23",32,"/я прикинул и по пути лепкой земли сделал подземные полости на дороге человека пешего выдержит а вот лошадь провалится на метр в глубь.",64123,null],[70420,"2026-06-23T20:40:55",5,"// ох-хо-хо, где сделал эту полость?",70418,null],[70421,"2026-06-23T20:40:59",40,"/а чё ты землю копаешь даже без проверки кубов?",64123,null],[70423,"2026-06-23T20:41:03",32,"/Несколько таких ям на пути откуда слышен стук копыт",70418,null],[70426,"2026-06-23T20:41:18",32,"(заговор лепка земли)",70421,null],[70428,"2026-06-23T20:41:33",40,"/будь у меня такой перс я бы блять только и делал что траншеи и окопы",64123,null],[70429,"2026-06-23T20:41:37",40,"/у сука",64123,null],[70432,"2026-06-23T20:41:49",9,"— Мне будет трудно спрятаться, поможешь? — *Леда просит ему яму чтобы спрятаттся.*",70423,null],[70433,"2026-06-23T20:41:50",5,"// проверку магии сл 15 всё же. Конструкцию ты придумал сложную",64123,null],[70434,"2026-06-23T20:42:08",32,"На четвертом уровне бери черту для получения заговора",70428,null],[70439,"2026-06-23T20:42:58",32,"/А чем она сложная? Просто часть почвы вытянуть и разрыхлить оставив верхний слой целым он слежавшийся и полукругом уперт как мост",70433,null],[70443,"2026-06-23T20:43:31",5,"// окей, тогда лошадь останавливает просто",70439,null],[70444,"2026-06-23T20:44:12",32,"/она если попадет в квадрат провалится на пол метра/ метр в землю и скорее всего поломает лапы",64123,null],[70448,"2026-06-23T20:44:58",5,"/r +9",64123,null],[70450,"2026-06-23T20:45:12",32,"?",70448,null],[70451,"2026-06-23T20:45:30",5,"\\\\ пишу",64123,null],[70464,"2026-06-23T20:49:38",40,"/а звука нет?",64123,null],[70465,"2026-06-23T20:49:51",40,"/звук магии, вжух!",64123,null],[70466,"2026-06-23T20:50:05",32,"/А вербальный компонент это стрекотание на три-кринском",70464,null],[70467,"2026-06-23T20:50:23",40,"/Лан а земля копалась беззвучно?",64123,null],[70468,"2026-06-23T20:50:31",5,"// что-то я не понимаю, тогда конструкция сложная, кидай кубы",70439,null],[70469,"2026-06-23T20:50:40",47,"... /",64123,null],[70471,"2026-06-23T20:50:47",47,"Мастер что-то выдумать хочет/",64123,null],[70472,"2026-06-23T20:51:04",47,"Лепкой земли был снят дёрн. Вытащен пласт земли. После чего дёрн поместили обратно/",64123,null],[70473,"2026-06-23T20:51:15",32,"Абсолютно!",70472,null],[70475,"2026-06-23T20:51:19",47,"И уплотнили одним из свойств заговора/",64123,null],[70476,"2026-06-23T20:51:33",40,"/нет бы как я. - лопатой",64123,null],[70477,"2026-06-23T20:51:39",32,"/Да пешком пройдешь и не заметишь",70475,null],[70478,"2026-06-23T20:51:40",5,"// мм ладно убедили",64123,null],[70480,"2026-06-23T20:52:02",40,"@Xaosick",70467,null],[70481,"2026-06-23T20:52:54",32,"//но лошадь в пять раз тяжелее всадника. (Даже больше немного 600-700 килограмм в среднем) Она на скаку пробьёт дерн как будто его и не было",70478,null],[70482,"2026-06-23T20:53:12",5,"/r +4 акробатика",64123,null],[70484,"2026-06-23T20:53:28",32,"/разве что лёгкий шелест от движения земли такой на скаку услышать нереально",70467,null],[70486,"2026-06-23T20:53:49",32,"/это чьё?",70483,null],[70487,"2026-06-23T20:53:59",5,"// всадника",70486,null],[70488,"2026-06-23T20:54:11",32,"/Эму очень больно",70487,null],[70490,"2026-06-23T20:55:42",40,"Хорхе выглянул после услышанного разъеба всадника. Смотрит где второй огонь и что с тем кто упал",64123,null],[70491,"2026-06-23T20:55:44",5,"Из тумана выныривает всадник в тяжёлой броне. Ноги лошади попадают в импровизированную ловушку, она проваливается в землю и падает. Всадник с громкой руганью кубарем летит прямо под ноги вам.\n\nС его головы падает шлем, от доспеха отлетает какая-то металлическая брошка.",64123,null],[70493,"2026-06-23T20:56:17",40,"*тогда я ищу второй огонь*",64123,null],[70495,"2026-06-23T20:56:31",32,"-ааа всадник без головы!\n(Смазка под всадника)",70491,null],[70496,"2026-06-23T20:56:38",47,"Слежу за тем куда падает брошка, поднимаю её и продолжаю дальше прятаться в дожде",70491,null],[70500,"2026-06-23T20:57:36",5,"Два огонька факела уже близко к вам. Услышав шум, они начинают приближаться гораздо быстрее. Вы слышите тяжёлые шаги",70493,null],[70502,"2026-06-23T20:57:54",5,"// садист",70495,null],[70506,"2026-06-23T20:58:19",32,"/дракон😁",70502,null],[70507,"2026-06-23T20:58:19",5,"/r +1",64123,null],[70509,"2026-06-23T20:58:46",5,"Удивительно ловким движением всадник встаёт на ноги и стоит прямо посреди лужи жира.",64123,null],[70510,"2026-06-23T20:59:25",47,"?",70496,null],[70511,"2026-06-23T20:59:28",5,"Брошка у тебя. На ней изображён некий символ: 3 серебряных полумесяца над синим пламенем на чёрном поле.",70496,null],[70512,"2026-06-23T20:59:31",32,"(и видит направленную на него руку с посохом фокусом жука с готовой сорваться огненной стрелой при первом движении)",70509,null],[70513,"2026-06-23T20:59:45",47,"Прячу её в кармане и отхожу на 30 фт/",70511,null],[70516,"2026-06-23T21:00:33",40,"-Это пизда...",64123,null],[70517,"2026-06-23T21:00:41",32,"(и в одной из нижних рук держит баночку с маслом готов кинуть/облить если подойдёт)(отложенное действие на движение рыцаря)",70512,null],[70518,"2026-06-23T21:00:51",5,"Лицо всадника искажено гневом, но он удивительно спокойно для положения говорит.\n\n— Не так быстро, три-крин. Я не желаю тебе зла",70512,null],[70519,"2026-06-23T21:00:57",5,"// кстати он не видит остальных",64123,null],[70521,"2026-06-23T21:01:43",47,"Талон наблюдает за ним. Ждёт действий всадника. Чему уж жизнь его научила, что не стоит лезть вперёд, если можно подождать развития событий. Он лишь кладёт на лук стрелу вновь",64123,null],[70525,"2026-06-23T21:02:01",32,"-Я просто не понимаю чего ты ко мне скакал. Ты меня пугаешь. А мог место смазки громовой волной ударить, цени",70518,null],[70528,"2026-06-23T21:02:30",40,"Хорхе прижался в дну окопа и слушает",64123,null],[70537,"2026-06-23T21:04:56",5,"Он окидывает тебя с ног до головы. И вместо гнева на лице постепенно появляется выражение удивления и уважения.\n\n— Мы, рыцари ордена Миф Драннора, патрулируем эти проклятые земли, охотясь на нежить. Любое движение вокруг карьера привлекает наше внимание. Ни одна нежить не покинет его",70525,null],[70543,"2026-06-23T21:05:01",32,"(жук был напряжён и действительно чуял шестым чувством подставу)",70525,null],[70553,"2026-06-23T21:06:30",47,"/r d20+2 проницательность",64123,null],[70555,"2026-06-23T21:06:37",32,"-а так ты друг? \nМы с друзьями, они кстати все держат тебя на прицеле, тоже на нежить охотится пока правда только одного скелета прибили но это детали",70537,null],[70557,"2026-06-23T21:06:46",32,"Выступление",64123,null],[70558,"2026-06-23T21:06:53",5,"Это воин в тяжёлой броне.",70554,null],[70559,"2026-06-23T21:07:02",32,"/roll d20+4",64123,null],[70564,"2026-06-23T21:07:22",47,"- Если ты и вправду тот, за кого себя выдаешь, я готов выступить вам в помощь - раздаётся из дождя",64123,null],[70566,"2026-06-23T21:07:35",5,"— Друг? Навряд ли. Но коли и вы охотитесь на нежить, то союзник",70555,null],[70568,"2026-06-23T21:07:48",9,"— Нежить. — *Из тумана сзади появляется рука гиганта и ложится рыцарю на плечо, мягко, без угрозы.* — Раскажи нам, друг. Наш путь лежит туда.",70537,null],[70573,"2026-06-23T21:08:38",5,"Огоньки впереди потухли. И вы больше не слышите шагов.\n\nОдин лишь рыцарь перед вами. И гигант за его спиной",64123,null],[70574,"2026-06-23T21:08:47",32,"-Я действительно думал что враг, раз скачет на нас без предупреждения. А если бы ты крикнул \"я друг не стреляйте\" мы бы тебя о ловушке предупредили. Так что сам виноват",70566,null],[70579,"2026-06-23T21:09:17",40,"Хорхе просто лежит смотрит в небо и слушает Тарантиновские диалоги",64123,null],[70583,"2026-06-23T21:09:53",32,"(И три-крин в пяти шагах перед рыцарем, погасил сияние магии огненного снаряда)",70573,null],[70586,"2026-06-23T21:10:20",5,"Всадник вздрагивает от неожиданности.\n\n— Нежить. Лезет из карьеры, покоя не даёт. Мы патрулируем поверх, вниз не спускаемся. Сбрасываем когда лезут",70568,null],[70588,"2026-06-23T21:10:49",9,"— Признавать ошибку хороший навык. — *Леда обошёл рыцаря к своим и попустил взгляд, немного смущённый (не в романтическом смысле).* — Простите за него.",70574,null],[70589,"2026-06-23T21:11:00",32,"-я хочу изучить источник. Возможно это по тайнику",70586,null],[70590,"2026-06-23T21:11:09",47,"Талон выходит из дождя, сначала показываясь на глаза. А потом отдаёт жетон",64123,null],[70593,"2026-06-23T21:11:31",5,"— Справедливо. Но кричать здесь — плохая идея. Их — Он показывает в сторону карьереа — Это беспокоит. Прокричи разок и жди десяток скелетов в гости",70574,null],[70595,"2026-06-23T21:11:46",32,"-Какую ошибку Леда? О том что ловушки не без полезны?",70588,null],[70597,"2026-06-23T21:12:04",40,"@elsio28 (будучи бывшим разведчиком, и коронером)\nХорхе по интонации голоса пытается уловить ложь в словах рыцарей",64123,null],[70598,"2026-06-23T21:12:10",5,"— Я не держу зла. В этих землях всем стоит быть настороже. И мне",70588,null],[70600,"2026-06-23T21:12:29",9,"— Ты сбил человека. Не извинился. (Извинись перед рыцарем)",70595,null],[70601,"2026-06-23T21:12:30",5,"// кидай проницательность с преимуществом",70597,null],[70607,"2026-06-23T21:13:14",32,"-Он первый начал.\nНо ладно, прости.\n(Сказал три-крин поддав в голос раскаяния)",70600,null],[70608,"2026-06-23T21:13:17",40,"/r d20+4+2",64123,null],[70610,"2026-06-23T21:13:20",40,"/r d20+4+2",64123,null],[70612,"2026-06-23T21:13:20",5,"— Спасибо, воин. — он делает небольшой поклон. — Подобная честность вызывает уважение.",70590,null],[70614,"2026-06-23T21:13:46",5,"— Не держу зла. Мы не враги",70607,null],[70616,"2026-06-23T21:14:26",32,"(к этому времени жир должен был испарится минута диалога прошла)",70614,null],[70617,"2026-06-23T21:14:41",5,"Этот паладин совершенно искренен. Ты не можешь найти даже намёка на неправду в его словах.",70611,null],[70619,"2026-06-23T21:14:59",9,"— Мы ищем некие ступени. Наш друг поведал о том что ему дорого, он оставил его там. — *Леда почти пряио сказал зачем они здесь и спросил почти прямо о месте.*",70612,null],[70620,"2026-06-23T21:15:04",5,"— Выходите, тут союзники! — отдаёт приказ рыцарь",64123,null],[70622,"2026-06-23T21:15:50",5,"К вам со спины подходят два воина с обнажёнными клинками. Они убирает мечи в ножны.\n\nЕщё два воина с тяжелыми арбалетами выступают из тьма впереди",64123,null],[70623,"2026-06-23T21:16:23",32,"-Слушай меня кличут Жук. А ты кто? \n(И показывая на каждого вытянутой ладонью по очереди представляет)\nЭто Талон, это Хорхе, а это Леда.",70620,null],[70627,"2026-06-23T21:17:15",5,"— Дорого? — паладин иронично усмехнулся — Как обычно, авантюристы лезут за золотом и будят нежить. А потом их проблемы решают другие.\n\n— Но я расскажу о карьере, что знаю",70619,null],[70628,"2026-06-23T21:17:39",32,"-Разве стрелковое эффективно против скелетов? Ты ещё в кость поди попади. \n(Совершенно не испугался жук он знал что их попробуют окружить и его расклад полностью устраивал)",70622,null],[70631,"2026-06-23T21:18:25",5,"— Глорир — воин поклонился — Приятно, познакомиться, о хитроумный три-крин\n\nОн слабо улыбнулся",70623,null],[70632,"2026-06-23T21:18:37",32,"-в нашем случае мы вам эту нежить поможем уничтожить раз и навсегда. Так что ты нам ещё и должен будешь.\n(Обижено сказал жук)",70627,null],[70634,"2026-06-23T21:19:23",32,"/Я иду к его лошадке. Хочу осмотреть на предмет травм.\nМедецина",70631,null],[70638,"2026-06-23T21:20:03",5,"— Мы не спускаемся вниз, стреляем сверху. — суровым голосом произнёс один из арбалетчиков.",70628,null],[70640,"2026-06-23T21:20:33",32,"/roll d20+4",70634,null],[70642,"2026-06-23T21:20:51",32,"Медицина",70641,null],[70645,"2026-06-23T21:21:22",5,"— Вы пришли уничтожить нежить? Что ж... если вам удастся. Обратитесь в аванпост ордена в городе рядом. Награда будет щедрая. Очень щедрая\n\n//рассказывает где найти пост ордена",70632,null],[70646,"2026-06-23T21:21:38",32,"- а знаешь что? Я пожалуй вас в этом начинании поддержу и то же магией в низ хочу покидаться",70638,null],[70649,"2026-06-23T21:22:27",5,"Ты осмотрел лошадь. Ноги повреждены, но не критично. ИСпольозвать как боевой транспорт уже не выйдет, но до конюшни довести получится",70634,null],[70650,"2026-06-23T21:23:04",5,"— О, ты волен делать, что хочешь. Пока это убивает нежить. — говорит тот же арбалетчик",70646,null],[70651,"2026-06-23T21:23:55",32,"-Уже не боец.\n(Коротко констатировал жук) \n-У меня нечем её врачевать. Ходить будет но хромать",70649,null],[70653,"2026-06-23T21:24:17",5,"— Заброшенный карьер состоит из множества ступеней. Каждая 10 футов в ширину и ещё около 10 вниз. И ступеней тут много.",70619,null],[70656,"2026-06-23T21:25:22",9,"— Не сможем избавить. — *Говорит скорее жуку чем рыцарю.* — Года, их не меньше, нежить восстаёт снова. Есть источник.",64123,null],[70657,"2026-06-23T21:25:24",5,"— Мы разберемся — паладин кивнул\n\nДругой воин подошёл и взял лошадь за уздцы. Она с трудом выбирается из ямы",70651,null],[70658,"2026-06-23T21:25:55",32,"//я могу лепкой земли выровнять пол чтобы её вытянуть",70657,null],[70660,"2026-06-23T21:25:59",40,"Хорхе молча вылез из ямы, мол, ничего необычного. Так и должно быть",64123,null],[70661,"2026-06-23T21:26:15",5,"Вы вспоминаете, что дед Алексий рассказал: тайник находится на второй или третей ступени. И на ступени наверху есть метка.",64123,null],[70667,"2026-06-23T21:26:50",32,"//мастер а если бы мы вступили с паладинами в бой мы бы имели шансы на победу с учётом подготовленной позии",70660,null],[70669,"2026-06-23T21:27:43",5,"// очень мало шансов, их 5 и высокий уровень. Но было бы много шансов прекратить драку",70667,null],[70671,"2026-06-23T21:28:04",32,"-План прост в своей дерзости. Обзаводится дальнобоем и просто чистим ступень за ступенью.\nЯ сделаю лепкой земли нам насыпь и бойницы",70661,null],[70672,"2026-06-23T21:28:23",40,"/после ядерного удара в виде кары мириться было бы не с кем",64123,null],[70674,"2026-06-23T21:28:36",32,"(жук уже просчитывал как будем действовать)",64123,null],[70675,"2026-06-23T21:28:44",5,"Воины с удивлением наблюдали за дедом",70660,null],[70677,"2026-06-23T21:29:00",40,"Хорхе прикрывает спину и идёт замыкающим",64123,null],[70678,"2026-06-23T21:29:10",32,"(на жука и кара не нужна урон средний с руки паладина (d8)5+3 )",70672,null],[70679,"2026-06-23T21:29:30",5,"— Могу лишь пожелать удачи. Чем дальше вниз, тем больше нежити.",70671,null],[70681,"2026-06-23T21:29:52",9,"— Мы не помощь — проблема. — *Леда грустно посмотрел на рыцаря, словно извинялся, и пошёл за группой.*",64123,null],[70682,"2026-06-23T21:29:59",40,"-может заготовим позиции тогда?",64123,null],[70684,"2026-06-23T21:30:15",5,"— Мы патрулируем поверху. Если совсем прижмёт, выбирайтесь и бегите к нам. Нежити вылезти мы не позволим",64123,null],[70686,"2026-06-23T21:30:48",32,"(жук кивнул и двинул к краю карьера.)",70684,null],[70688,"2026-06-23T21:31:41",5,"Мечники зажгли факела, арбалетчики встали за ними и сформировали квадрат.\n\nКапитан отряда наблюдает за вами.",64123,null],[70689,"2026-06-23T21:31:41",47,"/Талон не представлялся. Просьба учесть",70623,null],[70690,"2026-06-23T21:31:50",9,"*Леда крепко задумался о том что проще и безопаснее просто содержать деда чем лезть в карьер.*",64123,null],[70692,"2026-06-23T21:32:04",5,"// жук не знает имя эльфа?",70689,null],[70697,"2026-06-23T21:33:08",47,"/нет",70692,null],[70699,"2026-06-23T21:33:12",47,"Никто из вас не знает/",64123,null],[70701,"2026-06-23T21:33:23",40,"*как же всем похуй* подумал дед",64123,null],[70703,"2026-06-23T21:33:29",32,"Оттуда он (дистанция заговора 30 футов вроде) начал поднимать насыпь на уровень этого этажа вытягивая почву с двух сторон по пласту делая подъем по пятнадцать футов и мягкий уклон чтобы понемногу снижать по сути высокий (10футов мост) поднимая насыпь над уровнем ступеней карьера и собственно её опуская под наклон и по кругу на следующие ступени)",70686,null],[70704,"2026-06-23T21:33:35",40,"С грязным от земли ебалом",64123,null],[70705,"2026-06-23T21:33:36",47,"Даже если бы он представился. Это было бы чужое имя. Так как имена обладает страшным свойством. На них нацеливается часть заклинаний",64123,null],[70707,"2026-06-23T21:33:44",32,"(зато жук всех представил)",70689,null],[70710,"2026-06-23T21:33:51",47,"/нельзя так",70707,null],[70711,"2026-06-23T21:34:04",47,"/мой персонаж не представлялся",64123,null],[70713,"2026-06-23T21:34:06",32,"(да вроде же в начале представился в доме ещё)",70692,null],[70716,"2026-06-23T21:34:24",9,"//Самое прикольное то что Леда это имя которое Леда знает сам, а не его 😏👌",64123,null],[70717,"2026-06-23T21:34:33",47,"/не представлялся. Найди",70713,null],[70718,"2026-06-23T21:34:41",47,"/он молчал всё время",64123,null],[70719,"2026-06-23T21:34:49",32,"Ну ок тогда назвал тебя просто \"эльф\"",70717,null],[70721,"2026-06-23T21:35:15",5,"// так так",70703,null],[70722,"2026-06-23T21:35:20",5,"// ты делаешь лестницу?",64123,null],[70723,"2026-06-23T21:35:28",40,"-А вы чейние будете, молодые люди @elsio28",64123,null],[70725,"2026-06-23T21:35:35",32,"И фортификацию",70722,null],[70728,"2026-06-23T21:35:50",47,"/благодарю",64123,null],[70729,"2026-06-23T21:35:51",40,"-Какой фракции",64123,null],[70730,"2026-06-23T21:36:03",5,"Если вы накладываете это заклинание несколько раз, вы не можете поддерживать более 2 длительных эффектов одновременно. Вы можете действием отменить один из действующих эффектов",70725,null],[70731,"2026-06-23T21:36:10",5,"// не понял? это кому",70723,null],[70732,"2026-06-23T21:36:24",40,"/Паладинам",64123,null],[70733,"2026-06-23T21:36:26",9,"*Безучастно стоит, смотрит что делают остальные. Не знает чем помочь просто.*",64123,null],[70735,"2026-06-23T21:36:38",40,"-али государю какому присягнули?",64123,null],[70736,"2026-06-23T21:36:45",32,"//Нам с высоты отбиваться удобнее склон гладкий и пологий и крепче на 10 футов над карьерным",70725,null],[70744,"2026-06-23T21:37:31",32,"//Не ебет я делаю не длительный а ПОСТОЯННЫЙ ефект переместил землю и все не концентрируясь на ПЕРЕМЕЩЕНОЙ породе",70730,null],[70745,"2026-06-23T21:37:35",5,"— Орден Миф Драннора. Сохраняем порядок и справедливость в этом мире. Во славу Аскелатора! — паладин отвечает грязному деду",70735,null],[70747,"2026-06-23T21:38:10",40,"-Во славу! Аж душа радуется, хоть кто то занят благим делом",70745,null],[70748,"2026-06-23T21:38:41",5,"// так ещё раз, ты делаешь укрепление на стене карьера?",70744,null],[70749,"2026-06-23T21:38:43",9,"//Там кстати ток землю и почву можно, карьер часом не каменный?)",70730,null],[70751,"2026-06-23T21:38:54",5,"// нет, песчаный",70749,null],[70752,"2026-06-23T21:39:03",40,"-Ну... Укрепить позиции да потом спуститься? Или на авось сунем ебало к чертям что лезут оттудава?",64123,null],[70754,"2026-06-23T21:39:26",5,"Вы замечаете, что дождь усилился. Он бьёт по земле, размывая и так влажную почву",64123,null],[70757,"2026-06-23T21:39:28",9,"//Ммм, тоже такая се идея, вот бы наш, твердый чернёзём или глину ~",70751,null],[70760,"2026-06-23T21:39:45",40,"Дед закрылся щитом",64123,null],[70762,"2026-06-23T21:40:02",40,"От дождя",64123,null],[70765,"2026-06-23T21:40:09",47,"- Я бы предложил укрыться за стенами. Отдохнуть. Восстановить силы и продолжить путь - высказывается эльф",64123,null],[70770,"2026-06-23T21:40:43",5,"Это помогло. Капли стучат о щит. Как о крышу таверны",70762,null],[70774,"2026-06-23T21:41:07",40,"-так и бухнуть захотелось как про таверну вспомнил",64123,null],[70775,"2026-06-23T21:41:09",5,"// да, но какого-то эффекта достичь можно",70757,null],[70778,"2026-06-23T21:41:20",32,"/Нет я собираю землю и перемещаю на более низкий уровень карьера и по кругу делая высокую насыпь на которой мы стоим на уровень выше зомби. Землю чуть на искось вглубь карьера и с учётом дождя канавки стоки. \nЧтобы мы были на 10 футов выше текущей ступени карьера",70748,null],[70780,"2026-06-23T21:41:35",40,"/сделайте бля уже чё нить",64123,null],[70783,"2026-06-23T21:41:40",40,"/поехали дальше",64123,null],[70786,"2026-06-23T21:41:51",5,"// окей, каждая следующая ступень на 10 футов ниже",70778,null],[70789,"2026-06-23T21:42:08",5,"// если продолжишь далеко, это займёт часы работы",64123,null],[70794,"2026-06-23T21:42:29",32,"/Я делаю плавный спуск а не ступенчатый \nДа но мы никуда не спешим",70786,null],[70800,"2026-06-23T21:43:00",32,"А эта фортификация в последствии и самим паладинам пригодится",64123,null],[70801,"2026-06-23T21:43:02",47,"/отдыхаю.4 часа. Мне пох",70794,null],[70802,"2026-06-23T21:43:06",5,"// можешь смотреть вглубь карьера",70780,null],[70805,"2026-06-23T21:43:12",9,"*Леда стоит, дождь стекает по нему, волосы давно намокли, он просто стоит на краю обрыва, смотрит вдаль. Ветер треплет его прическу, золотистые глаза прорезают взглядом туман. Одинокая фигура на самом краю, просто наблюдает за стихией.*",64123,null],[70806,"2026-06-23T21:43:17",40,"-нам надо спуститься. На определенном участке выстроить заужение из земли и камней. Чтобы враг вынужден был соваться по одному. Часть идёт на спуск, а кто дальним боем владеет сидит на укреплении. Воюем от линии обороны",64123,null],[70811,"2026-06-23T21:43:30",40,"-шо, бля сопли жевать тут долго, не пойму?",64123,null],[70812,"2026-06-23T21:43:35",40,"-широкую на широкую",64123,null],[70813,"2026-06-23T21:43:37",9,"*Пока остальные спорят что делать.*",70805,null],[70817,"2026-06-23T21:43:45",40,"-ШИРОКУЮ НА ШИРОКУЮ...",64123,null],[70818,"2026-06-23T21:43:54",40,"-простите, кантузия",64123,null],[70819,"2026-06-23T21:43:58",5,"// окей",70794,null],[70820,"2026-06-23T21:44:10",9,"//Как я обожаю Леду, он может эпично нихуя не делать 🥰",64123,null],[70821,"2026-06-23T21:44:17",32,"-Я по сути для себя и арбалетчиков и делаю",70817,null],[70824,"2026-06-23T21:44:39",5,"Жук сделал насыпь на первой ступени. Она на уровне где вы стояли. Насыпь медленно размывает.",64123,null],[70828,"2026-06-23T21:44:58",40,"-Ой блять...",64123,null],[70830,"2026-06-23T21:45:11",40,"-хуй с ним, пусть на первой ступени...",64123,null],[70831,"2026-06-23T21:45:35",40,"-а мы блять в случае чего отступать будем в самое начало, до первой ступени?",64123,null],[70832,"2026-06-23T21:45:55",40,"-не лучше ли было углубиться и линию обороны поставить ниже",64123,null],[70833,"2026-06-23T21:46:14",40,"Ворчит старый пидорас",64123,null],[70834,"2026-06-23T21:46:22",9,"— Верёвки связать и спуститься по ним, узлы каждый фут. Обрыва нет. — *Леда посмотрел, песок то под углом, назад главное залезть.*",64123,null],[70835,"2026-06-23T21:46:27",32,"Ну не так медленно. Я подумал\nВнимательность.\nЯ ищу камни (скорее гальку)",70824,null],[70836,"2026-06-23T21:47:03",5,"Ты находишь камни, но мало. Не хватит, даже чтобы заполнить объём в 5 футов",70835,null],[70837,"2026-06-23T21:47:05",40,"Короче дед сел под деревом с паладинам",64123,null],[70838,"2026-06-23T21:47:28",5,"Паладины понаблюдали за вашими усилиями и пошли дальше патрулировать вокруг карьера",70837,null],[70839,"2026-06-23T21:47:53",32,"(задумался) \n-Леда будь добр наруби нам веток",70836,null],[70841,"2026-06-23T21:48:11",5,"Осмотрев стены, голиаф понял, что по ним можно залезть и без верёвки. Но из-за дождя можно соскользнуть",70834,null],[70843,"2026-06-23T21:48:25",40,"-даже паладины сьебали от меня",64123,null],[70844,"2026-06-23T21:48:54",32,"-Ты можешь предлагать свои планы и идеи. Дави опытом",70843,null],[70846,"2026-06-23T21:49:10",40,"-дави лечинку, муравей",64123,null],[70848,"2026-06-23T21:49:47",9,"*Значит верёвка нужна подумал он. Смотрит как его союзники ругаются, а после оборачивается и снова смотрит в даль.*",70841,null],[70851,"2026-06-23T21:50:41",32,"(жук подходит к Голиафу и дёргает за рукав) -пожалуйста наруби веток. Я хочу это построить",70848,null],[70852,"2026-06-23T21:50:46",47,"Эльф в трансе. Он наслаждается спокойствием, возможностью расслабиться. Шум дождя создаёт ощущения цикличности и повторяемости любых действий. Спокойствие накатывает волнами. Дыхание уравновешивается. Он и дождь. Единое целое. Он и дождь неотделимое.",64123,null],[70854,"2026-06-23T21:51:08",5,"Дождь немилосердно бьёт авантюристов, готовящих спуск. Лишь дед надёжно укрыт от него.\n\nСтук капель разносится по карьеру. Из глубин в ответ доносится невнятный хруст.",64123,null],[70856,"2026-06-23T21:51:15",40,"-на волчьих кишках спустимся. Вместо веревок сойдут",64123,null],[70857,"2026-06-23T21:51:20",9,"— Ладно. — *Он не понимает плана, идет собирать ветки.*\n\n//Рыцари далеко?",70851,null],[70862,"2026-06-23T21:51:45",32,"(Жуку было нормально хитин не даёт замёрзнуть а мантия не промокает)",70851,null],[70865,"2026-06-23T21:51:53",5,"// факела рыцарей снова зажглись, 90 футов",70857,null],[70867,"2026-06-23T21:52:23",5,"// ты собираешь хворост в лесу?",70857,null],[70870,"2026-06-23T21:52:34",40,"Наблюдаю за теми кто ушел и за огнями",70865,null],[70873,"2026-06-23T21:52:45",32,"-Спасибо друг!\n(Радостно сказал жук и начал тягать землю к карьеру чтобы ускорить процесс)",70857,null],[70879,"2026-06-23T21:53:16",32,"/не мне нужно прямо много чтобы использовать их как опоры укрепления на манер корней",70867,null],[70882,"2026-06-23T21:53:32",5,"// тогда сбора веток не хватит)",70879,null],[70883,"2026-06-23T21:53:34",40,"/как ещё раз выглядит место куда спускаемся?",64123,null],[70885,"2026-06-23T21:53:46",32,"/чтобы уменьшить размытие а галькой зафиксировать края",70879,null],[70891,"2026-06-23T21:54:08",32,"/Я и говорил что наруби прямо капитально веток",70882,null],[70894,"2026-06-23T21:54:21",32,"И именно веток разветвленных",70891,null],[70895,"2026-06-23T21:54:34",5,"Огромный карьер, затянутый туманом. Чем ниже, тем он гуще. Вы видите только 2 ступени внизу, остальное лишь угадывается.\n\nКаждая ступень идёт всё ниже и ниже. 10 футов в ширину, 10 в высоту",70883,null],[70896,"2026-06-23T21:55:07",5,"По ступеням возможно лазать без приспособлений. Но дождь несколько затрудняет это",64123,null],[70898,"2026-06-23T21:55:54",5,"// нужен топор, а скорее инструменты плотника",70891,null],[70899,"2026-06-23T21:55:55",40,"Я кидаю камень вниз. Отсчитываю когда услышу звук падения. Короче чтобы понять расстояние. Ускорение свободного падения 10м/с",70895,null],[70903,"2026-06-23T21:56:11",5,"Прям далеко вперёд?//",70899,null],[70904,"2026-06-23T21:56:34",40,"/Ну да. Чтобы примерно понять",70903,null],[70905,"2026-06-23T21:56:55",32,"/Мне нужны просто ветви без обработки потому только топор но не нужны прямо большые потому великан их может сломать просто руками",70898,null],[70909,"2026-06-23T21:57:44",5,"Проходит около 3 секунд. Звук камня, разбивающего что-то хрупкое",70899,null],[70911,"2026-06-23T21:57:58",40,"-яйца?",64123,null],[70912,"2026-06-23T21:58:03",5,"// это займёт всю ночь, если великан согласен. И это нелёгкий труд",70905,null],[70913,"2026-06-23T21:58:13",5,"// можешь кинуть анализ или природу",70911,null],[70915,"2026-06-23T21:58:26",32,"-Череп",70911,null],[70918,"2026-06-23T21:58:43",47,"Момент с возвращением жетона учтён? /",70909,null],[70920,"2026-06-23T21:58:49",32,"Ну я готов работать а вот готов ли великан?",70912,null],[70923,"2026-06-23T21:59:02",40,"/r d20+1+2",64123,null],[70926,"2026-06-23T21:59:11",40,"/анализ",64123,null],[70928,"2026-06-23T21:59:15",5,"// вопрос ему) Hard",70920,null],[70931,"2026-06-23T21:59:41",5,"Это кости. Или череп. Твой камень только что убил скелета. Возможно.",70924,null],[70938,"2026-06-23T22:00:42",5,"// ещё предлагаю обдумать шансы спокойного сбора веток ночью в диком лесу. В одиночку",70920,null],[70952,"2026-06-23T22:02:28",9,"*Леда делает. Но пропускать отдых он не намерен.*",64123,null],[70953,"2026-06-23T22:02:28",9,"//Не, если хотите кидать на истощение то пожалуста, там первая сложность броска 10, каждая последующая на 5 больше",64123,null],[70955,"2026-06-23T22:02:36",32,"//не знаю даже. Просто подошёл к ближайшему дереву и пообламывал ветви или если достаточно маленькое переловил крону и тяни к нам. У нас эльф и человек. Они рядом",70938,null],[70960,"2026-06-23T22:03:12",47,"Не знаю. Мне и как игроку и персу моему похуй. Мы могли в крепости отдохнуть, а вы фигнёй маетесь /",70955,null],[70961,"2026-06-23T22:03:24",32,"//ну мне не нужно спать и я ещё не устал",70953,null],[70962,"2026-06-23T22:03:25",47,"/честно, никто бы не стал этим заниматься",64123,null],[70963,"2026-06-23T22:03:46",47,"/эльф тут остался только из-за того, что группе нельзя разьединятся",64123,null],[70966,"2026-06-23T22:04:20",40,"/нахуя ветки я не понял",64123,null],[70967,"2026-06-23T22:04:20",5,"Спустя час обламывания веток в ближайшей  великан добыл кучу. Все деревья рядом кончились. Хватит на небольшое сорружение",64123,null],[70970,"2026-06-23T22:04:29",5,"// можешь укрепить один помост",64123,null],[70972,"2026-06-23T22:04:35",32,"//конкретно я подрядился уничтожить нежить и мне нужен план и план у меня есть я его исполняю. Так как по такой тропе очень удобно и защищаться и атаковать и принимать подкрепление",70962,null],[70973,"2026-06-23T22:04:37",5,"// кто сказал что нельзя",70963,null],[70976,"2026-06-23T22:04:42",47,"/будь я этим эльфом я бы отдохнул, получил бы доп инфу, подружился с кем в крепости, нормально расслабился и как дождь закончился пошёл бы работать",64123,null],[70978,"2026-06-23T22:04:52",47,"/правила групп в днд",70973,null],[70980,"2026-06-23T22:05:07",40,"/я не пойму чё вы делаете, зачем ветки вам",64123,null],[70981,"2026-06-23T22:05:13",47,"Отдохни и у тебя будут ячейки для этого/",70972,null],[70983,"2026-06-23T22:05:43",5,"// здесь вы можете пойти в разные места. Но если они спустятся пока ты спишь, то да, пропустишь",64123,null],[70984,"2026-06-23T22:06:04",32,"//Ну за час можно и больше добыть. Тем более что мне нужно только первые 1,5 метра укрепить а так же нижнюю часть укрепить галькой",70970,null],[70986,"2026-06-23T22:06:09",47,"Я не сплю. Я в трансе/",70983,null],[70987,"2026-06-23T22:06:24",40,"/или транс в тебе",70986,null],[70989,"2026-06-23T22:06:48",47,"Скоро мой болт окажется в тебе/",70987,null],[70990,"2026-06-23T22:06:58",40,"/ну наконец-то",64123,null],[70991,"2026-06-23T22:07:06",5,"// тебе хватило укрепить первый помост",70984,null],[70992,"2026-06-23T22:07:21",32,"/мне для восстановления нужен исключительно долгий отдых и сейчас поработаю а потом четыре часа посижу пока остальные спят это вполне долгий отдых я не занимаюсь чем-то трудным так руками махаю да ногами пританцовываю",70981,null],[70993,"2026-06-23T22:07:22",47,"Это будет посмертный выдох/",64123,null],[70994,"2026-06-23T22:07:36",47,"Мне тоже 4 часа надо/",70992,null],[70995,"2026-06-23T22:07:55",32,"//Я не сплю в процессе и бдителен",70994,null],[70996,"2026-06-23T22:07:59",40,"@elsio28 Хорхе кидает туда свой факел",64123,null],[70999,"2026-06-23T22:08:11",5,"// куда?",70996,null],[71000,"2026-06-23T22:08:17",40,"/вниз в самый",64123,null],[71002,"2026-06-23T22:08:35",40,"/ну насколько я способен метнуть",64123,null],[71003,"2026-06-23T22:08:45",5,"// держи вдохновение д8",71000,null],[71004,"2026-06-23T22:09:04",40,"/ёпта, я бард",64123,null],[71005,"2026-06-23T22:09:07",40,"/ура",64123,null],[71006,"2026-06-23T22:09:22",32,"//???",71003,null],[71009,"2026-06-23T22:09:39",47,"Я тоже... /",70995,null],[71010,"2026-06-23T22:09:45",5,"Горящий факел прочерчивает огненную линию в воздухе и летит вниз. Где-то вдали он затухает.\n\nСпустя несколько минут вы наконец услышаны, какой-то хруст внизу стал громче и приближается к вам",64123,null],[71012,"2026-06-23T22:09:59",40,"-ребят...",64123,null],[71013,"2026-06-23T22:10:05",40,"-я кого то разбудил",64123,null],[71014,"2026-06-23T22:10:07",47,"/я так понимаю мастер не даст нам долгий отдых",64123,null],[71015,"2026-06-23T22:10:12",32,"-Бляяя. Дебил!",71010,null],[71016,"2026-06-23T22:10:15",47,"В связи с союзниками /",64123,null],[71019,"2026-06-23T22:10:28",40,"-отступаем до нашей траншеи",64123,null],[71020,"2026-06-23T22:10:30",5,"// я выполняю ваши заявки",71014,null],[71021,"2026-06-23T22:10:37",40,"-готовый окоп",64123,null],[71022,"2026-06-23T22:10:46",32,"(Ментальный крик жука деду)",71015,null],[71024,"2026-06-23T22:10:50",47,"/в связи с союзниками",71020,null],[71025,"2026-06-23T22:11:03",5,"Куча скелетов показалась внизу, они лезут на вторую ступень. Часть соскальзывает и сползает вниз",64123,null],[71026,"2026-06-23T22:11:04",47,"/r d20+6 скрытность внутри дождя + транс",64123,null],[71028,"2026-06-23T22:11:14",47,"23. В трансе дальше",64123,null],[71030,"2026-06-23T22:11:23",40,"Хорхе убегает к окопам",64123,null],[71031,"2026-06-23T22:11:28",32,"Я сразу же начинаю по КД посылать огненные стрелы",71025,null],[71033,"2026-06-23T22:11:53",32,"(Отступая к окопу",71031,null],[71035,"2026-06-23T22:12:10",5,"// в какой момент отступаешь?",71033,null],[71037,"2026-06-23T22:12:31",9,"*Леда подходит к самому краю, смотрит на это всё, вздыхает.*\n\n//Скажите когда скнлеты будут",64123,null],[71039,"2026-06-23T22:12:43",32,"Сразу же как увидел как первый скелет выглянул пустил стрелу и начал отходить",64123,null],[71041,"2026-06-23T22:12:55",40,"Лежу на дне окопа:",64123,null],[71046,"2026-06-23T22:13:10",47,"/ладно. Сори. Это не отыгрыш перса. Он скрылся в дожде. Натянул стрелу. Готов ебашить",64123,null],[71051,"2026-06-23T22:13:23",40,"-аскелатор, прости, я сдалал хуйню...",64123,null],[71052,"2026-06-23T22:13:36",32,"-Кстати Леда не задумывался о том чтобы приобрести пару метательных дротиков?",71037,null],[71053,"2026-06-23T22:13:45",5,"Скелеты видны, они лезут",71037,null],[71054,"2026-06-23T22:13:50",47,"Там и камнями норм дамаг/",71052,null],[71055,"2026-06-23T22:13:56",5,"// выстрелил 1 раз и отошёл?",71039,null],[71056,"2026-06-23T22:14:09",47,"/на сколько их много?",64123,null],[71057,"2026-06-23T22:14:12",5,"// кидай попадание",64123,null],[71058,"2026-06-23T22:14:14",32,"/roll d20+5",71055,null],[71060,"2026-06-23T22:14:15",5,"// восприятие",71056,null],[71063,"2026-06-23T22:14:28",47,"/r d20+4",64123,null],[71064,"2026-06-23T22:14:29",5,"// убил сразу) опиши",71059,null],[71068,"2026-06-23T22:14:52",32,"/Ну скелету просто взорвало бошку без вариантов тут даже урон кидать излишне",71059,null],[71070,"2026-06-23T22:15:20",5,"Ты видишь, что их 8. После выстрела жука уже 7",71065,null],[71071,"2026-06-23T22:15:43",32,"Скелет выглянул из карьера надеясь вылезти как росчерк огненной стрелы буквально мгновенно взорвал череп и костяк скатился вниз",64123,null],[71072,"2026-06-23T22:15:43",5,"// так, бой около окопа? или кто-то стоит у карьера?",64123,null],[71075,"2026-06-23T22:15:59",32,"/Я у карьера у меня есть план",71072,null],[71078,"2026-06-23T22:16:13",5,"// кидайте иню все",64123,null],[71079,"2026-06-23T22:16:17",40,"/я пока наблюдаю из окопа если чё войду в бой",64123,null],[71081,"2026-06-23T22:16:25",47,"/бой",64123,null],[71083,"2026-06-23T22:16:30",40,"/roll@roll_bot",64123,null],[71085,"2026-06-23T22:16:39",47,"/r +d20+8 первая стрела",64123,null],[71087,"2026-06-23T22:16:46",40,"/кал калыч",64123,null],[71089,"2026-06-23T22:16:49",47,"/баля/",64123,null],[71091,"2026-06-23T22:16:55",47,"/такой красивый выстрел",64123,null],[71095,"2026-06-23T22:18:28",47,"Эльф поднимается из транса. Он слегка раздражён на старого хрыча. Его взгляд и поза говорят, что он сейчас застрелит это бесполезное существо, но вдох. Выдох. И выстрел мгновенно перенаправляется в скелета. Она вонзается в тонкую косточку где-то внутри груди и отлетает аккуратно рядом. \n Косточка оказывается тем самым средоточием магии в скелете",64123,null],[71101,"2026-06-23T22:19:07",9,"/roll 1d20-1 иня, заготавливаю атаку как появится кто в досчгаемости у края конечн, для этого и подходил",64123,null],[71105,"2026-06-23T22:19:58",32,"(как скелеты начнут лезть на наш уступ использую лепку земли и буквально обрушу верхнюю часть карьера на лезущих закапывая нафиг",64123,null],[71106,"2026-06-23T22:20:11",47,"Он перебегает на более сухое место и повыше, дабы было удобнее вести отстрел. Натягивает следующую стрелку и целится. \n Он уже ненавидит свою импульсивность. Как же хорошо работалось с другими служителями ордена. Чёткое выполнение цели. Чёткие шаги. Минимум лишних движений. Смерть любому врагу",64123,null],[71107,"2026-06-23T22:20:23",47,"/так нельзя",71105,null],[71108,"2026-06-23T22:20:35",47,"/без разрешения мастера",64123,null],[71109,"2026-06-23T22:20:48",47,"/я бы на его месте ячейку или хоть что-то затребовал",64123,null],[71111,"2026-06-23T22:20:56",5,"// максимум можешь землю из-под ног одного скелета выбить",71105,null],[71112,"2026-06-23T22:21:03",5,"// 5 футов одна клетка",64123,null],[71113,"2026-06-23T22:21:09",32,"Оно не наносит урон прямо. Но я и не делаю прямо я буквально аккуратно сдвигаю часть песка чтобы он осыпался/ съехал",71107,null],[71122,"2026-06-23T22:21:43",32,"Причем процесс у схождения обычно лавинообразный",71113,null],[71123,"2026-06-23T22:21:44",5,"// иню",64123,null],[71127,"2026-06-23T22:22:13",47,"/r d20+4 Иня",64123,null],[71131,"2026-06-23T22:22:21",47,"/ебать.19/20/19",64123,null],[71132,"2026-06-23T22:22:29",47,"/вот это броски",64123,null],[71133,"2026-06-23T22:22:31",32,"Так что там весь кусок сойдёт если аккуратно вынуть основание",64123,null],[71135,"2026-06-23T22:22:34",5,"/r 2d20",64123,null],[71137,"2026-06-23T22:22:47",5,"// кусок 5 футов. Это не снежная лавина",71133,null],[71142,"2026-06-23T22:23:05",47,"Чтобы его вынуть, надо его видеть, чтобы сделать это правильно мастер может потребовать пройти проверку/",71133,null],[71145,"2026-06-23T22:23:42",32,"//это тот самый снежок для схождения и сойдут клетки по соседству.",71137,null],[71147,"2026-06-23T22:23:56",47,"/ты не пытайся доказать мастеру, что ты прав в случаях если не написано чётко в правилах, а попроси разрешения. Это правильнее",64123,null],[71148,"2026-06-23T22:24:07",47,"/и уважительнее",64123,null],[71149,"2026-06-23T22:24:13",5,"// видеть надо обязательно",71142,null],[71151,"2026-06-23T22:24:58",40,"Хорхе смотрит паладины в зоне моего крика?",71149,null],[71154,"2026-06-23T22:24:59",32,"Ну ладно тогда просто огненную стрелу использую снова.",71145,null],[71160,"2026-06-23T22:25:24",32,"А такая идея была",64123,null],[71163,"2026-06-23T22:25:33",5,"Нет. Пока вы копались паладины давным-давно ушли. Огонёк где-то далеко, будто на другой стороне карьера",71151,null],[71165,"2026-06-23T22:25:47",5,"// иню",71160,null],[71166,"2026-06-23T22:25:57",40,"Хорхе наблюдает из окопа дальше",64123,null],[71167,"2026-06-23T22:26:05",5,"// кидай восприятие",71166,null],[71168,"2026-06-23T22:26:08",47,"/дай запрос и спроси, можешь ли совершить броски и если да, то какие.",71154,null],[71169,"2026-06-23T22:26:08",32,"//что значит \"иню\"?",71165,null],[71170,"2026-06-23T22:26:14",47,"/инициатива",71169,null],[71172,"2026-06-23T22:26:16",5,"// инициативу",71169,null],[71173,"2026-06-23T22:26:16",40,"/инициатива",64123,null],[71179,"2026-06-23T22:26:47",47,"/запрос реально офигенный. Можно дать сложность 14-16 и сказать: кинь заклинательный стат. Или магию. Или ещё что",64123,null],[71181,"2026-06-23T22:26:49",40,"/r d20+4+2",71167,null],[71185,"2026-06-23T22:27:08",32,"/roll d20+7",64123,null],[71189,"2026-06-23T22:27:37",5,"// везёт же",71182,null],[71191,"2026-06-23T22:27:59",40,"/амбасадор долбаебских заявок",64123,null],[71193,"2026-06-23T22:28:02",5,"Сидящий в окопе дед заметил другую группу скелетов. Они выползли вверх значительно левее от вас и пока далеко",64123,null],[71195,"2026-06-23T22:28:14",5,"/r +2",64123,null],[71197,"2026-06-23T22:28:17",32,"/Я никогда не играл в таком формате потому не знал я вижу что мастер меня просто не слышит и говорит \"так нельзя\" и все как я должен был понять",71179,null],[71198,"2026-06-23T22:28:23",40,"-сука!!! Левый фланг!!!",64123,null],[71202,"2026-06-23T22:28:31",40,"*всех предупредил*",64123,null],[71204,"2026-06-23T22:28:50",32,"(жук если что передаст всем)",64123,null],[71207,"2026-06-23T22:29:17",32,"/У меня дальность передачи выше и без крика",71204,null],[71209,"2026-06-23T22:29:27",5,"// может тебе стоит с более опытным мастером сыграть. Я сам новичок, учусь понемногу",71197,null],[71216,"2026-06-23T22:30:22",5,"Эльф 23\nЖук 14\nСкелеты слева 14\nЛеда 12\nСкелеты 9\nДед 2",64123,null],[71219,"2026-06-23T22:30:27",47,"/ну я вам обоим подсказываю. Более подробно давайте друг другу запросы",64123,null],[71223,"2026-06-23T22:30:41",47,"/тип у меня с рп проблемки. С опытом ок всё",64123,null],[71225,"2026-06-23T22:30:47",32,"// в том и прикол что с более опытными я играл и у меня никогда не было такой проблемы что Мирдал (прислушивается либо сразу говорит нет) что Аренил (сним вообще нормально он просто принимал что я говорю и реагировал)",71209,null],[71226,"2026-06-23T22:30:57",47,"/r +d20+8",64123,null],[71231,"2026-06-23T22:31:05",40,"/офните нон рп плз",64123,null],[71232,"2026-06-23T22:31:19",5,"// урон",71229,null],[71236,"2026-06-23T22:31:35",32,"//Давай в следующий раз ты просто спросишь как ты это хочешь сделать и скажешь что нужно кинуть?",71209,null],[71237,"2026-06-23T22:31:35",5,"// это за рыцаря соламнии, ты считаешь их траты?",71229,null],[71241,"2026-06-23T22:32:03",47,"/r d8+4 на бегу вылетает ещё одна стрела. Она тонким росчерком пролетает насквозь черепушки. Скелет пройдя ещё шаг падает. Но встаёт и шагает дальше",64123,null],[71244,"2026-06-23T22:32:23",47,"/аааа.нет не за рыцаря. Тут мой затуп",71237,null],[71247,"2026-06-23T22:32:34",32,"/так что собственно думаешь о искусственном обвале?",71236,null],[71248,"2026-06-23T22:32:35",47,"/считай, что без преимущества. Левое значение",64123,null],[71255,"2026-06-23T22:33:28",5,"// жив",71248,null],[71256,"2026-06-23T22:33:51",9,"//У меня заготовленная атакп алибардой, как только скелет на 10 футов подойдёт, напоминаю",64123,null],[71258,"2026-06-23T22:34:22",5,"// хмм, ещё раз скажи, какой эффект ты хочешь?",71247,null],[71259,"2026-06-23T22:34:48",32,"//скелеты сейчас будут лезть на наш уступ?",71258,null],[71262,"2026-06-23T22:35:56",47,"/а, ок/",71255,null],[71263,"2026-06-23T22:36:13",47,"/изменил",64123,null],[71266,"2026-06-23T22:36:51",32,"Я в основании нашего уступа(песок на уровне ниже в основании нашего салона вынимаю и двигаю на скелетов а за ним и осыпится вся часть склона держащаяся на этом полутораметромом кубе породы что ещё примерно по три метра в обе стороны буквально засыпая всю толпу костяков",71259,null],[71268,"2026-06-23T22:37:05",47,"/ушёл спать",64123,null],[71269,"2026-06-23T22:37:38",32,"Не полностью но но ребра их точно засыпет песком (без урона но обездвижет)",64123,null],[71271,"2026-06-23T22:38:02",5,"// ты ход закончил?",71268,null],[71275,"2026-06-23T22:38:20",32,"/судя по всему да/",71271,null],[71279,"2026-06-23T22:39:01",5,"// то есть весь построенный тобой уступ обвалится?",71266,null],[71281,"2026-06-23T22:39:19",32,"Не только",71279,null],[71283,"2026-06-23T22:39:41",32,"Но да и на скелетов а это земля камни и ветки",71281,null],[71286,"2026-06-23T22:40:10",5,"// остальная часть ступень карьера стоит давно, с чего ей осыпатся? Когда ты свою насыпь ломаешь",64123,null],[71289,"2026-06-23T22:41:10",32,"Ну вообще я не свою имел ввиду изначально. Ступени карьера песчаные и стоят они давно только из-за того что их так поставили а я основание нашей ступени вытягиваю",71286,null],[71290,"2026-06-23T22:41:39",5,"// окей, тогда осыпется твоя насыпь и ещё 2 клетки карьера",71289,null],[71293,"2026-06-23T22:41:58",5,"// твой ход",64123,null],[71294,"2026-06-23T22:42:01",5,"// скелеты внизу",64123,null],[71296,"2026-06-23T22:42:10",32,"/Сколько скелетов закопает?",64123,null],[71299,"2026-06-23T22:42:38",5,"// засыпет 4",64123,null],[71301,"2026-06-23T22:43:37",5,"// ну и ты вытягиваешь землю которую не видишь. Так что проверка магии 14",64123,null],[71303,"2026-06-23T22:43:50",32,"Считай я лепкой земли аккуратно вытянул песок из основания нашей верхней части карьера. Обваливая все это дело. \n-Ну гори оно синим пламенем!\n(Тягучим движением руки двигаю землю и конструкция начала двигаться)",64123,null],[71307,"2026-06-23T22:44:13",32,"/roll d20+5",71301,null],[71309,"2026-06-23T22:44:54",5,"Кучу скелетов снизу засыпало землей и песком. Они копошатся, пытаясь выбраться.",64123,null],[71310,"2026-06-23T22:44:57",5,"// ход?",64123,null],[71312,"2026-06-23T22:45:35",5,"/r 4d20",64123,null],[71314,"2026-06-23T22:45:38",32,"Какой у них спас силы от ловушки? Там по идее от моей силы заклинаний",64123,null],[71319,"2026-06-23T22:46:05",32,"Но нет косвенный эффект",64123,null],[71320,"2026-06-23T22:46:07",5,"// это не твоя ловушка прям. Выберутся после двух спасов силы 10",71314,null],[71325,"2026-06-23T22:46:56",5,"Скелеты очень активно копаются наверх. Земля понемногу осыпается, они по пояс свободны. Но всё ещё не могут двигаться",64123,null],[71329,"2026-06-23T22:47:19",32,"(Я ментально командую.)\n-Дед в бой ленивая жопа для тебя идеальный спуск! И идеальный враг",71320,null],[71330,"2026-06-23T22:47:25",5,"2 скелета забегают прямо по насыпи, атакуя жука и эльфа",64123,null],[71331,"2026-06-23T22:47:38",5,"/Hard  реакция твоя, бей",64123,null],[71333,"2026-06-23T22:47:47",40,"-вперёд смотри, кузнечик",64123,null],[71334,"2026-06-23T22:47:59",32,"У меня КД 15 (если без щита считать)",71330,null],[71335,"2026-06-23T22:48:30",5,"/r +4 жук\n/r +4 эльф",64123,null],[71339,"2026-06-23T22:49:03",5,"Скелеты безбожно мажут",64123,null],[71343,"2026-06-23T22:49:29",5,"Другой отряд скелетов далеко слева уже не скрываясь бежит к вам",64123,null],[71346,"2026-06-23T22:49:34",5,"// 30 футов",64123,null],[71347,"2026-06-23T22:49:41",5,"// ход Леды",64123,null],[71353,"2026-06-23T22:50:35",9,"/roll 1d20+4 реакция до хода",64123,null],[71357,"2026-06-23T22:51:30",9,"/roll 1d10+2 урон простого удара еси попал",64123,null],[71361,"2026-06-23T22:52:13",9,"/roll +d20+4 безрассцдная в ярости в свой ход",64123,null],[71363,"2026-06-23T22:52:37",9,"/roll 1d10+2+2 вшик второй",64123,null],[71365,"2026-06-23T22:52:52",5,"// по одному?",64123,null],[71380,"2026-06-23T22:55:20",9,"*Леда машет алибардой, удар! Второй! Бъет плашмя, держа алибарду за край одной рукой (чисто для сцены), разворачиваясь всем корпусом, ветер вздымает накидку, видно его спину, как переливаются его точёные идеальные мыщцы.*\n\n//Ход, просто рандомных, он не целится в одного, а в того по кому легче",64123,null],[71381,"2026-06-23T22:55:58",9,"//По мне атаки с преимуществом ну и в ярости",64123,null],[71386,"2026-06-23T22:56:33",5,"Оба подбежавших скелета немного разваливаются. Но \"живы\"",64123,null],[71387,"2026-06-23T22:56:46",5,"// ход деда",64123,null],[71391,"2026-06-23T22:57:20",32,"/я всё-таки настаиваю на том чтобы он напал с преимуществом на тех кто внизу",64123,null],[71393,"2026-06-23T22:57:35",5,"// они забежали по твоему склону",71391,null],[71396,"2026-06-23T22:57:53",32,"//тех кто засыпан",71393,null],[71399,"2026-06-23T22:58:10",32,"Ты сам говорил ДВА броска на освобождение",64123,null],[71401,"2026-06-23T22:58:23",5,"// их с преимуществом, но бил других",64123,null],[71404,"2026-06-23T22:58:26",40,"Дед встал перед выкопанной им ранее волчьей ямой и крикнул:\n-Пустоголовые Дармоеды!!! (Привлекают внимание скелетов, чтобы часть врагов отвлеклась на меня и упала по пути в ловушку так как переть будут по прямой)",64123,null],[71406,"2026-06-23T22:58:37",32,"А пока они \"обездвижен\" и \"ничком\"",64123,null],[71407,"2026-06-23T22:58:48",40,"*если я по достанции достаю, то метаю топор*",64123,null],[71409,"2026-06-23T22:59:04",32,"/В кого?",71407,null],[71411,"2026-06-23T22:59:48",5,"// у топора 20 футов, с помехой",71407,null],[71414,"2026-06-23T23:00:18",32,"//А разве не 60 у метательного оружия дистанция с помехой?",71411,null],[71415,"2026-06-23T23:00:56",5,"// 20/60. 20 обычная, 60 макс",71414,null],[71416,"2026-06-23T23:01:01",40,"/r d20+3+2",64123,null],[71419,"2026-06-23T23:01:12",40,"(топор кидается от силы верно?)",64123,null],[71420,"2026-06-23T23:01:19",5,"// помеха",71419,null],[71423,"2026-06-23T23:01:27",40,"/r d20+3+2",64123,null],[71426,"2026-06-23T23:01:32",40,"/сука",64123,null],[71428,"2026-06-23T23:02:11",40,"Хорхе достаточно привлек внимание. Стоит так чтобы прущий прямо скелет упал на колья в волчья яму в будущем",64123,null],[71431,"2026-06-23T23:02:25",5,"// привлёк. Откуда колья?",71428,null],[71432,"2026-06-23T23:02:33",40,"/можем проверить сколько на меня отвлеклись?",64123,null],[71436,"2026-06-23T23:02:48",5,"// кинь выступление",71432,null],[71442,"2026-06-23T23:03:26",40,"/ну нарративно, копнул и топор какие нить палки заточил и листьями засыпал вот тебе и ловушка. Я умение делать такие штуки вписал в нарративные умения",71431,null],[71444,"2026-06-23T23:03:45",32,"/Ну я могу помочь телепатией точно не пропустят имитировать голос Хорхе.",71436,null],[71445,"2026-06-23T23:03:46",5,"// умеешь, но ты в этой яме сам сидел. Не было заявок на колья",71442,null],[71448,"2026-06-23T23:03:57",5,"// помощь +",71444,null],[71450,"2026-06-23T23:04:18",40,"/r d20+2",64123,null],[71452,"2026-06-23T23:04:22",32,"//как кидать?",71448,null],[71453,"2026-06-23T23:04:34",5,"// реролл, помогают",71450,null],[71455,"2026-06-23T23:04:49",32,"/roll d20+4",64123,null],[71458,"2026-06-23T23:05:03",5,"// не ты, от тебя помощь деду",71455,null],[71459,"2026-06-23T23:05:12",40,"/ну я две вещи заявил пока ждали насекомое. Окоп и волчью яму. Ну ладно, душнить не стану",71445,null],[71461,"2026-06-23T23:05:40",40,"/тоже самое кидаю или шо",71453,null],[71462,"2026-06-23T23:05:51",32,"/у меня бонус больше. Тем более что я по сути отдельно выступаю подхватываю идею дела",71458,null],[71463,"2026-06-23T23:05:55",40,"/r d20+2",64123,null],[71465,"2026-06-23T23:06:06",5,"// в свой ход",71462,null],[71466,"2026-06-23T23:06:24",40,"/забыл что у меня самого есть и перекид и д8",64123,null],[71467,"2026-06-23T23:06:26",32,"/ну то же самое получилось в итоге",71465,null],[71468,"2026-06-23T23:06:30",5,"// в следующий раз можешь конкретнее сказать, что в яму ставишь и откуда колья",71459,null],[71471,"2026-06-23T23:07:10",5,"Скелеты тебя заметили. 4 из них бежит. 1 в другую сторону",71464,null],[71472,"2026-06-23T23:07:24",5,"// ход @cirson",64123,null],[71476,"2026-06-23T23:07:57",32,"/Он спит. Сам писал что ушел. Стрельни от его лица и давай дальше",71472,null],[71480,"2026-06-23T23:08:41",5,"/r d20+6",64123,null],[71482,"2026-06-23T23:08:49",5,"/r d8+4",64123,null],[71484,"2026-06-23T23:08:57",32,"/А разве не +8 он кидал?",71480,null],[71487,"2026-06-23T23:09:26",5,"Эльф бросает лук и бьёт рапирой стоящего вплотную скелета. Тот рассыпается",64123,null],[71488,"2026-06-23T23:09:34",32,"//хотя не имеет значения попал-убил",71484,null],[71491,"2026-06-23T23:09:47",5,"// скелет прямо перед ним был",71484,null],[71494,"2026-06-23T23:09:52",5,"// ходи",71488,null],[71496,"2026-06-23T23:10:22",32,"/скелет перед мной Леда его не убил?",64123,null],[71497,"2026-06-23T23:10:28",5,"// жив",71496,null],[71502,"2026-06-23T23:11:59",32,"Бросок удара возможности  скелета знамение 8.\nЯ отбегаю на 30 футов к деду бегу обходя его бруствер и остановившись кидаю огненную стрелу в скелета наступающего с фланга",71497,null],[71503,"2026-06-23T23:12:20",32,"/roll d20+5",64123,null],[71505,"2026-06-23T23:12:27",9,"//... лааааддднннооооо, я бы палкой по голове бил за такое, на его месте",71487,null],[71506,"2026-06-23T23:12:34",32,"/roll d10",64123,null],[71508,"2026-06-23T23:12:43",5,"// почему?)",71505,null],[71512,"2026-06-23T23:12:52",9,"//Ненавижу когда за моего перса играют другие.",64123,null],[71514,"2026-06-23T23:12:55",5,"// жив",71507,null],[71517,"2026-06-23T23:13:15",5,"// понимаю. Ну я хз, могу сказать что эльф сбежал",71512,null],[71521,"2026-06-23T23:14:05",32,"//его проблемы что кинул бой.\n я бы на месте мастера вообще внезапный инфаркт схватил и кидал от смерти",71505,null],[71522,"2026-06-23T23:14:39",5,"// пиши ход если всё. А то непонятно",71521,null],[71523,"2026-06-23T23:14:53",32,"//Да пардон.\nХод",71522,null],[71524,"2026-06-23T23:15:10",5,"/r 4d20 скелеты бегут в яму",64123,null],[71532,"2026-06-23T23:15:54",5,"3 скелета провалились прямо в яму и теперь копошатся там. Один чудом перепрыгнул и ударил деда.\n\nЕщё один атаковал Леду",64123,null],[71533,"2026-06-23T23:16:01",5,"/r +4",64123,null],[71536,"2026-06-23T23:16:07",5,"/r +d20+4",64123,null],[71540,"2026-06-23T23:16:28",5,"// кд @H_Kruz Hard",64123,null],[71542,"2026-06-23T23:16:45",9,"// тогда бы 90% персов погибали по причине игрок уснул",64123,null],[71543,"2026-06-23T23:17:01",9,"// по мне так очень неприятно",64123,null],[71554,"2026-06-23T23:17:50",5,"/r d6+2 деду\n/r d6+2 леде",64123,null],[71556,"2026-06-23T23:17:51",9,"//Кд 12",64123,null],[71561,"2026-06-23T23:18:23",5,"// твой ход",71556,null],[71562,"2026-06-23T23:18:24",32,"//а мне вот неприятно что он просто взял и сказал \"все ребята я погнал\" посреди боя.\nСпорить не буду моё мнение и менять не буду",71543,null],[71582,"2026-06-23T23:20:38",9,"/roll +d20+4 юезрассудная по целому скелету",64123,null],[71586,"2026-06-23T23:21:13",9,"/roll 1d10+2+2+1d6 удар холмового докучи",64123,null],[71588,"2026-06-23T23:21:24",5,"// жив куча",71587,null],[71590,"2026-06-23T23:21:34",9,"//Спас силы 13 или он упал",64123,null],[71591,"2026-06-23T23:21:41",5,"/roll@roll_bot",64123,null],[71594,"2026-06-23T23:22:20",32,"/а какая у костяков сила?",71592,null],[71595,"2026-06-23T23:22:30",5,"// 0",71594,null],[71597,"2026-06-23T23:22:36",9,"*Леда с разворота бьёт скелета алибардой, но не подращитал и лишь зацепил.*",64123,null],[71599,"2026-06-23T23:22:40",9,"//Ход",64123,null],[71600,"2026-06-23T23:22:48",5,"/r 4d20",64123,null],[71604,"2026-06-23T23:23:04",5,"Скелеты лезут из песка, но всё не вылезают...",64123,null],[71606,"2026-06-23T23:23:15",5,"/r +d20+4",64123,null],[71609,"2026-06-23T23:23:24",5,"/r 2d6+2",64123,null],[71611,"2026-06-23T23:23:28",32,"/вот тут прямо люто везёт)",71604,null],[71612,"2026-06-23T23:23:30",5,"// леда урон",71610,null],[71614,"2026-06-23T23:23:50",5,"// ход деда @H_Kruz",64123,null],[71615,"2026-06-23T23:23:55",32,"/а тут не очень",71612,null],[71617,"2026-06-23T23:24:32",5,"// будем считать что дед закрылся щитом и стоит орёт на скелетов",64123,null],[71619,"2026-06-23T23:24:38",5,"// а эльф слился с дождём где-то",64123,null],[71620,"2026-06-23T23:24:44",5,"// ход жука",64123,null],[71621,"2026-06-23T23:25:10",32,"Огненная стрела в того кто не упал в яму деда",64123,null],[71622,"2026-06-23T23:25:21",32,"/roll d20+5",64123,null],[71626,"2026-06-23T23:25:54",32,"/Ход\n(Видимо усталость последних часов сказывается и руки уже дрожат)",64123,null],[71627,"2026-06-23T23:26:18",32,"Стрела улетела чуть правее и выше костяка",64123,null],[71628,"2026-06-23T23:26:24",5,"/r +d20+4 по леде\n/r d20+4 по деду",64123,null],[71631,"2026-06-23T23:26:39",5,"/r 2d6+2",64123,null],[71635,"2026-06-23T23:27:00",5,"Скелеты в яме всё ещё копошатся и не могут вылезти",64123,null],[71639,"2026-06-23T23:27:14",5,"// ход Hard",64123,null],[71640,"2026-06-23T23:27:30",5,"// даже не знаю, сделать паузу тут? 2 игроков нет",64123,null],[71641,"2026-06-23T23:27:48",9,"//Не получил пока урона?",64123,null],[71643,"2026-06-23T23:27:54",5,"// 12 урона",71641,null],[71645,"2026-06-23T23:28:05",9,"//Откуда?",64123,null],[71647,"2026-06-23T23:28:10",5,"// крит скелета",71645,null],[71648,"2026-06-23T23:28:16",5,".",71610,null],[71649,"2026-06-23T23:28:16",32,"//блин мы можем и в двоем затащить",64123,null],[71650,"2026-06-23T23:28:23",5,"// да",71649,null],[71652,"2026-06-23T23:28:43",9,"//Вродь то по деду, по мне там 6 и 1",64123,null],[71653,"2026-06-23T23:28:54",9,"//С преимуществом, но лан)",64123,null],[71654,"2026-06-23T23:28:58",5,"// вот твой раньше",71607,null],[71656,"2026-06-23T23:29:18",32,"//я просто хочу длинный отдых и поднять уровень. У меня капитально опыта скопилось",71650,null],[71657,"2026-06-23T23:29:20",9,"//значит 6 урона",64123,null],[71660,"2026-06-23T23:30:19",40,"/КД 18",64123,null],[71661,"2026-06-23T23:30:20",9,"/roll +d20+4 безрассудная",64123,null],[71663,"2026-06-23T23:30:29",32,"/Потому давай их добивать.\nСейчас я пристрелю не ловушного и просто закопаю в яме с кольями остальных",64123,null],[71664,"2026-06-23T23:30:29",40,"/а шо где",64123,null],[71666,"2026-06-23T23:30:43",5,"// тогда тебе 6 урона было",71660,null],[71667,"2026-06-23T23:30:48",32,"//доброе утро",71664,null],[71668,"2026-06-23T23:30:59",9,"/roll 1d10+2+2 в ярости сцук костлявого, вродь попал же",71662,null],[71670,"2026-06-23T23:31:03",40,"/жопа крепкая у меня",71667,null],[71671,"2026-06-23T23:31:08",5,"// убивай",71669,null],[71673,"2026-06-23T23:31:40",40,"/а кто со мной у окопа?",64123,null],[71675,"2026-06-23T23:31:51",32,"/жук",71673,null],[71679,"2026-06-23T23:32:26",32,"/я туда добежал чуть не получив по морде от костяка а мне напомню один удар и спасброски)",64123,null],[71684,"2026-06-23T23:33:11",40,"/тараканий подвиг",64123,null],[71688,"2026-06-23T23:33:39",9,"*Ещё один тяжёлый вмах, костлявый по запчастям улетает в пропасть. Леда весь мокрый, от дождя, напряжения и вложенной силы, воин без цели, только путь, и он не самурай.*\n\n— Покойтесь с миром...",64123,null],[71690,"2026-06-23T23:34:10",5,"/r 4d20",64123,null],[71694,"2026-06-23T23:34:32",5,"3 скелета выкопалось и вместе с 4 напали на великана",64123,null],[71698,"2026-06-23T23:35:07",9,"//Пл мне с преимуществом",64123,null],[71699,"2026-06-23T23:35:09",5,"/r +d20+4\n/r +d20+4\n/r +d20+4\n/r +d20+4",64123,null],[71703,"2026-06-23T23:35:35",5,"/r 5d6+8",64123,null],[71705,"2026-06-23T23:35:41",32,"/мне кажется или великану станет нехорошо)",64123,null],[71706,"2026-06-23T23:35:43",9,"/roll 1d10+3 выносливость камня реакцией от крита уменьшить урон",64123,null],[71708,"2026-06-23T23:35:47",5,"// 34, ход",64123,null],[71709,"2026-06-23T23:36:00",9,"//29÷2=14 мне",64123,null],[71712,"2026-06-23T23:37:02",40,"/Ну шо",64123,null],[71713,"2026-06-23T23:37:05",9,"*Леда ловит на себе удары, не дрогнув, не пошевелив и бровью, истекая кровью.*\n\n— Поднимется солнце... ворон укравший песню героя...",64123,null],[71714,"2026-06-23T23:37:09",5,"// ходи",71712,null],[71718,"2026-06-23T23:37:34",40,"-Две атаки, на костяные сраки",64123,null],[71720,"2026-06-23T23:37:48",40,"/r d20+3+2",64123,null],[71724,"2026-06-23T23:37:56",40,"/r d20+3+2",64123,null],[71726,"2026-06-23T23:38:05",5,"// всплеск?",64123,null],[71727,"2026-06-23T23:38:08",40,"/всплеск кала",64123,null],[71729,"2026-06-23T23:38:18",9,"//Как на деле кайфово просто фармить ауру",64123,null],[71732,"2026-06-23T23:38:34",40,"/два урона?",64123,null],[71733,"2026-06-23T23:38:50",40,"/бля, ща гляну чё там по топору",64123,null],[71740,"2026-06-23T23:39:30",40,"/д6+3 верно?",64123,null],[71750,"2026-06-23T23:40:52",40,"/r d6+3",64123,null],[71752,"2026-06-23T23:40:55",40,"/r d6+3",64123,null],[71754,"2026-06-23T23:40:58",5,"// убил",64123,null],[71763,"2026-06-23T23:42:21",40,"Нарративно описание:\n\nДед зацепил топором словно крюком за затылок одного и ударил его ребром щита сломав лицевые кости.\n\nПосле чего второму обухом топора выбил коленную чашку о",64123,null],[71765,"2026-06-23T23:42:46",5,"// ход жука",64123,null],[71780,"2026-06-23T23:45:00",32,"(Я лепку земли использую и просто натягиваю кусок земли из выкопанной насыпи на яму засыпая скелетов в ней и пресную землю чтобы костяки точно не вылезли в ближайшее время.)\nЖук стоял спокойно медленным тягучим движением рук двигал землю",64123,null],[71781,"2026-06-23T23:45:19",5,"Яма засыпана, скелеты упокоились",64123,null],[71790,"2026-06-23T23:46:59",32,"Ход",64123,null],[71793,"2026-06-23T23:47:23",9,"//Ух, по мне с преимуществом там, если ходют)",64123,null],[71794,"2026-06-23T23:47:30",5,"// ты ходишь",71793,null],[71797,"2026-06-23T23:47:47",9,"/roll +d20+4 по классике",64123,null],[71799,"2026-06-23T23:48:03",9,"/roll 1d10+2+2 тоже",64123,null],[71801,"2026-06-23T23:48:11",5,"/r d4",64123,null],[71803,"2026-06-23T23:48:18",5,"// убил",64123,null],[71811,"2026-06-23T23:49:21",32,"//Там ведь вокруг Леды одни подранки?",64123,null],[71812,"2026-06-23T23:49:30",5,"// смотри персом",71811,null],[71816,"2026-06-23T23:50:07",32,"//я и так помню что по там уже 4 атака 3 из которых не убили",71812,null],[71818,"2026-06-23T23:50:18",32,"/Просто вспоминаю",64123,null],[71823,"2026-06-23T23:50:36",5,"// ладно, ты не прав. Остались только засыпанные скелеты, их вообще не били",71816,null],[71825,"2026-06-23T23:51:10",32,"//А о них вообще забыл",71823,null],[71826,"2026-06-23T23:51:22",32,"Тогда пардон туплю",71825,null],[71827,"2026-06-23T23:51:24",9,"*Крюк алибарды упал на скелета раздробив правую часть костяка, лезвие топорища упало в землю, от уже не встанет.*\n\n— Ужас запряжённый ежами не прийдёт... прогоню, не отпущу, перекину упряжь... — *Красные ленты мысли заплетались, текли, ложились на уста словно в трансе...*",64123,null],[71829,"2026-06-23T23:51:29",9,"//Ход",64123,null],[71830,"2026-06-23T23:51:42",5,"// запряжённый ежами, ух",64123,null],[71834,"2026-06-23T23:51:55",5,"/r d20",64123,null],[71837,"2026-06-23T23:52:07",5,"Бедняга скелет не может выбраться из завала",64123,null],[71838,"2026-06-23T23:52:11",9,"//По мне с преимуществом все атаки",64123,null],[71839,"2026-06-23T23:52:20",5,"/r +d20+4\n/r +d20+4\n/r +d20+4",64123,null],[71841,"2026-06-23T23:52:30",9,"//Все попали",64123,null],[71842,"2026-06-23T23:52:33",32,"/а кстати почему все с приимуществом?",71838,null],[71844,"2026-06-23T23:52:38",5,"/r 3d6+6",64123,null],[71848,"2026-06-23T23:52:52",9,"//8 урона мне",64123,null],[71849,"2026-06-23T23:52:53",5,"// ход",64123,null],[71850,"2026-06-23T23:53:04",32,"//дед!",64123,null],[71851,"2026-06-23T23:53:08",5,"// теперь дед",64123,null],[71857,"2026-06-23T23:53:33",40,"-попричмокивай, сучара!!!",64123,null],[71859,"2026-06-23T23:53:39",40,"/r d20+3+2",64123,null],[71861,"2026-06-23T23:53:43",9,"*Леда, испустил тяжёлый вдох, до этого словно не дышал. Когда так близка смерть... это и есть жизнь?*",64123,null],[71864,"2026-06-23T23:54:01",40,"/r d6+3",64123,null],[71866,"2026-06-23T23:54:07",5,"// жив",71865,null],[71867,"2026-06-23T23:54:23",40,"Поцарапал топором скелет в паховой области",64123,null],[71878,"2026-06-23T23:55:51",9,"//Типа у нас ограничение 16+",64123,null],[71883,"2026-06-23T23:56:31",5,"// пиши ход пж в конце",71867,null],[71896,"2026-06-23T23:58:16",32,"(жук смотрит на скелетов и едва живого Леду, вода стекает по хитину. Руки уже трясутся столько магии он не творил уже да никогда подряд слишком слаб.\nвыпускаю огненную стрелу. В скелета (тот что выше по карте)",64123,null],[71897,"2026-06-23T23:58:28",32,"/roll d20+5",64123,null],[71905,"2026-06-23T23:59:17",32,"(руки трясутся в глазах немного плывет, магия отказывается повиноваться. Стрела улетает куда-то сильно в сторону)\n/Ход",64123,null],[71908,"2026-06-24T00:00:11",5,"Снаряд взорвался у тебя в руках",64123,null],[71909,"2026-06-24T00:00:15",5,"// кидай урон",64123,null],[71910,"2026-06-24T00:00:37",32,"/roll d10",64123,null],[71913,"2026-06-24T00:00:56",32,"Сил не хватило даже на запитку снаряда",71911,null],[71916,"2026-06-24T00:01:11",5,"// хард",64123,null],[71917,"2026-06-24T00:01:50",32,"//??\nЯ же вроде написал \"ход\"",71916,null],[71919,"2026-06-24T00:02:00",9,"/roll +d20+4 даже скучновато как-то благо всего два уровня в варе будет",64123,null],[71921,"2026-06-24T00:02:15",5,"// да, хард пропал куда-то",71917,null],[71922,"2026-06-24T00:02:22",9,"/roll 2d10+2+2 бац",64123,null],[71924,"2026-06-24T00:02:30",5,"// смэрть естественно",71923,null],[71925,"2026-06-24T00:02:36",32,"// что за хард?)",71921,null],[71931,"2026-06-24T00:05:15",9,"*Леда переносит свой вес, и просто разворачивается прокрутив алибарду над головой сняся ещё один костяк на мелкие щепки, кости осыпались на его торс и лицо, он готов ко всему, если прийдётся...*\n\n— Рука нефритовой обезьяны мнёт розы...",64123,null],[71932,"2026-06-24T00:05:18",9,"//Ход",64123,null],[71933,"2026-06-24T00:05:40",5,"/r d20",64123,null],[71936,"2026-06-24T00:06:09",5,"3 последних скелета сосредоточили усилия на голиафе",64123,null],[71939,"2026-06-24T00:06:27",5,"/r +d20+4\n/r +d20+4\n/r +d20+4",64123,null],[71943,"2026-06-24T00:06:36",5,"/r 2d6+4",64123,null],[71946,"2026-06-24T00:07:00",5,"// урон харду (его ник буквально)",71944,null],[71947,"2026-06-24T00:07:05",9,"//Так, их чё меньше не стало? И прошлый раз 3, кого убил я)",64123,null],[71949,"2026-06-24T00:07:12",5,"/r 1d6",64123,null],[71951,"2026-06-24T00:07:22",5,"// это за крит, всего 16",71950,null],[71952,"2026-06-24T00:07:32",5,"//последний выкопался",71947,null],[71954,"2026-06-24T00:07:43",9,"/roll 1d20+4 сила могилы",64123,null],[71974,"2026-06-24T00:10:19",9,"*Первый удар леду не сложил, он словил клинок своим торсом, тот зажался и поломался об его тело, лезвие застряло внутри. Но этого не хватило, второй удар его сложил, силы утекали как вода сквозь пальцы.*\n\n— Сон...\n\n//Так, я на 0, сила могилы ток один удар заблочила",64123,null],[71978,"2026-06-24T00:10:55",5,"// даже скучновато как-то?",71919,null],[71979,"2026-06-24T00:11:09",40,"/мое зелье здоровья никто не трогал же?",64123,null],[71980,"2026-06-24T00:11:15",9,"*Леда воткнул алибарду в землю и просто закрыл глаза опёршись на неё, словно никогда и не собирался падать.*",64123,null],[71981,"2026-06-24T00:11:24",32,"//не не трогал",71979,null],[71983,"2026-06-24T00:11:56",9,"//Хорошо что третья атака не попала, а то был бы 1 провал от смерти автоматом",64123,null],[71984,"2026-06-24T00:12:07",32,"-Леда вставай! Ты нам нужен!\n(Я использую кость вдохновения в борьбе от смерти",71980,null],[71988,"2026-06-24T00:12:26",32,"+к12 Леде",64123,null],[71989,"2026-06-24T00:12:34",5,"// ближние атаки это автокриты, сразу 2 провала. Не люблю эту механику",71983,null],[71992,"2026-06-24T00:12:55",5,"// отхил костью?",71984,null],[71993,"2026-06-24T00:13:00",5,"// хмм опиши красиво тогда",64123,null],[71994,"2026-06-24T00:13:06",5,"// ты опиши)",64123,null],[71997,"2026-06-24T00:13:28",9,"//Меня в 0 сложила одна, вторая силой могилы прошёл спас не защиталась. Так что просто щас в 0 упал, без провалов пока",71989,null],[72006,"2026-06-24T00:14:37",32,"//жук увидел как великан встал на колено. В нем закипела магия невиданная прежде и его телепатический зов достиг самой души великана тяня его в мир живых. \nЖук отчаянно не хотел смерти товарища который несколько раз спас его жизнь",71992,null],[72013,"2026-06-24T00:15:12",32,"/roll d12",64123,null],[72015,"2026-06-24T00:15:19",5,"// отхил на д12, ход деда",64123,null],[72018,"2026-06-24T00:16:12",9,"//Скорее как кукла неваляшка, у него нет коленей",72006,null],[72021,"2026-06-24T00:16:28",9,"//Мне 9 хитов?",64123,null],[72031,"2026-06-24T00:18:30",9,"*Ярость ушла, но... чей то голос ухватился за уплывающее сознание и удержал его... падать рано... на тебя расчитывают союзники. Рука что едва не отпустила, снова сжала древко почти до хруста древисины, золотистые глаза что собирались погаснуть снова воссияли.*",64123,null],[72033,"2026-06-24T00:18:37",32,"//после такого только мультиклас барда брать",72006,null],[72034,"2026-06-24T00:18:42",5,"// @H_Kruz",64123,null],[72040,"2026-06-24T00:19:27",5,"// держи вдохновение к6",72006,null],[72043,"2026-06-24T00:19:42",32,"//спасибо!",64123,null],[72056,"2026-06-24T00:21:07",9,"//Если Леда погибнет его место займёт другой гигачад 100%",64123,null],[72062,"2026-06-24T00:21:48",32,"//не позволю! Погибнуть Леде я не дам",72056,null],[72065,"2026-06-24T00:22:06",5,"// окей ходи ты",72062,null],[72070,"2026-06-24T00:22:47",32,"Я выпускаю огненную стрелу и бегу вперёд к великану.",72065,null],[72075,"2026-06-24T00:23:11",9,"*Маленький великан всё ещё стоит... время не пришло...*",64123,null],[72078,"2026-06-24T00:23:22",32,"Становясь прямо за его спиной чуть сбоку хватая за бедро одной рукой",72070,null],[72081,"2026-06-24T00:23:40",32,"/roll d20+5",64123,null],[72087,"2026-06-24T00:24:29",32,"Ярость три-крина была столь велика что огненный взрыв буквально смел одного из скелетов",64123,null],[72088,"2026-06-24T00:24:41",5,"/r d3",64123,null],[72091,"2026-06-24T00:24:50",9,"*Ты чувствуешь что под тканью импровизированной юбки и мешков точно не бедро и не нога, словно нечто переплетено, но не будем об этом пока.*",72078,null],[72094,"2026-06-24T00:25:16",5,"// 2 скелета живо",64123,null],[72100,"2026-06-24T00:25:44",32,"Я хочу кинуть выступление",72094,null],[72101,"2026-06-24T00:25:50",5,"// давай",72100,null],[72103,"2026-06-24T00:25:58",32,"Вдохновить Леду на бой",64123,null],[72105,"2026-06-24T00:26:14",32,"/roll d20+4",64123,null],[72110,"2026-06-24T00:26:56",9,"*Леда оставляет алибарду торчать на земле и берётся за жезл что висел на поясе, взмах тяжёлым магическим жезлом по хлебалу одного из скелетов.*\n\n//Без ярости та спала и без безрассудной",64123,null],[72111,"2026-06-24T00:26:58",32,"-Ты настолько сильнее меня что мне и вообразить тяжело! Так раздави ты этих костяков!!!",64123,null],[72113,"2026-06-24T00:27:31",5,"/r d6+1",72106,null],[72116,"2026-06-24T00:27:41",5,"// 4 временных хитов Леде",64123,null],[72119,"2026-06-24T00:28:02",9,"// 22! Я точно вдохновлён, это лучше чем крит. Мне с преимуществом или +4? Ну лан, временные хиты",72106,null],[72121,"2026-06-24T00:28:19",9,"/roll 1d20+2 удар жезлом как импровизированное",64123,null],[72124,"2026-06-24T00:28:29",9,"//Ну, оке",64123,null],[72126,"2026-06-24T00:28:35",5,"// рерроль вместо хитов",64123,null],[72127,"2026-06-24T00:28:42",9,"*Просто отмахнулся от одного из скелетов.*",64123,null],[72128,"2026-06-24T00:28:50",9,"//Да пусть, бей!",72126,null],[72130,"2026-06-24T00:29:09",5,"/r +4\n/r +4",64123,null],[72135,"2026-06-24T00:29:17",5,"/r d6+2",64123,null],[72139,"2026-06-24T00:29:26",5,"/r d6",64123,null],[72143,"2026-06-24T00:29:34",5,"// 9 урона",64123,null],[72145,"2026-06-24T00:29:56",9,"//9 и +2 вродь 11, как раз пригодилось, 2 хита осталось",64123,null],[72152,"2026-06-24T00:30:31",5,"// ещё)",72116,null],[72155,"2026-06-24T00:30:52",9,"*Великан ранен, он устал, но ещё стоит, его лицо тронула лёгкая улыбка.*",64123,null],[72157,"2026-06-24T00:31:07",9,"//У меня 9 было всего, с временными 13",72152,null],[72160,"2026-06-24T00:31:49",5,"// тут без +2, это за крит, в сумме 9. 13-9=4",72145,null],[72161,"2026-06-24T00:32:07",5,"// дед заснул прямо перед скелетами",64123,null],[72162,"2026-06-24T00:32:10",5,"// ходит жук",64123,null],[72163,"2026-06-24T00:32:15",9,"//Крит удваивает кубы +2 остаётся приэтом",64123,null],[72165,"2026-06-24T00:32:41",5,"// знаю. одно крит попадание 2д6+2. чекни что я бросал",72163,null],[72166,"2026-06-24T00:33:01",9,"//Аааа, тогда 4, да",72165,null],[72168,"2026-06-24T00:33:30",32,"Жук вновь и вновь использует магию огненной стрелы.\nНовый выстрел с вдохновением к6",64123,null],[72170,"2026-06-24T00:34:31",32,"Для жука бой тянулся уже вечность он чудовищно устал но три-крин единый народ у них нет понятия оставить товарища",64123,null],[72171,"2026-06-24T00:34:48",32,"/roll d20+5 +d6",64123,null],[72173,"2026-06-24T00:35:04",5,"// урон",64123,null],[72174,"2026-06-24T00:35:09",32,"/roll d10",64123,null],[72176,"2026-06-24T00:35:28",5,"// убивай",72175,null],[72179,"2026-06-24T00:36:43",32,"Удар который целился в грудь скользнул выше будто сама судьба вела руку три-крина выстрел угодил прямо в череп и взорвал в крошево костей голову скелета",64123,null],[72180,"2026-06-24T00:37:53",5,"Последний скелет стоит прямо перед голиафом. Он не понимает, почему тот ещё жив. А может и не думает об этом. Он же скелет.",64123,null],[72182,"2026-06-24T00:42:09",9,"*Леда проводит перед собой рукой, формируя чёрное зеркало которое ничего не отражает, а скорее поглощает свет, после касается пальцем и то с неприятным хрустом стекла разбивается на множество осколков что летят в скелета, прямо сквощь негос раня не тело, скорее дух и исчезают развеявшись в черный дым.*\n\n//Волшебная стрела",64123,null],[72183,"2026-06-24T00:42:24",9,"/roll 1d4+1 излучением три раза",64123,null],[72185,"2026-06-24T00:42:38",5,"// он ещё жив)",72184,null],[72186,"2026-06-24T00:42:45",9,"//Ход",64123,null],[72187,"2026-06-24T00:42:52",5,"/r +4",64123,null],[72189,"2026-06-24T00:43:08",5,"/r d6+2",64123,null],[72191,"2026-06-24T00:43:22",5,"Скелет вонзает свой клинок прямо в живот Леды",64123,null],[72192,"2026-06-24T00:43:27",5,"// опиши что с ним",64123,null],[72193,"2026-06-24T00:45:15",32,"(а разве на волшебную стрелу не все кубики отдельно кидаются?",72184,null],[72194,"2026-06-24T00:45:19",9,"*В животе торчит уже второй клинок... слишком много. Великан медленно заваливается падая на спину.*",64123,null],[72195,"2026-06-24T00:45:50",9,"//Обычно один куб по правилам для всех стрел, а так кто как хочет",72193,null],[72196,"2026-06-24T00:46:06",9,"//Дмы редко душнят по этому поводу",64123,null],[72199,"2026-06-24T00:46:38",5,"Скелет победоносно стоит над телом павшего голиафа. Он видит жука, но в руках скелета пусто. Скелет сжимает кулаки",64123,null],[72200,"2026-06-24T00:46:42",5,"// ходи жук",64123,null],[72202,"2026-06-24T00:46:52",9,"//Напомню, первфй клинок в дивоте обломился я испольщовал силу могилы 😏👌",64123,null],[72206,"2026-06-24T00:47:55",32,"-Не смей умирать!\n(Я поднимаю руку с посохом Кристал фокус немного треснул от взрыва но все ещё работает. Он сиял магией и был направлен прямо в скелета.)\nМесто обычного вербального компонента жук прошипел \"умри!\" И выпустил снаряд",64123,null],[72208,"2026-06-24T00:48:07",32,"Стоит буквально в 10 футах",64123,null],[72209,"2026-06-24T00:48:23",32,"/roll d20+5",64123,null],[72211,"2026-06-24T00:48:36",32,"/roll d10",64123,null],[72213,"2026-06-24T00:48:56",5,"Левая рука скелета отломилась, но он жив",64123,null],[72214,"2026-06-24T00:49:32",32,"//Это уже 11 урона с стрелами",64123,null],[72215,"2026-06-24T00:49:41",5,"// верно",72214,null],[72216,"2026-06-24T00:50:56",9,"//Ух, если доживу до 4го уровня начну фармить ауру с заклинаниями, так что жучара мочи костяка!)",64123,null],[72217,"2026-06-24T00:51:05",32,"Ну что же тогда я подхожу и дополнительным действием от рук атакую посохом",72215,null],[72218,"2026-06-24T00:51:15",5,"// так нельзя",72217,null],[72219,"2026-06-24T00:51:38",32,"/И чё? Дай мне уже его добить",64123,null],[72220,"2026-06-24T00:51:52",5,"// не",72219,null],[72221,"2026-06-24T00:52:13",32,"//Он и так пережил больше некоторых собратьев.",64123,null],[72222,"2026-06-24T00:52:18",9,"//это так не работает, лучше отбегай",64123,null],[72224,"2026-06-24T00:52:33",32,"И тогда он добьет Леду",64123,null],[72225,"2026-06-24T00:52:37",5,"// у всех скелетов одинаково хп",72221,null],[72226,"2026-06-24T00:52:44",5,"// не факт",72224,null],[72230,"2026-06-24T00:53:13",9,"//Бонусны бить дают лишь некоторые навыки, черты или если ты ударил основным одноручным и потом бонусным оружием со свойством лёгкое",64123,null],[72231,"2026-06-24T00:53:21",32,"Хотя... Да я разворачиваясь и бегу от скелета телепатией передаю.\n-Попробуй убить меня скотина",72225,null],[72233,"2026-06-24T00:53:51",32,"//Ну да нужно лёгким оружием обзавестись",72230,null],[72234,"2026-06-24T00:54:14",32,"Я его провоцирую",72231,null],[72235,"2026-06-24T00:54:30",32,"/roll d20+4",64123,null],[72237,"2026-06-24T00:54:32",9,"//Оба раза ты должен оружием ударить и в обоих руках оружие, для мага эт невыгодно)",64123,null],[72239,"2026-06-24T00:55:12",32,"//да эх видимо если доживу возьму мастер метамагии",72237,null],[72241,"2026-06-24T00:55:34",32,"Одбегаю в сторону деда насколько могу",72236,null],[72243,"2026-06-24T00:56:12",9,"//А деда что, вырубило?",64123,null],[72244,"2026-06-24T00:56:20",5,"// заснул от усталости",72243,null],[72245,"2026-06-24T00:57:00",9,"//С союзниками не полегли бы, эх, я бы ждал сколько нужно",64123,null],[72246,"2026-06-24T00:58:03",32,"//Леда будет кидать от смерти надеюсь я успею ему помочь медециной",72245,null],[72247,"2026-06-24T00:58:18",5,"// кидай спас смерти",72245,null],[72248,"2026-06-24T00:58:32",9,"/roll 1d20 от смерти вродь очередь",64123,null],[72251,"2026-06-24T00:59:27",9,"//А вообще нет, я кину когда меня проверят или попытаются поднять :3",64123,null],[72252,"2026-06-24T00:59:43",5,"Щёлкающий черепом скелет со всех ног устремляется за жуком. Его ноги хрустят, пока он набирает скорость по застланной туманом траве. Наконец, он догоняет жука и хватает за панцирь.",64123,null],[72253,"2026-06-24T00:59:44",5,"// рывок",64123,null],[72254,"2026-06-24T00:59:47",5,"// ход жука",64123,null],[72255,"2026-06-24T00:59:49",9,"//Так интересней ^^",72251,null],[72256,"2026-06-24T01:00:26",5,"// отказываешься от успешного спаса ради риска?",72251,null],[72258,"2026-06-24T01:00:59",32,"Удар посохом по скелету с разворота.",64123,null],[72259,"2026-06-24T01:01:11",32,"/roll d20-1",64123,null],[72261,"2026-06-24T01:01:24",32,"/Кажется мне звизда",72260,null],[72262,"2026-06-24T01:01:29",9,"//Мне не нравится метагейм, я ради этого и помереть готов",72256,null],[72263,"2026-06-24T01:01:55",9,"//2 спаса накопил, ход",64123,null],[72264,"2026-06-24T01:02:06",32,"У меня напомню 3 ХП.\nИ 15 КД",64123,null],[72265,"2026-06-24T01:02:17",5,"Скелет дёргает жука за ус",64123,null],[72266,"2026-06-24T01:02:19",5,"/r +2",64123,null],[72268,"2026-06-24T01:02:26",5,"Ус отрывается",64123,null],[72269,"2026-06-24T01:02:29",5,"// -1 хп",64123,null],[72270,"2026-06-24T01:02:32",5,"// ход",64123,null],[72271,"2026-06-24T01:02:55",9,"//и вырывает его вытягивая его вместе с мозгом",72265,null],[72272,"2026-06-24T01:03:00",32,"Несмотря на маленький урон это было ОЧЕНЬ больно",72268,null],[72273,"2026-06-24T01:03:09",5,"// неее, это безоружная, а у скелета 0 силы",72271,null],[72274,"2026-06-24T01:03:44",9,"//А, безоружная 1+сила, норм",64123,null],[72275,"2026-06-24T01:04:11",32,"/roll d20-1",64123,null],[72277,"2026-06-24T01:04:15",32,"(Я ещё раз бью посохом уже позабыв о магии да и не смогу в плотную)",64123,null],[72278,"2026-06-24T01:04:31",32,"(И промахиваясь вновь...",64123,null],[72279,"2026-06-24T01:04:40",9,"//3 спаса, ход",64123,null],[72280,"2026-06-24T01:04:47",5,"/r +2",64123,null],[72282,"2026-06-24T01:05:01",5,"Скелет пытается подставить подножку, но сам падает на землю",64123,null],[72284,"2026-06-24T01:05:06",5,"// ход",64123,null],[72285,"2026-06-24T01:05:24",5,"// лежит ничком",64123,null],[72286,"2026-06-24T01:05:30",32,"Атакую посохом уже по лежачей цели.\nС преимуществом.",72281,null],[72287,"2026-06-24T01:05:44",32,"/roll 2d20-1",64123,null],[72289,"2026-06-24T01:05:51",5,"// попал)",64123,null],[72291,"2026-06-24T01:06:11",32,"/roll d8-1",64123,null],[72293,"2026-06-24T01:06:19",5,"// добивай",64123,null],[72294,"2026-06-24T01:06:57",32,"Пятка посоха воткнулась в ребра и с хрустом проломила уже хрупкую от прошлых повреждений грудину",64123,null],[72296,"2026-06-24T01:07:28",32,"Поставив таки окончательную точку в не жизни этого скелета.",64123,null],[72297,"2026-06-24T01:07:42",32,"Подобрал усик и поковылял к Леде",64123,null],[72298,"2026-06-24T01:07:46",9,"//4 спаса, все равно у него в этом ходу нет дайствия даж если добежит",64123,null],[72299,"2026-06-24T01:08:08",5,"// рисковый ты",72298,null],[72300,"2026-06-24T01:08:26",32,"//а как ты спасы считаешь?",64123,null],[72301,"2026-06-24T01:08:32",9,"//Мне интереснее по правилам",72299,null],[72302,"2026-06-24T01:08:47",5,"// да, но первый ты прошёл так-то)",72301,null],[72303,"2026-06-24T01:08:53",9,"//Каждый мой ход 1 спас на смерть",72300,null],[72304,"2026-06-24T01:08:54",5,"// но твой выбор",64123,null],[72305,"2026-06-24T01:09:54",9,"//Мне интереснее не видеть, я даже сам бегу подымать союзников сразу и пох видел или нет успех там или провал",72302,null],[72306,"2026-06-24T01:10:17",9,"//Что жук?",64123,null],[72307,"2026-06-24T01:10:19",5,"Бой окончен, скелеты уничтожены.\n\nИдёт сильный дождь.",64123,null],[72308,"2026-06-24T01:10:41",9,"//Пробуешь стабилизировать?)",64123,null],[72309,"2026-06-24T01:11:17",32,"Я собираюсь до тела великана. Он ещё жив? \nМедецина. \nСкинув свою мантию я перевязал рукавами несколько ран",64123,null],[72310,"2026-06-24T01:11:29",32,"/roll d20+4",72308,null],[72312,"2026-06-24T01:11:51",9,"/roll 1d20\n/roll 1d20\n/roll 1d20\n/roll 1d20\nПропущенные",64123,null],[72314,"2026-06-24T01:12:07",5,"// депнул и не проиграл",64123,null],[72315,"2026-06-24T01:12:24",32,"А потом принялся за торчащий в животе меч.",72311,null],[72316,"2026-06-24T01:12:37",9,"*Леда кажется жив? По нему не скажешь, немного холодный, не дышит, но вроде бы...*",64123,null],[72317,"2026-06-24T01:12:56",9,"//Думаю это 1д4 урона)",72315,null],[72318,"2026-06-24T01:13:14",9,"//Дай восстановить хиты",64123,null],[72319,"2026-06-24T01:13:27",9,"/roll 1d4 часов в отключке",64123,null],[72321,"2026-06-24T01:13:38",5,"// просто меч в животе)",72317,null],[72322,"2026-06-24T01:14:05",9,"*Леде сильно досталось. Он точно не скоро очнётся.*",72320,null],[72323,"2026-06-24T01:14:10",5,"Все товарищи спят, кто от усталости, кто от ран. Один жук стоит под проливным дождём",64123,null],[72324,"2026-06-24T01:15:21",32,"Ладно сначала я в любом случае пытаюсь просто обработать раны зажать кровоточащие места и зашить некоторые открытые раны. У меня в кармашках мантии был моток нити из паутины и костяная игла",72318,null],[72325,"2026-06-24T01:15:46",32,"В общем занимаюсь великаном несколько часов к ряду",64123,null],[72326,"2026-06-24T01:15:52",5,"// можешь нарративно описать как хочешь. Леда жив и проснётся через 4 часа",72324,null],[72327,"2026-06-24T01:16:36",32,"Да я именно это и делаю жук выхаживает и прикрывает великана время от времени осматривая окрестности",64123,null],[72328,"2026-06-24T01:16:51",32,"Ладно продолжим долгий отдых?",64123,null],[72329,"2026-06-24T01:17:35",5,"// вы встали на долгий отдых около карьера? Какие-то приготовления к нему? Как проводишь?",64123,null],[72330,"2026-06-24T01:18:31",32,"Я просто слился с местностью (я без мантии по сути голый и мимикрирующий панцирь сработал сам) и сижу рядом с великаном сам пытаюсь прийти в себя",64123,null],[72331,"2026-06-24T01:19:11",32,"Мне не нужны приготовления три-крины не так часто едят и не спят потому мне нет нужды что-то готовить",64123,null],[72332,"2026-06-24T01:20:14",32,"//ладно что по опыту за стычку с волками и этот бой и с паладином и вообще как начисляется опыт и уровень",64123,null],[72333,"2026-06-24T01:20:34",5,"// окей, долгий отдых значит, продолжим потом",64123,null],[72334,"2026-06-24T01:20:42",5,"// опыт за 2 боя выдам",72332,null],[72335,"2026-06-24T01:20:53",5,"// а так много опыта будет за завершение квеста",64123,null],[72336,"2026-06-24T01:21:13",5,"// Опыт за первые 2 боя:\n+ 113 каждому за волков и\n+ 217 всем за бой наверху каньона",64123,null],[72337,"2026-06-24T01:21:50",9,"//Это шо, вместеилипо отдельности?",72336,null],[72338,"2026-06-24T01:22:06",5,"// 113+217 всем кроме эльфа",72337,null],[72339,"2026-06-24T01:22:29",32,"//да я и Леда по сути тащили.",72334,null],[72340,"2026-06-24T01:22:47",5,"// да, но у деда была роль",72339,null],[72341,"2026-06-24T01:23:06",32,"/На верху каньона жук по сути сам стал той соломинкой об которую переломилась нападение нежити.\nЧетыре фрага огненной стрелой и ещё 7 вывел из боя трёх навечно",64123,null],[72342,"2026-06-24T01:23:47",32,"Не зря инженер иззетов! И строим и ломаем",64123,null],[72344,"2026-06-24T01:25:14",5,"// уровень можешь повышать там",64123,null],[72345,"2026-06-24T01:25:43",32,"+330 опыта?",64123,null],[72346,"2026-06-24T01:26:02",32,"То есть уровень.",64123,null],[72347,"2026-06-24T01:26:26",32,"Хорошо как отдохну так и займусь",64123,null],[72348,"2026-06-24T01:26:33",32,"Спасибо за игру мастер",64123,null],[72349,"2026-06-24T01:40:09",32,"https://t.me/c/3239766844/2358",64123,null],[72350,"2026-06-24T03:02:52",5,"// если что, тёмное зрение 60 футов, телепатия 120",72349,null],[72351,"2026-06-24T03:03:38",32,"Спасибо что поправил я действительно не знал где что поставить но помнил что обе цифры важны",72350,null],[72352,"2026-06-24T03:39:54",5,"// предварительно игра снова будет в 20:00",64123,null],[72353,"2026-06-24T05:57:28",47,"/я извиняюсь, но 500 сообщений...",64123,null],[72354,"2026-06-24T06:52:34",47,"/ещё и награду за бой на каньоне забрали. Хотя логично что человек не будет играть до 3 часов ночи. \n И я предупредил, что отхожу. Ладно бы молча свалил",64123,null],[72356,"2026-06-24T07:47:37",9,"//Мне тож не нравится тот факт что игроков не ждут",72354,null],[72357,"2026-06-24T07:58:22",47,"/если я мастеру не нравлюсь, стоит прямо сказать, я просто уйду с квеста",64123,null],[72381,"2026-06-24T11:29:24",32,"//Награда проста ты не участвовал не дал распоряжений никаких просто сказал \"я ухожу\" то есть оставил товарищей в смертельной битве и пока эльф в кустиках делал свои несомненно важные дела, все остальная группа чуть не полегла",72354,null],[72387,"2026-06-24T12:11:35",47,"Выстрел",71106,null],[72388,"2026-06-24T12:11:44",47,"Иня/",71127,null],[72389,"2026-06-24T12:11:55",47,"Я с вами учавствовал в бою.",64123,null],[72392,"2026-06-24T12:12:13",47,"И сказал пошёл спать, так как у меня ЕГЭ. Вот только вышел",64123,null],[72407,"2026-06-24T12:19:57",47,"/я понимаю, если бы я постоянно просто не приходил ко времени, или ещё что. Но я был. Писал посты в меру сил, не выебывался даже сильно, п тут просто взяли и махнули рукой. Это даже обиднее чем нахуй: бля иди отсюда, ты не оч чел",64123,null],[72409,"2026-06-24T13:01:05",40,"/да, слушай, от тебя не убудет, а эльфу приятно. Накинь потом ему тоже чё нить.",72336,null],[72412,"2026-06-24T13:02:41",40,"/подожди, он зайдет, поговорите и разрулите",64123,null],[72633,"2026-06-24T18:56:52",32,"Я могу сегодня задержаться у меня ещё работа возможно длительная",64123,null],[72651,"2026-06-24T19:19:49",5,"/ Окей, тогда ты тоже получаешь опыт за бой. И можешь писать чтобы мы тебя подождали, когда уходишь? Типа я тут не раз видел, что человек исчезает и говорит бой доигрывать, а перса отдает под управление другому.",72407,null],[72653,"2026-06-24T19:22:52",5,"/ Так, сегодня игры не будет. Но если есть желание, можете отыграть как вы проснулись после отдыха, что там делали и разговорчики между персами. Но без спуска в карьер",64123,null],[72657,"2026-06-24T19:28:42",5,"/ И на долгом отдыхе каждый тратит рацион",64123,null],[72659,"2026-06-24T19:29:09",9,"//Я два, харя крупная)",64123,null],[72662,"2026-06-24T19:35:53",9,"*Леда лицом ловит удары, это же лицо хоть и ест оносительно мало но за двох как минимум!*",64123,null],[72666,"2026-06-24T19:50:00",47,"Ну я же предупредил как раз, чтобы подождали. Если бы мне похер было бы, я бы просто лёг и ничего не написал/",72651,null],[72667,"2026-06-24T19:50:34",47,"/ладно. В следующий раз буду знать и уточнять целиком \"я ушёл спать, просьба продолжить завтра \"",64123,null],[72684,"2026-06-24T20:12:59",32,"Ок",72651,null],[75435,"2026-06-25T19:45:46",40,"/писюнярики мужицкие, Добрый вечер",64123,null],[75436,"2026-06-25T19:45:54",40,"/играем?",64123,null],[75439,"2026-06-25T19:51:20",5,"// Нет. К сожалению, игра будет только в субботу в 20:00",64123,null],[77763,"2026-06-26T17:23:28",9,"//Тэкс, ну. Я бы за то чтобы домучать как нибудь. Мы же длинный совершили?",64123,null],[77799,"2026-06-26T17:54:35",5,"// верно. Но я вести дальше завтра буду, у меня щас 2 квеста. Вы можете только социалку без продвижения отыграть",77763,null],[77820,"2026-06-26T18:17:51",47,"О, так рп можно было делать всё это время, ёмаё",64123,null],[77821,"2026-06-26T18:19:45",32,"Да и где там эльф? Так как жук точно рядом с ледой. Под скрытностью (панцирь мимикрирующий слил с окружением)",64123,null],[77822,"2026-06-26T18:20:27",47,"Будем считать будто он подскользнулся и получил состояние ошеломление.",64123,null],[77824,"2026-06-26T18:20:38",32,"Ок",77822,null],[77825,"2026-06-26T18:20:44",47,"А раз он типо скрылся, то вы его не видели и он просто а грязи валяется рядом",64123,null],[77831,"2026-06-26T18:21:23",32,"/roll 2 d20+4 \n(Скрытность)",64123,null],[77839,"2026-06-26T18:21:51",47,"2 и д вместе пиши! /",64123,null],[77843,"2026-06-26T18:23:55",32,"У меня оно не срабатывает",64123,null],[77846,"2026-06-26T18:24:41",32,"/roll 2d20+4",64123,null],[77848,"2026-06-26T18:25:01",32,"Ну пусть будет 24 скрытности",64123,null],[77867,"2026-06-26T18:39:41",5,"// конечно",77820,null],[77868,"2026-06-26T18:39:48",5,"// рановато вы скрытность бросаете но окей",64123,null],[77869,"2026-06-26T18:40:47",5,"// вот немного описания если хотите диалог повести",64123,null],[77871,"2026-06-26T18:41:42",5,"Утро. Дождь прекратился, туман отступил и теперь клубился только в самом карьере. Герои проснулись прямо на поле битвы посреди костей, ужасно промокнув за ночь.",64123,null],[77873,"2026-06-26T18:44:25",9,"*Леда стоит или полусидит опёршись на дерево. Поставив на себя сундук ниже пояса, достал бумагу и пишет на ней что-то, чертит используя сундук как столешницу.*",64123,null],[77874,"2026-06-26T18:45:36",32,"Ну я её заявил ещё тогда. Что жук просто на инстинктах применил панцирь и замаскировался",77868,null],[77926,"2026-06-26T19:31:59",47,"Эльф с больной головой шатаясь встаёт. Он не навидит своих союзников. И особенно деда. Хочется его пристрелить. Собирает стрелы",64123,null],[77949,"2026-06-26T19:45:54",40,"Дед уходит и исчезает в тумане лесов\n\n---выхожу с квеста, всем спасибо за игру---",64123,null],[77952,"2026-06-26T20:34:35",32,"А за что он ненавидит союзников?",77926,null],[77953,"2026-06-26T20:34:56",32,"Удачи дед с тобой было весело",77949,null],[77954,"2026-06-26T20:35:20",32,"Видимо тайник мы с Ледой будем чистить в двоем",64123,null],[77955,"2026-06-26T20:36:10",5,"// мхм, вообще я надеюсь, что Юнус успокоится и вернётся",64123,null],[77956,"2026-06-26T20:36:50",5,"// Михаил же не уходит, а просто ненавидит союзников",64123,null],[77958,"2026-06-26T20:38:07",32,"//А что с Юнусом?",77955,null],[77959,"2026-06-26T20:39:22",5,"// ну из-за его квеста https://t.me/c/3898923231/3/64102",77958,null],[77960,"2026-06-26T20:40:53",32,"//Ну ладно лично мне дед ничего плохого не сделал. Даже наоборот у нас отличный слаженный коллектив получился",77959,null],[77961,"2026-06-26T20:41:06",5,"// да, мне нравится ваша химия",77960,null],[78094,"2026-06-26T23:45:52",5,"// @H_Kruz не хочешь вернуться доиграть?",64123,null],[78097,"2026-06-26T23:49:20",40,"/Нет, чтоб не отвлекаться от ведения своей игры. Спасибо что предложил",64123,null],[78098,"2026-06-26T23:49:37",5,"// жаль",64123,null],[78663,"2026-06-27T19:16:48",32,"//Я тоже хочу дракона в квесте на поговорить.",78098,null],[78685,"2026-06-27T19:41:19",5,"// мой дракон понравился?",78663,null],[78686,"2026-06-27T19:41:51",5,"// кстати вы здесь? В 20 начало. Жаль, что без деда, но ничего",64123,null],[78687,"2026-06-27T19:42:01",5,"// @cirson Hard",64123,null],[78689,"2026-06-27T19:43:28",47,"Тут0",64123,null],[78690,"2026-06-27T19:44:23",32,"// я вообще драконов люблю до одури. Вот так вот. Не просто же так персонаж носит с собой икону начальства.",78685,null],[78693,"2026-06-27T19:45:04",47,"/не надо вдвоем",64123,null],[78694,"2026-06-27T19:45:08",47,"Хард подойдёт/",64123,null],[78696,"2026-06-27T19:45:13",47,"/уже был ведь опыт",64123,null],[78702,"2026-06-27T19:51:04",32,"//ладно прости. За резкость. Я не хотел",78693,null],[78704,"2026-06-27T19:53:15",47,"/ну просто лучше чутка подождать, чем обижать кого-то",64123,null],[78705,"2026-06-27T19:55:04",5,"// да, ждём",64123,null],[78707,"2026-06-27T19:58:41",32,"//Насялькика, самый умный сильный и красивый. Пример для подражания\n(Вырезано из методички \"как говорить с драконом\"",78698,null],[78708,"2026-06-27T20:00:55",32,"/да жук на ковре у начальства бывал не раз так что бывалый по разговору с драконами",64123,null],[78709,"2026-06-27T20:02:05",5,"//  почему дракон его начальник?",64123,null],[78710,"2026-06-27T20:02:58",32,"//он инженер иззетов. А создатель и бессменный лидер организации. Нив-Миззет. Дракон",64123,null],[78711,"2026-06-27T20:09:54",9,"//Ну, я тут. Пару минут туда сюда разгрести и могу",64123,null],[78712,"2026-06-27T20:10:56",5,"// тогда начинаем отыгрыш",64123,null],[78713,"2026-06-27T20:11:08",5,"Утро. Дождь прекратился, туман отступил и теперь клубился только в самом карьере. Герои проснулись прямо на поле битвы посреди костей, ужасно промокнув за ночь.",64123,null],[78714,"2026-06-27T20:12:17",47,"Эльф едва двигался и постоянно, чихал. Кажется он слегка простудился",64123,null],[78715,"2026-06-27T20:12:49",47,"Подойдя к своей команде он оглядел местность. Он был явно удивлён количеством... Трупов",64123,null],[78716,"2026-06-27T20:13:13",32,"(жук чувствовал себя нормально отдохнул. Для его коренного жителя пустыни все было нормально хитин не так холодила вода как кожу",64123,null],[78719,"2026-06-27T20:13:39",32,"//13 скелетов и ещё трое закопаны целиком",78715,null],[78721,"2026-06-27T20:13:52",5,"На голом песке, более не укрытом туманом, посреди костей скелетов что-то едва поблескивало.",64123,null],[78722,"2026-06-27T20:14:07",32,"(Потому он хорошо отдохнул)",78716,null],[78723,"2026-06-27T20:14:17",32,"//что там?",78721,null],[78724,"2026-06-27T20:14:34",32,"(кстати жука не где не было видно)",64123,null],[78725,"2026-06-27T20:14:38",47,"Чихнув эльф оглянулся на великана",64123,null],[78726,"2026-06-27T20:14:39",5,"// персом ищи. Лут сам к тебе не прыгнет",64123,null],[78727,"2026-06-27T20:14:49",9,"//Леда...",77873,null],[78728,"2026-06-27T20:15:37",32,"(о сундук же оперевшись сидит жук слившись камуфляжем просто не обнаружымо.)",78727,null],[78729,"2026-06-27T20:16:12",32,"//я сижу и могу посмотреть просто повернув голову я метагеймово прошу подробностей \"что блестит\"",78726,null],[78730,"2026-06-27T20:16:22",9,"— Доброе утро. — *Отвлёкся он от записей, и немного улыбнулся, стараясь показать что желает доброе утро по настоящему.*",78725,null],[78731,"2026-06-27T20:16:25",5,"// мечи скелетов",64123,null],[78732,"2026-06-27T20:16:40",9,"//Заглядываешь что пишет великан?",78728,null],[78733,"2026-06-27T20:16:41",47,"К великану подходит эльф и говорит:\n- Доброе - протянул руку для рукопожатия",64123,null],[78734,"2026-06-27T20:17:34",32,"//не мне и так ок. Кстати куда великан дел мантию которой было перевязано несколько самых глубоких ран",78732,null],[78735,"2026-06-27T20:17:36",47,"- Я Талон - решает представиться он",64123,null],[78736,"2026-06-27T20:17:46",5,"// жесть а мне интересно",78732,null],[78738,"2026-06-27T20:18:58",32,"Жук телепатией направление не определили прямо из скрытности)\nя жук но меня на работе звали и эй ты там. Приятно",78735,null],[78739,"2026-06-27T20:19:19",9,"*Леда оттолкнулся и сгреб записи под руку, а сундук снова повис на верёвке. Он пожал руку длинноухуму.*\n\n— Леда. Кажется моё имя. — *Кивнул он, яно был осторожен, при руклпожатии не показывал силы как обычно делают гиганты, словно боялся её сам.*",78733,null],[78740,"2026-06-27T20:19:47",9,"//Какю мантию?",78734,null],[78741,"2026-06-27T20:20:15",9,"//Никто не интересуется, так что пока тайна ^^",78736,null],[78742,"2026-06-27T20:20:21",32,"...",72309,null],[78743,"2026-06-27T20:20:45",32,"//ну я в любом случае узнаю",78741,null],[78744,"2026-06-27T20:20:51",47,"- Что дальше? - спрашивает кратко эльф. Он явно выглядит так, будто заболел серьёзно и хотел бы быстрее закончить",64123,null],[78745,"2026-06-27T20:21:02",9,"*Леда на утро снял. Мистическим образом ран словно небыло. Он не забыл поблагодарить.*",78742,null],[78746,"2026-06-27T20:21:13",32,"- кстати Леда ты применял магию в бою. Помоги мне изучить твои заклинания",78741,null],[78747,"2026-06-27T20:21:56",32,"//ну тогда она лежит рядом с жуком которому было лень её одевать",78745,null],[78748,"2026-06-27T20:23:06",9,"— Не против помочь. Но сам не совсем понимаю как это работает. — *Он протягивает руку, словно пытаясь ухватить пустоту, ничего не происхидит.* — Так далека и так близка. Магия...",78746,null],[78749,"2026-06-27T20:23:08",32,"-Кстати, Талон. Ты где был пока мы сражались?",64123,null],[78750,"2026-06-27T20:24:24",32,"-Ничего у тебя получится \n(Подбодрил великана жук. Он не раз работал с стажорами потому знает как общаться спокойно)",78748,null],[78751,"2026-06-27T20:24:54",32,"//ну мета то я знаю но за персонажа должен спросить",78749,null],[78752,"2026-06-27T20:25:27",47,"- Меня вырубило сзади",64123,null],[78753,"2026-06-27T20:25:33",9,"— Жизнь — не стоит риска. Золото лежит, не сгинет, не уйдёт. — *Леда кажется задумался.* — Искать сокровище не обязательно. Достаточно просто помочь, коль силы наши ещё не достаточны.",64123,null],[78754,"2026-06-27T20:27:14",32,"-Ну мертвяков действительно было много. Но в бою я настолько сильно выложился что моя аура окрепла так что я стал на шаг ближе к второму кругу магии",64123,null],[78755,"2026-06-27T20:27:36",32,"-А будь у меня ячейки я бы смог больше",64123,null],[78757,"2026-06-27T20:27:50",32,"/кстати мастер утро мне знамения кидать пора",64123,null],[78758,"2026-06-27T20:28:04",5,"// кидай конечно. После отдыха всё восстановилось",64123,null],[78759,"2026-06-27T20:28:20",32,"Раз в день а не после отдыха как и восстановление чар",78758,null],[78760,"2026-06-27T20:28:34",32,"/roll 2d20",64123,null],[78762,"2026-06-27T20:28:47",5,"// гарант крит",64123,null],[78763,"2026-06-27T20:28:57",32,"Закрепи пж",78762,null],[78765,"2026-06-27T20:29:41",9,"— Смерть сильнее самых сильных магов.",78755,null],[78767,"2026-06-27T20:30:01",47,"/пиздец. Как ему везёт на знамения",64123,null],[78768,"2026-06-27T20:30:15",9,"*Словно прочитал заклятие, с небольшой грустью.*",78765,null],[78769,"2026-06-27T20:30:26",32,"-Ну мой начальник уже шестнадцатую тысячу лет на смерть плевал (и разводит руками)",78765,null],[78771,"2026-06-27T20:31:02",32,"/Ну в прошлой ролке у меня четыре 1 подряд прошли. Так что все это кармическое равновесие",78767,null],[78772,"2026-06-27T20:31:12",9,"*Не спорит, не соглашается. Начал складывать записи в стопку.*",78769,null],[78775,"2026-06-27T20:32:33",9,"— Прости. Не смог помочь. — *Извинился великан.*",78752,null],[78776,"2026-06-27T20:33:00",32,"-Ладно, туда нам надо.\n(И указываю на спуск)",78772,null],[78777,"2026-06-27T20:33:08",47,"- Это только моя вина - жёстко отрезал эльф. Так как именно так и считал. Это его проблема. Опытный воин и упал... Ещё и вырубился. Ужас",64123,null],[78778,"2026-06-27T20:33:55",32,"-Ладно со всеми бывает. Идём как говорится \"сокровища сами себя не добудут\"",64123,null],[78779,"2026-06-27T20:34:08",5,"Даже мимолётного взгляда на спуск достаточно, чтобы увидеть улучшение условий. Земля ещё мокрая, но солнце всё сушит её. Залезать по такому склону можно почти без риска упасть",78776,null],[78781,"2026-06-27T20:34:46",32,"Я просто лепкой земли сделаю винтовой десницей ступеньки",78779,null],[78782,"2026-06-27T20:35:04",9,"*Собрав всё своё Леда встал у края спуска.*",64123,null],[78783,"2026-06-27T20:35:36",5,"Ступеньки держатся",78781,null],[78784,"2026-06-27T20:36:30",47,"Следом спускается и эльф",64123,null],[78785,"2026-06-27T20:36:37",32,"мы спокойно спускаемся. На второй высматривая метку не находя спускаемся на третий уровень",64123,null],[78786,"2026-06-27T20:37:27",5,"Туман в карьере оокутывает вас с ног до головы. Далеко не видно. Чтобы что-то увидеть, придётся подойти поближе",64123,null],[78787,"2026-06-27T20:37:41",47,"В руках щит и рапира",64123,null],[78788,"2026-06-27T20:37:41",5,"// вы идёте по третьему уровню?",78785,null],[78789,"2026-06-27T20:38:54",32,"//Ну если на втором не видно (а нам нужно как я понимаю полный круг по карьеру провести чтобы искать метку)\nТо на третий",64123,null],[78791,"2026-06-27T20:39:25",5,"// да, вопрос по какой ступене вы будете круг делать",64123,null],[78793,"2026-06-27T20:40:44",47,"/что?",64123,null],[78794,"2026-06-27T20:40:50",47,"/мы сейчас второй исследуем",64123,null],[78795,"2026-06-27T20:40:55",47,"/в поисках метки",64123,null],[78796,"2026-06-27T20:41:13",32,"//сначала вторая",78791,null],[78798,"2026-06-27T20:41:44",5,"Окутанные туманом, вы едва различаете силуэты друг друга. Откуда-то снизу карьера периодически доносится неприятный хруст. Пробираясь вперёд, вы иногда спотыкаетесь обо что-то на земле",64123,null],[78799,"2026-06-27T20:42:04",9,"*Леда ищет что-то что напоминало бы метку, своими золотистыми глазами.*",64123,null],[78801,"2026-06-27T20:42:30",9,"/roll 1d20+3 по закону равновесия вероятностей",64123,null],[78803,"2026-06-27T20:42:58",9,"//Оооооо, как всегда! 22, мой любимый число 🥰",64123,null],[78804,"2026-06-27T20:43:25",5,"Метки здесь не видно. Однако ты понимаешь, что под ногами лежат отдельные костяшки. И чуешь, что чем дальше вниз, тем их больше",78802,null],[78805,"2026-06-27T20:43:35",32,"/Ну я посохом постукиваю по костям держа на готове огненную стрелу.",78798,null],[78806,"2026-06-27T20:44:02",32,"/запоздал запрос но ок",64123,null],[78807,"2026-06-27T20:44:18",5,"// кидайте иню",64123,null],[78808,"2026-06-27T20:44:41",5,"Спустя несколько минут пути в ваших головах звучит незнакомый голос, как будто мужской",64123,null],[78810,"2026-06-27T20:44:54",5,"// это чтобы отдельно ответили ему",64123,null],[78811,"2026-06-27T20:45:45",32,"/roll d20+7",64123,null],[78814,"2026-06-27T20:46:11",32,"/что я слышу в голосе? И могу ли понять откуда источник?",78810,null],[78815,"2026-06-27T20:46:19",47,"/r d20+4",64123,null],[78818,"2026-06-27T20:47:03",9,"/roll 1d20-1 инициатива",64123,null],[78820,"2026-06-27T20:47:14",5,"// в свой ход бросишь магию",78814,null],[78821,"2026-06-27T20:47:17",5,"// пока талону",64123,null],[78822,"2026-06-27T20:47:17",9,"— Гиблое место...",64123,null],[78823,"2026-06-27T20:47:46",32,"/какая сложность проверки будет?)",78820,null],[78825,"2026-06-27T20:49:00",5,"В голове эльфа раздаётся обеспокоенный голос.\n\n— Прямо здесь, в карьере он ударил меня в спину. Тебе ведь знакомо, как это бывает? Ты не можешь доверять союзникам.  Ты должен уходить отсюда, немедленно!",64123,null],[78826,"2026-06-27T20:49:26",5,"// ответь чтобы снизить сложность проверки",64123,null],[78827,"2026-06-27T20:49:30",5,"// мм 18",78823,null],[78830,"2026-06-27T20:50:32",32,"//я слышу это же?",78825,null],[78833,"2026-06-27T20:51:06",5,"// ща напишу другим, чтобы думали над ответом",64123,null],[78834,"2026-06-27T20:51:35",5,"Голос в голове жука звучит пугающе.\n\n— Такой хрупкий, такой слабый. Зачем ты здесь? Возвращайся, не погибай зря! Надеешься на спутников? Им на тебя плевать, не обольщайся!",64123,null],[78838,"2026-06-27T20:52:59",5,"Властный голос прозвучал в голове Леды.\n\n— Я знаю, кто ты, Покажи себя настоящего! Они слабы, они не друзья тебе. Убей их! Убей! Убей! Убей!",64123,null],[78839,"2026-06-27T20:53:14",32,"я просто транслирую своей телепатией это же союзникам как пересылка за одно накладывая послания друг на друга и получая кашу из видений а не четкое указание",78834,null],[78841,"2026-06-27T20:53:50",32,"А ещё определяю источник",64123,null],[78842,"2026-06-27T20:54:04",32,"Знамения 15+5 аркана",64123,null],[78843,"2026-06-27T20:54:41",9,"— Гррррр, смерти не заслуживает никто. — *Леда скорее злится на голос за то что тот говорит, сам Леда ещё учился жить, но он скорее умрет сам.*",78838,null],[78844,"2026-06-27T20:54:44",32,"//у союзников преимущество спасброска",78839,null],[78845,"2026-06-27T20:55:19",9,"*Великану плевать, слышит это только он или все. Говорит вслух.*",64123,null],[78846,"2026-06-27T20:55:22",5,"Это телепатическая передача с Эфирного плана. Однако существо должно находиться недалеко, если оно проявиться на Материальном",78842,null],[78847,"2026-06-27T20:55:33",47,"- Меня не били в спину - растерян эльф - хотя им я и не доверяю... - сомнения борятся с эльфом",78825,null],[78848,"2026-06-27T20:55:43",5,"// союзники могут отыграть преиущество",78844,null],[78849,"2026-06-27T20:56:14",32,"//у них сразу несколько голосов в головах один из которых обращается к жуку",64123,null],[78850,"2026-06-27T20:57:02",32,"//враг эфирен? Бред. Но мне все больше не нравятся карьер",78846,null],[78851,"2026-06-27T20:57:32",5,"// сложность меньше. Все кидайте спас мудрости",78849,null],[78854,"2026-06-27T20:58:19",32,"/roll d20+4",64123,null],[78856,"2026-06-27T20:58:41",32,"/Спас я прохожу",78855,null],[78857,"2026-06-27T20:59:43",9,"*Леда просто уверен в своих решениях, полностью даже если получит кинджал под лопатку он от них не отступит пока это не произойдёт на самом деле.*",64123,null],[78858,"2026-06-27T21:00:20",9,"/roll 1d20+1 мудрость, но по мне так харизма больше пожошла как сила личности",64123,null],[78860,"2026-06-27T21:01:19",9,"*Великану просто плевать на голос в голове, тот скорее его раздражает чем сеет сомнения.*\n\n//Надеюсь так?)",78859,null],[78861,"2026-06-27T21:01:37",5,"// вы не знаете)",64123,null],[78862,"2026-06-27T21:02:05",9,"//Ну ты дм, ты и описывай. Пишу как чувствую",64123,null],[78863,"2026-06-27T21:02:18",5,"Но спустя несколько секунд Леда своим острым взглядом замечает какое-то пятно на стене впереди",64123,null],[78864,"2026-06-27T21:02:21",32,"//поддерживаю",78862,null],[78865,"2026-06-27T21:02:43",47,"Услышав разные послания эльф понимает, здесь что-то не так",64123,null],[78866,"2026-06-27T21:02:59",9,"— Я слышу голос, и он подстрекает меня на поступки о которых я бы и не подумал.",64123,null],[78867,"2026-06-27T21:03:00",47,"/r +d20+1",64123,null],[78869,"2026-06-27T21:03:25",47,"/не прошёл/",64123,null],[78870,"2026-06-27T21:03:25",9,"*Прижмуривается чтобы понять что там.*",78863,null],[78871,"2026-06-27T21:03:28",5,"// такс",64123,null],[78872,"2026-06-27T21:03:36",5,"*Это метка. Наверняка*",78870,null],[78873,"2026-06-27T21:03:41",5,"Эльф 16\nЖук 15\nЛеда 11\nПризрак\nСкелеты",64123,null],[78876,"2026-06-27T21:03:48",5,"// ход эльфа",64123,null],[78878,"2026-06-27T21:03:58",5,"// говорить персами в чужой ход можно",64123,null],[78879,"2026-06-27T21:04:13",47,"/сори, я на 10-15 мин отошёл",64123,null],[78880,"2026-06-27T21:04:18",9,"//Ну, по мне с преимуществом, леда не ждет удара от союзника",64123,null],[78881,"2026-06-27T21:04:47",5,"// хд тебя пока не бьют вроде",78880,null],[78882,"2026-06-27T21:04:51",5,"// ходи жук",64123,null],[78883,"2026-06-27T21:05:02",32,"/По кому?",78880,null],[78884,"2026-06-27T21:05:16",32,"Опиши что я вижу или слышу хоть",64123,null],[78889,"2026-06-27T21:06:54",5,"Отряд стоит в каньоне, бок о бок. Впереди виднеется что-то на стене. Голос в голове затих",64123,null],[78890,"2026-06-27T21:07:07",32,"Передаю союзникам\n\"Не слушайте голос в голове это все специально для вас подобранная ложь\"\nпока что я иду к метке, чтобы осмотреть что там есть.",64123,null],[78902,"2026-06-27T21:11:43",5,"Ты в 15 футах от метки. Какая-то краска нанесенная на песчаную стену карьера. Ничего особенного. Рядом с ней на земле что-то торчит из тумана",64123,null],[78903,"2026-06-27T21:12:55",32,"Я иду вперёд осмотреть место около метки искать скарб Но если что-то нападёт я держу как отложенное действие громовая волна.",64123,null],[78904,"2026-06-27T21:13:52",5,"// ты истратил движение, если идти дальше - то дейтсвие рывок",78903,null],[78905,"2026-06-27T21:14:07",5,"// а значит без подготовленного",64123,null],[78907,"2026-06-27T21:14:57",9,"//Короче, я тоже иду, чё",64123,null],[78908,"2026-06-27T21:15:02",32,"//а ок тогда именно подготовленные действие",78904,null],[78909,"2026-06-27T21:15:14",5,"// ходи, ещё что-то?",78907,null],[78910,"2026-06-27T21:15:21",9,"*Леда идёт рядом.*",64123,null],[78911,"2026-06-27T21:16:15",9,"//Я бля откуда знаю что и куда произойдётс перс не ипёт, думает все норм, он даже не знает что жук подготовил закл который и по нему попадёт)",78909,null],[78913,"2026-06-27T21:17:12",32,"//почему и по тебе? Если ты со мной в одной клетке то не попадет. Как и если мы за мной или сбоку меня",78911,null],[78914,"2026-06-27T21:17:31",5,"Туман недвижно лежит, куча не шевелится, снизу всё так же доносится неприятный хруст. Ничего не происходит",64123,null],[78916,"2026-06-27T21:17:43",9,"//Думаю эльфа го ждать",64123,null],[78917,"2026-06-27T21:18:04",5,"// окей да",78916,null],[78918,"2026-06-27T21:18:10",32,"/ да и вариантов у меня два либо волна либо хаотический заряд. Второй нас всех может поубивать",64123,null],[78920,"2026-06-27T21:18:32",5,"// сейчас у эльфа 2 хода будет",64123,null],[78921,"2026-06-27T21:18:58",9,"//Мне очень не нравится что мы без него + громовая волна использует жука как точку выхода и никак не контролируется на остальных или ты чародей/военный маг с абилками/метамагией которые это фиксят?)",64123,null],[78922,"2026-06-27T21:19:08",32,"//мастер. Когда закончим с тайником. Я хочу дракона",78917,null],[78923,"2026-06-27T21:19:43",5,"// да, закончим сегодня скорее всего",78922,null],[78924,"2026-06-27T21:19:45",9,"//Короче не парься, я переживу, хп больше всего",64123,null],[78926,"2026-06-27T21:20:31",32,"/Неа нихрена нет но как я сказал жук просто не пустит идущего сзади Леду вперёд",78921,null],[78933,"2026-06-27T21:27:44",32,"(Высказывание голоса про слабость жука заставило того не бежать а наоборот немного разозлится так как слабых среди жуков не бывает бывают не стандартные и он знает что его интелект как волшебника выдающийся и хочет доказать силу своей магии. Потому и подготовил самое прямое к силе заклинание громовая волна)",64123,null],[78957,"2026-06-27T22:03:34",9,"//Учитывая что Миха в ирл нагруже то скорей всего сегодня усё",64123,null],[78959,"2026-06-27T22:04:04",47,"/я тут",64123,null],[78960,"2026-06-27T22:04:09",47,"/у меня есть полчаса час",64123,null],[78961,"2026-06-27T22:04:43",5,"// окей, посмотрим сколько успеем",78960,null],[78962,"2026-06-27T22:05:21",47,"Талон оглядывает своих союзников. Как же они кажутся ему подозрительными... И сообщение это... Ощущение будто жук сам планирует ударить в спину. Просто ждёт момента... Талон не будет подставляться, но едва союзники будут ослаблены, он ударит им в спину",64123,null],[78963,"2026-06-27T22:05:32",9,"//Оооо, збс. На Веспираль не отвлекайся, потом доиграем",78960,null],[78964,"2026-06-27T22:05:43",5,"// у тебя сразу 2 хода",78962,null],[78965,"2026-06-27T22:05:58",47,"Голос разговаривает лишь с Талоном, ведь это Он! Избранный",64123,null],[78967,"2026-06-27T22:07:07",47,"Талон исчезает в тумане (ебанный ниндзя, то в дожде, то в тумане)",64123,null],[78968,"2026-06-27T22:07:10",47,"/r +d20+6",64123,null],[78971,"2026-06-27T22:07:48",47,"И движется так, чтобы его никто не заметил, а сам оглядывается. На Луке стрела он готов совершить, атаку по любому, кто покажется ему подозрительным",64123,null],[78976,"2026-06-27T22:09:14",5,"//куда ты идёшь",78927,null],[78978,"2026-06-27T22:10:13",32,"//могли бы пингануть раз продолжили",64123,null],[78979,"2026-06-27T22:10:18",47,"Я встаю в углубление справа",64123,null],[78981,"2026-06-27T22:10:29",47,"/сори, я ходы отписывал",78978,null],[78983,"2026-06-27T22:10:37",47,"/чисто свои/",64123,null],[78984,"2026-06-27T22:10:46",5,"// ход?",78979,null],[78985,"2026-06-27T22:11:01",47,"/да. Два действия совершено",64123,null],[78986,"2026-06-27T22:11:04",32,"//я просто отошёл заниматься своими и проверил почти на экстрасенсорике",78981,null],[78987,"2026-06-27T22:11:06",47,"/скрыт, и заготовка.",64123,null],[78991,"2026-06-27T22:12:16",5,"// ход твой",78986,null],[78992,"2026-06-27T22:12:45",32,"(жук подходит к метке осматривая метку. Он заметил что Талон ушёл в скрыт и видимо поддался искушению. Но просто ждёт становясь так чтобы прикрыться Ледой (+2 КД лишними не будут)",64123,null],[78993,"2026-06-27T22:13:05",47,"/как же вы это всё чётко без бросков понимаете. Может он тыл прикрывает",78992,null],[78994,"2026-06-27T22:13:11",5,"// чтобы укрыться за Ледой надо вернуться к нему",78992,null],[78995,"2026-06-27T22:13:17",32,"И собственно подходит к метке осматривая метку",64123,null],[78996,"2026-06-27T22:13:25",5,"// и да, жук больше не видит эльфа",78993,null],[78997,"2026-06-27T22:13:28",9,"//Да я иду рядом, что)",64123,null],[78998,"2026-06-27T22:13:31",32,"//Леда со мной шел рядом за спиной",78994,null],[78999,"2026-06-27T22:13:44",9,"//Пох то, мы не сражаемся вродь.",64123,null],[79000,"2026-06-27T22:13:47",5,"Краска на стене. Просто краска",78995,null],[79001,"2026-06-27T22:13:55",32,"/А у нас карьер линия.",64123,null],[79002,"2026-06-27T22:14:11",32,"/Ну я осматриваю вокруг ищу тайник",79000,null],[79003,"2026-06-27T22:14:34",5,"Тайника рядом в стене определённо нет",79002,null],[79004,"2026-06-27T22:14:37",5,"// ход?",64123,null],[79005,"2026-06-27T22:15:21",32,"Нет я всматриваюсь в туман в низ и спускаюсь на ступеньку вниз \nВосприятие знамение 20+4",64123,null],[79006,"2026-06-27T22:15:33",47,"Оу май гад/",64123,null],[79007,"2026-06-27T22:15:34",32,"(кстати эльфа я то же вижу)",64123,null],[79008,"2026-06-27T22:15:53",47,"/если спецом его ищешь, то да",64123,null],[79009,"2026-06-27T22:16:18",9,"— Старик говорил что увидев метку надо спустится вниз. Там и тайник.",64123,null],[79011,"2026-06-27T22:16:29",32,"Магия прорицания показывает и подсвечивает все интересное. Специально не искал но магия и эльфа спалила",64123,null],[79012,"2026-06-27T22:16:59",32,"/хотя с начала искал того кто на нас видение наслал",79005,null],[79013,"2026-06-27T22:17:38",47,"/я кажется скоро начну такие заявки в лс мастеру кидать, как же заебало сверх интелектуальная игра от всех/. В общем лук направлен в сторону в вашу",64123,null],[79014,"2026-06-27T22:18:01",5,"Жук разглядел в стене ступени признаки засыпанныз песком досок. А ещё слабое сияние прямо перед его лицом",79005,null],[79015,"2026-06-27T22:18:14",9,"//Мне пох, я не жду подвоха)",64123,null],[79016,"2026-06-27T22:18:23",32,"/что за сияние?",79014,null],[79017,"2026-06-27T22:18:24",5,"// нет, ты не смотрел в сторону эльфа. Не видишь",79005,null],[79018,"2026-06-27T22:18:40",5,"// ты не знаешь",79016,null],[79019,"2026-06-27T22:18:43",9,"//Вот за Хардинта да, там бы была бы игра в амонгас",64123,null],[79020,"2026-06-27T22:18:47",32,"/я ведь тоже могу родить броски знамения в ЛС.",79013,null],[79021,"2026-06-27T22:18:56",47,"/го",79020,null],[79022,"2026-06-27T22:19:13",32,"/да и кучу другого",79021,null],[79023,"2026-06-27T22:19:44",32,"//я впринципе осматривался. но ладно",79017,null],[79025,"2026-06-27T22:19:58",5,"// ход харда",64123,null],[79026,"2026-06-27T22:20:41",32,"Жук указал на них Леде",79014,null],[79027,"2026-06-27T22:20:54",32,"/ход",64123,null],[79029,"2026-06-27T22:21:36",9,"*Леда просто идёт, ищет противников, но скорее нежить.*\n\n//А так бля я хз, если дошел то вместе с жуком же, хз что делать",64123,null],[79032,"2026-06-27T22:22:38",5,"// ок, ты с жуком",79029,null],[79033,"2026-06-27T22:23:21",32,"(жук показал на ступеньки) и за одно передал всем.\n-Я вижу странную синюю дымку прямо перед мной.\n/Для! Это аватар через заклинание \"эфирность\"?",79029,null],[79035,"2026-06-27T22:23:40",47,"/r d20 для себя бросок",64123,null],[79037,"2026-06-27T22:24:21",47,"Эльф резко что-то понимает \"Тебя предали союзники, верно? И ты ненавидишь тех, кто  предаёт?\"",64123,null],[79038,"2026-06-27T22:24:30",47,"/мысль практически вслух",64123,null],[79040,"2026-06-27T22:25:47",32,"/он это в слух? Чтобы мы услышали?",79038,null],[79041,"2026-06-27T22:26:09",47,"/мысль практически вслух. Имеется ввиду что буквально громкая мысль. Без текста",64123,null],[79042,"2026-06-27T22:26:15",47,"/без вслух",64123,null],[79044,"2026-06-27T22:26:48",32,"/а свою догадку жук озвучил телепатией",79033,null],[79045,"2026-06-27T22:26:50",5,"Дымка материализовалась прямо перед лицом жука. Размытый полупрозрачный образ какого-то мужчины. И он завопил прямо в лицо.\n\n— Слабый жук! Не... Трогаааай!\n\nУдар исчезающей руки полетел в жука.",64123,null],[79046,"2026-06-27T22:26:59",5,"https://www.youtube.com/watch?v=7ZBIEskpbXY&list=PLnFCQHcdt5oGZ8sqTNhZTirNA8a5aVu_G&index=2",64123,null],[79047,"2026-06-27T22:27:01",5,"// музыка",64123,null],[79048,"2026-06-27T22:27:08",47,"/+++",64123,null],[79049,"2026-06-27T22:27:11",5,"/r +5 атака",64123,null],[79051,"2026-06-27T22:27:38",32,"Громовая волна или призрак имуннет к звуку. Вродь только сопротивление",79045,null],[79052,"2026-06-27T22:27:43",5,"// кому адресовано?",79037,null],[79053,"2026-06-27T22:27:53",47,"/голосу",79052,null],[79055,"2026-06-27T22:28:22",5,"Голос откликнулся в голове эльфа\n\n\"Верно... Так и было... Один удар в спину...\"",79037,null],[79056,"2026-06-27T22:28:47",5,"// волну реакцией? рядом с тобой леда",79051,null],[79057,"2026-06-27T22:28:49",32,"/Если что я по реакции атакую первым",79051,null],[79058,"2026-06-27T22:28:58",32,"Он за мной",79056,null],[79059,"2026-06-27T22:29:12",47,"\"Тогда ты будешь ненавидеть и меня. Смысла нет бить союзниками в спину, они меня не предавали\"",64123,null],[79060,"2026-06-27T22:29:16",32,"И потому не попадает в куб ПЕРЕД мной",64123,null],[79061,"2026-06-27T22:29:35",47,"/r +d20+8",64123,null],[79063,"2026-06-27T22:29:41",32,"Подожди я реакция первый",79059,null],[79064,"2026-06-27T22:29:49",47,"Тоже реакция/",79063,null],[79066,"2026-06-27T22:30:04",5,"// он не твоём радиусе зрения. Они на ступени ниже, а ты у стенки",79061,null],[79067,"2026-06-27T22:30:10",32,"У призрака спас силы ещё следом тогда",64123,null],[79069,"2026-06-27T22:30:20",47,"А, хорошо/",79066,null],[79070,"2026-06-27T22:30:52",32,"Мастер сложность спас броска 13. Какая у призрака сила",64123,null],[79071,"2026-06-27T22:30:54",47,"Просто тут не видно как союзники двигались, я то думал на одной ступеньке с ними",78927,null],[79072,"2026-06-27T22:31:03",47,"/там спас тела?",79070,null],[79073,"2026-06-27T22:31:06",47,"Ведь",64123,null],[79074,"2026-06-27T22:31:13",5,"/r тело",64123,null],[79076,"2026-06-27T22:31:28",5,"// урон волны",64123,null],[79077,"2026-06-27T22:31:51",32,"Ок тело. Но его от меня сметает на десять футов и сбивает с ног (если призрак может упасть ничком)",79072,null],[79078,"2026-06-27T22:32:03",32,"/roll 2d8",64123,null],[79081,"2026-06-27T22:32:20",32,"/сопротивление есть?",64123,null],[79082,"2026-06-27T22:33:50",5,"Звуковая волна отбрасывает призрака от тебя. Его дымка рвётся, исчезая в тумане. Он как будто растворяется, ты не видишь никого на своей ступени.",64123,null],[79083,"2026-06-27T22:33:54",32,"/Значит я не так помню. Волшебника уже память не та",79072,null],[79084,"2026-06-27T22:34:03",5,"// вот на это я не отвечать не буду",79081,null],[79085,"2026-06-27T22:34:16",5,"// персы сами думать должны",64123,null],[79086,"2026-06-27T22:34:29",5,"// ход жука",64123,null],[79087,"2026-06-27T22:34:47",5,"Под ногами ты чувствуешь кости и ткань.",64123,null],[79088,"2026-06-27T22:35:10",32,"(кстати волна громыхнула знатно)",79086,null],[79089,"2026-06-27T22:35:26",5,"// и жук об этом знает",79088,null],[79090,"2026-06-27T22:35:51",32,"/Спускаюсь вниз искать тайник. У меня все равно нечем проявить гада.",79086,null],[79091,"2026-06-27T22:36:24",5,"// ты стоишь перед засыпанной песком деревянной загородки",79090,null],[79093,"2026-06-27T22:37:09",32,"/но телепатией передаю всем.\n-Тут привидение, оно живо и может атаковать в любой момент. Будьте бдительны",64123,null],[79094,"2026-06-27T22:37:23",5,"// а сорри",64123,null],[79095,"2026-06-27T22:37:26",5,"// ход эльфа блин",64123,null],[79096,"2026-06-27T22:37:31",5,"// @cirson",64123,null],[79097,"2026-06-27T22:37:36",32,"/Лепка земли чтобы раскопать засыпаное",79091,null],[79099,"2026-06-27T22:39:04",47,"Эльф спускается ниже, стрела заготовлена. Он на ступени с союзниками, рядом с местом где был грохот. В тумане",64123,null],[79100,"2026-06-27T22:39:07",47,"/ход",64123,null],[79101,"2026-06-27T22:39:22",32,"/Ход",79097,null],[79102,"2026-06-27T22:40:22",32,"...",79093,null],[79103,"2026-06-27T22:40:43",5,"Перед отрядом сколоченные вместе доски. Навес, стоит вертикально и свободен от земли.",79101,null],[79104,"2026-06-27T22:40:58",9,"//Я, нихуя не понимаю",64123,null],[79105,"2026-06-27T22:41:03",32,"//открывать явно Леде",64123,null],[79106,"2026-06-27T22:41:13",47,"/я не могу слышать тебя. Ты должен видеть существт",79093,null],[79107,"2026-06-27T22:41:18",9,"*Леда просто идёт держа в руке алибарду.*",64123,null],[79108,"2026-06-27T22:41:39",32,"/это твои проблемы",79106,null],[79110,"2026-06-27T22:41:59",5,"// куда?",79107,null],[79111,"2026-06-27T22:42:00",47,"/ну я поясняю. На всякий случай",64123,null],[79113,"2026-06-27T22:42:28",9,"//С жуком",79110,null],[79114,"2026-06-27T22:42:38",5,"// вы втроём на ступени перед досками. Призрак появился, а потом сдуло волной жука. Которая славно громыхнула",79104,null],[79115,"2026-06-27T22:42:47",32,"//я уточняю что я передал всем кому мог. Если появишься в поле зрения то и тебе скажу",79111,null],[79116,"2026-06-27T22:43:05",9,"//Тоесть жука с нами уже нет?",64123,null],[79118,"2026-06-27T22:43:16",47,"/призрака нет",79116,null],[79119,"2026-06-27T22:43:28",47,"/жук волну грома ебнул",64123,null],[79120,"2026-06-27T22:43:34",9,"//А, просто читаю что жука волной сдуло 😂👍",64123,null],[79121,"2026-06-27T22:43:54",47,"Волна чья? Жука/",64123,null],[79122,"2026-06-27T22:44:47",32,"-Леда будь добр, открой.",64123,null],[79124,"2026-06-27T22:45:13",9,"*Открывает.*",64123,null],[79125,"2026-06-27T22:45:14",32,"(указываю на ну как оно там выглядит если закрыто)",64123,null],[79126,"2026-06-27T22:45:25",5,"// проверка силы",79124,null],[79127,"2026-06-27T22:45:30",9,"//Похуй",79125,null],[79128,"2026-06-27T22:45:59",9,"*Леда ложит алибарду и сука не открывает, а вырывает нахуй.*",79126,null],[79129,"2026-06-27T22:46:36",9,"/roll 1d20+2 сила если проверка все ещё требуется, но у меня даже грузоподьёмность удвоена",64123,null],[79132,"2026-06-27T22:46:44",9,"//Ууув сука",64123,null],[79133,"2026-06-27T22:47:01",5,"Похоже, силы покинули Леду. Он пыхтит, но доски не поддаются",64123,null],[79134,"2026-06-27T22:47:16",9,"//Ладно",64123,null],[79135,"2026-06-27T22:47:19",32,"-Дядя великан давай!",64123,null],[79136,"2026-06-27T22:47:28",5,"// действие потратил",64123,null],[79137,"2026-06-27T22:47:28",32,"Помощь (моральная)",64123,null],[79138,"2026-06-27T22:47:30",47,"/опасности больше не возникает?",64123,null],[79139,"2026-06-27T22:47:32",9,"*Берет алибарду и просто рубит.*",64123,null],[79140,"2026-06-27T22:47:42",5,"// не твой ход",79137,null],[79141,"2026-06-27T22:47:43",9,"/roll 1d20+4 алибардой",64123,null],[79144,"2026-06-27T22:47:53",5,"// попал, кидай урон",79142,null],[79145,"2026-06-27T22:47:56",9,"//А мы по ходам?",64123,null],[79146,"2026-06-27T22:47:57",32,"//говорить можно в любой)",79140,null],[79147,"2026-06-27T22:48:06",9,"/roll 1d10+2 урон",64123,null],[79150,"2026-06-27T22:48:20",47,"Устал/",64123,null],[79151,"2026-06-27T22:48:24",47,"Леда/",64123,null],[79152,"2026-06-27T22:48:29",5,"Доски выглядят для тебя неприступным бастионом.",79148,null],[79153,"2026-06-27T22:49:13",9,"//Мой заклятый враг, нищкие потолки, тесные помещения, узкие проходы... и доски...",64123,null],[79155,"2026-06-27T22:49:41",32,"-Хочешь анекдот расскажу?",64123,null],[79156,"2026-06-27T22:49:57",32,"(Решил жук поднять всем настроение)",64123,null],[79157,"2026-06-27T22:51:09",5,"Призрак возник будто из-под земли. А точнее дымка вылетела прямо из засыпанной песком ткани у вас под ногами. Она сформировалась в тело и ударила потного варвара",64123,null],[79158,"2026-06-27T22:51:13",5,"/r +5",64123,null],[79160,"2026-06-27T22:51:18",32,"-Был гордый и величественный дракон. Имя его давно стёрлось в веках но прославился он тем что никогда не преклонял голову. Говорят борозды в потолках находят до сих пор",64123,null],[79161,"2026-06-27T22:51:27",47,"/r +d20+8",64123,null],[79163,"2026-06-27T22:51:35",47,"/r d20+8 переброс",64123,null],[79165,"2026-06-27T22:51:45",47,"/r d8+4 если урон есть",64123,null],[79167,"2026-06-27T22:52:12",5,"При виде призрака ты перепугался, хоть его слова не убедили тебя, что-то внутри дрожало.\n\n//ты не прошёл спас, помеха",79161,null],[79168,"2026-06-27T22:52:37",47,"/а, ну тогда Крит провал",64123,null],[79169,"2026-06-27T22:53:21",32,"(Анекдот рассказываю и призраку раз он в поле зрения то слышит)",79160,null],[79170,"2026-06-27T22:53:33",32,"(а то как не родной)",79169,null],[79171,"2026-06-27T22:53:55",5,"Стрела улетела куда-то вглубь карьера, звякнув вдали",79168,null],[79172,"2026-06-27T22:54:35",5,"/r 3d6+3 урон леде",79159,null],[79174,"2026-06-27T22:55:23",32,"/вы его ещё сходу вынесете.",79173,null],[79175,"2026-06-27T22:55:34",5,"Волна звука пробудила что-то внизу. Хруст нарастает и приближается.",64123,null],[79176,"2026-06-27T22:55:47",32,"/а анекдот как-то на призрака повлияет?",64123,null],[79177,"2026-06-27T22:56:02",5,"// он его услышал",79176,null],[79178,"2026-06-27T22:56:09",32,"/кану на всякий случай выступление",64123,null],[79179,"2026-06-27T22:56:25",32,"/roll d20+4",64123,null],[79181,"2026-06-27T22:56:39",5,"// ход эльфа",64123,null],[79182,"2026-06-27T22:56:44",32,"(ну явно не то на что рассчитывал)",64123,null],[79183,"2026-06-27T22:56:49",9,"/roll 1d12+3 стойкость камня реакцией",79173,null],[79185,"2026-06-27T22:57:04",9,"*Леда жить будет.*",64123,null],[79187,"2026-06-27T22:59:50",32,"/кажется сначала я хожу а потом эльф.\nИли ждём?",64123,null],[79189,"2026-06-27T23:00:29",9,"//Я за ждать, всё равно почти",64123,null],[79190,"2026-06-27T23:00:37",5,"// ок, ждём",64123,null],[79191,"2026-06-27T23:00:45",32,"Тогда пингуйте",64123,null],[79192,"2026-06-27T23:01:00",5,"// @cirson",64123,null],[79196,"2026-06-27T23:06:21",47,"Эльф появляется и говорит: \n- предлагаю забрать сундук и оставить призрака одного!",64123,null],[79198,"2026-06-27T23:07:34",47,"/лады, я ушёл. Больше не могу, спать пора",64123,null],[79199,"2026-06-27T23:09:26",9,"//Я ща то чтобы завтра доиграть",64123,null],[80401,"2026-06-28T19:32:06",5,"// вы свободны доиграть сегодня?",64123,null],[80402,"2026-06-28T19:32:22",5,"Hard @cirson @Xaosick",64123,null],[80403,"2026-06-28T19:36:58",32,"(только если минимум через пол часа)",64123,null],[80404,"2026-06-28T19:44:48",9,"//Голова болит но могк как нит",64123,null],[80405,"2026-06-28T19:44:56",9,"//Тпблетку сел",64123,null],[80408,"2026-06-28T19:51:18",47,"/тут",64123,null],[80411,"2026-06-28T19:52:38",32,"/Я кое-как справился. Но жука явно контузило его же громовой волной",64123,null],[80416,"2026-06-28T19:53:39",32,"/на сеновале кидал проверки атлетики и телосложения. Вроде прошел но это была жесть",64123,null],[80417,"2026-06-28T19:57:51",5,"// м? Играть готовы?",80416,null],[80418,"2026-06-28T19:58:38",32,"//готовы начинай",64123,null],[80419,"2026-06-28T19:58:54",32,"Ход Талона",64123,null],[80424,"2026-06-28T19:59:39",5,"/ @cirson",64123,null],[80425,"2026-06-28T20:02:51",47,"Эльф пытается взломать сундук",64123,null],[80426,"2026-06-28T20:03:01",47,"/r d20+6 ловкость рук",64123,null],[80428,"2026-06-28T20:03:15",5,"Там деревянный заслон",64123,null],[80430,"2026-06-28T20:04:53",32,"-я могу выбить его заклинанием",64123,null],[80438,"2026-06-28T20:13:08",47,"/что за заслон?",64123,null],[80439,"2026-06-28T20:13:13",47,"Не понимаю?",64123,null],[80440,"2026-06-28T20:13:34",47,"Ну ок тогда оказываю помощь великану и держу с другой стороны слегка ящик. Чтобы легче вытащить",64123,null],[80441,"2026-06-28T20:13:46",47,"- Утаскиваем ящик!",64123,null],[80442,"2026-06-28T20:14:28",5,"Перед отрядом сколоченные вместе доски. Навес, стоит вертикально и свободен от земли.",64123,null],[80443,"2026-06-28T20:14:28",5,"*Леда ложит алибарду и сука не открывает, а вырывает нахуй.*",64123,null],[80444,"2026-06-28T20:14:29",5,"Похоже, силы покинули Леду. Он пыхтит, но доски не поддаются",64123,null],[80446,"2026-06-28T20:17:53",47,"Сори не совсем понимаю со стороны как выглядит, слегка туплю. В общем действие помощь, помогаю вырвать нахуй херню. Свободным действием убрал лук",64123,null],[80447,"2026-06-28T20:18:21",5,"// ход?",64123,null],[80450,"2026-06-28T20:20:29",32,"/а какая у эльфа с учётом+4 ловкость собственно сила",80446,null],[80452,"2026-06-28T20:27:21",5,"// твой ход",80450,null],[80453,"2026-06-28T20:30:16",32,"/Так что с дверью переброс силы Ледой за помощь эльфа будет?",80452,null],[80454,"2026-06-28T20:31:12",5,"// в ход Леды у него преимущество на открытие",80453,null],[80455,"2026-06-28T20:32:32",32,"(Мм ну что же я осматриваюсь вокруг ищу врагов и держу на отложенное действие огненную стрелу в увиденного",80454,null],[80456,"2026-06-28T20:32:41",32,"Ход",64123,null],[80457,"2026-06-28T20:32:51",9,"//Щас охуеете ток мой ход будет",64123,null],[80458,"2026-06-28T20:32:59",5,"// призрак прямо перед тобой",80455,null],[80460,"2026-06-28T20:35:13",32,"Хз тогда кидаю хаотический заряд в дальнего скелета",80458,null],[80461,"2026-06-28T20:35:18",9,"*Леда входит в транс (ярость) у него нет перед глазами ничего кроме этих досок, он поднимает руки и со всех сил (безрассудно) бъет по ним, кулаки крепко сжимаются словно он черпает силы откуда-то (удар великана).*",64123,null],[80462,"2026-06-28T20:35:34",9,"//Бросок атаки все ещё нужен?)))",80461,null],[80463,"2026-06-28T20:35:48",5,"// давай",80460,null],[80464,"2026-06-28T20:35:54",5,"// погоди, жук",80461,null],[80465,"2026-06-28T20:36:10",9,"//Мы вродь не мешаем друг другу но ладно",64123,null],[80466,"2026-06-28T20:36:14",32,"/roll d20+5",80460,null],[80468,"2026-06-28T20:36:27",32,"Попал?",64123,null],[80469,"2026-06-28T20:36:53",32,"/roll 2d8+d6",64123,null],[80471,"2026-06-28T20:37:02",5,"//убил",80470,null],[80472,"2026-06-28T20:37:18",32,"У меня два одинаковых значения урона перескок",64123,null],[80473,"2026-06-28T20:37:46",32,"/roll 2d8+d6",64123,null],[80475,"2026-06-28T20:38:11",5,"// убил",80474,null],[80476,"2026-06-28T20:38:15",32,"И второго там если не ошибаюсь вообще психическим приложило",64123,null],[80477,"2026-06-28T20:38:27",5,"// можешь описать",64123,null],[80478,"2026-06-28T20:38:47",32,"//сейчас посмотрю что там первый урон тройка)",64123,null],[80479,"2026-06-28T20:39:38",47,"/там атака при перескоке тоже кидается",64123,null],[80480,"2026-06-28T20:40:42",32,"Да сейчас кину.",80479,null],[80481,"2026-06-28T20:40:53",32,"/roll d20+5",64123,null],[80483,"2026-06-28T20:41:32",32,"Первого скелета невнятная радужная жыжа взорвала пламенем а второго вморозила в лёд",64123,null],[80484,"2026-06-28T20:42:31",5,"// красиво но кинь проверку атлетики)",80461,null],[80485,"2026-06-28T20:43:12",9,"/roll +d20+4 атлетик",64123,null],[80487,"2026-06-28T20:43:28",5,"// с трудом пробился, опиши",80486,null],[80488,"2026-06-28T20:44:51",9,"*Тяжёлые руки провалились сквощь доски и застряли в них, кое с кским напором Леда их вытащил, доски — разбиты, повержены грубой силой, хоть и с трудом.*",80487,null],[80489,"2026-06-28T20:46:03",5,"В углублении в стене стоит сундук, изрядно присыпанный песком. За спиной Леды призрак тянёт свои руки к нему и шипит.\n\n— Так близкоооо! Наконец!",64123,null],[80490,"2026-06-28T20:46:21",5,"// действия?",64123,null],[80491,"2026-06-28T20:46:37",32,"/можно жук скажет?",64123,null],[80492,"2026-06-28T20:46:45",5,"// говорить можно",64123,null],[80493,"2026-06-28T20:46:48",9,"//Ход наверное, хотя в теории свободным можно сунду взять, хз",64123,null],[80494,"2026-06-28T20:46:59",32,"Подождите секунду",64123,null],[80495,"2026-06-28T20:47:06",5,"// сундук выглядит тяжёлым",80493,null],[80496,"2026-06-28T20:47:29",9,"//Не, ну у меня грузоподьёмность моё почтение, но видимо ход",80495,null],[80498,"2026-06-28T20:49:37",32,"//Так я вернулся. Сейчас тирада жука будет",64123,null],[80499,"2026-06-28T20:52:00",32,"(обращаясь к призраку и счелкая жвалами и дублируя телепатией)\n- ну что выкусил!? Это значит Я СЛАБЫЙ!!? Ты НИЧТОЖЕСТВО! Простой мстительный дух который просто хочет отомстить непонятно зачем конкретно нам, мы тебя видим впервые. И ты слабак!",64123,null],[80500,"2026-06-28T20:52:06",32,"Выступление",64123,null],[80501,"2026-06-28T20:52:14",32,"/roll d20+4",64123,null],[80503,"2026-06-28T20:52:29",32,"(я рассчитывал на большее",64123,null],[80504,"2026-06-28T20:52:36",9,"//Двойки, они везде. Это моё проклятие",80502,null],[80506,"2026-06-28T20:52:50",5,"// ща ход призрака",64123,null],[80507,"2026-06-28T20:53:14",32,"//ну в соло у меня вообще 4 единицы подряд падают так что двойка не так плохо",80504,null],[80510,"2026-06-28T20:56:07",5,"Призрак отвлёкся от созерцания заветного сундука. Теперь он смотрит на жука.\n\n— Ничтожество! Недостоин моего... тайника...",80499,null],[80511,"2026-06-28T20:56:12",5,"/r +5",64123,null],[80513,"2026-06-28T20:56:32",32,"//Мм ну прощайте друзья",64123,null],[80515,"2026-06-28T20:57:07",5,"// могу кинуть урон или просто скажу, что ты лежишь на песке, а над тобой шипуче смеётся привидение",64123,null],[80516,"2026-06-28T20:57:29",32,"Дай мне кинуть урон",64123,null],[80517,"2026-06-28T20:57:49",32,"/roll 6d6+6",64123,null],[80520,"2026-06-28T20:58:08",32,"Ну это точно больше моих 10 ХП",64123,null],[80521,"2026-06-28T20:58:25",9,"//Призрак атаковал огненным шаром?)",80518,null],[80522,"2026-06-28T20:58:37",32,"Меня капитально тряхнуло некротикой",64123,null],[80524,"2026-06-28T20:58:45",32,"У шара 8 д6",80521,null],[80525,"2026-06-28T20:58:47",5,"// ага, но мне не нравится мгновенная смерть. Так что ты ранен",80520,null],[80527,"2026-06-28T20:59:02",5,"// крит. ПРичём призрак с ослабленной атакой от мануала",80521,null],[80529,"2026-06-28T20:59:29",32,"Ну СР 4",64123,null],[80530,"2026-06-28T20:59:34",32,"Как ни как",64123,null],[80531,"2026-06-28T20:59:47",9,"— Талон... бери друга и убегай...",64123,null],[80532,"2026-06-28T20:59:50",32,"Кидать спас?",80525,null],[80533,"2026-06-28T21:00:00",5,"// нет, в твой ход спасы",80532,null],[80535,"2026-06-28T21:01:33",5,"Падая и прямо перед потерей сознания жук увидел на песке скелета в каком-то грязном, но удивительно целом доспехе. Компания топталась на нём всё время, пока открывала тайник. А теперь пустые глазницы как будто с усмешкой глядят на три-крина.",64123,null],[80537,"2026-06-28T21:02:07",5,"Хруст костей снизу становится всё сильнее и сильнее.",64123,null],[80538,"2026-06-28T21:02:09",5,"/r +2",64123,null],[80540,"2026-06-28T21:02:25",5,"Один скелет заполз по склону на вашу ступень",64123,null],[80541,"2026-06-28T21:02:33",9,"— БЕРИ ДРУГА И УБЕГАЙ ТАЛОН! — *Берет алибарду.*\n\n//Условно потратил то свободное что было",80531,null],[80543,"2026-06-28T21:02:41",5,"Он тыкает эльфа мечом",64123,null],[80544,"2026-06-28T21:02:50",5,"/r +4",64123,null],[80546,"2026-06-28T21:03:00",5,"// думаю не попал",64123,null],[80548,"2026-06-28T21:03:35",47,"/r d20 борьба мысли",64123,null],[80550,"2026-06-28T21:04:07",47,"Эльф считает, что жизнь насекомого не так важно и бьёт клиником по скелету (там же скелет, верно?)",64123,null],[80551,"2026-06-28T21:04:37",47,"Мастер? 0",64123,null],[80553,"2026-06-28T21:05:06",5,"// жук кидает спас",64123,null],[80556,"2026-06-28T21:05:14",5,"// 1 скелет и 1 призрак рядом",80550,null],[80559,"2026-06-28T21:05:57",5,"Тайник свободен от досок тоже",64123,null],[80560,"2026-06-28T21:06:07",47,"/r +d20+6",64123,null],[80562,"2026-06-28T21:06:14",47,"/r d20+6 по селу",64123,null],[80564,"2026-06-28T21:06:21",47,"/r 2d8+4",64123,null],[80566,"2026-06-28T21:06:25",5,"// убил",80565,null],[80567,"2026-06-28T21:07:26",47,"Вдруг эльф смазывается прямо в воздухе, ощущение будто он становится воплощением скорости. Он оказывается мгновенно у насекомого",64123,null],[80568,"2026-06-28T21:07:28",32,"/roll d20",80553,null],[80570,"2026-06-28T21:07:33",47,"/r d20+1 медицина",64123,null],[80573,"2026-06-28T21:07:44",47,"/всплеск действий",64123,null],[80574,"2026-06-28T21:07:54",47,"/а... Ещё мой ход не закончился, но ок",64123,null],[80575,"2026-06-28T21:08:04",5,"// стабилизация это действие",64123,null],[80576,"2026-06-28T21:08:22",47,"/я всплеск действий сделал. Он даёт действие",64123,null],[80577,"2026-06-28T21:08:44",5,"// да, удар + стабилизация",64123,null],[80578,"2026-06-28T21:08:53",47,"В общем я сейчас занят, отбежал вместе с насекомым на 15 футов. Схватить свободное",64123,null],[80579,"2026-06-28T21:09:36",5,"Призрак смотрит как ты уносишь жука от него и только трясётся в воздухе. Как будто от смеха",64123,null],[80581,"2026-06-28T21:12:18",9,"/roll 2d20+4 безрассудная по призраку без ярости чтобы совершить не действие атака а совершить атаку заговором громовой клинок на призрака",64123,null],[80583,"2026-06-28T21:12:55",5,"// так я не понял. Ты без ярости и это атака бонусным действием?",80581,null],[80584,"2026-06-28T21:13:14",9,"//Я совершаю атаку частью заговора громовой клинок",64123,null],[80585,"2026-06-28T21:13:31",9,"//Так как совершаю атаку решаю бить безрассудно",64123,null],[80586,"2026-06-28T21:13:44",9,"//Но без ярости чтобы наложить заговор",64123,null],[80587,"2026-06-28T21:14:09",32,"(Лежу, висю. Нихрена не вижу но все ещё соображаю так как не могу быть без сознания. Тело холодное полностью некротика морозит душу до самого позвоночника. Больно, холодно. Но я три-крин мы не сдаёмся",80579,null],[80589,"2026-06-28T21:14:37",9,"/roll 1d10+2+1d6 с ударом великана по призраку если шестнадцать хватило на попадание",80582,null],[80591,"2026-06-28T21:15:09",9,"//По мне с преимуществои и я без ярости, ход",64123,null],[80592,"2026-06-28T21:15:28",9,"*Леда кажется решил остаться здесь, союзники должны убежать...*",64123,null],[80593,"2026-06-28T21:15:42",9,"//Если призрак сдвинется — получит урон",64123,null],[80594,"2026-06-28T21:16:10",5,"Магический удар попал по призраку и как будто изорвал ветром его эфирную ткань. Но затем призракснова собрался воедино.",64123,null],[80595,"2026-06-28T21:17:04",32,"/кстати чувства и некоторые мысли жука слышат товарищи отрывочно",64123,null],[80596,"2026-06-28T21:17:10",5,"Привидение летит вокруг Леды и шепчет прямо в его голове.\n\n— Мой тайник... Мой! Уходиии... Уходи!",64123,null],[80597,"2026-06-28T21:17:25",5,"// кидай",80593,null],[80598,"2026-06-28T21:17:50",5,"/r +5 касается шеи ледяной рукой",64123,null],[80600,"2026-06-28T21:18:48",9,"/roll 1d8",80597,null],[80602,"2026-06-28T21:19:08",5,"/r 3d6+3",64123,null],[80605,"2026-06-28T21:19:20",5,"// урон Леде",80603,null],[80607,"2026-06-28T21:19:31",9,"*Пространство, колючее как стекло кусает призрака.*",80601,null],[80610,"2026-06-28T21:20:00",5,"*Призраку как будто всё равно, хотя куски его тела отлетают прочь*",80607,null],[80611,"2026-06-28T21:20:13",9,"/roll 1d12+3 выносливость камня",80603,null],[80613,"2026-06-28T21:20:38",5,"/r 3d20",64123,null],[80615,"2026-06-28T21:21:25",5,"Ещё 2 черепа скелетов показались снизу. Он взобрались на ступень и ползут за эльфом.\n\n// ничком",64123,null],[80616,"2026-06-28T21:21:47",5,"// ход @cirson",64123,null],[80618,"2026-06-28T21:28:05",47,"/r 3d20+6",64123,null],[80620,"2026-06-28T21:28:23",47,"/r 2d8+4 по ближайшему и убегаю дальше с насекомым на 17.5 футов",64123,null],[80622,"2026-06-28T21:28:27",32,"(эльф как тот кто в поле зрения. Жук не воспринимает но и не может не видеть. Слышит.) -холодно... Життьь",64123,null],[80623,"2026-06-28T21:28:33",5,"// убил",80621,null],[80624,"2026-06-28T21:28:42",5,"// ты бежишь вдоль стены ступени?",64123,null],[80625,"2026-06-28T21:28:51",47,"/не понял вопроса?",64123,null],[80626,"2026-06-28T21:28:56",47,"Я тяну его вверх/",64123,null],[80627,"2026-06-28T21:29:00",47,"На следующие этапы",64123,null],[80628,"2026-06-28T21:29:02",32,"Там вообще то где-то удобные ступеньки были",80624,null],[80629,"2026-06-28T21:29:11",5,"// они есть, но вы отошли от них",80628,null],[80630,"2026-06-28T21:29:22",5,"// окей, вы на 2 тогда",80626,null],[80632,"2026-06-28T21:29:39",32,"/roll@roll_bot",64123,null],[80634,"2026-06-28T21:29:48",5,"// тебя стабилизировали",80633,null],[80635,"2026-06-28T21:30:09",32,"А ок",80634,null],[80636,"2026-06-28T21:30:29",32,"/Тогда просто валяюсь мешком с песком?",64123,null],[80639,"2026-06-28T21:34:11",5,"// конец хода?",80627,null],[80641,"2026-06-28T21:40:53",5,"Леда видит, что эльф с раненым жуком растворились в тумане, слышит шарканье их ног где-то выше себя. Одинокий скелет ползёт по ступени. А вокруг голиафа вьётся призрак.\n\n— Так близко! Так далеко!\n\nУсыпанный песком сундук всё также стоит в углублении в стене.",64123,null],[80643,"2026-06-28T21:42:07",32,"//Леда отсупай",64123,null],[80661,"2026-06-28T22:14:12",47,"/да",64123,null],[80663,"2026-06-28T22:14:49",47,"- Леда, бегом к нам! - кричит эльф великану",64123,null],[80680,"2026-06-28T22:30:32",9,"*Великан бросается на верх.*\n\n//С рывком",64123,null],[80681,"2026-06-28T22:30:39",9,"//Ход",64123,null],[80683,"2026-06-28T22:32:25",47,"/без сундука?",64123,null],[80685,"2026-06-28T22:36:38",32,"//ясен хрен. К сундуку призрак привязан.",64123,null],[80692,"2026-06-28T22:42:17",5,"Призрак не пытается атаковать и растворяется за спиной великана. Лишь слабое свечение остаётся в том же месте.\n\nВ голосах героев звучит усталый голос.\n\n- Так близко, он так близко!",80680,null],[80693,"2026-06-28T22:42:50",5,"Несколько скелетов залезают на ступень с тайником и хрустят в тумане. На вашей ступени никого не видно.",64123,null],[80694,"2026-06-28T22:42:56",5,"// ход эльфа",64123,null],[80699,"2026-06-28T22:48:41",47,"/надеваю щит",64123,null],[80700,"2026-06-28T22:48:58",47,"Тащу ещё на 17.5 фт союзника. Ход",64123,null],[80701,"2026-06-28T22:50:01",5,"Эльф и жук на первой ступени. Наверху уже видно чистое небо",64123,null],[80702,"2026-06-28T22:50:27",5,"// Hard",64123,null],[80704,"2026-06-28T22:54:09",9,"*Движется со всей скорости чтобы вылезть из рва.*",64123,null],[80705,"2026-06-28T22:54:22",9,"//Рывок снова",64123,null],[80706,"2026-06-28T22:54:55",5,"Леда очень быстрый и теперь он стоит на земле на краю карьера.",64123,null],[80707,"2026-06-28T22:55:03",5,"// конец ини",64123,null],[80708,"2026-06-28T22:55:28",5,"Скелеты хрустят внизу и понемногу лезут наверх. Но вы выбрались гораздо быстрее",64123,null],[80709,"2026-06-28T22:55:55",5,"Снаружи все такое же тихое утро. Рыцарей ордена нигде не видно",64123,null],[80710,"2026-06-28T22:56:03",9,"— Эйты жив?",64123,null],[80711,"2026-06-28T22:57:04",9,"*Леда смотрит на скелетов и делает пасы руками осыпая их гратом чёрных осколков.*",64123,null],[80712,"2026-06-28T22:57:30",5,"*Скелеты внизу в тумане, ты их не видишь, только слышишь*",64123,null],[80713,"2026-06-28T22:57:32",9,"/roll 1d4+1\n/roll 1d4+1 обе ячейки на волшебные стрелы",64123,null],[80715,"2026-06-28T22:58:15",9,"//Опять туман, ладно, если увижу — делаю просто",64123,null],[80716,"2026-06-28T22:58:46",5,"// да. Ну у вас есть время решить, что делать дальше",64123,null],[80717,"2026-06-28T22:59:39",9,"— Слишком слабы чтобы справится с мертвецом. Нам пора. — *Говорит Талону.*",64123,null],[80754,"2026-06-28T23:34:13",32,"(тяжёлый ментальной голос как будто из под воды вяло) \n-Я жив. Но я не чувствую тела. \nКак бы ревенантом не встать",80710,null],[80755,"2026-06-28T23:34:51",5,"// можно сделать скип, вы убежали в лес, там встали на отдых и жук очнулся",64123,null],[80756,"2026-06-28T23:34:55",5,"// чтобы обсудить что дальше",64123,null],[80758,"2026-06-28T23:36:48",9,"//Миха уже спит похоже",64123,null],[80762,"2026-06-28T23:38:24",5,"// тогда до завтра получается",64123,null],[80965,"2026-06-29T07:04:46",47,"/ну как-будто бы надо. Один этап сделали, следующий вытащить сундук",64123,null],[80966,"2026-06-29T07:06:13",47,"Встаём на отдых! /",64123,null],[80982,"2026-06-29T08:54:44",32,"-да призрак не подвержен физическому и мало уязвим полу магическому (звук) урону. И потому у меня из подходящего разве что хаотический заряд если ударит психический или силовой урон",64123,null],[80983,"2026-06-29T08:55:33",47,"/не знаю. Меня смущает стиль общения насекомого",64123,null],[80985,"2026-06-29T08:56:02",47,"Талон смотрит странно на Три-крина. Ему не понятна его манера речи",64123,null],[80987,"2026-06-29T08:57:08",47,"/ну тип ты общаешься как игрок, а не как персонаж. Тип персонаж как будто бы сказал: \n\"Призрак неуязвим к простому оружию, мне не хватает знаний/сил/другого чтобы его можно было обезвредить\"",64123,null],[80988,"2026-06-29T08:57:10",9,"//Да, он слишком современный для фэнтези. Но жук так то космонавт так что хер знает что там у них ^^",80983,null],[80989,"2026-06-29T08:57:32",47,"/ну ок",64123,null],[80990,"2026-06-29T08:58:19",9,"//Типа, будем за персов тупить и думать что это что-то на слишком умном, пусть обьясняет по 2-3 раза)))",64123,null],[80991,"2026-06-29T08:58:28",32,"//В основном я это как раз воину и варвару",80987,null],[80992,"2026-06-29T08:59:11",9,"— Он согласен бежать? — *Переспрашивает Талона.*",64123,null],[80993,"2026-06-29T08:59:24",32,"-Так что бить руками приведение не имеет смысла",64123,null],[80994,"2026-06-29T08:59:43",32,"-Нет нам нужно восстановится",80992,null],[80995,"2026-06-29T08:59:49",47,"/ну как игрокам понятно, как воину и варвару нет",64123,null],[80996,"2026-06-29T09:00:04",9,"— Сокровища не стоят смерти.",80994,null],[80997,"2026-06-29T09:00:34",32,"- я просто не был готов к бою с конкретным врагом.",80996,null],[80998,"2026-06-29T09:00:43",9,"//Нус Леда был волшебником, но он сук не помнит этого, типа сообразительность осталась + - но на этом как бы",80995,null],[80999,"2026-06-29T09:01:59",32,"-Нам в любом случае нужно его успокоить. \nВернёмся в деревню. Заберём масло, и пройдемся к церкви может есть святая вода",64123,null],[81000,"2026-06-29T09:02:48",9,"//Мне как игроку не нравятся ещё упёртые персонажи, но ладно)",64123,null],[81001,"2026-06-29T09:03:49",32,"//в том то и проблема что это не упоротось а расчет",64123,null],[81002,"2026-06-29T09:04:24",47,"Талон кивает, соглашаясь",64123,null],[81003,"2026-06-29T09:05:06",32,"//мы идём в деревню перегруппировать силы",64123,null],[81005,"2026-06-29T09:05:27",47,"/а может к рыцарям?",81003,null],[81006,"2026-06-29T09:06:03",47,"- Я предлагаю обратиться к рыцарям. Я думаю они будут не против поделиться с нами средствами убийства нежити за помощь с убийством нежити",64123,null],[81007,"2026-06-29T09:06:07",32,"//тоже об этом подумал но у нас полтора десятка мечей с трофеев",64123,null],[81008,"2026-06-29T09:06:10",47,"- И идти ближе",64123,null],[81009,"2026-06-29T09:06:13",9,"— Мёртвые не восстают им быть причины есть, слова звучащие в уме, не забыть — спросить. Наш старый друг поведает в чём дело.",80999,null],[81010,"2026-06-29T09:06:16",47,"/им и продать",64123,null],[81011,"2026-06-29T09:06:41",32,"Хорошо идём к рыцарям",64123,null],[81012,"2026-06-29T09:07:20",9,"//Чую смерть персов близка)",64123,null],[81013,"2026-06-29T09:07:47",47,"@elsio28",64123,null],[81014,"2026-06-29T09:07:52",47,"/идём к рыцарям",64123,null],[81044,"2026-06-29T09:26:43",32,"//Ну на коротком отдыхе я восстановлением чар вернул себе ячейку (сейчас 2/3) \nИ нет если мы и в село сгоняем за маслом то у жука есть план. Суицидальный правда зато план",64123,null],[81046,"2026-06-29T09:27:44",47,"/восстарвоил всплеск действий",64123,null],[81048,"2026-06-29T09:27:50",47,"/r d10+2",64123,null],[81051,"2026-06-29T09:28:00",47,"Избавился от болезни",64123,null],[81066,"2026-06-29T09:35:03",32,"-Кстати эльф. Спасибо, ты спас мне жизнь",64123,null],[81069,"2026-06-29T09:36:16",47,"Эльф вздрагивает... Ощущение будто он впервые слышит, чтобы ему подобное говорили. Он слегка притормаживает и с осторожностью кивает",64123,null],[81070,"2026-06-29T09:36:29",32,"Жук развёл мандибулы и подвигал антенками (одна серая а оторванная потихоньку отрастает)",64123,null],[81072,"2026-06-29T09:37:00",32,"(жук искренен в своей благодарности)",64123,null],[81075,"2026-06-29T09:38:02",32,"-Ребята у меня есть план как установить тут Арвентус в миниатюре но нужна ваша помощь",64123,null],[81077,"2026-06-29T09:39:09",9,"/roll 1d12+1d6+6 востанавливаюсь на коротком",64123,null],[81080,"2026-06-29T09:39:51",47,"- Авернус?",64123,null],[81081,"2026-06-29T09:40:20",9,"// Естить, у меня было 15 и востановил фулл ровно, ведь макс 31, чё так везёт то)))",64123,null],[81095,"2026-06-29T10:09:52",32,"/опечатался и не заметил.\nАвернус\n\nАвтоподства",81080,null],[81102,"2026-06-29T10:15:47",47,"/я знаю что такое авнрнус... Перс нет",64123,null],[81123,"2026-06-29T11:04:36",32,"-Первый слой ада. Лавовые реки пепел и тысячи исчадий которые рубятся в вечной войне крови. \nВ нашем случае настолько эпическое побоище нам не по карману но залить карьер огнем и перемолоть мертвяков на подготовленной позии и с подготовленными расходниками это святое",81080,null],[81128,"2026-06-29T11:10:46",9,"//Теперь у твоего персонажа неофициальное прозвище \"Адский жучара\"",81123,null],[81148,"2026-06-29T11:41:03",32,"/мне нравится",64123,null],[81159,"2026-06-29T11:59:41",9,"*Леда не смотрит, Леда отдыхает.*",64123,null],[81160,"2026-06-29T12:19:32",32,"(жук на песке палкой чертит план нет не так ПЛАН. масштаб задуманного был велик, полукруг карьера по плану превращался в линию волчьих ям и насыпей с кольями. У ступеней вниз, предполагались вязанки с брёвнами, так же на плане было несколько высоко поставленных в насыпях чанов с маслом)\n-Они должны быть сбиты в низ брёвнами и разбившись вспыхнуть подсветив дно карьера а за одно подпалив нежить.\nБыла бы сера, силитра и фосфор можно было и кислотный туман мертвякам устроить.",64123,null],[81167,"2026-06-29T12:52:09",47,"- А ты не боишься, что тем самым сгорит и сундук? Задал закономерный вопрос эльф",64123,null],[81170,"2026-06-29T12:54:00",32,"-Нет конечно. Мы будем воевать в другой части карьера а масла на то чтобы его целиком поджечь просто нет.",64123,null],[81179,"2026-06-29T13:04:08",47,"- Хорошо. Тогда нужно будет спросить у служащих масло - соглашается эльф",64123,null],[81180,"2026-06-29T13:04:56",32,"-Я заказывал в деревне. И у служак нужно ещё взять",64123,null],[81182,"2026-06-29T13:05:13",32,"-Тогда хватит для капитального поджога",64123,null],[81183,"2026-06-29T13:05:26",47,"- Тогда нужно ускориться - соглашается эльф",64123,null],[81184,"2026-06-29T13:06:19",32,"-Да а ещё нам нужны лопата и большой топор для вырубки.",64123,null],[81185,"2026-06-29T13:06:33",32,"Лопата эльфийская и топор великана",64123,null],[81261,"2026-06-29T18:15:25",5,"// такс",64123,null],[81262,"2026-06-29T18:15:51",5,"// ещё можно персом анализировать врага с броском",80982,null],[81263,"2026-06-29T18:16:20",5,"// заявок на сбор мечей не было",81007,null],[81264,"2026-06-29T18:16:46",5,"// вы решили куда идетё?",64123,null],[81265,"2026-06-29T18:17:17",5,"// если к рыцарям, то один будет вести отряд через лес и кинет выживание с преимуществом",64123,null],[81266,"2026-06-29T18:17:46",32,"//я их в любом случае собираю. Реставрярую починкой и на парящий диск (который то же надо призвать)",81263,null],[81267,"2026-06-29T18:18:26",32,"//я думал это само собой разумеется что пройтись и пособирать",81263,null],[81268,"2026-06-29T18:18:53",32,"//не знал. Обычно мой прошлый мастер не требовал такого.",81262,null],[81269,"2026-06-29T18:19:13",32,"//Тогда кину аркану на анализ призрака?",81262,null],[81270,"2026-06-29T18:20:46",32,"/roll d20+5",64123,null],[81273,"2026-06-29T18:21:18",5,"// ты их мог собрать, когда был у каньона. И сбор не автоматический, я не могу игрокам в руки давать всё. Вдруг там не лут а приманка для клептоманов.\n\n\nНо тут не буду душнить, допустим вы их собрали",81266,null],[81274,"2026-06-29T18:21:32",5,"/r d10 целых мечей",64123,null],[81277,"2026-06-29T18:21:52",5,"Только 2 меча остались целыми. (короткие мечи)",64123,null],[81278,"2026-06-29T18:22:11",32,"//Мы настрогали 12 скелетов и мечи у них никто не ломал вроде.",81274,null],[81279,"2026-06-29T18:22:16",32,"Эх ладно",64123,null],[81281,"2026-06-29T18:22:57",32,"//Не нашли в грязи бывает",81277,null],[81282,"2026-06-29T18:23:11",5,"// а часть поломали скелеты когда били. Плюс они ржавые и так",64123,null],[81283,"2026-06-29T18:24:00",32,"//ну да логично. Нужно будет самому уксуса купить чтобы отбелить. Но обломки то же на метал собрать",64123,null],[81285,"2026-06-29T18:24:37",5,"// у меня можно в непонятной ситуации пытаться персом понять что делать. Если кубы одобрят",81268,null],[81286,"2026-06-29T18:24:39",32,"/приманка для клептоманов это сундук а мечи это лут",81273,null],[81287,"2026-06-29T18:24:40",9,"//Михи нет и я темнейшее ща поведу",64123,null],[81288,"2026-06-29T18:25:53",32,"Тогда можно жук в деревню за маслом и назад сходит и мы все скажем что готовили укреп район.\n(Схему накидаю с руки)",81286,null],[81289,"2026-06-29T18:26:55",32,"//Я так понимаю мне про призрака просто из манула прочитать?",81285,null],[81291,"2026-06-29T18:27:31",5,"// не, ща напишу",81289,null],[81301,"2026-06-29T18:34:18",32,"//забавно но я призрака похоже в доль и поперек уже изучил. Ощущение откуда внушение. Внимательность Крит. И вот аркана Крит",64123,null],[81306,"2026-06-29T18:40:51",5,"Привидение, увиденное вами, определённо можно убить и физическим оружием. Однако и оно, и заклинания нанесли лишь слабый вред призраку. В момент побега он был почти не повреждён.\n\nТы вспоминаешь и истории про появление призраков. А также скелет в броне, лежащий перед тайником. Этот призрак явно имеет невыполненное дело. И оно связано с тайником. А выполнить цель призрака — самый лёгкий способ изгнать его.",81271,null],[81311,"2026-06-29T18:48:42",5,"// можно. Остальные ждут в лесу",81288,null],[81312,"2026-06-29T18:51:01",5,"// можешь описать как ты гуляешь по лесу",64123,null],[81313,"2026-06-29T18:51:06",5,"// ща напишу что в деревне",64123,null],[81314,"2026-06-29T18:52:21",32,"-Так ребята я в деревню, за маслом и парой инструментов ,скоро вернусь.\n(Сказал жук за одно закинув да диск и короткие мечи и обломки тех что развалились. Так как оставлять оружие даже обломки тут не имею желания)\nИду по лесу постоянно осматриваясь помня нападение волков и держу хаотический заряд на готове чтобы ударить если увижу и нападут.\nНо лес оказался достаточно спокоен",64123,null],[81315,"2026-06-29T18:53:11",32,"//ты играешь с другими? Если занят скажи. Если нет, поиграем)",81313,null],[81316,"2026-06-29T18:53:22",5,"В деревне ты сразу заприметил телегу, стоящую у дома травника. В ней несколько горшков.",64123,null],[81317,"2026-06-29T18:53:52",5,"// да, играю. Но тут время отвечать есть",81315,null],[81319,"2026-06-29T18:55:06",32,"Иду к травнику.\nМне все равно нужно спросить куда обломки и вроде как приведенные в более менее товарный вид мечи деть. (Починка вещь)\nНу и забрать масло.",81316,null],[81320,"2026-06-29T18:55:27",32,"-Привет. Как мой заказ?",81316,null],[81321,"2026-06-29T18:55:48",32,"-И куда можно деть металлолом и пару старых мечей?",64123,null],[81323,"2026-06-29T18:56:29",32,"И ещё у тебя та дрянь которую ты деду продавал осталась? Мне на дымовые шашки нужна",64123,null],[81324,"2026-06-29T18:56:54",5,"— Покупатель вернулся.\n\nПробормотал травник. Затем погромче сказал.\n\n— Прибыло твоё масло, жук. Будешь в горшках забирать или по флягам разлить?",81320,null],[81325,"2026-06-29T18:57:05",5,"// масла достаточно для 78 фляг",64123,null],[81326,"2026-06-29T18:57:31",32,"(жук был спокоен. Разве что его слегка потряхивало. Некрос все ещё холодил внутренности.)",64123,null],[81327,"2026-06-29T18:57:39",5,"— Деньги у тебя?\n\nБуркнул он, увидев как ты тянешься к маслу.",64123,null],[81328,"2026-06-29T18:57:45",32,"//а в литрах это сколько?",81325,null],[81330,"2026-06-29T18:58:43",32,"//мы уже вычли всю стоимость в 6 золотых из которых 4 были задатком) потому\n\nотдал эму две отложенные монеты и забрал на диск прямо кувшинами",81327,null],[81332,"2026-06-29T18:59:15",5,"// вообще не знаю. Тут масло во флягах считают",81328,null],[81336,"2026-06-29T18:59:55",5,"// а не,  80 фляг это 40 литров",64123,null],[81337,"2026-06-29T19:00:20",32,"//да где-то пол литра на флягу",81336,null],[81338,"2026-06-29T19:01:05",32,"-Так куда можно пару ковырялок продать. Сталь вроде не плохая пусть и старая",64123,null],[81339,"2026-06-29T19:01:47",5,"— Ковырялки в нашей деревне? Да на кой они мне сдались? Жук, ты малину принёс? Вот за неё заплачу",81338,null],[81343,"2026-06-29T19:02:15",5,"// напомни что это",81323,null],[81344,"2026-06-29T19:02:39",32,"//хапки которые дед курнул и получил радужных пони на час",81343,null],[81347,"2026-06-29T19:03:34",32,"- малины увы не набрал. Шкуры волчьи есть, обрезки от них тоже. Кости из восставших скелетов и их оружие. А малина как-то на глаза не попадалась",81339,null],[81350,"2026-06-29T19:04:23",32,"-А шкуры кому? Две целых и ещё два бобика на ленточки?",64123,null],[81354,"2026-06-29T19:06:22",5,"— Малины тут полный лес. \n\nСтарик ворчит.\n\n— Ладно, шкуры и обрезки возьму. Плачу 1 золотой",81347,null],[81359,"2026-06-29T19:07:14",32,"Проницательность на анализ цены (мне кажется капитальное занижение)",64123,null],[81361,"2026-06-29T19:07:23",32,"/roll d20+4",64123,null],[81363,"2026-06-29T19:07:34",5,"Цена честная, так всем платят",81362,null],[81365,"2026-06-29T19:07:57",32,"Но мои подозрения быстро осыпались. Потому отдал шкуры и забрал монетку",64123,null],[81367,"2026-06-29T19:08:14",5,"// погоди насчёт хапок подумаю",64123,null],[81370,"2026-06-29T19:08:55",32,"(ну жук в любом случае идёт к старику с которого все началось. Задать вопросы по призраку",64123,null],[81373,"2026-06-29T19:10:07",5,"Та же хижина, на крыше неподвижно замер флюгер. \n\nПасмурный день, солнце лишь иногда проглядывает сквозь облака.",81370,null],[81376,"2026-06-29T19:10:42",32,"Стучусь в дверь и дожидаясь ответа если пустят вхожу.",64123,null],[81379,"2026-06-29T19:11:29",5,"— Входите, входите!",64123,null],[81382,"2026-06-29T19:12:12",5,"Внутри ты видишь того же старика Алексия, он сидит за столом и есть походный рацион.\n\n— А, это ты, внучок! А где остальные? Неужто...\n\nСтарик побледнел.",64123,null],[81384,"2026-06-29T19:12:21",32,"-Приветствую старший. Я к вам с парой вопросов.\nМы командой напоролись на призрака у сундука.\nЯвно кто-то из наших коллег и кучу мертвецов.\nЧто вообще в вашем кладе и были ли мертвецы в карьере до вас",64123,null],[81394,"2026-06-29T19:13:02",32,"-Дед куда-то ушел матом послав затею. А остальные у карьера",81382,null],[81398,"2026-06-29T19:13:56",5,"— Ох, успокоил. Я уж подумал, никто не выбрался живым",81394,null],[81405,"2026-06-29T19:14:53",32,"-Так кто тот призрак?",64123,null],[81407,"2026-06-29T19:15:09",32,"(направил мысли деда в нужное русло)",64123,null],[81408,"2026-06-29T19:15:38",5,"— В сундуке трофеи со времён, когда я был авантюристом. Ох, молодость! Порядочно там золота, да...",81384,null],[81409,"2026-06-29T19:15:44",5,"— Призрак? Что за призрак?",64123,null],[81410,"2026-06-29T19:15:50",5,"— Он говорил что-то?",64123,null],[81412,"2026-06-29T19:17:05",32,"- да говорил что его сокровища. Как красный дракон банкрот к сундуку тянулся.\nГоворил что он почти их заполучил и что-то ещё.",64123,null],[81419,"2026-06-29T19:18:27",32,"-И этот призрак нас всех чуть не положил. Как и куча мертвяков. В карьере были мёртвые до вашего появления и что в сундуке было",81409,null],[81433,"2026-06-29T19:22:23",5,"— Вокруг сундука вился?\n\nАлексий задумался.\n\n— Неужели это мой старый друг? Ох, неужели это Андрейка?! Чем ты стал, друг...",81412,null],[81439,"2026-06-29T19:23:33",5,"Старик собрался и продолжил.\n\n— Это мой друг был, вместе немало дорог прошли. Вместе тайники копали. Но однажды он ушёл и не вернулся. Пропал, ни слуху, ни духу...",64123,null],[81447,"2026-06-29T19:24:46",32,"//я немного занят прошу прощения",64123,null],[81452,"2026-06-29T19:26:26",5,"— А мертвяки в карьере... Что ж, значит из-за них туда больше не ходят. Лет 20 назад, когда мы тайник закапывали, то был заброшенный карьер. Пустая яма песка, никаких мертвяков. Плохие времена настали, сынок!",64123,null],[81467,"2026-06-29T19:29:37",32,"- мне кажется вы знаете как упокоить призрака. \nИли я просто пойду за святой водой и вылью в карьер сорок литров священного масла и запалирую лезущих мертвяков святой водой",64123,null],[81498,"2026-06-29T19:37:05",5,"— Призрака? Да, был я жрецом раньше...\n\nДед задумался.\n\n— Можно и водой святой, или магией святой тоже. Такой, чтобы жгла нечистый дух. Но лучше всего понять причину, что держит призрака в этом мире. Тогда и драться не придётся",81467,null],[81505,"2026-06-29T19:39:50",32,"- вот именно о причине я и говорю. Если вы поняли кто это то вы же и лучше всего знаете кто это по характеру и легче всех поймёте как его успокоить.\nА ещё если вы жрец вы ведь ещё можете в божественную магию? Мне усик исцелить бы. (Указываю на оторванный) И просто организм от некротики почистить.",81498,null],[81507,"2026-06-29T19:40:20",32,"-Да и скелетов всеравно уничтожать думаю святая вода лишней не будет",64123,null],[81513,"2026-06-29T19:47:22",5,"Старик медленно выпил кружку воды.\n\n— С твоих слов могу составить картину, сынок... Значится, пошёл мой старый друг Андрей за тайников. Один. Ох, зачем же ты без меня полез, друг...",81505,null],[81514,"2026-06-29T19:48:04",32,"-И не вернулся.",81513,null],[81520,"2026-06-29T19:49:21",5,"— Дошёл он до тайника, получается. Но погубили его мертвяки. А дух остался в этом мире. Думаю, в этом его цель теперь. Добраться до тайники. Возьмите сундук, и призрак упокоится.",64123,null],[81529,"2026-06-29T19:52:12",5,"—А насчёт исцеления... Старый уже, навыки не те. Дай сосредоточусь, попробую.\n\nАлексий встаёт, медленно подходит к тебя и касается остатков усика. Рука что-то сжимает. Усик медленно отрастает вновь.",81505,null],[81532,"2026-06-29T19:52:45",5,"/r d8+5 плюс отхил",64123,null],[81535,"2026-06-29T19:53:10",32,"-Ух спасибо дед. Ты прямо выручил.\n//На полное ХП исцелил",64123,null],[81536,"2026-06-29T19:53:34",5,"// ещё могёт дед",64123,null],[81538,"2026-06-29T19:53:50",32,"-А то не знал как и жить калекой по сути",64123,null],[81549,"2026-06-29T19:55:33",5,"— Рад помочь, сынок\n\nСтарик устало опускается на скамью",64123,null],[81567,"2026-06-29T20:00:00",32,"(жук задумался как отблагодарить деда.)- а давайте вы тоже посмотрите как горит нежить? \nЭто должно быть то ещё зрелище",64123,null],[81573,"2026-06-29T20:01:29",5,"Старик изрядно утомился после использование магии.\n\n— На горящую нежить я с радостью посмотрю. Но ноги уже не те, придётся вам меня ждать.\n\n// лёгкая проверка убеждения если хочешь взять с собой",64123,null],[81595,"2026-06-29T20:05:24",5,"// насчёт травки. Она дымила, но это не прям дымовая завеса. Травник продаст, если прокинуть убеждение",64123,null],[81608,"2026-06-29T20:09:09",32,"//я сделаю завесу и без конкретной травки мне от неё нужен только \"головокружительный аромат\"",81595,null],[81609,"2026-06-29T20:09:26",32,"/roll d20+4",64123,null],[81612,"2026-06-29T20:09:36",32,"/roll d20+4",64123,null],[81614,"2026-06-29T20:09:53",32,"Ну травку мне похоже не видать",64123,null],[81617,"2026-06-29T20:10:45",5,"— Молодой ты ещё, шутливый. Не лезь за травкой, не нужна она тебе",81610,null],[81620,"2026-06-29T20:10:59",5,"// не знаю откуда у тебя преимущество, но не помогло",64123,null],[81658,"2026-06-29T20:18:57",32,"Я кидал вторым убеждение деда",81620,null],[81661,"2026-06-29T20:19:07",5,"// убедил",81658,null],[81668,"2026-06-29T20:20:26",32,"//Отлично. Теперь у нас есть шанс реально затащить. \n-Дед отлично идём я помогу тебе на парящий диск усесться и ты поедешь на моём диске за мной",64123,null],[81691,"2026-06-29T20:23:48",5,"Старик Алексий выходит из домика и идёт за тобой, опираясь на посох",64123,null],[81726,"2026-06-29T20:29:47",32,"Я усаживаю его на парящий диск к своему скарбу и мы выходим обратно к нашим",64123,null],[81727,"2026-06-29T20:30:03",32,"Ну я выхожу а он просто едет следом",64123,null],[81729,"2026-06-29T20:30:41",5,"// безопасно возвращаетесь к остальным",64123,null],[81734,"2026-06-29T20:31:13",5,"// можешь им описать свою прогулку",64123,null],[81769,"2026-06-29T20:38:00",32,"(жук выходит на поляну диск выплывает следом)\n- парни я могу все объяснить (выдал он панически. Просто прикалываясь) в общем сходил я в деревню и набрал всего нужного. Сорок литров горючего масла, жреца, сдал трофеи. Собственно ваша доля с шкур по три серебряника.",64123,null],[82161,"2026-06-29T22:59:45",47,"Я ток прилёг",64123,null],[82164,"2026-06-29T23:04:02",47,"/поцы.сори но сейчас у меня ад, сейчас заканчиваю квест и буду с дерьмом в жизни разбираться",64123,null],[82166,"2026-06-29T23:05:16",32,"Держись",64123,null],[82245,"2026-06-30T00:30:19",32,"-Только надо разменять у меня только целым золотым или тремя серебряными",81769,null],[84440,"2026-06-30T09:39:27",5,"// если вы не спите, то можем продолжать сейчас и днём",64123,null],[84445,"2026-06-30T10:04:48",32,"/Я не сплю",64123,null],[84446,"2026-06-30T10:06:59",9,"// + - тут, наверное",64123,null],[84523,"2026-06-30T11:12:07",32,"//в общем обещал нарисовать укрепления жука но как-то мотивации что-то делать вообще нет. \nСилы на нуле.",84440,null],[84524,"2026-06-30T11:13:06",5,"//м? Ну можешь описать. А так я пока не понимаю что ты задумал с маслом устроить",84523,null],[84527,"2026-06-30T11:22:41",32,"//смотри. Что я хочу. Вокруг модема с карьера нарыть полукругом ям в сторону карьера и насыпь из всей вырытой земли на нашу сторону. Это укрепления для того чтобы стрелять по скелетам с высоты и не давать подойти.\nДалее у самого спуска ступеней просадить песок так чтобы получились скос убрав ступень по сути сразу к второй ступени (её до третей завалить сплошной на искось насыпью по факту сделав крутой спуск поедем а не пологие склоны.) на верху оставить пару тройку бревен (Я забыл топор нормальный в деревне купить так бы можно больше было нарубать) чтобы по пологому склону катились и сбивали разбивали скелетов и получив разгон падали в низ.\nДалее. Масло. В чем его прикол. Это в основном просто факел. Который привлечёт мертвяков. Но ещё и приличный столб пламени туман может разогнать и если повезёт зальёт дно карьера а что-то мне подсказывает что именно там источник некротики. Ибо туман поднимается оттуда. \nПосле масла и бревен. Мы отходим на линии для обстрела с собой желательно иметь пузырьки с святой водой если полезет привидения или ещё какая сильная нежить. (Как бы из карьера \"гора костей\" не вылезла. Хотя надеюсь там что-то с уровнем опасности меньше 10 а не больше) \nСобственно как я сказал масло несёт три цели. Свет, жар(под ноги скелетам разлилось и на Черёмушки стекает когда те лезут) и просто это весело когда бревна в горящем масле перепачканы и в полёте ещё и горят",84524,null],[84529,"2026-06-30T11:28:05",32,"//а если серьезно я сам не до конца понимаю нахрена мне масло.",64123,null],[84530,"2026-06-30T11:28:05",32,"Но надо",64123,null],[84531,"2026-06-30T11:31:40",5,"// план у тебя масштабный, такое и рыцари ордена могут поддержать.",84527,null],[84532,"2026-06-30T11:32:50",5,"// единственное, что напомню, так это что карьер огромный",64123,null],[84533,"2026-06-30T11:33:26",32,"//Конечно как в патруле проедут и увидят стройку там и расскажу. Я ведь им пообещал зачистку карьера? Пообещал а инженеры Иззетов держат слово особенно если это слово что-нибудь взорвать!",64123,null],[84534,"2026-06-30T11:34:50",5,"// похоже мне надо проработать детали карьера. Настрой на зачистку у тебя серьезный. Хотя масштаб квеста таким не задумывался)",84533,null],[84535,"2026-06-30T11:34:50",32,"Я знаю потому и готовлю именно такую оборону. Полукруг из полукругов чтобы когда нежить со всех сторон попрёт не зажали с флангов. А огонь тут ещё и привлечение внимания чтобы лезли на самое лучшее для нас естественно место",84532,null],[84536,"2026-06-30T11:36:13",32,"//Занимайся. Конечно серьезный. У рыцарей точно есть свитки для меня или маги которые будут рады меня научить. А значит интерес шкурный. А ещё просто потому что не хочу мусорку за собой оставлять",84534,null],[84541,"2026-06-30T11:42:59",32,"Если рыцари придут то закажу у них. Посеребренные наконечники для стрел эльфу и десяток литров святой воды",64123,null],[84543,"2026-06-30T11:45:03",5,"// возможность будет",84541,null],[84547,"2026-06-30T12:09:40",9,"//Такс, сорян что не тут. Я буду рад помочь жуку и закончить всё)",64123,null],[84548,"2026-06-30T12:10:01",9,"//Леда закроется потом, его место займут",64123,null],[84549,"2026-06-30T12:10:25",32,"//Леда уйдёт? Печально",84548,null],[84550,"2026-06-30T12:10:45",9,"//На покой, как перс",64123,null],[84551,"2026-06-30T12:10:53",9,"//Но после игры)",64123,null],[84553,"2026-06-30T12:11:09",32,"// нахрена я тогда нам жреца тянул?",84550,null],[84554,"2026-06-30T12:11:37",9,"//Не, он живой будет, просто закрою анкету)",64123,null],[84555,"2026-06-30T12:12:02",9,"//Что происходит кстати, я чуть нить повествования потерял",64123,null],[84556,"2026-06-30T12:12:20",5,"// да мы без Михи не идём никуда",64123,null],[84557,"2026-06-30T12:12:36",32,"//жук готовится осадить карьер и начать зачистку",64123,null],[84558,"2026-06-30T12:13:16",5,"// а так жук ходил в деревню, закупился и поговорил со стариком",64123,null],[84559,"2026-06-30T12:19:32",9,"//Я думаю что тот дух это друг старика, он его убил",64123,null],[84560,"2026-06-30T12:20:10",9,"//Но Леда молчит о своих догадках, судить по отдельным деталям не зная всей истории хня",64123,null],[84561,"2026-06-30T12:21:09",5,"// жук кое-что по этой теме узнал, может рассказать",84559,null],[84562,"2026-06-30T12:21:24",9,"*Леда в это время решил заняться лесопилкой и подтаскиванием брёвен к карьеру. Так-то он заранее спросил где можно рубить у местного лесника, чтобы местным не мешать. Да и 5а бревна после дела он не претендует.*",64123,null],[84563,"2026-06-30T12:22:32",9,"//Раз жук настроен то чё нет",64123,null],[84564,"2026-06-30T12:23:11",5,"// да, бревна будут на месте",84562,null],[84565,"2026-06-30T12:23:29",9,"//Мооооощьььь",64123,null],[84566,"2026-06-30T12:23:38",9,"//Безмерная мощь)))",64123,null],[84567,"2026-06-30T12:24:27",5,"// так для исполнения плана нужно будет отыграть встречу с рыцарями",64123,null],[84568,"2026-06-30T12:24:43",5,"// и можно в их аванпост съездить при желании",64123,null],[84569,"2026-06-30T12:24:55",5,"// а потом готовиться к великой битве хд",64123,null],[84570,"2026-06-30T12:25:01",9,"//Жук верхом на великане!",64123,null],[84571,"2026-06-30T12:27:10",32,"Стандарт качества!",64123,null],[85379,"2026-07-01T08:07:20",5,"@cirson ты здесь появишься? Я теперь веду утром и днём//",64123,null],[85409,"2026-07-01T09:50:38",47,"/да блин/как получится. По возможности",64123,null],[85681,"2026-07-01T13:30:59",5,"// с тобой очень трудно совпасть. Все есть тебя нет",85409,null],[85682,"2026-07-01T13:31:40",5,"// как насчёт отыграть ролевую часть с рыцарями без Михи, а для финальной битвы подождать",64123,null],[85684,"2026-07-01T13:32:03",5,"// ну я конечно могу просто ждать пока все появятся, но как будто очень надолго затянется",64123,null],[85695,"2026-07-01T14:11:15",32,"//Я готов отыграть и без эльфа. Но мне почему-то кажется что можно было бы наконец доиграть а уже потом блин вести свою компанию",64123,null],[85721,"2026-07-01T15:29:58",47,"/ну я тип отвечаю по возможности",64123,null],[85739,"2026-07-01T15:40:18",5,"// давайте отыграем сейчас дальше",64123,null],[85740,"2026-07-01T15:40:31",5,"// вы в лесу, вернулись из деревни",64123,null],[85741,"2026-07-01T15:41:44",9,"*Великан отдыхал, ел. Он явно постарался на лесоповале.*",64123,null],[85742,"2026-07-01T15:44:51",5,"Сидящий на летающем диске дед Алексий:\n\n— Славное изобретение! Не задерживаю вас старческими ногами, сижу, смотрю на лес. Как же хорошо на природе! Эх, вспоминается юность...",64123,null],[85745,"2026-07-01T15:52:28",32,"-да Тензер действительно гениальный маг был.\n(Отвечаю деду сам правда знаю о маге только по названию заклинания но эту деталь жук тактично опустил)",85742,null],[85746,"2026-07-01T15:54:08",5,"Дед кивает и немного болтает ногами, удобно устроившись",85745,null],[85747,"2026-07-01T15:55:13",32,"-Ладно где будем искать рыцарей. Я с ходу не припомню чтобы они говорили где их логово.\nХотя... Идём просто в круговую искать патруль и у них спросим",64123,null],[85748,"2026-07-01T15:55:51",5,"// они рассказали где аванпост если правильно помню. Либо к карьеру",85747,null],[85750,"2026-07-01T16:04:02",47,"/говорили общее направление да.",64123,null],[85752,"2026-07-01T16:04:56",9,"/roll 1d20+3 думаю леда тусуясь основном возле карьера мог бы немного понаблюдать чё куда",64123,null],[85754,"2026-07-01T16:05:55",5,"// леда пока не у карьера. Все в лесу. Я твою заявку на лес заранее принял, ты разузнал про рубку в деревне и будешь рубить когда группа придёт",85752,null],[85755,"2026-07-01T16:06:09",9,"//Аааа, ну ладно",85754,null],[85756,"2026-07-01T16:06:26",9,"//Пох тода, я лумал все заняты своим делом",64123,null],[85758,"2026-07-01T16:09:22",32,"//я и говорю что я не могу вспомнить куда именно они нас посылали. Ассоциативная память пасует.\nИ именно потому и говорю в круговую вокруг карьера искать патруль",85748,null],[86096,"2026-07-02T09:29:29",5,"// тогда жду заявок",64123,null],[86302,"2026-07-02T12:20:40",47,"- Я помню куда нам надо. За мной - кратко объявляет эльф   ведёт союзников за собой",64123,null],[86305,"2026-07-02T12:22:28",5,"// если остальные согласятся, то выживание с преимуществом",64123,null],[86325,"2026-07-02T12:25:11",9,"*Леда не против пойти.*",64123,null],[86328,"2026-07-02T12:25:58",47,"/r +d20+3",64123,null],[86346,"2026-07-02T12:32:27",5,"// дальше нужен жук",64123,null],[86352,"2026-07-02T12:35:51",47,"@Xaosick",64123,null],[86357,"2026-07-02T12:44:28",32,"//я только проснулся. Но идём я давал на это согласие",64123,null],[86360,"2026-07-02T12:48:17",5,"Эльф уверенно ведёт вас по лесу, ориентируясь по солнцу. И вскоре вы находите тропу, ведущую как раз в нужном направлении. \n\nСпустя час ходьбы по ней вы слышите ржание коня невдалеке и хруст. Вокруг всё такой же густой лес, признаков построек нет.",64123,null],[86368,"2026-07-02T12:53:04",32,"(жук идёт держа на готове огненную стрелу как ответ на атаку по нему или его команде) \nПодозрительно осматривается",86360,null],[86408,"2026-07-02T14:17:10",5,"На тропу перед вами выезжает тяжёло бронированный рыцарь. Знакомая брошка ордена Миф Драннора видна на доспехе.\n\nРыцарь замирает на несколько секунд, а потом снимает шлем. Под ним ваш старый знакомый, Глорир. Он смотрит на вас, и его лицо угрюмо.\n\n— А это вы. Не могу сказать, что рад встрече. Работы вы нам подкинули знатно. И не собираетесь успокаиваться, как я вижу. Мои дурные предчувствия никогда не подводят...",64123,null],[86413,"2026-07-02T14:33:55",47,"- Мы хотим помочь. Нам нужно посеребренное оружие и святая вода. Мы упокоим часть нежити. Ваша служба станет легче - чётко обозначил цель и взаимную выгоду от неё эльф",64123,null],[86416,"2026-07-02T14:37:33",47,"/?",64123,null],[86417,"2026-07-02T14:37:47",5,"// да ничего, отвечу",64123,null],[86434,"2026-07-02T15:03:10",5,"— Хотите помочь?! Вам нужно!?\n\nРыцарь выкрикивает, а потом прижимает свободную руку к сердцу, склоняет голову и тихо бормочет:\n\n— О Аскелатор, открой глаза сем слепым грешникам и дай сил совладать с гневом...\n\nГлорир смотрит на эльфа и говорит медленно, едва сдерживая гнев.\n\n— Мы встречались вчера, и вы обещали уничтожить источник нежити. И сегодня мы увидели результат ваших действий. Я скажу от чистого сердца, если хотите помочь — убирайтесь вон отсюда. Убирайтесь и никогда не возвращайтесь! Проклятые наёмники, ослеплённые жаждой наживы...\n\nРыцарь начинал речь спокойно, но чем дальше, тем сильнее злился. Он сжал кулак, стараясь успокоиться. И произнёс совершенно безэмоциональным голосом.\n\n— Утром туман отступает, нежить не лезет наверх. Единственное время для воинов, чтобы отдохнуть между патрулями. Но не сегодня. Охотник из деревни увидел скелетов в лесу, прибежал на аванпост. Я отправил все доступные патрули, прочёсывать лес. И каждый наткнулся на нежить, бредущую по лесам. Много нежити. Мы потеряли нескольких братьев... И это — ваша вина. Я не знаю, что вы делали в карьере. Но после мертвяки разбрелись по всему лесу. Слава Аскелатору, что не добрались до деревень...\n\nГлорир замолчал на секунду.\n\n— Посему я говорю — уходите. Уходите, и не испытывайте моё терпение!",64123,null],[86599,"2026-07-02T16:08:44",47,"- Мы не знаем, что случилось. Но мы сами уничтожили немало скелетов! - убеждает его Талон",64123,null],[86625,"2026-07-02T16:15:17",32,"-Это тот дед который был снами виноват (передал телепатией жук) он кинул в карьер факел. Мы сами едва отбились а дед сбежал после боя.\n(Жук знал что виной всему был призрак, но козёл отпущения им был нужен)",86434,null],[86629,"2026-07-02T16:15:53",32,"(жук был расстроен произошедшим)",64123,null],[86672,"2026-07-02T16:23:38",47,"- Возможно. Я тоже это видел - подтверждает эльф",64123,null],[86696,"2026-07-02T16:33:09",9,"*Леда стоит с недовольным видом, что его товарищи врут?*\n\n//Вы же врёте?)",64123,null],[86701,"2026-07-02T16:34:20",5,"— Значит, орда нежити вылезла из-за деда, а вы отступили?\n\nРыцарь недоверчиво смотрит.",86625,null],[86705,"2026-07-02T16:34:29",5,"// можешь кинуть обман с помехой",86599,null],[86706,"2026-07-02T16:34:35",5,"// а ты просто обман",86625,null],[86856,"2026-07-02T17:06:30",47,"/r -d20",64123,null],[86859,"2026-07-02T17:06:38",47,"/Крит проебан(",64123,null],[86908,"2026-07-02T17:15:58",32,"/roll d20+4",86706,null],[86918,"2026-07-02T17:17:53",32,"//В том прикол что ты ещё поди пойми что жук лжёт. Мимики нет(читаемой) телепатический голос не дрожит а главное слова подобраны так что все это правда.",64123,null],[86920,"2026-07-02T17:18:20",32,"//Так что тут даже критический провал это максимум недоверие",64123,null],[86932,"2026-07-02T17:21:58",32,"(жук рассуждает)\n(а кстати рыцарь говорил про то что нежить полезла ночью. А к сундуку мы полезли уже днём. То есть виноват именно дед а не мы)",64123,null],[86936,"2026-07-02T17:23:06",5,"// нет, рыцарь сказал как раз что нежить полезла утром, когда обычно спит. После вашей утренней вылазки то есть",86932,null],[86951,"2026-07-02T17:29:07",9,"*Щас вас недовольный Леда сдаст с потрохами. Он не любит лжецов.*",64123,null],[86960,"2026-07-02T17:30:33",5,"// ты можешь",86951,null],[86961,"2026-07-02T17:30:40",5,"// реакцию рыцаря позже опишу",64123,null],[87003,"2026-07-02T17:42:54",9,"— Ложь не имеет цены. Виноваты мы. — *Леда просто вздыхает и опускает руки.* — Давно уйти просит голос разума, но друзья пойдут туда, могу лишь смириться, помочь. Злато не стоит смертей, но смерти прийдут, нас мало.\n\n*Леда поднял свою большую ладонь и положил на сердце.*\n\n— Надеюсь, правла имеет цену. Останусь здесь, надолго, заменю ваших павших товарищей, заплачу цену продолжив дело. Не прошу рисковать, лишь сделать что должно. Смерть — лучше моя. Проблем будет меньше коль поможете вы. — *Он погрустнел, сделал паузу, никогда раньше не просил с таким старанипм. Для кого? Для чего? Не знал, но твёрдо решил, покачал головой.* — Их не отговорить.",86701,null],[87006,"2026-07-02T17:43:20",9,"//Учитесь быть искренними, даже если это подкинет невзгоды ❤️",64123,null],[87082,"2026-07-02T17:55:50",47,"/не знаю. Мой персонаж не знает кто виноват",64123,null],[87083,"2026-07-02T17:55:58",47,"/дед кидал факел? Кидал",64123,null],[87086,"2026-07-02T17:56:07",47,"/считаю виноватым деда",64123,null],[87107,"2026-07-02T17:59:23",32,"/Я вообще-то то же деда виновным считал и считаю",64123,null],[87112,"2026-07-02T18:00:32",9,"//Слишком вы умны для таких игр)",64123,null],[87113,"2026-07-02T18:00:54",9,"//Я частично ток вкурил что происходит, часть упустил. Так что хз",64123,null],[88302,"2026-07-03T04:06:35",5,"Глорир переводит взгляд с эльфа на жука. А потом обратно. И молчит.",86625,null],[88305,"2026-07-03T04:25:45",5,"Капитан рыцарей посветлел с первых же слов голиафа. Он выслушал до конца и кивнул. Гнев отпустил его.\n\n— Признавать прегрешения — великий навык! Ибо все мы грешны, а путь искупления начинается с признания!\n\n— Правда дороже денег, и я благодарен за неё. И ценю твою готовность сражаться. Право, такие воины нужны ордену!",87003,null],[88306,"2026-07-03T04:26:43",5,"// знаю что ты собираешься закрыть Леду, а так персу за это открывается возможность посвящения в орден и особая форма работы в простое",64123,null],[88307,"2026-07-03T04:35:59",5,"— Ты говоришь, что вы продолжите дело? Продолжите лезть в карьер? Какую помощь вы ожидаете от рыцарей ордена? Мы охраняем покой простых жителей наверху. Лезть в карьер ради наживы — не наш путь",87003,null],[88308,"2026-07-03T04:37:54",5,"// на перекрестном допросе инквизиции вас бы как орешки раскололи. Но это лишь рыцарь в лесу",87107,null],[88313,"2026-07-03T07:25:03",9,"— Лишь не пустить нежить на верх. О большем просить не могу я. Больно видеть как рискуют люди по чьей-то неосторожности. — *Леда не просил ничего сверхъестественного, просто выполнить обычную работу.*",88307,null],[88316,"2026-07-03T07:33:11",5,"— Мы не пускаем нежить наверх каждый день, патрулируем вокруг карьера. Об этом просить не надо, это наша задача здесь. Или ты имеешь в виду что-то другое?",88313,null],[88318,"2026-07-03T07:37:55",9,"— Товарищи хотят полезть туда сами. Буду там. Лишь бы не знать, не быть — нежить нас смогла вылезть и навредить кому либо. Большее — не знаю, личная просьба. — *Попростл только о своём, что надо союзникам? Пусть просят сами, по факту Леда считал что просить о большем — наглость.*",88316,null],[88321,"2026-07-03T07:45:09",5,"— Полагаю, мы можем подождать наверху, когда вы полезете туда. И отбить нежить за вами. Да, на это я согласен. Только не шумите сильно, Аскелатора ради!",64123,null],[88322,"2026-07-03T07:46:49",9,"*Кивает, и делает признательный поклон положив руку на сердце.*",88321,null],[88333,"2026-07-03T08:20:12",32,"- вообще по плану и у меня нет ни малейшей нужды лезть в в карьер, сначала выманить мертвяков и перебить. Для этого я и хотел снарядится святой водой и посеребренными стрелами.\nИбо хочу перебить как можно больше на заготовленных ловушках а уже потом идти устранять источник.",88318,null],[88336,"2026-07-03T08:39:46",5,"— Получить святую воду можно на аванпосте ордена, у интенданта. Скажите, что покупаете ради зачистки карьера, и вам сделают скидку.",88333,null],[88337,"2026-07-03T08:40:11",5,"// если хочешь более значительную помощь рыцарей, то стоит посвятить их в план",64123,null],[88342,"2026-07-03T08:56:51",47,"/блин.а я хотел бы в орден",64123,null],[88343,"2026-07-03T08:59:25",5,"// это особые заслуги. Может если проявишь себя в уничтожении нежити и потом убеждение прокинешь возьмут",88342,null],[88348,"2026-07-03T09:13:23",47,"- Я рад буду помочь в уничтожении нежити. Хотя изначально я прибыл за добычей, но не это было моей первоначальной целью",64123,null],[88349,"2026-07-03T09:14:32",9,"– Золото не стоит смертей.",64123,null],[88391,"2026-07-03T09:55:19",47,"Простой кивок",64123,null],[88408,"2026-07-03T10:04:38",47,"Эльф знал, что честь стоит дорогого. И сейчас ему стыдно, что он вообще допустил мысль о выстреле в спину союзникам. Что он поддался этому... Этому... \"***\"",64123,null],[88820,"2026-07-03T11:28:24",32,"Если хотите купить воды святой то за свои деньги ибо у меня три золотых на карманные расходы осталось",64123,null],[88821,"2026-07-03T11:29:11",5,"// к рыцарю больше запросов не будет?",64123,null],[88822,"2026-07-03T11:29:18",47,"@elsio28 идём в орден.",64123,null],[88825,"2026-07-03T11:31:43",5,"— Что ж, мне пора вернуться к охране карьера. Пожалуйста, думайте о последствиях, когда связываетесь с нежитью!\n\nГлорир надел шлем, повернул лошадь и съехал с тропы в лес. Он направился примерно в направлении карьера.",64123,null],[88830,"2026-07-03T11:33:12",9,"— У меня всего шестьдесят золотых. — *Покачал головой.* — Капканы лучше и больше",64123,null],[88831,"2026-07-03T11:33:21",47,"- Так, точно - кивает эльф",64123,null],[88901,"2026-07-03T11:43:24",5,"Спустя час пути по тропе через лес впереди становится виден просвет. Тропа расширяется, становится небольшой дорогой. На ней видны глубокие следы от телег.\n\nПо мере продвижения по бокам от тропы всё чаще видны вырубки — поляны со множеством пней.",64123,null],[88924,"2026-07-03T11:45:46",47,"Это эльфа не касается. Да, он лесной. Но в первую очередь он воспитанник ордена, а не своей рассы",64123,null],[88980,"2026-07-03T11:52:38",5,"Вскоре вы выходите из леса на открытое пространство. Перед вами возвышается частокол, дорога уходит в открытые деревянные ворота. Из них выезжает небольшой отряд рыцарей. Они проезжают мимо вас, не обращая никакого внимания.",64123,null],[89085,"2026-07-03T12:05:13",47,"Эльф отдаёт приветствие, так, как это положено",64123,null],[89089,"2026-07-03T12:05:37",5,"Один из рыцарей замечает это и кивает",64123,null],[89674,"2026-07-03T14:17:22",32,"Жук телепатией приветствует но никто кроме рыцарей не слышит\n-Приветствую.",64123,null],[89722,"2026-07-03T14:25:56",5,"Такой способ привлекает их внимание. Они дружно оборачиваются и сквозь шлемы глядят на странное существо. На секунду даже останавливают лошадей.",89674,null],[89730,"2026-07-03T14:30:23",32,"С видом \"не понимаю что тут такого\" помахал руками (всеми четырьмя)",89722,null],[89735,"2026-07-03T14:31:23",5,"Один из них произнёс:\n\n— Приветствую, три-крин! Давно не встречал таких как ты.\n\nПо голосу ты понимаешь, что это немолодой, бывалый воин.",89730,null],[89742,"2026-07-03T14:33:26",32,"-Приветствую воин. Я просто Жук. \nРад что есть те кто видели три-кринов.\n(Да жуку действительно было радостно что в этом мире есть такие же как он)\n-Куда вы направляетесь, могу узнать?",64123,null],[89767,"2026-07-03T14:40:35",5,"— В командорство ордена близ Аннежа. Здесь наши дела закончены, аванпост готов к работе.",89742,null],[89770,"2026-07-03T14:41:24",5,"// вы где-то здесь в лесу. На севере Веспираль",64123,null],[89774,"2026-07-03T14:42:46",47,"Эльф двигает дальше к аванпосту",64123,null],[89781,"2026-07-03T14:45:33",5,"Ворота всё ещё открыты, и немного дальше стоит лишь 1 стражник. Он выглядит весьма расслабленным.\n\n— Цель визита?",89774,null],[89793,"2026-07-03T14:47:20",47,"- Помощь ордену с чисткой нежити. Борьба с нежитью! - чётко отвечает эльф",64123,null],[89802,"2026-07-03T14:49:27",5,"Воин смотрит на тебя и как будто не верит. Но ещё больше ему плевать.\n\n— Проходите. Капитан сейчас в патруле, с ним пообщаться не сможете. А интендант вон там.\n\nОн указывает на статную женщину, стоящую около небольшого сруба.",89793,null],[90001,"2026-07-03T15:31:56",47,"@Xaosick Hard",64123,null],[90002,"2026-07-03T15:31:58",47,"Вы где?",64123,null],[90087,"2026-07-03T15:46:12",9,"//Я не знаю что делать, хз зачем мы тут. Помощи я попростл 🤔",64123,null],[90195,"2026-07-03T16:04:39",32,"//я только вернулся домой у меня был жаркий день.\nСенокос, солнышко +50 и пыль.\nТакое чувство что для стопроцентного сходства с Авернусом не хватало только лавовых рек",64123,null],[90199,"2026-07-03T16:05:16",32,"//я вообще-то хотел с рыцарями потрешать ещё",89767,null],[90201,"2026-07-03T16:05:25",5,"// говори",90199,null],[90202,"2026-07-03T16:06:33",32,"- рыцари уважаемые у вас тут нет дел но вам ведь не к спеху в штаб ордена? Может поможете с управлением нежити в одном примечательном карьере.",90201,null],[90238,"2026-07-03T16:12:37",5,"Тот же рыцарь говорит с тобой, остальные восседают на лошадях сзади.\n\n— Вы собрались очистить карьер от нежити? Втроём? Ха! Сынок, послушай слова ветерана. Для такого дела понадобится экспедиция ордена, а значит одобрение от самого магистра. У вас нет шансов. Впрочем, на этом аванпосте главный — капитан Глорир. Поговори с ним, может он выделит отряд.",90202,null],[90243,"2026-07-03T16:14:10",47,"- Он и посоветовал к вам обратится. Он не так давно убыл на охрану Карьера",64123,null],[90250,"2026-07-03T16:15:52",5,"— Да ну? Мы тут инспекцию аванпоста проводим,а все дела на нём.\n\nРыцарь меряет тебя взглядом.",90243,null],[90251,"2026-07-03T16:16:00",5,"// он не советовал если что",90243,null],[90259,"2026-07-03T16:18:11",32,"-Наоборот у меня есть план. Я как инженер не собираюсь принимать бой лоб в лоб. У меня есть куча идей как на ловушках перемолоть минимум пол сотни костяков и это именно самими ловушками а через хорошую фортификацию ещё сколько то выбьем сами.",90238,null],[90260,"2026-07-03T16:18:28",32,"(жук встал и вытянулся как на докладе)",64123,null],[90262,"2026-07-03T16:18:36",5,"// кинь убеждение чтобы они тебя выслушали",90259,null],[90270,"2026-07-03T16:20:20",32,"//Я забыл, а сегодня вы с призраком дрались",64123,null],[90273,"2026-07-03T16:20:34",5,"// да, сегодня утром",64123,null],[90274,"2026-07-03T16:20:38",5,"// сейчас почти вечер",64123,null],[90276,"2026-07-03T16:20:49",32,"/roll d20+4",64123,null],[90278,"2026-07-03T16:20:56",32,"Убеждение",64123,null],[90289,"2026-07-03T16:22:40",5,"— Ах, у тебя есть идея! Даже не знаю, стоит ли мне тратить своё время на это.\n\nРыцарь замер в нерешительности. А потом снял шлем. Под ним лицо воина, покрытое множеством шрамов.\n\n— Ну говори. Только покороче!",90259,null],[90350,"2026-07-03T16:29:58",32,"(жук коротко пересказывает и перерисовывает план фортификации)\n-при грамотном перекрытии полей обстрела скелетов можно перемалывать сотнями. А святая вода это страховка от призраков и более сильных тварей если они там найдутся.\nМасло подожженное это маяк для скелетов чтобы лезли именно в ловушку. А ещё у меня есть подозрение почему образовалась эта зона и кто является главным мертвяков на районе. Собственно сильный призрак",84527,null],[90352,"2026-07-03T16:31:03",5,"// кинь выступление с преимуществом",64123,null],[90373,"2026-07-03T16:36:23",32,"/roll 2d20H",64123,null],[90377,"2026-07-03T16:36:39",32,"+4 (забыл написать",64123,null],[90379,"2026-07-03T16:36:47",32,"Потому 20 выступление",64123,null],[90405,"2026-07-03T16:44:14",32,"//жук явно привык к отчётам перед начальством и не только",64123,null],[90420,"2026-07-03T16:47:00",5,"Когда жук начинал свою речь на лице ветерана были безразличие и скука. Однако теперь он слушает с интересом, а глаза как будто стали ярче. Он немного кивает, слушая твои доводы.\n\n— Дельный план, давно таких не слышал. Очень дельный! Да, сработает, если будет достаточно воинов наверху. А потом можно спуститься вниз, как поток нежити ослабнет...\n\nВнезапно один из рыцарей сзади выезжает чуть вперёд. Он тоже снял шлем и смотрит на три-крина.\n\n— Капитан Глорир знает? Что он сказал?",64123,null],[90460,"2026-07-03T17:02:11",32,"-Он не выслушал нас. Матерился на то что нежить лезла и то что пару людей в патрулях потерял потому был не настроен вникать",64123,null],[90463,"2026-07-03T17:02:47",32,"(жук разводит руками) \n-Но вы можете с ним и сами поговорить",64123,null],[90496,"2026-07-03T17:13:11",5,"Рыцарь без шлема впереди бросает долгий взгляд на остальных.\n\nРыцарь в шлеме (сзади):\n— У капитана были причины для недовольства. И очень веские. Значит, это вы — виновники утренней тревоги!\n\nРыцарь без шлема (спереди):\n— Все планы должен одобрить капитан Глорир. Он командует аванпостом.\n\nРыцарь-ветеран:\n— План три-крина дельный. Я поговорю с капитаном.",64123,null],[90506,"2026-07-03T17:17:35",9,"//Сорри, я уже не могу за леду отыгрывать + игры идут, решайте так что)",64123,null],[90508,"2026-07-03T17:17:41",32,"(жук невозмутимо кивнул. Он был не виноват в произошедшем как минимум на свой скромный взгляд)\n-Хорошо я работать. Возводить укрепления по плану.",90496,null],[90509,"2026-07-03T17:18:14",5,"// ну пока жук ведёт. Леда для боя будет нужен",90506,null],[90511,"2026-07-03T17:21:21",32,"//рубит лес пусть и помогает в укреплении.\nСтволы на бревна, ветви на укрепление земляных насыпей (армирование) а жук будет ямы копать и насыпи поднимать",90509,null],[90516,"2026-07-03T17:23:35",5,"Рыцарь в шлеме Варра(сзади):\n— Эти авантюристы правда думают, что смогут очистить проклятый карьер! Я даже задержусь на несколько дней, чтобы посмотреть на это.\n\nРыцарь без шлема Лансель(спереди):\n— Это может сработать, Варра! И мы должны участвовать в битве\n\nРыцарь-ветеран Айзек обращается к вам:\n— Постойте. Можете получить снаряжение у интенданта. Лансель, передашь ей приказ? Я отправлюсь к карьеру, потолкую с Глориром.",90508,null],[90521,"2026-07-03T17:26:15",5,"Рыцарь в шлеме Варра(сзади):\n— Интересно, что скажет магистр, когда узнает, что вы тут задумали. Это необоснованный риск, и вы это знаете!\n\nОн тронулся с места и поскакал по дороге.",64123,null],[90522,"2026-07-03T17:27:13",32,"-Я не верю вера как понятие три-кринам чужда но я не отступлю.\nМне из снаряжения надо только пара склянок с святой водой для метания по жирной или не материальной цели",64123,null],[90523,"2026-07-03T17:28:23",5,"Рыцарь без шлема Лансель(спереди):\n— Всё будет. Следуйте за мной, к арсеналу",90522,null],[90524,"2026-07-03T17:28:38",32,"(жук как всегда был абсолютно спокоен.)",64123,null],[90525,"2026-07-03T17:29:17",32,"(спокойно двинулся за рыцарем. Осматривая окружение и лагерь)",90523,null],[90528,"2026-07-03T17:30:41",5,"Вы попали сюда, стражник уважительно отступил и не стал задавать вопросы, увидев кто вас ведёт.",89802,null],[90529,"2026-07-03T17:31:20",5,"Лансель подъехал в женщине-интенданту и что-то сказал. Она кивнула.",64123,null],[90532,"2026-07-03T17:33:50",32,"-Приветствую (жук вежливо поздоровался)",64123,null],[90535,"2026-07-03T17:34:31",5,"— День добрый. Сейчас принесу святую воду. Вижу, ты маг. Свитки защитные есть, хочешь посмотреть?",90532,null],[90537,"2026-07-03T17:35:04",5,"У арсенала каждому из вас бесплатно выдают 3 склянки святой воды.",64123,null],[90539,"2026-07-03T17:35:32",32,"-У меня денег нет но если у вас есть та же \"защита от добра и зла\" или \"псевдожинь\" я бы вот прямо не отказался",64123,null],[90540,"2026-07-03T17:35:35",5,"// Hard @cirson запишите себе тоже",90537,null],[90541,"2026-07-03T17:35:43",32,"Да и остальное тоже что есть",90535,null],[90542,"2026-07-03T17:35:58",5,"— Сейчас покажу. Скидку сделаю, дело хорошее",90539,null],[90544,"2026-07-03T17:36:38",32,"-Леда, Талон. Денег займете?",90542,null],[90545,"2026-07-03T17:37:09",32,"//тут без товарищей уже никак",64123,null],[90547,"2026-07-03T17:37:55",9,"//63 золотых естт, бери без б",90544,null],[90553,"2026-07-03T17:41:31",32,"-Леда спасибо тебе.\n(Поблагодарил жук великана и сложив свои 3,4 золотых и 63 от Леды)",64123,null],[90557,"2026-07-03T17:44:33",5,"Перед вами товары на выбор. Все с большой скидкой, это видно сразу.\n\nЗелье лечения — 21 зм\nСвятая вода (до 3 штук) — 9 зм\nПосеребренный кинжал — 52 зм\n\nСвитки:\nЗащита от оружия — 4 зм\nСлово сияния — 6 зм\nОбнаружение зла и добра — 9 зм\nЗащита от зла и добра — 16 зм\nЩит веры — 18 зм\nНетленные останки — 39 зм\nОхраняющая связь — 43 зм\nМаяк надежды — 96 зм",64123,null],[90558,"2026-07-03T17:45:52",32,"-охраняющая связь это что? и слово сияния.",64123,null],[90559,"2026-07-03T17:46:02",5,"https://dnd.su/spells/455-word-of-radiance/",64123,null],[90560,"2026-07-03T17:46:08",5,"https://dnd.su/spells/220-warding-bond/",64123,null],[90565,"2026-07-03T17:52:38",32,"Обнаружение добра и зла, защита от добра и зла и щит веры.\n9+16 (25)+18 =43 зм и зелье лечения+21\n64 зм.\nИ осталось у меня 2,4 зм",90557,null],[90566,"2026-07-03T17:53:39",5,"// продано",64123,null],[90567,"2026-07-03T17:55:20",5,"// также напомню, что у меня даже немаги могут использовать свитки, пройдя проверку магии сл.5",64123,null],[90570,"2026-07-03T17:57:08",32,"//Сгребу себе в инвентарь? И разсую по кармашкам.",64123,null],[90572,"2026-07-03T17:59:01",5,"// @cirson ты можешь купить из списка тоже, когда появишься. Даже если мы по сюжету уйдём уже оттуда",90557,null],[90676,"2026-07-03T19:37:24",47,"Он так и сказал: обратитесь, поясните так. Получите скидку",90251,null],[90677,"2026-07-03T19:38:15",47,"Посеребренного оружия нет?",90557,null],[90678,"2026-07-03T19:38:56",47,"Из этого только зелья лечения и святая вода +- работают",90557,null],[90727,"2026-07-03T21:15:31",47,"В общем мы готовы. Посоциалил бы с рыцарями, но чувствую будет выглядеть как жоползиство, не охота /",64123,null],[90734,"2026-07-03T21:52:50",32,"//в целом да жук будет заниматься строительством. Эх видимо прийдется рисовать карту",64123,null],[91196,"2026-07-04T03:12:48",5,"// добавил кинжал",90677,null],[91197,"2026-07-04T03:12:49",5,"// про скидку да",90676,null],[91198,"2026-07-04T03:12:49",5,"// схематично можешь",90734,null],[91199,"2026-07-04T03:49:15",5,".",84527,null],[91200,"2026-07-04T04:01:39",5,"// я вот представляю. Полукруги — насыпи, круги рядом — ямы",64123,null],[91206,"2026-07-04T07:39:25",32,"Немного не так. Яма как окоп полукругом. За ней насыпь. Они чуть сильнее закручены и поставлены можно сказать по карте в нахлест и за перем уровнем насыпей идём более высокий второй. Для отступления",91200,null],[91207,"2026-07-04T07:39:46",32,"Но в целом да",91200,null],[91208,"2026-07-04T07:42:12",5,"// у ската для бревён тоже яма и насыпь?",91206,null],[91209,"2026-07-04T07:43:08",32,"//Нет смысла",91208,null],[91210,"2026-07-04T07:43:16",32,"Там просто скат",64123,null],[91211,"2026-07-04T07:43:20",5,"// тогда яма не сплошная?",64123,null],[91213,"2026-07-04T07:44:40",32,"Нет конечно. Это по сути окоп зигзагом по которому с одной на другую огневую точку переходить если нас зажмут а путь один через узкие и простреливамые сверху отвесные коридоры и либо лезть либо идти и так и так жесть",91211,null],[91214,"2026-07-04T07:45:14",5,"// что-то ты сложно для одной земли придумал",91213,null],[91215,"2026-07-04T07:45:18",5,"// и немного бревен",64123,null],[91216,"2026-07-04T07:45:37",5,"// давай чтобы я мог нарисовать, это будет длинная яма и насыпь за ней",64123,null],[91217,"2026-07-04T07:46:08",32,"//Если я вернусь домой сегодня я так и быть нарисую сам",91216,null],[91218,"2026-07-04T07:46:35",32,"Там прикол в том что есть несколько слоев и оборонятся там чудо как легко",91216,null],[91219,"2026-07-04T07:46:56",32,"А нападать это брать окоп своими телами(или костями)",64123,null],[91220,"2026-07-04T07:47:15",5,"// какие преимущества механически?",91218,null],[91221,"2026-07-04T07:47:37",5,"// сорри мне сложно понять всю постройку",64123,null],[91222,"2026-07-04T07:48:21",32,"Очень сложная местность. Либо петляй в коридорах и теряй скорость просто капитально. Либо лезь на добрых дядей которые тебе черепашку размажат",91220,null],[91223,"2026-07-04T07:48:40",32,"//я прекрасно понимаю что плохо объясняю",91221,null],[91224,"2026-07-04T07:48:48",32,"Но лучше сейчас не смогу",64123,null],[91225,"2026-07-04T07:48:57",32,"//На работе, ошалевши.\nПытаюсь я в себя прийти\nВовремя не легши \nМожно ,по миру пойти",64123,null],[91226,"2026-07-04T07:49:08",5,"// окей",91222,null],[91227,"2026-07-04T07:49:16",5,"// в общем нарисуй схему",64123,null],[91229,"2026-07-04T08:05:52",5,"// Серебряное оружие очень дорогое оказывается",90677,null],[91231,"2026-07-04T08:15:31",47,"Эльф грустно смотрит на кинжал, но готов биться тем, что есть",91229,null],[91234,"2026-07-04T08:52:00",32,"/так не серебряное а посеребренное по идее такое покрытие в районе 20-50 золотых на меч должно стоить не больше",91229,null],[91244,"2026-07-04T10:38:17",5,"// 100 зм любое",91234,null],[91245,"2026-07-04T10:39:08",32,"//разве серебро дороже золота?",91244,null],[91246,"2026-07-04T10:39:30",32,"//Тут просто по весу монет получается",64123,null],[91247,"2026-07-04T10:39:39",5,"// хз, такие правила",64123,null],[91248,"2026-07-04T10:39:40",9,"//Типа того, только у нас 20 боеприпасов",91244,null],[91249,"2026-07-04T10:40:31",9,"//Хотя если по квесту надо можно оценить ÷2 итоговую сумму, игроки за больше не продадут.",64123,null],[91250,"2026-07-04T10:40:51",9,"//Или выдатт как лут, решать дм",64123,null],[91251,"2026-07-04T10:41:18",32,"//тип просто разменяю серебром золотые монеты.\nСейчас в книге посмотрю сколько они по весу",91248,null],[91252,"2026-07-04T10:42:21",9,"//А как получишь осеребрённое оружие без потери качества? Хотя мне пох, я и серебрянной вилкой призрака накуканю ^^",91251,null],[91253,"2026-07-04T10:43:30",32,"//Так я к тому же просто молотком выровнять плюс минус из монеты наконечник и насадить на стрелу чтобы призрака повреждало",91252,null],[91254,"2026-07-04T10:45:10",9,"//Мне не принципиально, веду не я",64123,null],[91255,"2026-07-04T10:45:10",32,"//и получается коэффициент идиота 10 золотых за снаряд к 1 серебряной то есть 100 кратный мой \"хай так\" относительно продаваемого",64123,null],[91349,"2026-07-04T16:12:31",5,"Герои покинули аванпост ордена и отправились к карьеру. Они прибыли без происшествий. Уже вечер, туман зловеще клубится под ногами, а патруль рыцарей ходит вокруг карьера. Сейчас свет от их факелов мерцает вдали.",64123,null],[91361,"2026-07-04T16:36:49",47,"/100 голды за посеребрение и вправду не логично, так как существует лунный меч, который как маг предмет стоит 50-70 голды",64123,null],[91362,"2026-07-04T16:37:13",47,"/а он считается магическим при определении сопра, или иммунитета не только у нежити и им подобных, но и вообще",64123,null],[91641,"2026-07-04T20:09:15",32,"Что-то вроде вот такого",91200,null],[91642,"2026-07-04T20:13:08",5,"// ямы за первыми насыпями есть?",64123,null],[91665,"2026-07-04T20:55:41",32,"Да там насыпь яма поочередно. Ямы там это окоп по сути и в этом Z образном коридоре в конце подъем ступеньками",64123,null],[91758,"2026-07-04T22:41:24",47,"/пасаны.мв планируем укрепления дольше, чем идёт квест. Давайте переедем хребет нежити и всё?",64123,null],[91787,"2026-07-04T22:48:03",32,"//можно но я пока все равно занят не много. Ток завтра если. И это если не отыгрывать постройку всего этого великолепия на сутки не очень напряжной работы",91758,null],[91808,"2026-07-04T22:53:50",47,"/завтра",64123,null],[91855,"2026-07-05T05:34:13",5,"На месте вчерашнего боя, у лестницы из песка, видна куча следов. Похоже, обитатели карьера оценили изобретательность жука. И воспользовались удобными ступеньками.",91349,null],[91856,"2026-07-05T05:38:48",5,"Вскоре до героев добирается патруль рыцарей. Его ведут сразу два всадника: Глорир и Айзек. Капитана посвятили в планы и он не против. Его слова жуку:\n\n— Предоставлю столько воинов, сколько смогу. Полагаюсь на твой план. Вижу, ты уже начал строительство укреплений. Воины воспользуются ими, но если я увижу потерю преимущества этой позиции, то прикажу отступить. Не стоит терять жизни понапрасну. \n\nЧуть позже он добавил:\n\n— Не знаю как, но вы убедили Варру, Ланселя и Айзека остаться на время битвы. Они обещали присоединиться.\n\nРыцаря пошли патрулировать дальше, пообещав быть на месте в условленное время.",64123,null],[91857,"2026-07-05T05:40:46",5,"В течение следующих суток герои ведут строительные работы. Жук усердно перемещает землю заклинаниями, Леда доставляет брёвна. А эльф... наблюдает за опасностями?",64123,null],[91858,"2026-07-05T05:41:52",5,"// у вас точно ещё один долгий отдых. Потом битва, если вечером. Или ещё один отдых, если битва утром. Вычтите рационы у себя)",64123,null],[91859,"2026-07-05T05:43:16",5,"// жук кидает магию, без возможности повлиять на бросок. Строительство идёт успешно, но в масштабных проектах всегда есть ошибки. Которые никто не заметил",64123,null],[91862,"2026-07-05T06:29:58",32,"/кинуть магию?",91859,null],[91863,"2026-07-05T06:34:51",32,"/roll d20+5",64123,null],[91866,"2026-07-05T06:40:38",5,"Укрепления построены. Выглядят как и задумано. Остаётся лишь надеяться, что они не подведут в бою",64123,null],[91867,"2026-07-05T06:51:08",32,"//инженер растерял хватку",91864,null],[91868,"2026-07-05T07:03:38",32,"/roll 2d20 \nЗнамения на сегодня",64123,null],[91880,"2026-07-05T08:19:11",47,"/завтра наступило",64123,null],[91881,"2026-07-05T08:20:06",5,"// если все игроки здесь, проведу",64123,null],[91882,"2026-07-05T08:20:27",5,"// там бой, так что нужна активная игра",64123,null],[91883,"2026-07-05T08:21:02",9,"//Я ток проснулся, скажите что делать, а то не туту вообще покачто ^^",64123,null],[91893,"2026-07-05T08:41:38",32,"//я на поле но вроде свободен пока",64123,null],[95899,"2026-07-06T14:57:31",5,"// так, нужно собраться всем. Поэтому предлагаю о времени договориться.Как насчёт завтра в 10?",64123,null],[95900,"2026-07-06T14:57:44",47,"Здесь и сейчас не могу ответить",64123,null],[95903,"2026-07-06T14:58:21",32,"//я не против и поддержу любое время если не будет непредвиденных форс-мажоров",95899,null],[95906,"2026-07-06T14:58:46",5,"// окей, можешь сказать время в которое ты чётко будешь?",95900,null],[95908,"2026-07-06T14:59:41",47,"/нет",64123,null],[95909,"2026-07-06T15:00:04",47,"/я не могу пока",95900,null],[95912,"2026-07-06T15:03:29",5,"// тогда как мне провести бой, чтобы все были на месте?",95909,null],[95916,"2026-07-06T15:10:26",32,"(жук ещё на стрелы эльфа взял 20 штук и по серебряной монетке наковал.\n(Расплющил и просто обмотал холодной формовкой))\n- Выдержат пару тройку выстрелов но оборотней из них гасить будет сложно",95906,null],[95917,"2026-07-06T15:10:59",5,"// инструменты кузнеца? или обоснуй как-то",95916,null],[95919,"2026-07-06T15:13:02",32,"//просто молотком из инструментов жестянщика на слитке. Это элементарная задача даже без владения ковкой",95917,null],[95920,"2026-07-06T15:13:20",5,"// окей пойдёт",95919,null],[95921,"2026-07-06T15:13:57",32,"//я такое буквально на железной ступеньке проделывал в реале обычным рабочим молотком.\nА так же на кувалде делал",95920,null],[95931,"2026-07-06T15:53:40",47,"Я в выходной был /",95912,null],[95955,"2026-07-06T16:14:49",5,"//когда это будет?",95931,null],[96227,"2026-07-06T20:32:06",47,"/вчера это было. С утра писал",64123,null],[96228,"2026-07-06T20:32:16",47,"/предложил как раз отыграть. Все отписались... И всё",64123,null],[96229,"2026-07-06T20:32:58",5,"// ладно, тогда напиши опять как будет выходной",64123,null],[96230,"2026-07-06T20:33:41",47,"Хорошо/",64123,null],[96231,"2026-07-06T20:33:47",47,"/благодарю за понимание",64123,null],[99235,"2026-07-08T01:58:32",32,"Про жука просто",64123,null],[101224,"2026-07-09T13:07:21",9,"// @Xaosick @cirson @elsio28 квест встал и уже давно. Я предлагаю его закончить. Выдать по 100 золотых и по 100 опыта и не задердивать персонажей игроков просто подвести итоги.",64123,null],[101226,"2026-07-09T13:07:28",9,"//Это лишь предложение",64123,null],[101234,"2026-07-09T13:10:14",5,"// я могу провести квест в любой момент, там последняя битва осталась. Он не встал, мы чисто ждём одного игрока",64123,null],[101236,"2026-07-09T13:10:26",5,"// кстати ты сам писал, что очень не нравится, когда игроков не ждут",64123,null],[101238,"2026-07-09T13:11:26",9,"//Мне очень не нравится когда игроков не ждут, и мне очень не нравится когда квесты не идут. У меня то лишь Леда остался тутт я им не играю уже, но тут ещё 2 игрока, с ними три)",64123,null],[101240,"2026-07-09T13:12:20",5,"// квест не идёт только потому что игроков ждут",101238,null],[101241,"2026-07-09T13:13:22",9,"// Ну, вот такая вот диллема. Мне всё равно говорю, смотрите сами, лишь предложил.",101240,null],[101242,"2026-07-09T13:13:40",5,"// окей, жду их мнения",64123,null],[101259,"2026-07-09T13:20:57",32,"Если Миша не поучаствует в течение суток я валю с этого квеста.",64123,null],[101267,"2026-07-09T13:26:31",5,"В таком случае могу вам через несколько часов провести этот квест",101259,null],[101406,"2026-07-09T15:45:25",5,"Игра через полчаса. Будете?",64123,null],[101458,"2026-07-09T16:01:52",5,"Или завтра утром тогда",64123,null],[105164,"2026-07-10T08:56:21",47,"/к сожалению я хочу закончить. Так как это важно для меня",64123,null],[105165,"2026-07-10T08:56:37",47,"/ближайшие два часа могу",64123,null],[105166,"2026-07-10T08:56:43",47,"@elsio28 @Xaosick Hard",64123,null],[105167,"2026-07-10T09:05:29",5,"// я тут",64123,null],[105168,"2026-07-10T09:26:04",47,"@Xaosick",64123,null],[105169,"2026-07-10T09:26:11",47,"/давайте потихоньку начнём?",64123,null],[105170,"2026-07-10T09:26:20",47,"/не прям резко, но по посту хотя бы",64123,null],[105171,"2026-07-10T09:26:44",5,".",91857,null],[105172,"2026-07-10T09:27:06",5,"// во-первых выберите когда начинаете бой. Утром или вечером",64123,null],[105173,"2026-07-10T09:27:17",47,"/утро",64123,null],[105174,"2026-07-10T09:27:22",5,"// дальше ваша подготовка и отыгрыш",64123,null],[105175,"2026-07-10T09:27:41",9,"//У нас есть жук, он пусть решает)",64123,null],[105176,"2026-07-10T09:27:54",5,"// да, жук нужен",64123,null],[105177,"2026-07-10T09:29:32",47,"Эльф, в то время пока остальные готовят ловушки, точит оружие, заготавливает места, за которыми можно спрятаться, помечает себе возвышенности, с которых будет удобно вести обстрел и смешивает часть глины со святой водой и покрывает им рапиру и стрелы",64123,null],[105194,"2026-07-10T11:28:47",32,"Нам надо лучшая видимость потому поздним утром",64123,null],[105195,"2026-07-10T11:32:23",5,"// опиши как ловушки поставил перед битвой. Я про масло и бревна",105194,null],[105196,"2026-07-10T11:32:34",5,"// и дальше первый этап, как вы начинаете",64123,null],[105197,"2026-07-10T11:32:44",5,"// я буду через полчаса",64123,null],[105198,"2026-07-10T11:34:24",32,"//бревна на скат. Масло туда же. Масло это чисто приманка",105195,null],[105203,"2026-07-10T11:37:26",5,"Туман клубится в самом карьере, не выходя наружу. Сверху вам примерно видно до третьей ступени.",105194,null],[105207,"2026-07-10T11:43:09",5,"К вашим позициям также прибыл отряд воинов ордена, в том числе 4 рыцаря. У укреплений они спешились. Суммарно немного меньше двух десятков воинов. \n\nГлорир (капитан рыцарей):\n— Вижу, инженеры Изеттов могут построить укрепление даже из грязи. Я прикажу воинам разместиться внутри. Мы будем охранять фланги, а вы займитесь центром.",64123,null],[105208,"2026-07-10T11:44:04",5,"// союзники защищают оба фланга. Ваши герои в центре и с вами будет 1 солдат и 1 рыцарь.",64123,null],[105209,"2026-07-10T11:44:41",5,"// во время битвы вы можете потратить действие, чтобы привлечь внимание союзных воинов. И они как-то помогут",64123,null],[105223,"2026-07-10T11:59:17",32,"-Палки сильно подорожали. Дальше строим просто из говна. \n(Жук смотрел в низ с мрачной решимостью и пониманием что сегодня все пойдет совсем не по плану)",105207,null],[105224,"2026-07-10T11:59:33",32,"/roll 2d20 \nЗнамения",64123,null],[105226,"2026-07-10T12:00:01",32,"(пардон забыл что их кидал уже)",105225,null],[105227,"2026-07-10T12:01:24",32,"-Все готовы?\nТогда начнем с простого",64123,null],[105228,"2026-07-10T12:02:09",32,"(жук если получит подтверждение несмотря на ужасно плохое предчувствие кинет в карьер огненную стрелу)",64123,null],[105240,"2026-07-10T12:23:37",47,"- Готов - эльф распологается рядом с воинами и прячется за заслоном /надо скрыт?",64123,null],[105241,"2026-07-10T12:24:46",32,"//кстати стрелы сделанные жуком можно считать импровизированным оружием",105240,null],[105242,"2026-07-10T12:30:04",47,"/да, но я бы предпочёл ими пользоваться как стрелами. А вообще потом хотел бы договориться на тему серебрянных кинжалов. И может ещё чего. Хочу из эльфа сделать максимально универсального бойца",105241,null],[105243,"2026-07-10T12:30:19",47,"/типо и в ближний бой может, и в дальний и метнуть если надо",64123,null],[105244,"2026-07-10T12:30:40",47,"/ток проблема с щитом. Либо обучение щитом брать, либо ещё что выдумывать",64123,null],[105245,"2026-07-10T12:31:26",32,"//я имею ввиду стрелять из лука но так как стрелы сделаны на коленке то к попаданию -2 модификатор",105242,null],[105246,"2026-07-10T12:32:50",5,"// нет, авто скрытность пока",105240,null],[105247,"2026-07-10T12:33:01",47,"/я думаю оно всё же так не работает. Импровизированное оружие, это когда ты используешь что-то, что как оружие не исользуется",105245,null],[105248,"2026-07-10T12:33:16",47,"/вот если бы я стрелял из лука серебрянными вилками...",64123,null],[105249,"2026-07-10T12:33:27",47,"Вместо одной, четыре дырки, ага/",64123,null],[105250,"2026-07-10T12:33:32",5,"// не в рамках этого квеста, я такое решать не буду. Но для призраков пойдёт",105245,null],[105251,"2026-07-10T12:33:59",47,"/дырявые призраки 😁",64123,null],[105252,"2026-07-10T12:34:13",5,"Стрелы упала огненной дугой. Из карьера всё также слышит хруст. Но пока ничего не происходит",105228,null],[105253,"2026-07-10T12:34:25",5,"// Hard будешь?",64123,null],[105254,"2026-07-10T12:34:37",47,"/заготовка действия",64123,null],[105255,"2026-07-10T12:34:49",32,"/аналогично",105254,null],[105256,"2026-07-10T12:35:50",9,"//Я щас готовлю, я не против чтобы леда условно был и всё. Просто варвар 2го уровня считайте, сейчас нет делания играть даже за действующих персонажей.",64123,null],[105257,"2026-07-10T12:36:24",5,"// кто хочет за него сыграть?",105256,null],[105258,"2026-07-10T12:36:46",47,"/я могу чисто как бойцом отыграть. Без рп",64123,null],[105259,"2026-07-10T12:37:47",5,"// давай, если пропадать не будешь",64123,null],[105260,"2026-07-10T12:39:22",5,"Вы подождали несколько минут, но ничего не изменилось. По ступеням никто не лезет.",64123,null],[105261,"2026-07-10T12:40:34",32,"Лепкой земли побвиваю одну чашу с маслом и выливаю вниз поджигая стрелой",105260,null],[105262,"2026-07-10T12:41:54",5,"// сколько там масла?",105261,null],[105263,"2026-07-10T12:42:02",5,"// льёшь на первую ступень?",64123,null],[105264,"2026-07-10T12:42:57",32,"Примерно половину. Там ступень сглажены. До третьей",105262,null],[105265,"2026-07-10T12:45:11",5,"// значит около 40",64123,null],[105266,"2026-07-10T12:45:15",5,"// ща посчитаю",64123,null],[105267,"2026-07-10T12:48:40",5,"Огненный поток льётся вниз по склону, освещая карьер. На третьей ступени масло замедляется и растекается вниз. Но поток не прекращается и вот уже четвёртая ступень в огне. \n\nВ огненных отбликах вы видите сквозь туман, что скелет поднимается в потоке, медленно идёт в вашу сторону, но через несколько секунд его кости плавятся и остатки падают в масляное море.\n\nМасло всё льётся вниз.",64123,null],[105271,"2026-07-10T12:54:33",5,"Ещё несколько скелетов встают, объятые огнём. Но \"живут\" недолго. Огненное море течёт дальше вниз, вы видите зарево сквозь туман, но не можете разобрать, насколько глубоко уже ушло масло.",64123,null],[105281,"2026-07-10T13:03:46",47,"/я пропал... Я и так дольше возможного сидел.",64123,null],[106523,"2026-07-11T10:36:44",47,"@elsio28 @Xaosick Hard",64123,null],[106524,"2026-07-11T10:36:47",47,"Я тут",64123,null],[106525,"2026-07-11T10:37:02",47,"Возможно весь день буду тут. Кроме обеда и ужина",64123,null],[106526,"2026-07-11T10:54:04",5,"Масляное море ещё горело внизу, когда хруст костей заметно усилился. Вскоре в тумане появились силуэты врагов. Десятки скелетов лезут по ступеням карьера. Они наступают слева и справа от ваших укреплений. По догорающему маслу никто не идёт.\n\nДалеко внизу раздался топот. Как будто что-то массивное пробудилось.",64123,null],[106528,"2026-07-11T10:55:51",5,"Скелеты разного роста, некоторые человеческого, с короткими мечами. Другие ниже и с топорами. И всей толпы выделяется несколько высоких скелетов, на них виднеется броня, а в руках двуручные мечи.",64123,null],[106529,"2026-07-11T11:01:16",47,"@Xaosick",64123,null],[106531,"2026-07-11T11:10:11",32,"(Ну начнём. Враги с ближним оружием. Потому у стрелков стратегическое приимущество)\n- первоочередная цель топоры.(Скомандовал жук покрывая телепатией все укрепления с запасом)",106527,null],[106533,"2026-07-11T11:57:53",47,"/r +d20+8",64123,null],[106535,"2026-07-11T11:58:19",47,"/r 2d8+4 урона серебрянной стрелой из лука по скелету воину",64123,null],[106541,"2026-07-11T13:16:14",5,"Воины ордена с арбалетами слушаются и стреляют по нежити с топорами.  К моменту приближения таких скелетов почти не остаётся. Враги вскоре начнут вылезать из карьера с левого и с правого фланга.\n\nМасло потухло, и спереди лезет плотная группа скелетов.",64123,null],[106542,"2026-07-11T13:16:34",5,"// урон 1д4 импровизированным оружием. У тебя не настоящие серебряные стрелы",106536,null],[106543,"2026-07-11T13:16:44",5,"/ и по какому скелету?",64123,null],[106545,"2026-07-11T13:20:54",5,"В тумане снизу большой силуэт, быстро взбирающийся по ступеням",64123,null],[106550,"2026-07-11T14:16:20",47,"/r 2d4",64123,null],[106552,"2026-07-11T14:16:35",47,"/как реагирует на серебро нкжить?",64123,null],[106553,"2026-07-11T14:17:16",47,"/всё, Иня?",106545,null],[106554,"2026-07-11T14:17:23",5,"// как на попадание камнем. У скелетов нет уязвимости к излучению",106552,null],[106555,"2026-07-11T14:17:50",9,"*Леда берет бревно и кидает в эту хню.*",106545,null],[106556,"2026-07-11T14:18:15",9,"/roll +d20+4 безрассудная нах в ярости пусть",64123,null],[106558,"2026-07-11T14:18:38",9,"//Цель — сбить",64123,null],[106559,"2026-07-11T14:19:02",5,"// безрассудные только на ближние атаки вообще",64123,null],[106560,"2026-07-11T14:19:18",5,"// но у бревна авто попадание, монстр ловкость кидать будет",64123,null],[106561,"2026-07-11T14:19:55",5,"/r +1 чудище уклоняется от бревна",64123,null],[106565,"2026-07-11T14:21:36",5,"/r d10",64123,null],[106567,"2026-07-11T14:22:27",32,"Второе масло в уродца",106555,null],[106568,"2026-07-11T14:22:37",5,"Бревно задевает ноги косматой твари, и она с грохотом падает на ступень. Это её задержит",64123,null],[106569,"2026-07-11T14:22:46",5,"// всю порцию?",106567,null],[106570,"2026-07-11T14:22:51",32,"Жук обламывает вторую чашу и поджигает",64123,null],[106571,"2026-07-11T14:23:03",32,"Да их всего две и было",106569,null],[106572,"2026-07-11T14:23:41",5,"// кидайте иню",64123,null],[106573,"2026-07-11T14:23:41",32,"И потом использую хаотический заряд в чудище",64123,null],[106574,"2026-07-11T14:23:52",32,"/roll d20+7",64123,null],[106576,"2026-07-11T14:23:57",5,"Масло выливается и вновь устремляется вниз",64123,null],[106577,"2026-07-11T14:24:09",5,"// урон",106575,null],[106578,"2026-07-11T14:24:20",32,"Иня",106575,null],[106579,"2026-07-11T14:24:40",32,"В масло огненная стрела поджигает",106576,null],[106580,"2026-07-11T14:24:54",32,"/заряд уже в свой ход",106573,null],[106581,"2026-07-11T14:25:16",5,"// ок, тогда жду ини Hard @cirson",64123,null],[106582,"2026-07-11T14:25:30",5,"/r +1 чудо-юдо",64123,null],[106584,"2026-07-11T14:26:14",9,"/roll 1d20-1 если не отвечаю действуйте за меня, перс уже закрыт",64123,null],[106586,"2026-07-11T14:26:50",47,"/r d20+4",64123,null],[106588,"2026-07-11T14:27:15",5,"/r высокие скелеты",64123,null],[106590,"2026-07-11T14:27:26",5,"/r +2 остальные скелеты",64123,null],[106592,"2026-07-11T14:29:02",32,"//горящий зад ходит первым",106583,null],[106593,"2026-07-11T14:29:13",5,"// ща сделаю)",64123,null],[106596,"2026-07-11T14:33:40",5,"/r -1 Рыцарь-ветеран Айзек",64123,null],[106600,"2026-07-11T14:35:38",5,"Горящее чудо 20\nРыцарь-ветеран Айзек и солдат со щитом 17\nЖук 16\nЭльф 14\nСкелеты 12\nВысокие скелеты 9\nЛеда 5",64123,null],[106614,"2026-07-11T14:40:26",5,"На флангах обошедшие скелеты уже атакуют воинов ордена. Но спереди к вам приближается другая группа нежити.\n\nМасло течёт по скату, прямо к косматому монстру внизу. Скелеты вокруг него уже сгорели.",64123,null],[106631,"2026-07-11T14:42:36",5,"Монстр встаёт и удивительно ловко лезёт по ступеням в вашу сторону.",64123,null],[106635,"2026-07-11T14:44:00",5,"Айзек накладывает на себя Защиту от зла и добра. Другой воин со щитом стоит между эльфом и жуком, готовый прикрыть их.",64123,null],[106636,"2026-07-11T14:44:13",5,"// ход жука",64123,null],[106640,"2026-07-11T14:46:07",32,"/roll d20+5 \nХаотический снаряд в монстра",64123,null],[106643,"2026-07-11T14:46:32",32,"/roll 2d8+d6",64123,null],[106647,"2026-07-11T14:46:58",5,"// неплохо пробил, опиши",64123,null],[106649,"2026-07-11T14:47:07",32,"//сейчас по таблице посмотрю урон)",106644,null],[106650,"2026-07-11T14:47:27",5,"// можешь даже одну лапу оторвать)",64123,null],[106661,"2026-07-11T14:52:25",32,"(жук сотворил заклинание хаотического.\n радужная брызга прочертив дугу с удивительной меткостью впилась в монстра вспышка полупрозрачного тёмно-синего света и нематериальная волна силового поля буквально разрывает монстра одну из лап)\n-Вот это вжарил!",106650,null],[106676,"2026-07-11T14:56:09",5,"Обезьяна стучит по земле остальными лапами, её невидящие глаза направлены на жука.",64123,null],[106677,"2026-07-11T14:56:13",5,"// эльф",64123,null],[106678,"2026-07-11T14:56:19",5,"// и пиши ход в конце хода пж",64123,null],[106681,"2026-07-11T14:56:55",32,"/жук применяет странные соматические компоненты оттопыренные средний палец. Видимо проклясть хотел",106676,null],[106686,"2026-07-11T14:57:38",5,"— Да сгинет нечисть во славу Аскелатора! — торжественно произносит Айзек возле тебя",64123,null],[106707,"2026-07-11T15:01:33",5,"// напоминаю, что свободным действием можно рассматривать врагов и союзников",64123,null],[106711,"2026-07-11T15:02:09",32,"//это ты в тему я забыл. Могу кинуть аркану на монстрика?",106707,null],[106718,"2026-07-11T15:02:45",5,"// анализ либо природу",106711,null],[106720,"2026-07-11T15:02:57",32,"/roll d20+3",64123,null],[106725,"2026-07-11T15:03:31",5,"Это нежить, похожая на обезьяну. Большая и страшная. Зато попасть легко",106721,null],[106734,"2026-07-11T15:05:09",32,"//ход",64123,null],[106760,"2026-07-11T15:19:39",47,"Я хочу осмотреться, а не готовит ли пакость нам враг? В свой ход",64123,null],[106761,"2026-07-11T15:20:34",32,"//так твой ход",106760,null],[106767,"2026-07-11T15:22:15",5,"// куда смотришь",106760,null],[106769,"2026-07-11T15:23:09",47,"/ в тыл/",64123,null],[106771,"2026-07-11T15:25:20",5,"В тылу в центре стоит Глорир. Он командует воинам с обеих сторон. Оба фланга пока отлично держатся, скелетов сбрасывают в ямы и убивают. Два рыцаря с длинными мечами бьются на передовой.\n\nЭльф также видит, что до укреплений пока дошли лишь первые отряды нежити. Остальные, в том числе высокие скелеты с мечами, на которых висят трепещущие клоки плоти, ещё в пути.",64123,null],[106775,"2026-07-11T15:26:19",5,"Несколько арбалетчиков стоят на безопасных возвышениях. У них есть цели, но если позвать — они помогут стрельбой (позвать действием)",64123,null],[106781,"2026-07-11T15:27:30",32,"//у меня как игрока предчувствие плохое. К этой битве",64123,null],[106797,"2026-07-11T15:33:31",47,"Готовлю действие. Перед началом своего хода совершаю выстрел.",64123,null],[106801,"2026-07-11T15:33:37",47,"/тоже предчувствие не очень",64123,null],[106819,"2026-07-11T15:38:24",5,"/r 10d20",64123,null],[106822,"2026-07-11T15:39:04",5,"/r 5d20",64123,null],[106829,"2026-07-11T15:39:56",47,"/страшно.стращно и больно/",64123,null],[106830,"2026-07-11T15:40:03",5,"// пока без боли",64123,null],[106849,"2026-07-11T15:42:29",5,"Группа нежити, идущая справа, лезет по ступени карьера. Черепа врагов уже показываются наверху, как вдруг самый высокий из скелетов опрокидывается назад, увлекая за собой всех остальных. Слышен стук костей, куча нежити лежит друг на друге и ворочается.",64123,null],[106851,"2026-07-11T15:42:35",5,"/r 5d6",64123,null],[106858,"2026-07-11T15:43:42",5,"Группа, идущая с левой стороны от вас, движется гораздо более слаженно. Они быстро преодолевают сначала одну, а затем вторую ступень. Скелеты вылезли из карьера, их ржавые мечи блестят.",64123,null],[106865,"2026-07-11T15:44:55",5,"// ход леды",64123,null],[106928,"2026-07-11T16:05:21",32,"//походи за Леду",106865,null],[106929,"2026-07-11T16:05:39",5,"// ты бери под управление. Или Михаил",106928,null],[106930,"2026-07-11T16:06:26",47,"Леда оглядываясь берёт ближайший скелет и кидает его в группу что двигается к рыцарям:\n- Рррааааа - раздаётся рокот голоса",64123,null],[106932,"2026-07-11T16:07:07",32,"-Леда будь добр кинуть святую воду в тварь внизу",106930,null],[106933,"2026-07-11T16:07:18",5,"// проверка силы",106930,null],[106934,"2026-07-11T16:07:19",47,"/r d20+4 атлетика",64123,null],[106937,"2026-07-11T16:08:35",5,"Скелет улетает в сторону армии нежити, лезущей на укрепления левого фланга. Он встаёт и присоединяется к остальным.",64123,null],[106938,"2026-07-11T16:09:21",32,"(жук комментирует рыцарям)-Ммм простите!",106937,null],[106940,"2026-07-11T16:10:04",47,"/и что, он даже остальных не повалил за собой?",106937,null],[106941,"2026-07-11T16:10:17",47,"/типа кидал как бревно, чтобы сложно было забраться",64123,null],[106942,"2026-07-11T16:10:24",32,"//скелеты очень лёгкие",106940,null],[106944,"2026-07-11T16:10:48",47,"/ладно",64123,null],[106946,"2026-07-11T16:11:13",47,"Если Леда может, он кинет святую воду. Если нет, то возьмёт её в руки. Выпьет, но не проглотит",64123,null],[106947,"2026-07-11T16:11:25",5,"// берёт",106946,null],[106948,"2026-07-11T16:12:14",47,"Щеки Леды надуваются от того количества воды, что он заготовил",64123,null],[106949,"2026-07-11T16:12:18",47,"Ход",64123,null],[106953,"2026-07-11T16:13:16",32,"//кстати а бросок святой воды это действие или можно дополнительным от вторых рук кинуть если не кастовать магию",106947,null],[106954,"2026-07-11T16:13:32",5,"// действие",106953,null],[106959,"2026-07-11T16:14:22",5,"Горящая обезьяна удивительно быстро  лезет по ступеням, как будто всю жизнь этим и занималось. Даже на склоне она не тормозит, а ловко перебирает лапами.\n\nОна подобралась ближе, огромная туша уже высовывается из тумана карьера.",64123,null],[106964,"2026-07-11T16:15:23",32,"Знамения 18+5 попадание хаотического снаряда.",106959,null],[106965,"2026-07-11T16:15:28",5,"// погоди",64123,null],[106966,"2026-07-11T16:16:12",5,"Солдат всё также стоит между жуком и эльфом, готовый уклониться от атак врагов.\n\nАйзек бросается к скелету справа и атакует булавой. А потом ещё раз.",64123,null],[106967,"2026-07-11T16:16:19",5,"/r +6\n/r +6",64123,null],[106974,"2026-07-11T16:16:52",5,"/r d6+4",64123,null],[106977,"2026-07-11T16:17:10",5,"Скелет рассыпается от его удара.",64123,null],[106979,"2026-07-11T16:17:39",5,"// жук ходи",64123,null],[106983,"2026-07-11T16:18:07",32,"В монстра хаотический заряд знамения 18+5",106979,null],[106985,"2026-07-11T16:18:26",32,"/roll 2d8+d6",64123,null],[106987,"2026-07-11T16:18:42",47,"/имба",64123,null],[106988,"2026-07-11T16:18:50",32,"Звуковой распиздос",106986,null],[106989,"2026-07-11T16:18:51",47,"/везунчик)",64123,null],[106990,"2026-07-11T16:19:42",32,"/roll d20+5\n(Перескок)",106986,null],[106992,"2026-07-11T16:19:55",47,"/ахахахахахах)",64123,null],[106993,"2026-07-11T16:20:03",5,"// бро...",106986,null],[106994,"2026-07-11T16:20:07",32,"Ну вот и кончилась визучасть",106991,null],[106995,"2026-07-11T16:20:33",5,"// отрывай ещё руку",106986,null],[106997,"2026-07-11T16:20:52",5,"// а погдои)",64123,null],[106998,"2026-07-11T16:20:55",5,"// это яд",64123,null],[106999,"2026-07-11T16:21:29",5,"// снаряд попал но не сделал абсолютно ничего. Можешь описать",64123,null],[107000,"2026-07-11T16:21:37",47,"/пхахахха",64123,null],[107001,"2026-07-11T16:21:40",32,"Нежить травим угу. Я думал звук но в таблицу тоже посмотрел",106998,null],[107003,"2026-07-11T16:22:08",32,"А д6 как расчет урона не считается?",106999,null],[107004,"2026-07-11T16:22:15",47,"/он тоже яд",107003,null],[107005,"2026-07-11T16:22:23",5,"// не, читай описание закла",107003,null],[107009,"2026-07-11T16:23:40",32,"Ууу бля везёт как утопленнику",64123,null],[107012,"2026-07-11T16:24:28",47,"/опишешь?",64123,null],[107013,"2026-07-11T16:24:38",32,"Не хочу даже",107012,null],[107019,"2026-07-11T16:25:11",32,"Ладно сейчас кину выступление",64123,null],[107025,"2026-07-11T16:25:44",47,"Видя как болотистого цвета хрень безвредно разбилась об мутанта эльф отпускает стрелу, покрытую глиной со святой водой",64123,null],[107027,"2026-07-11T16:25:55",47,"/r +d20+8",64123,null],[107031,"2026-07-11T16:26:04",47,"/r d20+8 переброс 5",64123,null],[107033,"2026-07-11T16:26:16",47,"/r 2d8+4",64123,null],[107036,"2026-07-11T16:26:37",32,"Скелеты явно реагировали на ментальную речь и команды. Потому хочу попробовать приказать командовать",107019,null],[107037,"2026-07-11T16:27:02",47,"Он всматривается в туман. Слишком целенаправленное наступление идёт. Там должен быть тот, кто ими руководит",64123,null],[107044,"2026-07-11T16:29:56",32,"(нежити)- скелетам вокруг. Беги(тому кто за своими товарищами) падай (тому кто хочет атаковать нашего рыцаря) нападай (тому кто стоит в стороне и должен пробежать через яму чтобы ударить показанного) прыгай (тому кто должен перелезть но может упасть в ров) \n(Просто рандомным костякам раздавал телепатией рандомные команды)",107036,null],[107046,"2026-07-11T16:30:06",32,"/roll d20+4",64123,null],[107048,"2026-07-11T16:30:24",5,"// мм прям приказы. хмм",107044,null],[107051,"2026-07-11T16:30:48",5,"/r 8d20",64123,null],[107057,"2026-07-11T16:32:34",32,"//в том и прикол ими явно кто-то руководит и они слишком тупы чтобы отличить того кто им приказывает.",107048,null],[107062,"2026-07-11T16:33:02",5,"Один скелет действительно замер на месте. Ещё на левом фланге один сам упал в яму.",64123,null],[107064,"2026-07-11T16:33:09",47,"/артур.не стоит",64123,null],[107067,"2026-07-11T16:33:35",47,"/ты без затраты чего либо на толпу скелетов использовал спелл приказ. Наглеешь",64123,null],[107068,"2026-07-11T16:33:56",47,"/я не спорю, что охота по максимум юзануть, но даже меня вымораживает",64123,null],[107069,"2026-07-11T16:34:16",47,"/сори",64123,null],[107073,"2026-07-11T16:34:37",5,"// ну да, один раз можно.",64123,null],[107074,"2026-07-11T16:35:03",32,"Скелет\nИнт\n6 (-2)\nМдр\n8 (-1)\n(Хар\n5 (-3)",107062,null],[107076,"2026-07-11T16:35:20",32,"Они реально тупые!",107074,null],[107081,"2026-07-11T16:35:52",47,"/скелеты управляются только тем, кто их воскресил\nИ не телепатией. А магией",64123,null],[107083,"2026-07-11T16:36:12",11,"// моя кукла умная.\n\nГде-то в другом месте обиделась одна фея",107076,null],[107084,"2026-07-11T16:36:18",32,"//Псионики некроманты тоже бывают",107081,null],[107086,"2026-07-11T16:36:34",5,"/r 5d20",64123,null],[107089,"2026-07-11T16:36:49",47,"Мастер, что на счёт управления с той стороны?",64123,null],[107091,"2026-07-11T16:37:09",5,"// вы не знаете. Но нежить явно пришла из-за масла",107089,null],[107093,"2026-07-11T16:37:18",47,"/",107037,null],[107094,"2026-07-11T16:37:20",47,"Я про это/",64123,null],[107098,"2026-07-11T16:37:59",32,"-а еще туман почти наверняка искусственный",107037,null],[107099,"2026-07-11T16:38:03",5,"/ восприятие с помехой",64123,null],[107100,"2026-07-11T16:38:12",47,"/r d20+6 скрываюсь в тумане и обхожу слегка по стороне чтобы увидеть что там в глубине. Ищу того, кто прячется от рыцарей. Тот кто руководит армией скелетов",64123,null],[107104,"2026-07-11T16:38:24",47,"/бля",64123,null],[107111,"2026-07-11T16:39:07",5,"Эльфу не получается отойти далеко. И в тумане ничего не разобрать. А вот его заметили. Один из скелетов справа весьма заинтересовался его рапирой.",64123,null],[107112,"2026-07-11T16:39:09",47,"Неожиданно для себя эльф наступает на что-то, что очень громко хрустит... Кажется это рука скелета!",64123,null],[107114,"2026-07-11T16:39:36",47,"Проклиная всё, что возможно эльф делает вздох",64123,null],[107115,"2026-07-11T16:39:38",5,"// так, щас скелеты",64123,null],[107116,"2026-07-11T16:39:42",47,"Всплеск действий",64123,null],[107117,"2026-07-11T16:39:52",5,"// угу давай",107116,null],[107118,"2026-07-11T16:39:56",47,"/r d20+6 попытка номер два",64123,null],[107122,"2026-07-11T16:41:00",47,"Эльф ускоряется. Смазанное движение и его закрывает туман. Рука скелета на которую он наступил лишь жалко щёлкает пальцами и издаёт громкий щелчок, пытавшись ухватить эльф. Он совершает быстрое движение и оказывается сильно ниже",64123,null],[107124,"2026-07-11T16:41:03",47,"/ход",64123,null],[107133,"2026-07-11T16:41:51",5,"// куда идёшь?",107122,null],[107136,"2026-07-11T16:41:57",47,"К центру",64123,null],[107140,"2026-07-11T16:42:15",5,"// нарисуй стрелку пж",64123,null],[107141,"2026-07-11T16:42:17",47,"Ищу гавнюка, что вызвал нежить",64123,null],[107142,"2026-07-11T16:42:30",47,"Ааа, мне сложно понять",64123,null],[107143,"2026-07-11T16:42:45",5,"ты",107137,null],[107145,"2026-07-11T16:43:04",47,"Как-то так",64123,null],[107153,"2026-07-11T16:44:53",32,"-Леда метай святую воду в монстра",64123,null],[107157,"2026-07-11T16:45:57",5,"// услышал",107145,null],[107161,"2026-07-11T16:46:59",5,"Эльф прыгает на ступень ниже, а затем на склон, сделанный жуком. Масло уже догорело, и он спокойно обходит лужи",64123,null],[107170,"2026-07-11T16:47:53",5,"// ход скелетов, погоди",64123,null],[107193,"2026-07-11T16:52:27",5,"С правого фланга скелеты вылезли из карьера. Один остался у спуска и ударил эльфа. Заприметивший рапиру также гонится за ним.",64123,null],[107196,"2026-07-11T16:52:34",5,"/r +4",64123,null],[107198,"2026-07-11T16:52:52",47,"/я же сделал так чтобы меня видно не было? По новой скрытность кинул /",64123,null],[107202,"2026-07-11T16:53:04",47,"Или по итогу всплеск действий в пустоту?",64123,null],[107204,"2026-07-11T16:53:27",5,"// а сорри. Думал ты смотришь вторым действием",107198,null],[107205,"2026-07-11T16:53:30",5,"// ок не видно",64123,null],[107207,"2026-07-11T16:53:44",5,"/r -1",64123,null],[107210,"2026-07-11T16:54:01",5,"Ищущий рапиру скелет также потерял тебя из виду",64123,null],[107220,"2026-07-11T16:56:20",5,"/r d20 лезет",64123,null],[107223,"2026-07-11T16:56:30",5,"/r d6",64123,null],[107239,"2026-07-11T16:58:39",5,"Высокий скелет атакует Айзека, а плоть от него отделяется и наносит ещё два удара",64123,null],[107241,"2026-07-11T16:59:05",5,"/r -d20+4\n/r -d20+5\n/r -d20+5",64123,null],[107244,"2026-07-11T16:59:33",5,"Но все атаки впустую",64123,null],[107245,"2026-07-11T16:59:54",5,"Скелет дварфа рядом с ним также атакует",64123,null],[107246,"2026-07-11T17:00:01",5,"/r -d20+5",64123,null],[107250,"2026-07-11T17:00:23",5,"/r d10+3",64123,null],[107252,"2026-07-11T17:00:36",5,"/r d20+3",64123,null],[107256,"2026-07-11T17:00:56",5,"Айзек держит концентрацию.",64123,null],[107257,"2026-07-11T17:00:58",5,"// леда",64123,null],[107260,"2026-07-11T17:01:17",32,"//что за концентрация?",107256,null],[107267,"2026-07-11T17:02:07",47,"/защита от добра и зла",64123,null],[107268,"2026-07-11T17:02:12",47,"/Из-за этого атаки с помехой",64123,null],[107281,"2026-07-11T17:04:01",5,"// ты за леду",107268,null],[107283,"2026-07-11T17:04:16",47,"Леда хмыкает и входя в ярость берёт ещё один бутылек со святой водой и бежит на монстра. Добежав до него он разбивает оба кувшина об голову монстра:\n- за жизнь! - раздаётся крик и попытка вдохновить остальных!",64123,null],[107287,"2026-07-11T17:05:11",5,"// кидай сразу урон воды",107283,null],[107288,"2026-07-11T17:05:15",5,"// и спас ловкости",64123,null],[107299,"2026-07-11T17:07:43",47,"/r +d20",64123,null],[107301,"2026-07-11T17:07:54",47,"/пхахахаха). Спас ловкости идеален",64123,null],[107303,"2026-07-11T17:08:02",47,"/а какой там?",107287,null],[107305,"2026-07-11T17:08:20",5,"// 4d8",64123,null],[107306,"2026-07-11T17:08:27",47,"/r 4d8",64123,null],[107312,"2026-07-11T17:09:31",5,"Пузырьки разбиваются, вода шипит на теле чудовища. \n\nЛеда теряет равновесие, падает ему под ноги, и катиться дальше вниз по очень удобному склону.",64123,null],[107314,"2026-07-11T17:09:59",5,"Таким образом он оказывается прямо у ног эльфа...",64123,null],[107323,"2026-07-11T17:11:39",5,"Обезьяна-нежить оборачивается, кусает катящегося варвара, а затем бьёт каждой из 3 лап.",64123,null],[107324,"2026-07-11T17:11:54",5,"/r -2 восприятие против эльфа",64123,null],[107327,"2026-07-11T17:12:23",5,"/r +d20+6\n/r +d20+6\n/r +d20+6\n/r +d20+6",64123,null],[107329,"2026-07-11T17:13:14",5,"/r d6+4\n/r 4d4+4",64123,null],[107332,"2026-07-11T17:13:23",47,"/Леде больно. Но он в ярости.",64123,null],[107333,"2026-07-11T17:13:26",5,"// 22 рубящего ему",64123,null],[107334,"2026-07-11T17:13:29",47,"11/",64123,null],[107336,"2026-07-11T17:13:36",32,"//ебаная жесть",107323,null],[107339,"2026-07-11T17:14:23",5,"Но чудовище ещё не забыло жука. Оно отворачивается и лезел дальше по склону вверх.",64123,null],[107340,"2026-07-11T17:14:33",5,"// можете провокации сделать",64123,null],[107344,"2026-07-11T17:15:23",5,"С жуком очень хочет познакомиться эта мордашка. Она нависла над ним и \"смотрит\"",64123,null],[107346,"2026-07-11T17:15:48",47,"/r d20+4 от Леды",64123,null],[107350,"2026-07-11T17:16:47",32,"//Видимо проклятие соматических компонентов  сработало",107344,null],[107353,"2026-07-11T17:17:21",5,"Солдат со щитом прикрывает жука и бьёт по монстру.\n\n— Держись за мной",64123,null],[107354,"2026-07-11T17:17:25",5,"/r +5",64123,null],[107357,"2026-07-11T17:17:44",5,"Айзек атакует выского скелета",64123,null],[107359,"2026-07-11T17:17:53",5,"/r +6\n/r +6",64123,null],[107361,"2026-07-11T17:18:05",5,"/r 2d8+8",64123,null],[107364,"2026-07-11T17:18:30",5,"И тот рассыпается от его булавы. Но только кости. Плоть теперь висит в воздухе сама.",64123,null],[107365,"2026-07-11T17:18:33",5,"// ход жука",64123,null],[107376,"2026-07-11T17:19:56",32,"Смазка в проход монстру под ноги и отступаю выше на укреп",64123,null],[107389,"2026-07-11T17:21:12",5,"// какой спас",107376,null],[107390,"2026-07-11T17:21:19",32,"13",107389,null],[107392,"2026-07-11T17:21:30",32,"Но у монстра провал",64123,null],[107393,"2026-07-11T17:21:35",32,"Знамение 7",64123,null],[107394,"2026-07-11T17:21:55",5,"// там упал ничком?",107392,null],[107395,"2026-07-11T17:22:04",5,"// провокация с помехой тогда",64123,null],[107396,"2026-07-11T17:22:15",5,"/r -d20+6",64123,null],[107399,"2026-07-11T17:22:34",32,"А разве?",107395,null],[107400,"2026-07-11T17:22:43",5,"// да. Реакции не отнимает",64123,null],[107402,"2026-07-11T17:23:07",5,"/r d6+4 полагаю",64123,null],[107411,"2026-07-11T17:25:10",32,"хруст хитина и раздался по округе. Но жук остался жив",107403,null],[107415,"2026-07-11T17:26:03",32,"Но благо дед жрец на верху насыпи и может подлечить",107411,null],[107418,"2026-07-11T17:26:28",5,"// ах да, спасибо что напомнил)",107415,null],[107425,"2026-07-11T17:28:01",47,"/спас концы от жука",64123,null],[107426,"2026-07-11T17:28:09",47,"/если правильно понимаю",64123,null],[107430,"2026-07-11T17:28:32",32,"//ну а нахрена я его сюда тянул!?",107425,null],[107436,"2026-07-11T17:29:12",47,"/кого его?",64123,null],[107439,"2026-07-11T17:29:27",32,"//квестодатель дед жрец",107436,null],[107442,"2026-07-11T17:29:55",47,"/нет забей",64123,null],[107444,"2026-07-11T17:30:07",47,"/я не про это. Нет",64123,null],[107447,"2026-07-11T17:30:17",47,"/я уже почитал, просто забудьте",64123,null],[107448,"2026-07-11T17:30:26",5,"// ходи",64123,null],[107450,"2026-07-11T17:30:46",47,"Двигаюсь дальше в центр тумана",64123,null],[107452,"2026-07-11T17:31:04",47,"В центр карьера",64123,null],[107454,"2026-07-11T17:31:20",5,"// за 35 футов проходишь 2 ступени в ход",107450,null],[107455,"2026-07-11T17:31:26",47,"Го/",64123,null],[107457,"2026-07-11T17:31:40",5,"// ты на конце третьей",64123,null],[107458,"2026-07-11T17:31:50",47,"Рывок. Ещё на 2/",64123,null],[107460,"2026-07-11T17:31:54",5,"Вокруг не видно никаких врагов. Видимо, все заняты.",64123,null],[107481,"2026-07-11T17:36:32",5,"Дед Алексий:\n\n— Ох, ранили твой панцирь, сынок. У меня ещё остались силы...\n\nСотворяет лечащее слово.",64123,null],[107482,"2026-07-11T17:36:39",5,"/r d4+3 хила",64123,null],[107488,"2026-07-11T17:37:25",47,"/а у нас лечение из 2024 . Лечащее слово 2д4, лечение РАН 2д8 и так далее",64123,null],[107492,"2026-07-11T17:37:42",47,"/если конечно, вы как мастер не решили иначе",64123,null],[107496,"2026-07-11T17:38:05",5,"// с каких пор? ничего не видел про это. По крайней мере на этом квесте по 14",107488,null],[107500,"2026-07-11T17:38:23",47,"/там где хб. Там же сказано и про спеллы. В том числе про лечащие",107496,null],[107503,"2026-07-11T17:38:37",5,"// ладно. Не на этом квесте",107500,null],[107505,"2026-07-11T17:39:26",5,"/r 2d20",64123,null],[107507,"2026-07-11T17:39:30",47,"/может ошибаюсь. Извините если что",64123,null],[107510,"2026-07-11T17:39:48",5,"/r 3d20",64123,null],[107522,"2026-07-11T17:41:27",5,"/r +3d20+4",64123,null],[107524,"2026-07-11T17:41:42",5,"/r +d20+4\n/r +d20+4\n/r +d20+4",64123,null],[107529,"2026-07-11T17:42:04",5,"/r 6d6+6",64123,null],[107531,"2026-07-11T17:42:12",5,"// 25 урона леде от 3 скелетов",64123,null],[107532,"2026-07-11T17:42:23",5,"Двое из них покатились дальше по склону",64123,null],[107533,"2026-07-11T17:42:36",5,"/r 2d20",64123,null],[107536,"2026-07-11T17:42:43",5,"/r d6+2",64123,null],[107539,"2026-07-11T17:43:07",5,"Солдат получил один тычок",64123,null],[107542,"2026-07-11T17:43:28",5,"Айзека окружили и бьют сразу с двух сторон",64123,null],[107544,"2026-07-11T17:43:36",5,"/r 2d20",64123,null],[107547,"2026-07-11T17:43:47",5,"/r",64123,null],[107550,"2026-07-11T17:44:02",47,"12/",107531,null],[107552,"2026-07-11T17:44:20",47,"И ему уже фигово",64123,null],[107553,"2026-07-11T17:44:21",5,"/r d4+3",64123,null],[107555,"2026-07-11T17:44:26",5,"/r",64123,null],[107559,"2026-07-11T17:44:56",5,"Бескостное море плоти оплетает Айзека, сжимая в объятьях смерти. Но он стоит прямо и держит концентрацию.",64123,null],[107561,"2026-07-11T17:45:02",5,"// ход леды",64123,null],[107569,"2026-07-11T17:45:47",47,"Монстр встает. Он хватает свою секиру и разбивает об неё святую воду:\n- Рраааа",64123,null],[107570,"2026-07-11T17:45:53",47,"/r +d20+4 тык",64123,null],[107572,"2026-07-11T17:46:00",47,"/r d12+4",64123,null],[107576,"2026-07-11T17:46:12",5,"// убил",107573,null],[107581,"2026-07-11T17:46:55",5,"// скелета рядом с собой. Движется?",107567,null],[107592,"2026-07-11T17:49:56",47,"Нет, стоит на месте",64123,null],[107603,"2026-07-11T17:51:41",47,"/ход",64123,null],[107613,"2026-07-11T17:54:50",5,"Зверь атакует бедного солдата. Тот прикрывается щитом, смотря на сбежавшего жука.",64123,null],[107614,"2026-07-11T17:55:09",5,"/r d20+6\n/r d20+6\n/r d20+6\n/r d20+6",64123,null],[107617,"2026-07-11T17:55:21",5,"/r 2d4+8",64123,null],[107624,"2026-07-11T17:56:08",5,"Доспехи пробиты когтями, из них льётся кровь. Но солдат дал клятву и мужественно держится перед лицом смерти.",64123,null],[107632,"2026-07-11T17:57:44",5,"Вокруг Айзека появляется вспышка света, ранящая нежить",64123,null],[107633,"2026-07-11T17:57:49",5,"/r 3d20",64123,null],[107638,"2026-07-11T17:58:15",5,"/r 3d6",64123,null],[107641,"2026-07-11T17:58:41",5,"/r +3",64123,null],[107643,"2026-07-11T17:58:55",5,"А сам он вырывается из объятий нежити",64123,null],[107644,"2026-07-11T17:58:57",5,"// ход жука",64123,null],[108318,"2026-07-11T20:45:47",32,"//Вокруг Айзека или на нем ещё есть нежить?",107643,null],[108332,"2026-07-11T20:48:17",5,"// 3 штуки",108318,null],[108352,"2026-07-11T20:51:51",32,"В любом случае. Кидаю святую воду в одного из мертвяков рядом с паладином и дополнительным действием активирую свиток накладывая щит веры на Айзека.",64123,null],[108353,"2026-07-11T20:52:12",5,"// вода сразу 2д6 урона",108352,null],[108357,"2026-07-11T20:52:27",5,"// кидаешь в скелета или в плоть?",64123,null],[108359,"2026-07-11T20:52:35",32,"/roll 2d6 \nВ плоть",64123,null],[108369,"2026-07-11T20:54:21",5,"// жива",64123,null],[108376,"2026-07-11T20:55:17",32,"/дед паладину поможет?",64123,null],[108377,"2026-07-11T20:55:23",32,"/в любом случае ход",64123,null],[108379,"2026-07-11T20:55:56",5,"// скажи деду",108376,null],[108380,"2026-07-11T20:56:04",47,"Иду дальше. В центр на 35 футов",64123,null],[108381,"2026-07-11T20:56:13",47,"К тому месту где был призрак",64123,null],[108384,"2026-07-11T20:56:27",5,"Призрак был на 3 ступени.",64123,null],[108385,"2026-07-11T20:56:33",5,"// к нему?",64123,null],[108386,"2026-07-11T20:56:54",47,"Да/",64123,null],[108398,"2026-07-11T21:00:25",5,"Эльф идёт по 4 ступени. В тумане наверху, на 3 ступени, проявился призрак.\n\n// пока не ходит",64123,null],[109476,"2026-07-12T11:57:19",47,"Заготовил действие. В скрыте ещё.",64123,null],[109478,"2026-07-12T11:57:23",47,"@elsio28 ход/",64123,null],[109509,"2026-07-12T12:36:51",5,"/r +1 призрак смотрит",64123,null],[109511,"2026-07-12T12:37:39",5,"// кинь скрытность ещё раз, та давно была",109476,null],[109512,"2026-07-12T12:37:45",5,"// скелетами позже похожу",64123,null],[110077,"2026-07-12T16:59:43",47,"/r d20+6 Боже памаги",64123,null],[110079,"2026-07-12T16:59:49",47,"/помог",64123,null],[110081,"2026-07-12T17:02:42",5,"Привидение неподвижно мерцает в воздухе",64123,null],[110084,"2026-07-12T17:06:14",5,"Дед Алексий сидит на насыпи и что-то шепчет, держась за священный символ в руке. От него исходит эманация, дающая окружающим силы и надежду на победу.\n\n// заклинание Маяк надежды",64123,null],[110088,"2026-07-12T17:08:18",5,"Воины ордена позади жука продолжают сражаться. Нежить оттеснила их на вторую линию насыпей, и там ход боя значительно замедлился. Лишь иногда мерцают вспышки двуручных мечей рыцарей, рассекающих нежить.",64123,null],[110090,"2026-07-12T17:11:55",5,"Нежить взяла жреца Айзека в кольцо и атакует. Вокруг него 2 скелета с мечами и летающая плоть.\n\nАйзек из последних сил закрывается щитом и шепчет молитву. Вокруг него сияет ещё два магических щита.",64123,null],[110091,"2026-07-12T17:15:38",5,"/r +4\n/r +4\n/r +5\n/r +5",64123,null],[110094,"2026-07-12T17:16:22",5,"/r d6+2\n/r d4+3",64123,null],[110096,"2026-07-12T17:16:36",5,"/r 2d20",64123,null],[110098,"2026-07-12T17:17:44",5,"Бескостная плоть обволакивает Айзека вновь, один из магических щитов вокруг него погасает.\n\n// потерял защиту от зла",64123,null],[110099,"2026-07-12T17:18:28",5,"/r +5\n/r +4",64123,null],[110109,"2026-07-12T17:22:53",5,"/r d10+3",64123,null],[110113,"2026-07-12T17:23:46",5,"Доспехи солдата со щитом пробиты, из них течёт кровь. Но он ещё стоит на ногах, лишь немного отступая под ударами скелетов.",64123,null],[110116,"2026-07-12T17:24:07",5,"// ход Леды @Xaosick @cirson ходите за него",64123,null],[110125,"2026-07-12T17:27:42",5,"Скелеты около Леды все ещё кубарем катятся вниз по склону",64123,null],[110220,"2026-07-12T17:48:45",47,"Леда бежит к монстру и рубит его топором",64123,null],[110221,"2026-07-12T17:48:48",47,"/r +d20+4",64123,null],[110226,"2026-07-12T17:49:01",5,"// и спас ловкости",64123,null],[110229,"2026-07-12T17:49:17",47,"/r +d20",64123,null],[110232,"2026-07-12T17:49:31",47,"/леде будто бы могло и почаще что-то подобное падать",64123,null],[110248,"2026-07-12T17:51:53",5,"Леда залез наверх по склону, но промахнулся алебардой по огромному мностру перед ним.",64123,null],[110250,"2026-07-12T17:52:02",47,"/лох",64123,null],[110252,"2026-07-12T17:52:16",5,"// у него кд 11 кстати",64123,null],[110256,"2026-07-12T17:52:53",47,"/лохерище",64123,null],[110258,"2026-07-12T17:53:06",47,"/ладно.юмора 09",64123,null],[110262,"2026-07-12T17:53:34",5,"Уже потухшая огромная обезьяна наваливается на едва живого воина и дерёт когтями.",64123,null],[110265,"2026-07-12T17:54:02",5,"/r 3d20",64123,null],[110274,"2026-07-12T17:55:01",5,"На земле лежит бездыханный труп, а от обезьяны отваливается одна лапа и придавливает его.\n\nСамо чудище лезет по насыпям к жуку.",64123,null],[110277,"2026-07-12T17:55:07",5,"/r +1",64123,null],[110283,"2026-07-12T17:55:30",5,"И застревает ногой в одной из ям.",64123,null],[110302,"2026-07-12T17:57:54",5,"/r +6",64123,null],[110305,"2026-07-12T17:58:01",5,"/r d6+3",64123,null],[110309,"2026-07-12T17:58:37",5,"Айзек мощным ударом булавы расколол черепушку скелета, зашедшего сзади.",64123,null],[110313,"2026-07-12T17:58:48",5,"// @Xaosick твой ход",64123,null],[110314,"2026-07-12T17:58:55",5,".",110088,null],[110659,"2026-07-12T18:47:44",32,"Я кидаю святую воду в Айзека. Чтобы уничтожить плоть и все что рядом брызгами задеть.\n-Айзек отступай лучше оставь мелочь мне у меня волна грома. \n-Леда беги ко мне! Ты нужен тут",64123,null],[110664,"2026-07-12T18:48:33",32,"/roll 2d6",64123,null],[110666,"2026-07-12T18:48:36",5,"// урон по плоти 2д6 сразу. По другому 1д6",110659,null],[110670,"2026-07-12T18:48:55",32,"/roll d6",64123,null],[110674,"2026-07-12T18:49:16",32,"(ну лучше чем ничего)",110671,null],[110679,"2026-07-12T18:50:06",5,"// можешь бонусным действием обратиться к другим рыцарям за помощью (выступление)",64123,null],[110688,"2026-07-12T18:50:58",32,"(так же я держу концентрацию на щит веры Айзека)",64123,null],[110700,"2026-07-12T18:52:09",32,"(стрелкам)-поддержите отступления Айзека! Он должен отойти ко мне.",64123,null],[110705,"2026-07-12T18:52:20",32,"/roll d20+4",64123,null],[110708,"2026-07-12T18:52:45",32,"Голос телепатический жука звучал уже как паника",110706,null],[110711,"2026-07-12T18:53:01",5,"Один из арбалетчиков на момент обернулся в твою сторону и выстрелил в тающую от святой воды плоть на Айзеке",64123,null],[110712,"2026-07-12T18:53:08",5,"/r +7",64123,null],[110715,"2026-07-12T18:53:19",5,"/r d10+3",64123,null],[110721,"2026-07-12T18:53:55",32,"//плоть настолько живучая ей больше тридцати урона внесли точно",64123,null],[110722,"2026-07-12T18:53:56",5,"Болт пробил оставшиеся куски плоти и они упали кучей на землю.",64123,null],[110724,"2026-07-12T18:54:04",5,"// ровно 30",110721,null],[110739,"2026-07-12T18:55:46",5,"// ход @cirson",64123,null],[110787,"2026-07-12T19:01:05",32,"https://youtu.be/qq2jd-qSwMQ?is=61KkV9zyCGu2D_RM",64123,null],[110790,"2026-07-12T19:01:18",32,"Кстати отлично под тему боя пойдет",64123,null],[110796,"2026-07-12T19:01:56",5,"Дед Алексий сидит на насыпи, он сгорбился и побледнел. Удержание концентрации даётся нелегко.",64123,null],[110798,"2026-07-12T19:02:18",32,"//деду нериальная уважуха",110796,null],[110803,"2026-07-12T19:02:49",5,"Рыцарь Лансель где-то сзади использовал наложение рук на тяжело раненного солдата. Все раны зажили и он снова встал, готовый к бою.",64123,null],[110811,"2026-07-12T19:03:50",5,"// поскольу эльф фактически в отдельной боевой сцене, похожу скелетами",64123,null],[110834,"2026-07-12T19:06:09",5,"Скелеты попали в лабиринты насыпей, дальше двигаться непросто",64123,null],[110835,"2026-07-12T19:06:12",5,"/r 3d20",64123,null],[110840,"2026-07-12T19:07:28",5,"Лишь один добрался до три-крина и замахнулся коротким мечом",64123,null],[110844,"2026-07-12T19:07:36",5,"/r +4",64123,null],[110846,"2026-07-12T19:07:38",32,"Если полезет по склонам те могут буквально обвалиться",64123,null],[110847,"2026-07-12T19:07:49",32,"Попал у меня нет щита",110845,null],[110849,"2026-07-12T19:07:54",5,"// двое обвалились",110846,null],[110851,"2026-07-12T19:08:03",5,"// где-то валяются",64123,null],[110852,"2026-07-12T19:08:08",32,"//склоны насыпи",110849,null],[110854,"2026-07-12T19:08:24",5,"// будут кидать силу чтобы выбраться",64123,null],[110855,"2026-07-12T19:08:32",32,"//сделано буквально из говна😁",64123,null],[110857,"2026-07-12T19:08:38",5,"/r d6+2",64123,null],[110863,"2026-07-12T19:09:15",32,"Ну если бы не дед тут бы и закончилось а так у меня один ХП остался",110858,null],[110868,"2026-07-12T19:10:00",32,"/roll d20-1\n(Концентрация)",64123,null],[110870,"2026-07-12T19:10:08",32,"Пизда щиту веры",64123,null],[110874,"2026-07-12T19:10:28",5,"// 1 хп от чего?",110863,null],[110875,"2026-07-12T19:10:37",32,"//а можно мастерское вдохновение на переброс",110869,null],[110879,"2026-07-12T19:11:02",5,"// можешь сейчас помолиться, если хорошо то да",64123,null],[110890,"2026-07-12T19:12:58",32,"//вспоминает портрет своего начальства Нив-Миззета.\nО великий ,сильный и прекрасный Нив-Миззет, спаси и сохрани!",110879,null],[110892,"2026-07-12T19:13:10",5,"// норм, перебрасывай)",64123,null],[110894,"2026-07-12T19:13:42",32,"/roll d20-1",64123,null],[110902,"2026-07-12T19:14:10",32,"//Видимо мысленные обещания хождения в тренажерный зал помогли",64123,null],[110914,"2026-07-12T19:14:47",5,"/r +4 по айзеку",64123,null],[110917,"2026-07-12T19:14:57",5,"/r +5",64123,null],[110923,"2026-07-12T19:15:21",32,"//а сколько у него КД?",110919,null],[110927,"2026-07-12T19:15:59",5,"Скелет атаковал Айзека, но попал в воздух. Тот ловко повернулся и ударом щита столкнул неудачника в карьер. Там нежить разлетелась на кости",64123,null],[110928,"2026-07-12T19:16:07",5,"// сейчас 18",110923,null],[110933,"2026-07-12T19:16:41",5,"Теперь Айзек свободен от окружения и направляется к укреплениям",64123,null],[110941,"2026-07-12T19:17:36",5,"// леда",64123,null],[110943,"2026-07-12T19:18:09",32,"Кидает святую воду в бибезяна",110941,null],[110945,"2026-07-12T19:18:25",32,"И сближается если у него есть атаки на бонусное",64123,null],[110947,"2026-07-12T19:18:33",5,"// не помню, осталась ли вода у него, но окей",64123,null],[110948,"2026-07-12T19:18:39",5,"// давай урон",64123,null],[110949,"2026-07-12T19:18:44",32,"Последеяя",110947,null],[110952,"2026-07-12T19:18:59",32,"/roll 2d6",110948,null],[110957,"2026-07-12T19:19:29",5,"Вода больно жжётся, протекая внутрь и задевая внутренности",64123,null],[110961,"2026-07-12T19:20:13",5,"Чудовище замерло на месте. Он выискивает жука среди насыпей.",64123,null],[110962,"2026-07-12T19:20:22",5,"//  ты можешь высунуться или нет",110952,null],[110963,"2026-07-12T19:20:32",5,"// иначе он тебя потерял",64123,null],[110972,"2026-07-12T19:21:55",32,"(Я на насыпи видимый меня разве что скелет закрывает да согнуло от раны в боку и кое как на мате и молитвах удерживаемой концентрации",110962,null],[110976,"2026-07-12T19:22:21",5,"// привлекаешь его внимание или нет?",64123,null],[110978,"2026-07-12T19:22:41",32,"Так что я не спрятался пусть и на два этажа выше.\n//У него спас от смазки кстати",110963,null],[110982,"2026-07-12T19:23:22",5,"/r +1",64123,null],[110984,"2026-07-12T19:23:59",32,"(сознание жука плывет но увидев как монстр переводит свой плотоядный взгляд на других я решаю выйти на телепатическую связь) \n-Что ты за убожество криворукого химеролога!?",110976,null],[110995,"2026-07-12T19:25:13",5,"Монстр упал, услышал твоё послание, но вряд ли понял. Такие твари обычно не разговаривают. Тем не менее он ползком лезет к тебе\n\n// рывок",64123,null],[110997,"2026-07-12T19:25:19",5,"/r +1",64123,null],[110999,"2026-07-12T19:25:35",5,"И закапывается в одну из насыпей",64123,null],[111012,"2026-07-12T19:27:51",5,"Айзек лезет по насыпям\n\n/r +0",64123,null],[111013,"2026-07-12T19:27:55",5,"/roll@roll_bot",64123,null],[111020,"2026-07-12T19:29:22",5,"Залез на одну и наложил благословение на себя, жука и Леду.\n\n— Аскелатор, дай нам сил сокрушить врагов порядка!",64123,null],[111021,"2026-07-12T19:29:27",5,"// ходи жук",64123,null],[111027,"2026-07-12T19:31:00",32,"Отлично монстр свалился в яму? его там и закопаю лепкой сдвигаю стену самого окопа закапывая монстра и за одно свалив часть насыпи насыпная ещё горку земли сверху",110999,null],[111028,"2026-07-12T19:31:18",32,"Да безумно сложная задача",64123,null],[111032,"2026-07-12T19:31:46",32,"/roll d20+5+d4 \nАркана на обвал насыпи",64123,null],[111035,"2026-07-12T19:32:11",5,"// не, он слишком большой",111027,null],[111036,"2026-07-12T19:32:13",32,"Просто кучка земли упала в яму и нихрена",64123,null],[111037,"2026-07-12T19:32:30",5,"Он врезался в насыпь и обсыпан землёй",64123,null],[111040,"2026-07-12T19:33:45",32,"Ну что же у Айзека есть идеальная возможность атаковать",111037,null],[111042,"2026-07-12T19:34:18",5,"// конец хода?",64123,null],[111064,"2026-07-12T19:39:13",32,"Я не могу ничего кроме как позвать ещё раз стрелков но отвлекать ребят страшно у них ситуация не лучше",111042,null],[111065,"2026-07-12T19:39:21",5,"// окей",64123,null],[111066,"2026-07-12T19:39:29",32,"Тогда конец",64123,null],[111068,"2026-07-12T19:40:32",32,"//потому что если бы у них ситуация была лучше они бы и сами помогли",111064,null],[111080,"2026-07-12T19:43:42",5,"/r 2d20",64123,null],[111082,"2026-07-12T19:43:50",5,"/r d20",64123,null],[111085,"2026-07-12T19:44:26",5,"Один из обычных скелетов выбрался и успешно пролез по насыпям, подобравшись к сидящему на земле деду",64123,null],[111086,"2026-07-12T19:44:39",5,"Скелет у жука атакует его",64123,null],[111088,"2026-07-12T19:44:45",5,"/r +4",64123,null],[111103,"2026-07-12T19:46:26",32,"(ещё успею отстреляться)",111089,null],[111107,"2026-07-12T19:47:29",5,"//Леда",111103,null],[111112,"2026-07-12T19:49:10",32,"Леда нападает на гигантского обезьяна с яростью и что там ещё для бонусного урона он использовал? А громовой клинок обычная атака и урон из-за движения",111107,null],[111115,"2026-07-12T19:50:11",5,"// спас от смазки",111112,null],[111126,"2026-07-12T19:51:37",47,"/я отошёл на 40 минут, ну что же такое",64123,null],[111129,"2026-07-12T19:51:51",5,"// у тебя свои ходы с призраком",111126,null],[111130,"2026-07-12T19:51:51",32,"/roll 2d20H-1",111115,null],[111132,"2026-07-12T19:52:00",47,"/r +d20+8 по призраку серебрянной стрелой обмазанной глиной со святой водой",64123,null],[111135,"2026-07-12T19:52:09",47,"/r d20+8 переброс 8",64123,null],[111137,"2026-07-12T19:52:15",32,"Он упал и потом встал но все равно дойдет",111131,null],[111139,"2026-07-12T19:52:30",47,"/r d4+4 как понимаю. Тут же наступает мой ход",64123,null],[111141,"2026-07-12T19:52:43",47,"/r +d20+8 с юзом рыцаря соламнии",64123,null],[111143,"2026-07-12T19:52:52",47,"/r d20+8 за счёт эльф точности",64123,null],[111146,"2026-07-12T19:53:01",47,"/16 .  Пробил?",64123,null],[111148,"2026-07-12T19:53:25",47,"/r d8+d4+4",64123,null],[111154,"2026-07-12T19:54:03",47,"/эльф делает два выстрела целясь в самое светлое место призрака и в голову. Обе стрелы чётко попадают в него и оставляют за собой едва светящиеся следы",64123,null],[111155,"2026-07-12T19:54:42",5,"// щас пока с призраком несколько ходов будет",64123,null],[111156,"2026-07-12T19:54:44",47,"Бросаю лук, достаю рапиру обмазанную глиной со святой водой",64123,null],[111160,"2026-07-12T19:55:40",47,"Подошёл вплотную к нему и говорю:\n- Я не знаю кто ты, но ты зло. И я тебя уничтожу - чётко чеканит свои слова эльф оказываясь рядом. Его голос наполнен уверенностью в своей правоте",64123,null],[111163,"2026-07-12T19:57:09",5,"Призрак вьётся над костями в целой броне, рядом со входом к тайнику.\n\n— МОЁ-О-О! — раздаётся в голове у эльфа",64123,null],[111166,"2026-07-12T19:58:13",5,"/r +5",64123,null],[111168,"2026-07-12T19:58:31",5,"// не пробил, ходи эльф",64123,null],[111170,"2026-07-12T19:59:11",5,"// можешь описать как не дал коснуться с ебя",111160,null],[111173,"2026-07-12T20:00:00",47,"Эльф выставляет рапиру и она блестит серебром на солнце, луч которого пробился сквозь туман, что слепит призрака!",64123,null],[111175,"2026-07-12T20:00:16",47,"/r d20+6 атака... Без преимущества. Боль",64123,null],[111177,"2026-07-12T20:00:28",47,"/r d8+4 клинок мелькает",64123,null],[111179,"2026-07-12T20:00:39",47,"Во вторую руку свободным действием кинжал",64123,null],[111180,"2026-07-12T20:00:45",47,"/r d20+6",64123,null],[111182,"2026-07-12T20:00:50",47,"/r d4",64123,null],[111193,"2026-07-12T20:03:17",47,"Эльф совершает выпад рапирой, а после сделав разворот на коленях вонзает кинжал, так же обмазанный глиной в низ призрака. Рованных ран всё больше:\n- У тебя нечисть последний шанс искупить свою нечистивую душу! Сдайся! - в лицо выплёвывает слова эльф. Он уверен, что нежить не сдастся, но в ордене чётко сказано, любой противник, кроме того, что имеет метку, имеет шанс на пощаду",64123,null],[111196,"2026-07-12T20:03:33",5,"// кинжал обмазать не было времени",64123,null],[111203,"2026-07-12T20:04:29",5,"/r +5 касается",64123,null],[111207,"2026-07-12T20:04:49",5,"// окей ходи опять)",64123,null],[111230,"2026-07-12T20:08:36",47,"/обидно(",111196,null],[111233,"2026-07-12T20:08:52",47,"/Так-то там наш маг не знаю сколько времени копал, а тут 1 минуты не хватило(",64123,null],[111235,"2026-07-12T20:09:03",47,"/r d20+6 рапирой",64123,null],[111237,"2026-07-12T20:09:08",47,"/r d8+4",64123,null],[111239,"2026-07-12T20:09:34",47,"Вновь увернувшись эльф продолжил сражаться молча. Смысл разговарить с безумным существом?",64123,null],[111244,"2026-07-12T20:10:13",5,"Может и безумный, но призрак тебе отвечает.\n\n— Уходииии! Сгинь!",64123,null],[111248,"2026-07-12T20:11:01",47,"Смотрю призраку в глаза, хочу понять, почему он такой, какой есть?",64123,null],[111250,"2026-07-12T20:11:27",5,"Мерцающий мужской силуэт",111248,null],[111253,"2026-07-12T20:11:48",5,"// ход?",64123,null],[111256,"2026-07-12T20:12:39",47,"/да. Я бы как игрок вопросы позадавал, но как эльф... Только уничтожить",64123,null],[111258,"2026-07-12T20:12:52",5,"// призраку) удачи",64123,null],[111259,"2026-07-12T20:12:54",5,"/r +5",64123,null],[111262,"2026-07-12T20:13:06",5,"// ?",64123,null],[111263,"2026-07-12T20:13:12",47,"/щита нет, попал",64123,null],[111264,"2026-07-12T20:13:29",5,"/r 3d6+3 некротики",64123,null],[111268,"2026-07-12T20:13:36",47,"/больно таки",64123,null],[111270,"2026-07-12T20:13:56",5,"// помнится вы всей толпой от него бежали)",64123,null],[111272,"2026-07-12T20:14:37",47,"/ну мне не жалко перса этого. Он должен уничтожить нежить. Он типо рыцарь ебанутый",64123,null],[111274,"2026-07-12T20:14:54",47,"/наполовину с наёмным убийцей",64123,null],[111276,"2026-07-12T20:15:09",47,"/r d10+2 бонусным действием.",64123,null],[111281,"2026-07-12T20:15:50",47,"Прям на глазах призрака эльф мелькает прямо перед ним и... Возвращается на секунду назад. Удар призрака смазан и ранит не так больно!",64123,null],[111282,"2026-07-12T20:16:00",47,"/как должен был",64123,null],[111284,"2026-07-12T20:16:05",5,"// это второе дыхание?",64123,null],[111286,"2026-07-12T20:16:08",47,"/да",64123,null],[111287,"2026-07-12T20:16:11",5,"// твой ход",64123,null],[111293,"2026-07-12T20:16:38",47,"Из подсумка достаётся последняя бутылка со святой водой.... Я её поливаю на себя",64123,null],[111298,"2026-07-12T20:17:15",5,"// какой эффект ожидаешь?",64123,null],[111301,"2026-07-12T20:17:28",47,"/ну тип защита",64123,null],[111303,"2026-07-12T20:17:42",47,"/не знаю",64123,null],[111304,"2026-07-12T20:17:46",5,"// ок",64123,null],[111305,"2026-07-12T20:17:49",47,"/если на него урон, обратно - защита",64123,null],[111306,"2026-07-12T20:17:56",32,"Эффект шипов",64123,null],[111307,"2026-07-12T20:18:06",47,"/я сдохну. Раньше чем шипы сработают",64123,null],[111309,"2026-07-12T20:18:53",5,"Привидение вьётся вокруг тебя, а затем начинает орать. Прямо в твоей голове.",64123,null],[111311,"2026-07-12T20:19:00",5,"// мудрость сл 13",64123,null],[111315,"2026-07-12T20:19:19",47,"/r d20+2 Боже паси",64123,null],[111318,"2026-07-12T20:19:31",5,"// опиши и твой ход",64123,null],[111320,"2026-07-12T20:19:55",47,"- И да защитит меня Латандер. И да защитит меня Латандер..- шепчет всё громче и громче эльф",64123,null],[111321,"2026-07-12T20:20:12",47,"Пока не перебивает этот крик. Голова будто проясняется",64123,null],[111324,"2026-07-12T20:20:50",47,"Эльф делает резкий шаг прямо в призрака зажимая его в своих объятиях (что кинуть?)",64123,null],[111326,"2026-07-12T20:21:35",5,"// давай акробатику",64123,null],[111329,"2026-07-12T20:21:58",47,"/r d20+6",64123,null],[111332,"2026-07-12T20:22:11",5,"// урон воды 2д6",64123,null],[111334,"2026-07-12T20:22:24",47,"/r 2d6",64123,null],[111342,"2026-07-12T20:23:39",5,"Призрак как будто горит святым пламенем изнутри, он отлетает от тебя и касается вновь",64123,null],[111343,"2026-07-12T20:23:42",5,"/r +5",64123,null],[111347,"2026-07-12T20:23:55",5,"/r 1d6",64123,null],[111349,"2026-07-12T20:24:04",32,"А разве это не захват?",111330,null],[111351,"2026-07-12T20:24:18",5,"// призрака? ну нет",64123,null],[111352,"2026-07-12T20:24:37",32,"Святая вода не пропускает как и тряпка с водой",111351,null],[111353,"2026-07-12T20:24:52",5,"//он вбежал внутрь призрака и обжег его",64123,null],[111356,"2026-07-12T20:25:05",5,"// ходи",111334,null],[111370,"2026-07-12T20:27:01",47,"/это что?",111347,null],[111374,"2026-07-12T20:27:18",5,"Призрак обжёгся об тебя, когда касался",64123,null],[111375,"2026-07-12T20:27:29",47,"/а, прикольно",64123,null],[111380,"2026-07-12T20:27:49",47,"Беру действием щит и бегу с поднятым щитом на призрака!",64123,null],[111382,"2026-07-12T20:28:06",5,"// опять входишь внутрь?",64123,null],[111383,"2026-07-12T20:28:08",47,"/да",64123,null],[111385,"2026-07-12T20:28:17",5,"// акробатика",64123,null],[111387,"2026-07-12T20:28:23",47,"/r d20+6",64123,null],[111389,"2026-07-12T20:28:27",47,"Опа/",64123,null],[111392,"2026-07-12T20:28:47",5,"Призрак догадался, что ты жжёшься и увернулся, рассеявшись прямо перед тобой",64123,null],[111396,"2026-07-12T20:29:43",5,"/r +5",64123,null],[111401,"2026-07-12T20:30:10",5,"/r d6",64123,null],[111405,"2026-07-12T20:30:26",5,"// опиши, кеак призрак коснулся тебя, а затем окончательно рассеялся",64123,null],[111407,"2026-07-12T20:30:41",47,"/умер то есть",64123,null],[111408,"2026-07-12T20:30:44",47,"/?",64123,null],[111414,"2026-07-12T20:31:41",47,"- Латандер, забери душу того, кто должен очищен быть, дабы не мучать других - навстречу ладони призрака эльф сам двинулся с открытой грудью вперёд!",64123,null],[111422,"2026-07-12T20:34:18",5,"Эльф вошёл прямо в призрака, и тот испарился.",64123,null],[111423,"2026-07-12T20:34:26",5,"// а мы переходим к битве наверху",64123,null],[111424,"2026-07-12T20:35:07",5,"// @Xaosick Леда лезет по насыпям за  монстром, ещё спас ловкости",64123,null],[111425,"2026-07-12T20:35:13",47,"/вошёл",64123,null],[111501,"2026-07-12T21:02:50",32,"/roll d20-1",111424,null],[111511,"2026-07-12T21:06:17",32,"//без комментариев",111502,null],[111513,"2026-07-12T21:06:47",5,"// позже буду",64123,null],[111529,"2026-07-12T21:16:17",5,"Леда провалился в одну из ям. Он смотрит наверх, надеясь, что его не засыпят",111502,null],[111535,"2026-07-12T21:21:23",5,"Около деда Алексия появился Глорир, его меч сияет, он размахивается по скелету",64123,null],[111537,"2026-07-12T21:21:36",5,"/r +6",64123,null],[111539,"2026-07-12T21:21:43",5,"/r d10+3",64123,null],[111541,"2026-07-12T21:22:00",5,"И разбивает того на куски",64123,null],[111542,"2026-07-12T21:22:35",5,"— Нежить иссякает, хвала Аскелатору! Вперёд, воины!",64123,null],[111543,"2026-07-12T21:23:18",32,"Даже жук поддержал это подняв пустую верхнюю руку",64123,null],[111544,"2026-07-12T21:23:44",5,"Однако, обезьяна-нежить ещё жива. Она пытается вылезти из кучи земли",64123,null],[111545,"2026-07-12T21:24:29",5,"/roll@roll_bot",64123,null],[111548,"2026-07-12T21:25:04",5,"Тварь выбирается и атакует Леду в яме",64123,null],[111551,"2026-07-12T21:25:21",5,"/r +6\n/r +6\n/r +6",64123,null],[111553,"2026-07-12T21:25:38",5,"/r d6+4\n/r d4+4\n/r d4+4",64123,null],[111555,"2026-07-12T21:25:49",5,"// 20 физ урона",64123,null],[111558,"2026-07-12T21:26:48",32,"/Это с каменной кожей?",64123,null],[111560,"2026-07-12T21:27:04",5,"// это до вычета сопротивления",64123,null],[111561,"2026-07-12T21:27:13",5,"// 10 за ярость",64123,null],[111563,"2026-07-12T21:27:41",5,"// он жив?",64123,null],[111566,"2026-07-12T21:29:29",5,"Айзек спрыгивает прямо к раненому варвару и касается его плеча.\n\n— Твоя служба ещё не окончена, воин!",64123,null],[111569,"2026-07-12T21:29:56",5,"// лечение ран, отхил на 11 хп из-за ауры",64123,null],[111570,"2026-07-12T21:30:02",5,"// ход жука",64123,null],[111591,"2026-07-12T21:50:20",32,"//а скелет передо мной?",111566,null],[111592,"2026-07-12T21:50:31",5,"// да",64123,null],[111595,"2026-07-12T21:51:17",32,"И где монстр скелет и могу я стать как-то чтобы не спровоцировать атаку скелета и ударить монстрика громовой волной? И скелета и желательно не попадая по остальным",64123,null],[111596,"2026-07-12T21:51:38",5,"// можешь",111595,null],[111597,"2026-07-12T21:51:42",5,"// по скелету нет",64123,null],[111598,"2026-07-12T21:51:45",5,"// местность тяжелая",64123,null],[111599,"2026-07-12T21:51:51",5,"// только одного",64123,null],[111600,"2026-07-12T21:52:12",32,"Ох тогда громовая волна в монстра",111599,null],[111602,"2026-07-12T21:52:20",32,"Спас тело 13",64123,null],[111605,"2026-07-12T21:52:31",5,"/r +3",64123,null],[111607,"2026-07-12T21:52:34",32,"/roll 2d8",64123,null],[111609,"2026-07-12T21:52:42",5,"// убивай)",64123,null],[111614,"2026-07-12T21:54:40",32,"Громовая волна прокатилась по полю боя. Грохот от применения магии стоял дичайший. Несмотря на то что монстр был крепок волна звуковой энергии впечатала чудовище в троншею и разорвало его на части. Маг жук же с принятием неизбежного смотрел на заносяшего свой меч скелета воина",111609,null],[111622,"2026-07-12T21:55:50",5,"Одна из конечностей монстра оторвалась и сбила череп скелета, вылезающего из ямы",64123,null],[111623,"2026-07-12T21:56:02",5,"А скелет у жука заносит меч",64123,null],[111626,"2026-07-12T21:56:27",5,"/r +4",64123,null],[111630,"2026-07-12T21:58:17",32,"Спасибо великому Нив-Миззету. Клинок оставил ещё одну полосу на хитине но не пробил его.\n(Кд15)",111627,null],[111631,"2026-07-12T21:58:36",5,"/r +3",64123,null],[111633,"2026-07-12T21:58:41",5,"/r",64123,null],[111635,"2026-07-12T21:59:04",5,"Высокий скелет с двуручём выбрался из завала, но упал в другую яму",64123,null],[111636,"2026-07-12T21:59:07",5,"// ход леды",64123,null],[111637,"2026-07-12T22:00:10",32,"Если может двинется к жуку. Если к жуку надо лезть двинется к упавшему с двуручником чтобы добить",64123,null],[111638,"2026-07-12T22:00:33",5,"// спас ловкости в любом случае",64123,null],[111639,"2026-07-12T22:00:42",32,"Тогда к жуку",111638,null],[111640,"2026-07-12T22:00:48",5,"// кидай",64123,null],[111641,"2026-07-12T22:00:53",32,"/roll d20-1",64123,null],[111643,"2026-07-12T22:00:57",5,"// прошёл",64123,null],[111644,"2026-07-12T22:01:14",32,"Как там атаковать?",64123,null],[111645,"2026-07-12T22:01:40",5,"// допусти +5 и преимущество от безрассудной",64123,null],[111650,"2026-07-12T22:03:08",32,"/roll 2d20H+5",64123,null],[111654,"2026-07-12T22:03:45",32,"/roll d12+2+2",64123,null],[111657,"2026-07-12T22:04:25",5,"// убил",64123,null],[111661,"2026-07-12T22:06:26",5,"Позади бой понемногу стихает, с левого фланга появляется Лансель и ещё два воина.\n\nАрбалетчики побросали оружие и перевязывают раненых.\n\nГлорир ловко проходит по насыпям к упавшему скелету-воителя и заносит меч.",64123,null],[111664,"2026-07-12T22:07:17",5,"/r +6",64123,null],[111669,"2026-07-12T22:08:25",5,"/r d10+3+3d8",64123,null],[111673,"2026-07-12T22:09:34",32,"Ну что же жук видимо себя мантией замотал и двинет ассистировать стрелкам так как сам в медицине смыслит",111661,null],[111675,"2026-07-12T22:10:21",5,"Меч сияет и скелет разбивается на куски.\n\n— Такова участь нежити!",111670,null],[111681,"2026-07-12T22:11:06",5,"// конец ини",64123,null],[111684,"2026-07-12T22:11:36",5,"Боец благодарит тебя за помощь в перевязке",111673,null],[111685,"2026-07-12T22:11:43",32,"//ебаный пиздец. Еле вытянули",111681,null],[111692,"2026-07-12T22:13:13",5,"// понравилось?",111685,null],[111693,"2026-07-12T22:13:16",32,"(да жук сам выглядит очень потрепаным. Рана на боку истекает гемолимфой сам жук имеет несколько крупных сколов на панцире но он жив а значит может работать на благо улья. Тут немного не то но примерно",111684,null],[111695,"2026-07-12T22:13:25",32,"//Конечно да!",111692,null],[111698,"2026-07-12T22:14:07",5,"Дед Алексий лежит на боку на склоне. Он тяжело дышит, хоть ран и нет.",64123,null],[111702,"2026-07-12T22:14:34",5,"Лансель подходит к Айзеку и хлопает по плечу. Тот вытирает кровь",64123,null],[111705,"2026-07-12T22:15:08",32,"Подойти к деду и дать руку просто одну из малых рук поддерживая старого но все ещё сильного воина",111698,null],[111706,"2026-07-12T22:16:27",5,"— Спасибо, сынок. Я справлюсь... всего лишь устал",64123,null],[111708,"2026-07-12T22:16:41",32,"Отломил кусок разбитого хитина там будет все равно линька и положил на грудь. Оказывая уважение в ритуальном жесте три-крин",64123,null],[111712,"2026-07-12T22:17:42",5,"Глорир подходит к склону и смотрит вниз.\n\n— Три-крин, как там тебя... Леда! Отличный план, и отличная битва! Но что дальше?  Что думаете?",64123,null],[111717,"2026-07-12T22:19:07",32,"(только Глориру привлекая его внимание)-Дальше надо оказать последние почести.",111712,null],[111718,"2026-07-12T22:19:37",32,"/roll d20+4\nМедицина на деда. Хотя и так понятно что старик надорвался",64123,null],[111720,"2026-07-12T22:20:00",32,"//ну потому жук и считает что дед умирает",111719,null],[111721,"2026-07-12T22:20:01",5,"// опиши как ты чуть не убил его...",111719,null],[111722,"2026-07-12T22:20:13",32,"Я его осматривал только",111721,null],[111723,"2026-07-12T22:20:51",5,"// и случайно пнул) ладно",111722,null],[111725,"2026-07-12T22:21:03",5,"// дед при смерти, ты уверен",111719,null],[111726,"2026-07-12T22:21:25",32,"Именно потому и говорю про последние почести",111725,null],[111727,"2026-07-12T22:22:02",5,"Глорир смотрит на тебя и ждёт продолжения.\n\n— Да, многие воины пали. И мы отдадим им честь. Но дела живых не ждут... Почему ты так смотришь на почтенного Алексия, три-крин?",64123,null],[111732,"2026-07-12T22:24:38",32,"(ну тут у жука заскочело он конечно уверен что дед присмерти но) (только Глориру)-я уверен что он умирает.",111727,null],[111733,"2026-07-12T22:25:17",5,"— Умирает?\n\nГлорир подходит и смотрит на старика",64123,null],[111734,"2026-07-12T22:25:21",5,"/r +2 медицина",64123,null],[111739,"2026-07-12T22:26:47",5,"— Чёрт! Ты прав, три-крин!\n\nОн бросается к деду Алексию и касается обеими руками. Через них течёт живительная сила.",64123,null],[111748,"2026-07-12T22:28:30",32,"(Три-крина немного шатало раны зарубцевались но могли открыться при любом неосторожном движении)",64123,null],[111749,"2026-07-12T22:28:35",5,"Спустя несколько секунд дед поднимается и опирается на посох.\n\n— Спасибо за заботу, сынки. Я в порядке, правда!",64123,null],[111755,"2026-07-12T22:29:00",32,"(на него два ошалевших взгляда квадратных глаз)",111749,null],[111756,"2026-07-12T22:29:41",5,"Алексий:\n\n— Потрепало твой панцирь, сынок. Тебе самому подлечиться стоит",64123,null],[111760,"2026-07-12T22:30:04",32,"(жук смотрит на паладина)\n-ем видимо вам стало легче. Рад за вас",111749,null],[111764,"2026-07-12T22:30:34",5,"Глорир осмотрел деда и переключил внимание на тебя.\n\n— Да, он в порядке. Подойди, у меня достаточно живительной силы и для тебя",64123,null],[111766,"2026-07-12T22:30:40",32,"-как говорил мой коллега тифлинг \"это фигня\" (и даже рукой отмахивается)",111756,null],[111768,"2026-07-12T22:30:58",32,"Но подошёл к паладину",111764,null],[111770,"2026-07-12T22:31:19",5,"Тот возложил руки. Ты чувствуешь облегчение.",64123,null],[111771,"2026-07-12T22:31:21",5,"// фул хп",64123,null],[111780,"2026-07-12T22:33:22",5,"Воины сталкивают поверженную нежить в ямы. Раненных уже перевязали.\n\nНебольшая группа бойцов во главе с Варрой (рыцарем, который всё время критиковал идею) подходит к вам.\n\n—Нежить уничтожена! Не будем терять времени, разгадка должна быть в карьере!",64123,null],[111781,"2026-07-12T22:33:24",32,"-Это конечно повезло что та абразина не вылезла на патруль",64123,null],[111785,"2026-07-12T22:34:10",5,"Глорир:\n— Ничего подобного раньше не лезло. Масло пробудило её. Но тварь повержена, слава Аскелатору!",111781,null],[111801,"2026-07-12T22:36:57",32,"-Мне почему-то кажется что не лезло потому что ждало повинуясь чьей то нехорошей воле. Будем аккуратны интуиция мага прорицателя ещё не успокоилась",64123,null],[111802,"2026-07-12T22:37:01",32,"-Сначала восстановить силы! Обязательно. Лучше перебдеть чем там полечь у меня круговой магии нет проводимость ауры кончилась",111780,null],[111819,"2026-07-12T22:40:36",5,"*ты также вспоминаешь, что эльф отправился в карьер посреди боя. С тех пор от него нет вестей*",64123,null],[111829,"2026-07-12T22:42:39",32,"Ну тогда пойду посмотрю с высоты вниз двинуть к тайнику пока паладины готовятся",111819,null],[111835,"2026-07-12T22:43:35",5,"С высоты карьера как всегда видно лишь 3 ступени. Ты идёшь вдоль карьера к тайнику?",111829,null],[111836,"2026-07-12T22:43:44",5,"// так, на этом на сегодня всё",64123,null],[111839,"2026-07-12T22:44:11",5,"// от @cirson тебя жду действий около тайника. Вскоре звуки битвы вдали затихнут",64123,null],[111843,"2026-07-12T22:44:52",32,"Да посмотреть с высока и если что спасать эльфа суицыдника",111835,null],[111844,"2026-07-12T22:44:53",32,"//опыт начислишь?",111839,null],[111846,"2026-07-12T22:45:55",5,"// пока числа не скажу. Но лвл-ап можешь сделать уже",111844,null],[111852,"2026-07-12T22:46:49",32,"Спасибо за квест мастер. Было жарко думал ТПК и стыдно жуку бы было если бы паладины полегли.",64123,null],[111853,"2026-07-12T22:46:49",32,"Надеюсь на такой же формат на грани",64123,null],[111864,"2026-07-12T22:49:26",5,"// пожалуйста)",111852,null],[111866,"2026-07-12T22:49:47",5,"// хотя не можешь, нужен длинный отдых",111846,null],[111868,"2026-07-12T22:49:58",5,"// но вообще скажу заранее, тут осталось немного",64123,null],[111869,"2026-07-12T22:50:03",5,"// и без боевки",64123,null],[111871,"2026-07-12T22:50:41",5,"// в следующий раз хочу убивать игроков, тут я добрый был",111853,null],[111877,"2026-07-12T22:51:17",5,"// правда для этого надо достаточно активных игроков",64123,null],[111878,"2026-07-12T22:51:21",5,"// а то не то",64123,null],[111889,"2026-07-12T22:53:44",32,"Да я заметил что пощадил но жук как волшебник второго уровня просто беспомощен",111871,null],[111891,"2026-07-12T22:54:13",32,"//ты прости то у меня неотложные дела то михи нет то ещё что",111877,null],[111893,"2026-07-12T22:54:18",5,"// ну, волшебник)",111889,null],[111894,"2026-07-12T22:54:31",5,"// да ты актив тянул хорошо",111891,null],[111895,"2026-07-12T22:54:38",5,"// жаловаться не могу",64123,null],[111897,"2026-07-12T22:57:05",32,"Ничего жук присоединиться к инициативе развития магических знаний Арминара и заживём",111893,null],[112711,"2026-07-13T16:14:00",47,"@elsio28",64123,null],[112720,"2026-07-13T16:15:59",47,"Покончив с призраком эльф выбирается наружу. Он кивает своим мыслям, как он и думал, этой армией управлял призрак. Он молча подошёл к рыцарям и встал рядом. Едва они обратили на него внимание он отчитался:\n- Проклятье лежало на призраке, что охранял тайник. Временно, или навсегда я его развеял, того не знаю. Но тайник всё ещё там, возможно стоит уничтожить то проклятье, что находится на нём",64123,null],[112766,"2026-07-13T16:28:52",32,"//а ты его убил?",112720,null],[112802,"2026-07-13T16:44:10",47,"/давно уже",64123,null],[112803,"2026-07-13T16:44:16",47,"/Из-за этого и бой кончился, разве нет?",64123,null],[112805,"2026-07-13T16:45:09",47,"/втжу что нет,",64123,null],[112806,"2026-07-13T16:45:16",47,"/но повлиял, возможно",64123,null],[112807,"2026-07-13T16:46:00",47,"/в общем жду от мастера кат сцену. Вечером вяло смогу ещё что-то поотвечать пт сценам, желательно в отряд ордена вступить",64123,null],[112809,"2026-07-13T16:47:42",5,"// сегодня занят, поздно буду",64123,null],[114375,"2026-07-14T09:40:22",47,"@elsio28 ждём наград. Мне вместо золота можно место в ордене. Очень хотелось бы",64123,null],[114376,"2026-07-14T09:57:55",5,"// скоро",64123,null],[114377,"2026-07-14T10:05:37",5,"// я не люблю недосказанность, поэтому вам надо будет сделать ещё несколько выборов для внятной концовки",64123,null],[114379,"2026-07-14T10:07:44",47,"/ну нам бы посты тогда",64123,null],[114380,"2026-07-14T10:07:54",47,"/я то выдал пост",112720,null],[114382,"2026-07-14T10:13:56",5,"Три-крин шёл по краю карьера, ища пропавшего эльфа в тумане. За ним следовал отряд готовых к бою воинов во главе с рыцарем Варрой.\n\nСпустя несколько минут они заметили эльфа, выбирающегося из карьера. \n\nВарра:\n— Этот тот эльф, исчезнувший посреди боя? Послушаем, что он скажет!\n\nВскоре эльф вылез наружу и подошёл к рыцарю. Варра выслушал его отчёт.\n\nВарра:\n— Ха! Значит не трус, как я подумал! Проклятый призрак, говоришь. И ты развеял его? Неплохо!\n\nРыцарь внимательно осматривает тебя.\n\n— За такие заслуги я могу принять тебя в орден. Но сначала увидим, равно ли твое мужество твоей мудрости. Тайник проклят, без сомнений! Иди, и сожги его, эльф! Дай мне узреть очищающее пламя!\n\nВарра потянул тебе флягу масла.",64123,null],[114390,"2026-07-14T10:16:47",47,"Эльф твёрдым шагом вернулся назад. Ему не жалко то, что проклято. И хотя его орден хранил и изучал проклятое, что является более рациональным подходом, данная вещь буквально исходит ненавистью. И изучению не подлежит. Масло летит в тайник, а следом искра",114382,null],[114395,"2026-07-14T10:20:34",5,"Дед, опирающийся на посох, подошёл сзади и к три-крину и эльфу, разговаривающие у с рыцарем.\n\n— Проклят? Нет, не может быть... Я сам его закладывал, там нет ничего дурного внутри! \n\nАлексий увидел решимость эльфа и обратился к жуку:\n— Останови его, сынок!",64123,null],[114396,"2026-07-14T10:20:43",5,"// твои действия увидел, жду реакцию жука",114390,null],[114398,"2026-07-14T10:25:00",47,"Эльф слыша этот крик тормозит. Масло поверх тайника, но искра ещё не запущена",64123,null],[114399,"2026-07-14T10:25:06",47,"Он оглядывается. Ждёт",64123,null],[114400,"2026-07-14T10:26:34",47,"@Xaosick",64123,null],[114403,"2026-07-14T10:29:34",32,"-Как минимум надо изучить что там и что вызвало некротическую энергию вполне возможно что именно смерть того кто стал призраком и дала толчок! Ну а главное эльф не имеет чувства магии и говорит про проклятие прото ради \"места в ордене\" а не из-за знания",64123,null],[114404,"2026-07-14T10:29:59",47,"/нихуя себе",64123,null],[114405,"2026-07-14T10:30:09",47,"/вот это предъява",64123,null],[114407,"2026-07-14T10:30:33",32,"/Это не предъява а факт",64123,null],[114408,"2026-07-14T10:31:30",47,"- Я согласен. Я не имею чувства магии, но место в ордене? Что ты мелешь, жук? Я сам лично слышал от призрака, что это его сокровища. Я видел как он их охранял. Единственное верное объяснение - они прокляты",64123,null],[114411,"2026-07-14T10:31:51",47,"/он возможно глупый но не ради выгоды он это делал явно",64123,null],[114412,"2026-07-14T10:31:57",47,"/я - да. Персонаж - нет",64123,null],[114413,"2026-07-14T10:32:20",32,"-Этот призрак товарищ нашего деда (указываю пальцем на жреца) и это БУКВАЛЬНО его схрон. Так что не вижу ничего удивительного в том что призрак тянется к денюшкам или что он туда закладывал и ради чего вернулся и похоже нарвался на ту четерехрккую гориллу",64123,null],[114414,"2026-07-14T10:33:48",32,"Вот и весь ответ",114413,null],[114418,"2026-07-14T10:35:53",47,"- То есть, есть шансы, что схрон притянет ещё призраков. Мало ли с кем ещё вёл знакомства уважаемый. Я считаю, что он должен быть очищен. Ритуалом ли, или уничтожен. Если вы можете очистить, то считаю это возможным",64123,null],[114420,"2026-07-14T10:36:24",32,"-Вот потому дай это сделать жрецу",114418,null],[114421,"2026-07-14T10:36:57",32,"А за одно простится с товарищем",64123,null],[114423,"2026-07-14T10:38:01",47,"Эльф склоняет голову перед жрецом, разрешая тому подойти, но взгляд после поклона следит за жуком. \n Призрак был частично прав. Союзники слишком часто бьют в спину",64123,null],[114428,"2026-07-14T10:38:58",32,"/увы но жук в первую очередь учёный и эму важно изучить",64123,null],[114430,"2026-07-14T10:39:50",47,"/увы, но можно быть тактичным",64123,null],[114441,"2026-07-14T10:45:34",5,"Старик с помощью одного из воинов ордена спустился к тайнику. Он подошёл к скелету, лежащему у самого входа. Кинул взгляд на запыленный сундук внутри, а потом упал на землю, к костям. Алексий ощупывает неповреждённый доспех на скелете.\n\n— Да, узнаю... Доспех Андрейки... А теперь его неупокоенный дух бродит здесь! Зачем ты пошёл сюда без меня, старый друг!\n\nДед сидит полминуты около усохшего скелета, смотрит на сундук и поворачивается к вам.\n\n— Я был жрецом, но мои силы уже не те. Ритуалы очищения мне недоступны. Но призрак... Андрейка не проклят! Лишь не выполнил цели. Заберём сундук — и дух успокоится навеки.\n\nВарра стоит в стороне, опираясь на двуручный меч и наблюдает за участниками сцены. Он молчит, его лицо скрыто шлемом. Неизвестно, что рыцарь сейчас думает.",64123,null],[114450,"2026-07-14T10:52:50",32,"-Хмм а если кто-то из паладинов под вашим руководством проведёт ритуалы?",64123,null],[114452,"2026-07-14T10:54:28",32,"(задал вполне на свой взгляд резонный вопрос жук)",64123,null],[114453,"2026-07-14T10:55:23",47,"Эльф молча стоит. Он был прав. Место проклято. Тот факт, что он не разбирается в магии не значит, что он не умеет думать. И обвинение жука задело чувства эльфа, хотя он это и не показывал. \n Он помнит как вытаскивал жука с этого карьера, как провёл стабилизацию, хотя эта ошибка природы и не заслуживала этого. Он запомнил эту обиду на долго. До конца жизни. Жизни жука",64123,null],[114456,"2026-07-14T10:56:22",47,"@elsio28",64123,null],[114458,"2026-07-14T10:56:53",32,"//да уж этот взгляд от фасеточных глаз не укроется. Но если начнёшь ПВП у меня и шансов без знамений и круговой магии нет",64123,null],[114459,"2026-07-14T10:57:21",5,"Варра меряет жука взглядом из-под шлема:\n— Айзек может провести очищение. Но он ранен после боя.",114450,null],[114460,"2026-07-14T10:57:22",47,"/нет, пвп я не буду начинать",64123,null],[114462,"2026-07-14T10:57:33",5,"// так, тогда в чем заявка?",114456,null],[114463,"2026-07-14T10:57:51",47,"/я к заявке жука отослал",114462,null],[114468,"2026-07-14T10:58:51",32,"Тогда ждём. Говорил стоит посидеть и отдохнуть восстановив силы",114459,null],[114470,"2026-07-14T10:59:31",47,"В анкете сказано чем обернулись неосторожные слова",114468,null],[114471,"2026-07-14T10:59:59",32,"//вообще не люблю когда на меня обижаются особенно не за что так как я до сих пор не понимаю что я сделал не так",114453,null],[114472,"2026-07-14T11:00:00",5,"Варра:\n— Мы можем подождать Айзека. И проклятый призрак вернётся. Или покончим с нечистым схроном прямо сейчас!\n\nДед Алексий:\n— Дайте коснутся сундука! Обещаю, призрак не вернётся",64123,null],[114474,"2026-07-14T11:00:23",5,"// все согласны?",114468,null],[114478,"2026-07-14T11:01:51",47,"/я на тебя не обижался. Обиделся эльф. Он помог жуку. Сейчас он был готов сжечь тайник, но не стал его жечь, подождал пока что-то скажут другие. \n В ответ жук обвинил честного эльфа в корыстности.",114471,null],[114479,"2026-07-14T11:01:54",32,"-Я поддержу дедушку Алексия. (Спокойно рядом с жрецом стал жук)",114472,null],[114480,"2026-07-14T11:02:24",47,"Эльф молча встал рядом с рыцарем",64123,null],[114481,"2026-07-14T11:02:41",32,"/мда я не ожидал что это будет трактовал так.\nТем более что такого смысла в слова не закладывалось",114478,null],[114484,"2026-07-14T11:04:10",5,"Варра:\n— Осторожность. Хорошее качество для служителя ордена. \n\nРыцарь что-то шепчет и делает знак рукой. Затем прислоняется к стене и ждёт. Другие воины стоят наготове.",64123,null],[114487,"2026-07-14T11:05:42",5,"Один из воинов ранее был отправлен к основной группе, чтобы позвать Айзека.\n\nСпустя 10 минут наверху раздаётся чей-то говор, несколько воинов спускаются в карьер",64123,null],[114488,"2026-07-14T11:05:42",47,"/честно, с тобой не первы раз спорю. Но представь если бы эльф сейчас кинул спичку в схрон и озвучил в слух:\n- Жук беспокоится не о здравии Алексия, он беспокоится о том, чтобы получить в своё владение схрон, который обещал Алексий. Он движим лишь своими эгоистичными мотивами",114481,null],[114490,"2026-07-14T11:06:28",32,"/И попал бы в десяточку законно злого по мировоззрению жука",64123,null],[114492,"2026-07-14T11:06:44",47,"/но при этом настроил против него окружающих",64123,null],[114494,"2026-07-14T11:07:36",47,"/никто не хочет, чтобы его, считали хуже, чем он пытается притворится, или казаться, даже для самого, себя",64123,null],[114496,"2026-07-14T11:07:51",32,"/Да и это тоже но не настолько критично они уже вместе сражались насмерть. Не важно что движет жуком важно что это на пользу ордену",114492,null],[114497,"2026-07-14T11:07:54",5,"Однако перед этим над скелетом проявляется мерцание. При первых проблесках Варра бросается к мерцающей плоти и наносит размашистый удар мечом. Меч сияет ярким светом. Мерцание прекращается.\n\nВарра:\n— Призрак возвращался. Осторожность имеет цену.",64123,null],[114503,"2026-07-14T11:10:08",47,"Рядом встаёт эльф. Наготове серебрянная стрела",64123,null],[114504,"2026-07-14T11:10:24",5,"Вскоре к тайнику подходит Айзек и несколько воинов. Жрец делает шаг к сундуку и читает молитву. Спустя несколько минут сосредоточения он говорит:\n— Проклятия нет. Сундук чист!",64123,null],[114507,"2026-07-14T11:10:53",32,"-А что насчёт останков?",114504,null],[114509,"2026-07-14T11:12:09",5,"Дед Алексий:\n— Останки моего друга Андрея... Его надо похоронить!\n\nЖрец Айзек:\n— Кости лежат, но привидение не привязано ими",64123,null],[114512,"2026-07-14T11:12:41",32,"(жук все ещё чувствовал напряжение витающие в воздухе да и туман этот странный все ещё не начал рассеиваться что его капитально напрягало)\n- да и надо обследовать весь карьер на предмет источника некротики",64123,null],[114514,"2026-07-14T11:12:58",5,"// это он говорит?",114512,null],[114516,"2026-07-14T11:13:33",32,"-Предлагаю придать их огню (указываю на остатки) я помогу с погребальным костром",114509,null],[114519,"2026-07-14T11:15:15",5,"Айзек смотрит на деда, сидящего около костей и качает головой.\n\n— Нет, это неправильно. Мы заберём останки и похороним как следует. Орден позаботится об этом.",114516,null],[114522,"2026-07-14T11:16:32",32,"(спокойно кивает у всех свои погребальные традиции)\nТогда забираем клад",114519,null],[114523,"2026-07-14T11:17:05",5,"Дед Алексий поднимается на ноги и благодарит Айзека.\n\nСундук у вас в руках.",64123,null],[114524,"2026-07-14T11:17:10",32,"/напомню что жук эльфу серебряные стрелы ковал. Пусть он их почему-то и не использовал",114503,null],[114525,"2026-07-14T11:17:55",32,"(Призываю тендеров диск загружаю туда сундук и приглашаю деда) -могу довести до места похорон",114523,null],[114526,"2026-07-14T11:18:08",5,"Варра кивает и берёт в руки меч.\n\n— Причина тумана лежит не здесь. Мы спустимся дальше в карьер.",114512,null],[114527,"2026-07-14T11:18:23",5,"// да, с сундуком закончили",114525,null],[114528,"2026-07-14T11:18:45",5,"// можете сходить с рыцарями либо дождаться результата просто",64123,null],[114530,"2026-07-14T11:19:17",32,"//Хорошо пусть рыцари сами у жука нет ячеек он как маг поддержка почти бесполезен",114526,null],[114531,"2026-07-14T11:19:59",32,"Начисляй опыт за побоище.\nА ещё жук может исследовать гориллу",64123,null],[114532,"2026-07-14T11:20:14",5,"// тогда последняя вопрос и я подведу итоги",64123,null],[114536,"2026-07-14T11:21:26",47,"/использовал /",114524,null],[114537,"2026-07-14T11:21:57",32,"//тогда где-то проглядел прости",114536,null],[114540,"2026-07-14T11:23:11",5,"Спустя несколько часов жук и эльф вновь сидят в доме деда Алексия. На столе стоит открытый сундучок. Рядом лежит доспех, снятый со скелета призрака.\n\nДед:\n— Талон (или Эльф, если ты не назвал себя), вот доспех моего усопшего друга. Я вижу, что он совсем как твой. Но у него есть одно свойство — его невозможно сломать. Прими от меня, сынок!",64123,null],[114541,"2026-07-14T11:23:51",47,"Эльф склоняет голову. Он отдаст его ордену.",64123,null],[114542,"2026-07-14T11:24:21",5,"Из сундука вы достали мантию и приличный мешок золота.\n\nАлексий:\n— Как мы условились, мне нужна лишь малая часть. Чтобы дожить мой век.",64123,null],[114544,"2026-07-14T11:24:30",5,"// скажите, какую часть золота оставите старику",64123,null],[114545,"2026-07-14T11:24:42",32,"Сколько там золота?",64123,null],[114547,"2026-07-14T11:25:29",5,"// точное число не скажу сейчас. Так что скажите какая доля\nи напомню, что от ордена тоже будет награда",64123,null],[114549,"2026-07-14T11:26:17",47,"/я бы отдал 1/3 от всего количества золота",64123,null],[114550,"2026-07-14T11:26:27",32,"-Это была славная охота Старейшина. (Склонил голову и переплел руки в сложном узоре) Благодарю что вели нас в этой охоте. (Жук не посмотрел на награду ибо без жреца он мог до нее и не дойти а значит он ее по устою три-крин не достоин)",64123,null],[114552,"2026-07-14T11:26:33",47,"Я отдам 1/3 своей суммы",64123,null],[114553,"2026-07-14T11:26:53",32,"(жук не берет золото)",64123,null],[114555,"2026-07-14T11:28:16",32,"(как минимум если дед сам не скажет взять аннулированы вину такие правила признания ошибок)",64123,null],[114559,"2026-07-14T11:29:29",5,"// окей",64123,null],[114564,"2026-07-14T11:32:23",47,"Эльф пожимает плечами. Он отсыпает чётко треть из сундука. Ему не понравилось, то что жрец стал виновником проклятия из-за которого умирали люди",64123,null],[114566,"2026-07-14T11:32:55",5,"Дед Алексий благодарно смотрит на вас.\n— Спасибо, сынки!\n\nТри-крину он протягивает мантию.\n— Когда-то она послужила мне. Теперь мантия твоя",64123,null],[114569,"2026-07-14T11:34:03",32,"(Принимаю у меня конечно одежды изетов высокотехнологические но это награда как ни как)\n-Она магическая?",114566,null],[114570,"2026-07-14T11:34:26",47,"- Проклятье слишком глубоко сидит в этом золоте. Будьте осторожны. Я читал о многих проклятиях, что не рассеиваются одним лишь ритуалом",64123,null],[114571,"2026-07-14T11:34:31",5,"— Да. Она поможет тебе творить заклинания",114569,null],[114573,"2026-07-14T11:34:51",5,"// это арты, скоро скину что дают",64123,null],[114575,"2026-07-14T11:35:24",32,"-Проклятое золото оно на кругах ада бывает а так только как проклятие жадности.",114570,null],[114578,"2026-07-14T11:35:48",32,"-Но да стоит быть аккуратнее чисто из соображений паранои",64123,null],[114579,"2026-07-14T11:35:51",5,"Дед качает головой:\n— Никакого проклятия нет. Нежить в карьере не связана с призраком моего друга",114570,null],[114582,"2026-07-14T11:36:30",47,"- Как скажете, уважаемый - вновь склонил голову эльф",64123,null],[114585,"2026-07-14T11:40:02",5,"Вы покидаете дом деда и вскоре наведываетесь на аванпост рыцарей. Тай Айзек рассказывает, что отряд Варра спустился на дно карьера и обнаружил некий проклятый артефакт. Его аура высасывала силы из воинов, подошедших близко. Но рыцарь одним ударом благословлённого меча уничтожил нечистый артефакт.\n\nПосле вам обоим предложили вступить в орден рыцарей Миф Драннора на роль солдата и инженера.",64123,null],[114587,"2026-07-14T11:40:34",5,"// жук упоминал рыцарям, что он из гильдии Изеттов?",64123,null],[114592,"2026-07-14T11:43:33",32,"-Мне уставом гильдии запрещено без письменного разрешения старшего инженера или САМОГО (с указанием пальцем вверх) вступать в другие организации. Но благодарю за предложение и не запрещается внешнее сотрудничество как у нас уже было, то есть подряд \n(Спокойно и с некоторым сожалением сказал жук.)(Но гильдия Иззетов по идее не должна была рыцарям ничего сказать)",114585,null],[114598,"2026-07-14T11:49:10",47,"/ну раз на ускоре, эльф принял членство в ордене.",64123,null],[114600,"2026-07-14T11:50:01",47,"Он отдал артефакт ордену.",64123,null],[114602,"2026-07-14T11:51:17",5,"Спустя месяц три-крина нашёл посыльный с письмом. Текст был длинным, и жук запомнил лишь следующие строки письма:\n\n\"...дошло известие о блестящем инженерном плане...\n...помощь уважаемому ордену...\n..заслужил поощрение...\"\n\nПодпись на письме гласила: инженер Эверон, официальный представитель лиги Иззетов в Тор Каргоне.\n\nВместе с письмом прилагался магический свиток.",64123,null],[114604,"2026-07-14T11:53:18",32,"/Ооо ,кажется мне туда 😁",114602,null],[114606,"2026-07-14T11:54:20",5,"С эльфа взяли клятву вести борьбу со злыми силами и защищать обездоленных.",114598,null],[114607,"2026-07-14T11:54:40",47,"Я составлю и отправлю на редакцию",114606,null],[114608,"2026-07-14T11:54:50",5,"// давай",114607,null],[114609,"2026-07-14T11:54:57",5,"// а я считаю и пишу итоговые награды",64123,null],[114610,"2026-07-14T11:55:04",5,"// напишите отзывы пожалуйста",64123,null],[114612,"2026-07-14T11:55:19",47,"Здесь, или в основе?",114610,null],[114615,"2026-07-14T11:55:30",5,"// здесь",64123,null],[114620,"2026-07-14T11:56:46",47,"Итак. Квест изначально был простенький, мастер по ходу игры старался подстроиться под игроков, помочь, выдать варианты для развития, прислушивался. \nЯ прошу прощения, что не всегда мог учавствовать. \n Не понравилось поведение остальных игроков. Два человека просто слились",64123,null],[114622,"2026-07-14T11:57:00",32,"//бой явно подкручивался под наш уровень но мне понравилось что было ощущение \"все пиздец\" и при этом ты смог это разрулить за что большая благодарность. Мастер ты чуткий и явно чувствуешь грань между \"это эпик\" и \"это тпк\" \nОгромная благодарность за игру",64123,null],[114623,"2026-07-14T11:57:08",47,"Было достаточно интересно взаимодействовать с жуком, куча нарратива",64123,null],[114624,"2026-07-14T11:57:49",32,"Я стараюсь всегда отыгрывать мышление персонажа",64123,null],[114625,"2026-07-14T11:58:02",47,"Как за простой квест 9/10\nА так впечатления из-за остального/остальных  7/10",64123,null],[114626,"2026-07-14T11:58:42",32,"Как игра это был заслужено один из лучших квестов",64123,null],[114627,"2026-07-14T11:59:16",32,"На уровне с моим первым мастером с 17 годика и стажа так что ты прямо очень хорош",64123,null],[114629,"2026-07-14T12:00:07",5,"Спасибо)",64123,null],[114631,"2026-07-14T12:01:35",47,"/у меня были мастера лучше, но учитывая то какой хаос тут иногда происходил, ты вытянул",64123,null],[114633,"2026-07-14T12:02:04",47,"/а особенно учитывая те споры что начинались между мной и Артуром",64123,null],[114645,"2026-07-14T12:15:59",5,"Награды за квест \"Забытый тайник\":\n\nАрты\nЖук:\nМантия, притягивающая Плетение (обычный предмет, требуется настройка)\nПозволяет восстановить 1 ячейку 1-го круга. Способность восстанавливается с рассветом.\nЭльф (если отдал ордену, то без него):\nУдивительно крепкий проклёпанный кожаный доспех (обычный предмет)\nПережил не одного владельца (и переживёт вас). Невозможно сломать, лишь частично повредить.\n\nЗолото\nЖук 300 зм\nЭльф 400 зм\n\nСвиток жуку: Трюк с верёвкой [Rope trick]\n\nОпыт жуку и эльфу\n@Xaosick суммарно 1100 (600 бой+300 квест+200 отыгрыш)\n@cirson суммарно 950 (600 бой+300 квест+50 отыгрыш)\n\nотдельно исчезнувшему с квеста деду за отыгрыш @DIOGEN_0 100 опыта",64123,null],[114647,"2026-07-14T12:19:43",47,"/отдал ордену",64123,null],[114656,"2026-07-14T12:26:23",47,"@elsio28 так, а что мне даёт то, что я в ордене состою?",64123,null],[114657,"2026-07-14T12:26:52",47,"Как он называется? /",64123,null],[114658,"2026-07-14T12:27:28",5,"Рыцари Миф Драннора. Давным-давно, Рыцари Миф Драннора были знаменитой группой искателей приключений, а Дав Фальконхэнд, одна из знаменитых Семи Сестёр, была одной из них. Группа взяла себе имя в честь великого, но павшего города, также, как и новые Рыцари Миф Драннора современности. Когда город снова был разрушен, Дав Фальконхэнд решила реформировать группу, поставив главной целью - строить альянсы и прочные дружеские связи между цивилизованными расами мира и добрым людом для борьбы со злом. Нынче Рыцари Миф Драннора снова ездят по дорогам Долин и начинают распространяться во внешние земли. Члены отряда утверждаются самой Дав и ставят превыше всего смелость и честь.",64123,null],[114659,"2026-07-14T12:27:32",5,"// это офишиал лор",64123,null],[114660,"2026-07-14T12:27:49",5,"// тут осталась суть, то есть их цели",64123,null],[114661,"2026-07-14T12:28:06",5,"// напишу позже",114656,null],[114662,"2026-07-14T12:58:02",5,"// вариант простоя\nСлужба в ордене\nКаждый день получаешь 10 зм, каждый второй день 1 флягу святой воды\n\n// В личное \nБрошка ордена Миф Драннора.\nНа ней изображён символ: 3 серебряных полумесяца над синим пламенем на чёрном поле.",64123,null]]);
